#!/usr/bin/env python3
"""Execution bound reality acceptance for Company OS outcomes."""
from __future__ import annotations
import argparse, hashlib, importlib.util, json
from pathlib import Path, PurePosixPath
from typing import Any, Mapping
REQUEST_SCHEMA='company-os.reality-acceptance-request.v2'; RECEIPT_SCHEMA='company-os.reality-acceptance-receipt.v1'
OUTCOME_SCHEMA='company-os.outcome-contract.v1'; ARTIFACT_SCHEMA='company-os.artifact-observation-contract.v1'; EVALUATOR_SCHEMA='company-os.evaluator-runtime-contract.v1'; BENCHMARK_SCHEMA='company-os.benchmark-contract.v1'; CALIBRATION_SCHEMA='company-os.evaluator-calibration-receipt.v1'
SCHEMA=REQUEST_SCHEMA; OUT=RECEIPT_SCHEMA
_EXECUTION_MODULE=None; _CALIBRATION_MODULE=None
class RealityError(ValueError):
 def __init__(self,code,msg): self.code=code; self.message=msg; super().__init__(f'{code}: {msg}')
def canonical(v): return json.dumps(v,sort_keys=True,separators=(',',':'),ensure_ascii=False,allow_nan=False).encode()
def digest(v): return hashlib.sha256(canonical(v)).hexdigest()
def file_digest(p): return hashlib.sha256(p.read_bytes()).hexdigest()
def text(v,l):
 if not isinstance(v,str) or not v.strip() or '\x00' in v: raise RealityError('E_SCHEMA',f'{l} must be nonempty')
 return v
def obj(v,l):
 if not isinstance(v,Mapping): raise RealityError('E_SCHEMA',f'{l} must be object')
 return v
def sha(v,l):
 v=text(v,l)
 if len(v)!=64 or any(c not in '0123456789abcdef' for c in v): raise RealityError('E_SCHEMA',f'{l} must be sha256')
 return v
def safe(project,v,l):
 raw=text(v,l); pure=PurePosixPath(raw)
 if '\\' in raw or pure.is_absolute() or not pure.parts or any(x in {'','.','..'} for x in pure.parts): raise RealityError('E_PATH',f'{l} unsafe')
 root=project.resolve(); cur=root
 for part in pure.parts:
  cur/=part
  if cur.is_symlink(): raise RealityError('E_PATH',f'{l} traverses symlink')
 try: p=(root/Path(*pure.parts)).resolve(strict=True)
 except OSError as e: raise RealityError('E_PATH',f'{l} missing') from e
 if root!=p and root not in p.parents or not p.is_file() or p.is_symlink(): raise RealityError('E_PATH',f'{l} invalid')
 return p,pure.as_posix()
def read(p,l):
 try: return json.loads(p.read_text())
 except Exception as e: raise RealityError('E_JSON',f'invalid {l}') from e
def verify_self(v,field,l):
 observed=sha(v.get(field),f'{l}.{field}')
 if observed!=digest({**v,field:None}): raise RealityError('E_DIGEST',f'{l} changed')
 return observed
def module(relative,name):
 path=Path(__file__).resolve().parents[2]/relative; spec=importlib.util.spec_from_file_location(name,path)
 if not spec or not spec.loader: raise RealityError('E_RUNTIME',f'cannot load {name}')
 m=importlib.util.module_from_spec(spec); spec.loader.exec_module(m); return m
def execution_module():
 global _EXECUTION_MODULE
 if _EXECUTION_MODULE is None: _EXECUTION_MODULE=module('execute-outcome-evaluator/scripts/execute_evaluator.py','company_os_reality_eval')
 return _EXECUTION_MODULE
def calibration_module():
 global _CALIBRATION_MODULE
 if _CALIBRATION_MODULE is None: _CALIBRATION_MODULE=module('calibrate-outcome-evaluator/scripts/calibrate_evaluator.py','company_os_reality_cal')
 return _CALIBRATION_MODULE

def load_contract(project,path_value,label,schema):
 p,rel=safe(project,path_value,label); v=dict(obj(read(p,label),label))
 if v.get('$schema')!=schema: raise RealityError('E_SCHEMA',f'{label} bad schema')
 verify_self(v,'contract_sha256',label)
 return v,{'path':rel,'file_sha256':file_digest(p),'contract_sha256':v['contract_sha256']}
def load_sources(project,paths,objective_id,original):
 required={'outcome_contract','artifact_contract','evaluator_contract','benchmark_contract','calibration_receipts'}
 if set(paths)!=required: raise RealityError('E_SCHEMA','source_paths incomplete')
 outcome,ob=load_contract(project,paths['outcome_contract'],'outcome contract',OUTCOME_SCHEMA)
 artifacts,ab=load_contract(project,paths['artifact_contract'],'artifact contract',ARTIFACT_SCHEMA)
 evaluators,eb=load_contract(project,paths['evaluator_contract'],'evaluator contract',EVALUATOR_SCHEMA)
 benchmarks,bb=load_contract(project,paths['benchmark_contract'],'benchmark contract',BENCHMARK_SCHEMA)
 for label,v in [('outcome',outcome),('artifacts',artifacts),('evaluators',evaluators),('benchmarks',benchmarks)]:
  if v.get('objective_id')!=objective_id: raise RealityError('E_BINDING',f'{label} objective mismatch')
 if outcome.get('original_objective')!=original: raise RealityError('E_BINDING','outcome does not bind original objective')
 cp,crel=safe(project,paths['calibration_receipts'],'calibration_receipts'); raw=read(cp,'calibration receipts')
 if not isinstance(raw,list) or not raw: raise RealityError('E_CALIBRATION','calibration receipts required')
 cal=[]
 for i,r in enumerate(raw):
  r=dict(obj(r,f'calibration[{i}]'))
  try: v=dict(calibration_module().verify_receipt(project,r))
  except Exception as e: raise RealityError(getattr(e,'code','E_CALIBRATION'),f'calibration invalid: {e}') from e
  if v.get('objective_id')!=objective_id or v.get('execution_bound') is not True or v.get('passed') is not True: raise RealityError('E_CALIBRATION','calibration not accepted for objective')
  cal.append({'evaluator_id':v['evaluator_id'],'receipt_sha256':sha(v['receipt_sha256'],'calibration receipt_sha256')})
 return {'outcome_contract':ob,'artifact_contract':ab,'evaluator_contract':eb,'benchmark_contract':bb,'calibration_receipts':{'path':crel,'file_sha256':file_digest(cp),'receipts_sha256':digest(sorted(cal,key=lambda x:x['evaluator_id']))}},outcome,artifacts

def required_observation_evidence(artifact_contract):
 result={}
 for item in artifact_contract.get('artifact_classes',[]):
  if not isinstance(item,Mapping) or item.get('required') is not True: continue
  aid=text(item.get('artifact_class_id'),'artifact_class_id'); evidence=item.get('required_evidence',[])
  if not isinstance(evidence,list) or not all(isinstance(x,str) and x for x in evidence): raise RealityError('E_SCHEMA',f'{aid}.required_evidence invalid')
  result[aid]=set(evidence)
 return result

def accept(project,req=None):
 if req is None:
  req=project; raise RealityError('E_SCHEMA','project root is required for execution bound reality acceptance')
 project=project.resolve()
 if req.get('$schema')!=REQUEST_SCHEMA: raise RealityError('E_SCHEMA','bad request schema')
 oid=text(req.get('objective_id'),'objective_id'); original=text(req.get('original_objective'),'original_objective'); candidate_id=text(req.get('candidate_id'),'candidate_id')
 if req.get('production_narrative_admissible') is not False: raise RealityError('E_AUTHORITY','production narrative is inadmissible')
 production=sorted(set(req.get('production_actor_ids',[])))
 if not production: raise RealityError('E_AUTHORITY','production actors required')
 sources,outcome,artifact_contract=load_sources(project,obj(req.get('source_paths'),'source_paths'),oid,original)
 claims=req.get('claims')
 if not isinstance(claims,list) or not claims: raise RealityError('E_SCHEMA','claims required')
 known_claims={x.get('claim_id'):x for x in outcome.get('outcome_claims',[]) if isinstance(x,Mapping)}
 required_evidence_by_artifact=required_observation_evidence(artifact_contract)
 seen=set(); decisions=[]; blockers=[]
 for i,c in enumerate(claims):
  c=obj(c,f'claims[{i}]'); cid=text(c.get('claim_id'),'claim_id')
  if cid in seen: raise RealityError('E_DUPLICATE',f'duplicate claim {cid}')
  seen.add(cid); statement=text(c.get('statement'),'statement'); required=c.get('required',True)
  if not isinstance(required,bool): raise RealityError('E_SCHEMA','required must be boolean')
  if cid not in known_claims or known_claims[cid].get('statement')!=statement: raise RealityError('E_BINDING',f'claim {cid} not in outcome contract')
  artifact_bindings=[]
  for j,a in enumerate(c.get('artifact_evidence',[])):
   a=obj(a,f'artifact_evidence[{j}]'); p,rel=safe(project,a.get('path'),f'artifact_evidence[{j}].path'); actual=file_digest(p)
   if actual!=sha(a.get('sha256'),'artifact sha256'): raise RealityError('E_DIGEST',f'artifact evidence changed: {cid}')
   artifact_bindings.append({'artifact_id':text(a.get('artifact_id'),'artifact_id'),'artifact_class_id':text(a.get('artifact_class_id'),'artifact_class_id'),'path':rel,'sha256':actual,'size':p.stat().st_size})
  artifact_classes={a['artifact_class_id'] for a in artifact_bindings}
  required_evidence=set().union(*(required_evidence_by_artifact.get(aid,set()) for aid in artifact_classes)) if artifact_classes else set()
  eval_bindings=[]; eval_accept=True; observed_evidence=set()
  for j,path_value in enumerate(c.get('evaluator_execution_receipt_paths',[])):
   p,rel=safe(project,path_value,f'evaluator_receipt[{j}]'); receipt=dict(obj(read(p,'evaluator receipt'),'evaluator receipt'))
   try: v=dict(execution_module().verify_receipt(project,receipt))
   except Exception as e: raise RealityError(getattr(e,'code','E_EVALUATOR'),f'evaluator receipt invalid: {e}') from e
   if v.get('objective_id')!=oid or sorted(receipt.get('production_actor_ids',[]))!=production or receipt.get('independent_role') is not True: raise RealityError('E_BINDING','evaluator receipt authority or objective mismatch')
   eval_accept=eval_accept and receipt.get('accepted') is True
   for evidence in receipt.get('evidence_bindings',[]):
    if isinstance(evidence,Mapping) and isinstance(evidence.get('evidence_type'),str) and evidence.get('evidence_type'):
     observed_evidence.add(evidence['evidence_type'])
   eval_bindings.append({'evaluator_id':v['evaluator_id'],'path':rel,'file_sha256':file_digest(p),'receipt_sha256':sha(v['receipt_sha256'],'execution receipt_sha256'),'accepted':receipt.get('accepted') is True})
  missing_observation=sorted(required_evidence-observed_evidence)
  evidence_ok=bool(artifact_bindings); independent_ok=bool(eval_bindings) and eval_accept; observation_ok=not missing_observation; passed=evidence_ok and independent_ok and observation_ok
  if required and not evidence_ok: blockers.append({'claim_id':cid,'code':'NO_ARTIFACT_EVIDENCE'})
  if required and not independent_ok: blockers.append({'claim_id':cid,'code':'INDEPENDENT_EVALUATION_FAILED'})
  if required and not observation_ok: blockers.append({'claim_id':cid,'code':'REQUIRED_OBSERVATION_EVIDENCE_MISSING','missing':missing_observation})
  decisions.append({'claim_id':cid,'statement':statement,'required':required,'passed':passed,'artifact_evidence':artifact_bindings,'evaluator_execution_receipts':eval_bindings,'required_observation_evidence':sorted(required_evidence),'observed_evidence_types':sorted(observed_evidence),'artifact_evidence_count':len(artifact_bindings),'evaluator_receipt_count':len(eval_bindings)})
 blockers.sort(key=lambda x:(x['claim_id'],x['code'])); accepted=not blockers and all((not d['required']) or d['passed'] for d in decisions)
 out={'$schema':RECEIPT_SCHEMA,'schema_version':2,'execution_bound':True,'objective_id':oid,'original_objective':original,'original_objective_sha256':hashlib.sha256(original.encode()).hexdigest(),'candidate_id':candidate_id,'production_actor_ids':production,'production_narrative_admissible':False,'source_bindings':sources,'claim_decisions':sorted(decisions,key=lambda x:x['claim_id']),'blockers':blockers,'accepted':accepted,'receipt_sha256':None}
 out['receipt_sha256']=digest(out); return out

def verify_receipt(project,receipt):
 if receipt.get('$schema')!=RECEIPT_SCHEMA or receipt.get('schema_version')!=2 or receipt.get('execution_bound') is not True: raise RealityError('E_SCHEMA','reality receipt is not execution bound')
 receipt_sha=verify_self(receipt,'receipt_sha256','reality receipt'); oid=text(receipt.get('objective_id'),'objective_id'); original=text(receipt.get('original_objective'),'original_objective')
 if receipt.get('production_narrative_admissible') is not False: raise RealityError('E_AUTHORITY','production narrative became admissible')
 bindings=obj(receipt.get('source_bindings'),'source_bindings'); paths={k:obj(v,f'source_bindings.{k}').get('path') for k,v in bindings.items()}
 sources,outcome,artifact_contract=load_sources(project,paths,oid,original)
 for k,v in sources.items():
  observed=obj(bindings.get(k),k)
  if observed.get('file_sha256')!=v.get('file_sha256'): raise RealityError('E_DIGEST',f'source drift: {k}')
 production=sorted(set(receipt.get('production_actor_ids',[]))); blockers=[]; count=0
 required_evidence_by_artifact=required_observation_evidence(artifact_contract)
 known={x.get('claim_id'):x for x in outcome.get('outcome_claims',[]) if isinstance(x,Mapping)}
 for d in receipt.get('claim_decisions',[]):
  d=obj(d,'claim decision'); cid=text(d.get('claim_id'),'claim_id')
  if cid not in known or known[cid].get('statement')!=d.get('statement'): raise RealityError('E_BINDING',f'claim drift: {cid}')
  artifacts=d.get('artifact_evidence',[]); evals=d.get('evaluator_execution_receipts',[])
  artifact_classes=set()
  for a in artifacts:
   a=obj(a,'artifact evidence'); p,_=safe(project,a.get('path'),'artifact path')
   if file_digest(p)!=sha(a.get('sha256'),'artifact sha256'): raise RealityError('E_DIGEST',f'artifact drift: {cid}')
   artifact_classes.add(text(a.get('artifact_class_id'),'artifact_class_id'))
  required_evidence=set().union(*(required_evidence_by_artifact.get(aid,set()) for aid in artifact_classes)) if artifact_classes else set()
  eval_accept=True; observed_evidence=set()
  for e in evals:
   e=obj(e,'evaluator execution'); p,_=safe(project,e.get('path'),'execution receipt path'); raw=dict(obj(read(p,'execution receipt'),'execution receipt'))
   try: v=dict(execution_module().verify_receipt(project,raw))
   except Exception as ex: raise RealityError(getattr(ex,'code','E_EVALUATOR'),f'evaluator receipt drift: {ex}') from ex
   if v.get('receipt_sha256')!=e.get('receipt_sha256') or sorted(raw.get('production_actor_ids',[]))!=production: raise RealityError('E_DIGEST',f'evaluator drift: {cid}')
   eval_accept=eval_accept and raw.get('accepted') is True
   for evidence in raw.get('evidence_bindings',[]):
    if isinstance(evidence,Mapping) and isinstance(evidence.get('evidence_type'),str) and evidence.get('evidence_type'):
     observed_evidence.add(evidence['evidence_type'])
  missing_observation=sorted(required_evidence-observed_evidence)
  passed=bool(artifacts) and bool(evals) and eval_accept and not missing_observation
  if d.get('required') is True and not artifacts: blockers.append({'claim_id':cid,'code':'NO_ARTIFACT_EVIDENCE'})
  if d.get('required') is True and (not evals or not eval_accept): blockers.append({'claim_id':cid,'code':'INDEPENDENT_EVALUATION_FAILED'})
  if d.get('required') is True and missing_observation: blockers.append({'claim_id':cid,'code':'REQUIRED_OBSERVATION_EVIDENCE_MISSING','missing':missing_observation})
  if d.get('passed') is not passed: raise RealityError('E_REALITY',f'stored claim decision drift: {cid}')
  if d.get('required_observation_evidence',[]) != sorted(required_evidence): raise RealityError('E_REALITY',f'stored observation requirement drift: {cid}')
  if d.get('observed_evidence_types',[]) != sorted(observed_evidence): raise RealityError('E_REALITY',f'stored observation evidence drift: {cid}')
  count+=1
 blockers=sorted(blockers,key=lambda x:(x['claim_id'],x['code']))
 accepted=not blockers and receipt.get('accepted') is True
 if receipt.get('blockers') != blockers: raise RealityError('E_REALITY','stored blocker state no longer matches reality')
 return {'objective_id':oid,'candidate_id':text(receipt.get('candidate_id'),'candidate_id'),'receipt_sha256':receipt_sha,'accepted':accepted,'execution_bound':True,'claim_count':count}
def main():
 p=argparse.ArgumentParser(); p.add_argument('--project-root',type=Path,required=True); p.add_argument('--request',type=Path,required=True); p.add_argument('--output',type=Path,required=True); a=p.parse_args()
 try: out=accept(a.project_root,obj(read(a.request,'request'),'request')); a.output.parent.mkdir(parents=True,exist_ok=True); a.output.write_text(json.dumps(out,indent=2,sort_keys=True)+'\n'); print(json.dumps({'ok':True,'accepted':out['accepted'],'receipt_sha256':out['receipt_sha256']},sort_keys=True)); return 0
 except RealityError as e: print(json.dumps({'ok':False,'code':e.code,'error':e.message},sort_keys=True)); return 2
if __name__=='__main__': raise SystemExit(main())

#!/usr/bin/env python3
"""Assemble bound production lane manifests into one Company OS outcome candidate."""
from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path, PurePosixPath
from typing import Any, Mapping

FABRIC_MODE = "outcome_closed_loop"
MANIFEST_SCHEMA = "company-os.outcome-lane-artifact-manifest.v1"
CANDIDATE_SCHEMA = "company-os.outcome-candidate.v1"
ARTIFACT_SCHEMA = "company-os.artifact-observation-contract.v1"


class CandidateAssemblyError(ValueError):
    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(f"{code}: {message}")


def canonical(value: Any) -> bytes:
    return json.dumps(
        value,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
        allow_nan=False,
    ).encode("utf-8")


def digest(value: Any) -> str:
    return hashlib.sha256(canonical(value)).hexdigest()


def file_digest(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def text(value: Any, label: str) -> str:
    if not isinstance(value, str) or not value.strip() or "\x00" in value:
        raise CandidateAssemblyError("E_SCHEMA", f"{label} must be nonempty")
    return value.strip()


def sha(value: Any, label: str) -> str:
    value = text(value, label)
    if len(value) != 64 or any(character not in "0123456789abcdef" for character in value):
        raise CandidateAssemblyError("E_SCHEMA", f"{label} must be lowercase sha256")
    return value


def obj(value: Any, label: str) -> Mapping[str, Any]:
    if not isinstance(value, Mapping):
        raise CandidateAssemblyError("E_SCHEMA", f"{label} must be an object")
    return value


def read_json(path: Path, label: str) -> Any:
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except FileNotFoundError as exc:
        raise CandidateAssemblyError("E_MANIFEST_MISSING", f"missing {label}: {path}") from exc
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise CandidateAssemblyError("E_JSON", f"invalid {label}: {path}") from exc


def safe_relative(value: Any, label: str) -> PurePosixPath:
    raw = text(value, label)
    pure = PurePosixPath(raw)
    if (
        "\\" in raw
        or pure.is_absolute()
        or not pure.parts
        or any(part in {"", ".", ".."} for part in pure.parts)
    ):
        raise CandidateAssemblyError("E_PATH", f"{label} is unsafe")
    return pure


def resolve_file(project_root: Path, value: Any, label: str) -> tuple[Path, str]:
    pure = safe_relative(value, label)
    root = project_root.resolve()
    current = root
    for part in pure.parts:
        current /= part
        if current.is_symlink():
            raise CandidateAssemblyError("E_PATH", f"{label} traverses a symlink")
    try:
        resolved = (root / Path(*pure.parts)).resolve(strict=True)
    except FileNotFoundError as exc:
        raise CandidateAssemblyError("E_ARTIFACT_MISSING", f"{label} does not exist: {pure.as_posix()}") from exc
    except OSError as exc:
        raise CandidateAssemblyError("E_PATH", f"{label} cannot be resolved") from exc
    if (
        (resolved != root and root not in resolved.parents)
        or not resolved.is_file()
        or resolved.is_symlink()
    ):
        raise CandidateAssemblyError("E_PATH", f"{label} is not a regular project file")
    return resolved, pure.as_posix()


def inside_scope(path_value: str, scope_value: str) -> bool:
    path = PurePosixPath(path_value)
    scope = PurePosixPath(scope_value)
    return path == scope or scope in path.parents


def required_artifact_classes(project_root: Path, fabric: Mapping[str, Any]) -> set[str]:
    control = obj(fabric.get("outcome_control"), "outcome_control")
    contract_path, _ = resolve_file(
        project_root,
        control.get("artifact_contract_path"),
        "outcome_control.artifact_contract_path",
    )
    raw = obj(read_json(contract_path, "artifact contract"), "artifact contract")
    if raw.get("$schema") != ARTIFACT_SCHEMA:
        raise CandidateAssemblyError("E_SCHEMA", f"artifact contract must use {ARTIFACT_SCHEMA}")
    records = raw.get("artifact_classes")
    if not isinstance(records, list):
        raise CandidateAssemblyError("E_SCHEMA", "artifact contract artifact_classes must be an array")
    required = {
        text(record.get("artifact_class_id"), "artifact_class_id")
        for record in records
        if isinstance(record, Mapping) and record.get("required") is True
    }
    if not required:
        raise CandidateAssemblyError("E_ARTIFACT", "artifact contract contains no required artifact classes")
    return required


def production_workers(fabric: Mapping[str, Any]) -> list[dict[str, Any]]:
    workers: list[dict[str, Any]] = []
    managers = fabric.get("managers")
    if not isinstance(managers, list) or not managers:
        raise CandidateAssemblyError("E_FABRIC", "fabric contains no managers")
    for manager_index, manager_raw in enumerate(managers):
        manager = obj(manager_raw, f"managers[{manager_index}]")
        lane_id = text(manager.get("outcome_loop_lane_id"), f"managers[{manager_index}].outcome_loop_lane_id")
        lane_sha = sha(manager.get("outcome_loop_lane_sha256"), f"managers[{manager_index}].outcome_loop_lane_sha256")
        manager_workers = manager.get("workers")
        if not isinstance(manager_workers, list) or not manager_workers:
            raise CandidateAssemblyError("E_FABRIC", f"manager {lane_id} has no workers")
        for worker_index, worker_raw in enumerate(manager_workers):
            worker = dict(obj(worker_raw, f"manager {lane_id} worker {worker_index}"))
            if worker.get("outcome_loop_lane_id") != lane_id:
                raise CandidateAssemblyError("E_BINDING", f"worker lane does not match manager lane: {lane_id}")
            if worker.get("outcome_loop_lane_sha256") != lane_sha:
                raise CandidateAssemblyError("E_BINDING", f"worker lane digest does not match manager lane: {lane_id}")
            scopes = worker.get("write_scope")
            if not isinstance(scopes, list) or len(scopes) != 1:
                raise CandidateAssemblyError("E_SCOPE", f"production worker {worker.get('id')} must have exactly one write scope")
            scope = safe_relative(scopes[0], "worker.write_scope").as_posix()
            workers.append(
                {
                    "worker_id": text(worker.get("id"), "worker.id"),
                    "lane_id": lane_id,
                    "lane_sha256": lane_sha,
                    "write_scope": scope,
                    "manifest_path": f"{scope}/artifact-manifest.json",
                    "goal_id": worker.get("goal_contract", {}).get("goal_id"),
                    "goal_sha256": worker.get("goal_contract", {}).get("goal_sha256"),
                    "goal_route_state_sha256": worker.get("goal_assignment", {}).get("route_state_sha256"),
                }
            )
    return workers


def validate_lane_manifest(
    project_root: Path,
    manifest: Mapping[str, Any],
    worker: Mapping[str, Any],
    loop_binding: Mapping[str, Any],
    objective_id: str,
) -> tuple[list[dict[str, Any]], dict[str, Any]]:
    if manifest.get("$schema") != MANIFEST_SCHEMA or manifest.get("schema_version") != 1:
        raise CandidateAssemblyError("E_SCHEMA", f"lane manifest must use {MANIFEST_SCHEMA}")
    if manifest.get("objective_id") != objective_id:
        raise CandidateAssemblyError("E_BINDING", "lane manifest objective does not match fabric")
    if manifest.get("outcome_loop_state_sha256") != loop_binding.get("state_sha256"):
        raise CandidateAssemblyError("E_STALE", "lane manifest binds a stale outcome loop state")
    if manifest.get("organization_sha256") != loop_binding.get("organization_sha256"):
        raise CandidateAssemblyError("E_STALE", "lane manifest binds a stale organization")
    if manifest.get("lane_id") != worker["lane_id"]:
        raise CandidateAssemblyError("E_BINDING", "lane manifest lane_id is incorrect")
    if manifest.get("lane_sha256") != worker["lane_sha256"]:
        raise CandidateAssemblyError("E_BINDING", "lane manifest lane digest is incorrect")
    if manifest.get("production_actor_id") != worker["worker_id"]:
        raise CandidateAssemblyError("E_AUTHORITY", "lane manifest production actor is incorrect")
    if worker.get("goal_id") is not None:
        if manifest.get("goal_id") != worker.get("goal_id") or manifest.get("goal_sha256") != worker.get("goal_sha256") or manifest.get("goal_route_state_sha256") != worker.get("goal_route_state_sha256"):
            raise CandidateAssemblyError("E_BINDING", "lane manifest goal binding is incorrect")
    artifacts_raw = manifest.get("artifacts")
    if not isinstance(artifacts_raw, list) or not artifacts_raw:
        raise CandidateAssemblyError("E_ARTIFACT", f"lane {worker['lane_id']} has no materialized artifacts")
    artifacts: list[dict[str, Any]] = []
    seen: set[str] = set()
    for index, artifact_raw in enumerate(artifacts_raw):
        artifact = obj(artifact_raw, f"artifact[{index}]")
        artifact_id = text(artifact.get("artifact_id"), f"artifact[{index}].artifact_id")
        if artifact_id in seen:
            raise CandidateAssemblyError("E_DUPLICATE", f"duplicate artifact_id {artifact_id}")
        seen.add(artifact_id)
        artifact_class_id = text(
            artifact.get("artifact_class_id"),
            f"artifact[{index}].artifact_class_id",
        )
        artifact_path, relative_path = resolve_file(
            project_root,
            artifact.get("path"),
            f"artifact[{index}].path",
        )
        if not inside_scope(relative_path, worker["write_scope"]):
            raise CandidateAssemblyError(
                "E_SCOPE",
                f"artifact {artifact_id} is outside worker write scope {worker['write_scope']}",
            )
        observed_sha = sha(artifact.get("sha256"), f"artifact[{index}].sha256")
        actual_sha = file_digest(artifact_path)
        if observed_sha != actual_sha:
            raise CandidateAssemblyError("E_DIGEST", f"artifact bytes changed: {artifact_id}")
        artifacts.append(
            {
                "artifact_id": artifact_id,
                "artifact_class_id": artifact_class_id,
                "path": relative_path,
                "sha256": actual_sha,
                "goal_id": worker.get("goal_id"),
                "goal_sha256": worker.get("goal_sha256"),
            }
        )
    observations = []
    observations_raw = manifest.get("observations", [])
    if observations_raw is not None and not isinstance(observations_raw, list):
        raise CandidateAssemblyError("E_OBSERVATION", "lane observations must be an array")
    for index, raw in enumerate(observations_raw or []):
        observation = obj(raw, f"observation[{index}]")
        kind = text(observation.get("kind"), f"observation[{index}].kind")
        if kind not in {"runtime_observed", "journey_connected"}:
            raise CandidateAssemblyError("E_OBSERVATION", f"unsupported observation kind {kind}")
        capability_id = text(observation.get("capability_id"), f"observation[{index}].capability_id")
        evidence_path, relative_path = resolve_file(project_root, observation.get("path"), f"observation[{index}].path")
        if not inside_scope(relative_path, worker["write_scope"]):
            raise CandidateAssemblyError("E_SCOPE", f"observation evidence is outside worker write scope {worker['write_scope']}")
        observed_sha = sha(observation.get("sha256"), f"observation[{index}].sha256")
        actual_sha = file_digest(evidence_path)
        if observed_sha != actual_sha:
            raise CandidateAssemblyError("E_DIGEST", f"observation evidence changed: {relative_path}")
        observations.append({
            "kind": kind,
            "capability_id": capability_id,
            "path": relative_path,
            "sha256": actual_sha,
            "observation_kind": text(observation.get("observation_kind", kind), f"observation[{index}].observation_kind"),
            "goal_id": worker.get("goal_id"),
            "goal_sha256": worker.get("goal_sha256"),
        })
    return sorted(artifacts, key=lambda item: item["artifact_id"]), {
        "path": worker["manifest_path"],
        "file_sha256": digest(manifest),
        "lane_id": worker["lane_id"],
        "production_actor_id": worker["worker_id"],
    }, sorted(observations, key=lambda item: (item["capability_id"], item["kind"], item["path"]))


def assemble(
    project_root: Path,
    fabric_raw: Mapping[str, Any],
    candidate_id: str,
) -> dict[str, Any]:
    project_root = project_root.resolve()
    fabric = dict(fabric_raw)
    if fabric.get("topology_mode") != FABRIC_MODE:
        raise CandidateAssemblyError("E_FABRIC", f"fabric must use topology_mode {FABRIC_MODE}")
    loop_binding = obj(fabric.get("outcome_loop"), "outcome_loop")
    if loop_binding.get("phase") not in {"build_candidate", "rework"}:
        raise CandidateAssemblyError("E_PHASE", "candidate assembly requires build_candidate or rework phase")
    control = obj(fabric.get("outcome_control"), "outcome_control")
    objective_id = text(control.get("objective_id"), "outcome_control.objective_id")
    candidate_id = text(candidate_id, "candidate_id")
    required = required_artifact_classes(project_root, fabric)
    all_artifacts: list[dict[str, Any]] = []
    production_actor_ids: list[str] = []
    seen_artifact_ids: set[str] = set()
    seen_paths: set[str] = set()
    source_manifests = []
    all_observations = []
    for worker in production_workers(fabric):
        manifest_path = project_root / Path(*PurePosixPath(worker["manifest_path"]).parts)
        manifest_raw = obj(read_json(manifest_path, f"lane artifact manifest for {worker['lane_id']}"), "lane manifest")
        artifacts, manifest_binding, observations = validate_lane_manifest(
            project_root,
            manifest_raw,
            worker,
            loop_binding,
            objective_id,
        )
        production_actor_ids.append(worker["worker_id"])
        source_manifests.append(manifest_binding)
        all_observations.extend(observations)
        for artifact in artifacts:
            if artifact["artifact_id"] in seen_artifact_ids:
                raise CandidateAssemblyError("E_DUPLICATE", f"artifact_id reused across lanes: {artifact['artifact_id']}")
            if artifact["path"] in seen_paths:
                raise CandidateAssemblyError("E_DUPLICATE", f"artifact path reused across lanes: {artifact['path']}")
            seen_artifact_ids.add(artifact["artifact_id"])
            seen_paths.add(artifact["path"])
            all_artifacts.append(artifact)
    observed_classes = {artifact["artifact_class_id"] for artifact in all_artifacts}
    missing = sorted(required - observed_classes)
    if missing:
        raise CandidateAssemblyError(
            "E_ARTIFACT",
            "candidate is missing required artifact classes: " + ", ".join(missing),
        )
    mission = fabric.get("mission_control")
    if isinstance(mission, Mapping) and mission.get("first_reality_required") is True:
        runtime_classes = {item["capability_id"] for item in all_observations if item["kind"] == "runtime_observed"}
        connected_classes = {item["capability_id"] for item in all_observations if item["kind"] == "journey_connected"}
        missing_runtime = sorted(required - runtime_classes)
        if missing_runtime:
            raise CandidateAssemblyError("E_OBSERVATION", "first reality candidate lacks runtime observations: " + ", ".join(missing_runtime))
        if not connected_classes.intersection(required):
            raise CandidateAssemblyError("E_OBSERVATION", "first reality candidate lacks a connected journey observation")
    return {
        "$schema": CANDIDATE_SCHEMA,
        "candidate_id": candidate_id,
        "objective_id": objective_id,
        "production_actor_ids": sorted(set(production_actor_ids)),
        "artifacts": sorted(all_artifacts, key=lambda item: item["artifact_id"]),
        "observations": sorted(all_observations, key=lambda item: (item["capability_id"], item["kind"], item["path"])),
    }


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--project-root", type=Path, required=True)
    parser.add_argument("--fabric", type=Path, required=True)
    parser.add_argument("--candidate-id", required=True)
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    try:
        fabric = obj(read_json(args.fabric, "fabric"), "fabric")
        candidate = assemble(args.project_root, fabric, args.candidate_id)
        args.output.parent.mkdir(parents=True, exist_ok=True)
        args.output.write_text(json.dumps(candidate, indent=2, sort_keys=True) + "\n", encoding="utf-8")
        print(
            json.dumps(
                {
                    "ok": True,
                    "candidate_id": candidate["candidate_id"],
                    "artifact_count": len(candidate["artifacts"]),
                    "production_actor_count": len(candidate["production_actor_ids"]),
                },
                sort_keys=True,
            )
        )
        return 0
    except CandidateAssemblyError as exc:
        print(json.dumps({"ok": False, "code": exc.code, "error": exc.message}, sort_keys=True))
        return 2


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Assemble verified evaluator execution receipts into one Company OS evaluation batch."""
from __future__ import annotations

import argparse
import importlib.util
import json
from pathlib import Path, PurePosixPath
from typing import Any, Callable, Mapping

FABRIC_MODE = "outcome_closed_loop"
BATCH_SCHEMA = "company-os.outcome-evaluation-batch.v1"
EVALUATOR_SCHEMA = "company-os.evaluator-runtime-contract.v1"


class EvaluationAssemblyError(ValueError):
    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(f"{code}: {message}")


def text(value: Any, label: str) -> str:
    if not isinstance(value, str) or not value.strip() or "\x00" in value:
        raise EvaluationAssemblyError("E_SCHEMA", f"{label} must be nonempty")
    return value.strip()


def obj(value: Any, label: str) -> Mapping[str, Any]:
    if not isinstance(value, Mapping):
        raise EvaluationAssemblyError("E_SCHEMA", f"{label} must be an object")
    return value


def safe_relative(value: Any, label: str) -> PurePosixPath:
    raw = text(value, label)
    pure = PurePosixPath(raw)
    if (
        "\\" in raw
        or pure.is_absolute()
        or not pure.parts
        or any(part in {"", ".", ".."} for part in pure.parts)
    ):
        raise EvaluationAssemblyError("E_PATH", f"{label} is unsafe")
    return pure


def resolve_file(project_root: Path, value: Any, label: str) -> tuple[Path, str]:
    pure = safe_relative(value, label)
    root = project_root.resolve()
    current = root
    for part in pure.parts:
        current /= part
        if current.is_symlink():
            raise EvaluationAssemblyError("E_PATH", f"{label} traverses a symlink")
    try:
        resolved = (root / Path(*pure.parts)).resolve(strict=True)
    except FileNotFoundError as exc:
        raise EvaluationAssemblyError("E_RECEIPT_MISSING", f"missing {label}: {pure.as_posix()}") from exc
    except OSError as exc:
        raise EvaluationAssemblyError("E_PATH", f"cannot resolve {label}") from exc
    if (
        (resolved != root and root not in resolved.parents)
        or not resolved.is_file()
        or resolved.is_symlink()
    ):
        raise EvaluationAssemblyError("E_PATH", f"{label} is not a regular project file")
    return resolved, pure.as_posix()


def read_json(path: Path, label: str) -> Any:
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except FileNotFoundError as exc:
        raise EvaluationAssemblyError("E_RECEIPT_MISSING", f"missing {label}: {path}") from exc
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise EvaluationAssemblyError("E_JSON", f"invalid {label}: {path}") from exc


def execute_module():
    path = (
        Path(__file__).resolve().parents[2]
        / "execute-outcome-evaluator/scripts/execute_evaluator.py"
    )
    spec = importlib.util.spec_from_file_location("company_os_assemble_evaluations_runtime", path)
    if spec is None or spec.loader is None:
        raise EvaluationAssemblyError("E_RUNTIME", "execute outcome evaluator runtime cannot be loaded")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def required_evaluators(project_root: Path, fabric: Mapping[str, Any]) -> set[str]:
    control = obj(fabric.get("outcome_control"), "outcome_control")
    path, _ = resolve_file(
        project_root,
        control.get("evaluator_contract_path"),
        "outcome_control.evaluator_contract_path",
    )
    contract = obj(read_json(path, "evaluator contract"), "evaluator contract")
    if contract.get("$schema") != EVALUATOR_SCHEMA:
        raise EvaluationAssemblyError("E_SCHEMA", f"evaluator contract must use {EVALUATOR_SCHEMA}")
    records = contract.get("evaluators")
    if not isinstance(records, list):
        raise EvaluationAssemblyError("E_SCHEMA", "evaluator contract evaluators must be an array")
    required = {
        text(record.get("evaluator_id"), "evaluator_id")
        for record in records
        if isinstance(record, Mapping) and record.get("required") is True
    }
    if not required:
        raise EvaluationAssemblyError("E_EVALUATOR", "evaluator contract has no required evaluators")
    return required


def expected_receipts(fabric: Mapping[str, Any]) -> list[dict[str, str]]:
    managers = fabric.get("managers")
    if not isinstance(managers, list) or not managers:
        raise EvaluationAssemblyError("E_FABRIC", "evaluation fabric has no managers")
    expected = []
    for manager_index, manager_raw in enumerate(managers):
        manager = obj(manager_raw, f"managers[{manager_index}]")
        workers = manager.get("workers")
        if not isinstance(workers, list) or not workers:
            raise EvaluationAssemblyError("E_FABRIC", "evaluation manager has no workers")
        for worker_index, worker_raw in enumerate(workers):
            worker = obj(worker_raw, f"worker[{worker_index}]")
            scopes = worker.get("write_scope")
            if not isinstance(scopes, list) or len(scopes) != 1:
                raise EvaluationAssemblyError("E_SCOPE", "evaluation worker must have exactly one write scope")
            scope = safe_relative(scopes[0], "worker.write_scope").as_posix()
            evaluator_id = worker.get("evaluator_id")
            if not isinstance(evaluator_id, str) or not evaluator_id.strip():
                authority = worker.get("evaluation_authority")
                if isinstance(authority, Mapping):
                    evaluator_id = authority.get("evaluator_id")
            if not isinstance(evaluator_id, str) or not evaluator_id.strip():
                lane_id = worker.get("outcome_loop_lane_id")
                if isinstance(lane_id, str) and lane_id.startswith("evaluator:"):
                    evaluator_id = lane_id.split(":", 1)[1]
            evaluator_id = text(evaluator_id, "evaluation worker evaluator_id")
            expected.append(
                {
                    "evaluator_id": evaluator_id,
                    "worker_id": text(worker.get("id"), "worker.id"),
                    "receipt_path": f"{scope}/execution-receipt.json",
                }
            )
    return sorted(expected, key=lambda item: item["evaluator_id"])


def assemble(
    project_root: Path,
    fabric_raw: Mapping[str, Any],
    candidate_id: str,
    verifier: Callable[[Path, Mapping[str, Any]], Mapping[str, Any]] | None = None,
) -> dict[str, Any]:
    project_root = project_root.resolve()
    fabric = dict(fabric_raw)
    if fabric.get("topology_mode") != FABRIC_MODE:
        raise EvaluationAssemblyError("E_FABRIC", f"fabric must use topology_mode {FABRIC_MODE}")
    loop_binding = obj(fabric.get("outcome_loop"), "outcome_loop")
    if loop_binding.get("phase") != "evaluate":
        raise EvaluationAssemblyError("E_PHASE", "evaluation assembly requires evaluate phase")
    control = obj(fabric.get("outcome_control"), "outcome_control")
    objective_id = text(control.get("objective_id"), "outcome_control.objective_id")
    candidate_id = text(candidate_id, "candidate_id")
    required = required_evaluators(project_root, fabric)
    verify = verifier or execute_module().verify_receipt
    receipt_paths: list[str] = []
    observed: set[str] = set()
    for expected in expected_receipts(fabric):
        path, relative_path = resolve_file(
            project_root,
            expected["receipt_path"],
            f"execution receipt for {expected['evaluator_id']}",
        )
        receipt = obj(read_json(path, "execution receipt"), "execution receipt")
        try:
            verified = dict(verify(project_root, receipt))
        except Exception as exc:
            raise EvaluationAssemblyError(
                getattr(exc, "code", "E_EVALUATOR"),
                f"execution receipt failed verification: {exc}",
            ) from exc
        evaluator_id = text(
            verified.get("evaluator_id", receipt.get("evaluator_id")),
            "verified evaluator_id",
        )
        if evaluator_id != expected["evaluator_id"]:
            raise EvaluationAssemblyError("E_BINDING", "execution receipt evaluator does not match assigned worker")
        if verified.get("objective_id", receipt.get("objective_id")) != objective_id:
            raise EvaluationAssemblyError("E_BINDING", "execution receipt objective does not match fabric")
        if evaluator_id in observed:
            raise EvaluationAssemblyError("E_DUPLICATE", f"duplicate evaluator receipt: {evaluator_id}")
        observed.add(evaluator_id)
        receipt_paths.append(relative_path)
    if observed != required:
        raise EvaluationAssemblyError(
            "E_EVALUATOR",
            f"exact required evaluator set is needed; required={sorted(required)} observed={sorted(observed)}",
        )
    return {
        "$schema": BATCH_SCHEMA,
        "candidate_id": candidate_id,
        "receipt_paths": sorted(receipt_paths),
    }


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--project-root", type=Path, required=True)
    parser.add_argument("--fabric", type=Path, required=True)
    parser.add_argument("--candidate-id", required=True)
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    try:
        fabric = obj(read_json(args.fabric, "fabric"), "fabric")
        batch = assemble(args.project_root, fabric, args.candidate_id)
        args.output.parent.mkdir(parents=True, exist_ok=True)
        args.output.write_text(json.dumps(batch, indent=2, sort_keys=True) + "\n", encoding="utf-8")
        print(
            json.dumps(
                {
                    "ok": True,
                    "candidate_id": batch["candidate_id"],
                    "receipt_count": len(batch["receipt_paths"]),
                },
                sort_keys=True,
            )
        )
        return 0
    except EvaluationAssemblyError as exc:
        print(json.dumps({"ok": False, "code": exc.code, "error": exc.message}, sort_keys=True))
        return 2


if __name__ == "__main__":
    raise SystemExit(main())

