    "workspace_locator",
}


class CatalogError(RuntimeError):
    def __init__(self, code: str, message: str) -> None:
        super().__init__(message)
        self.code = code


def canonical_bytes(value: Any) -> bytes:
    return (
        json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False)
        + "\n"
    ).encode("utf-8")


def canonical_digest(value: Any) -> str:
    return hashlib.sha256(canonical_bytes(value)).hexdigest()


def _object(value: Any, label: str) -> Mapping[str, Any]:
    if not isinstance(value, dict):
        raise CatalogError("E_SCHEMA", f"{label} must be an object")
    return value


def _exact_keys(value: Mapping[str, Any], expected: set[str], label: str) -> None:
    actual = set(value)
    if actual != expected:
        raise CatalogError(
            "E_SCHEMA",
            f"{label} keys differ; missing={sorted(expected - actual)!r}, "
            f"extra={sorted(actual - expected)!r}",
        )


def _id(value: Any, label: str) -> str:
    if not isinstance(value, str) or not ID_RE.fullmatch(value):
        raise CatalogError("E_SCHEMA", f"{label} is not a canonical identifier")
    return value


def _string(value: Any, label: str, *, maximum: int | None = None) -> str:
    if not isinstance(value, str) or not value.strip():
        raise CatalogError("E_SCHEMA", f"{label} must be a nonempty string")
    if maximum is not None and len(value) > maximum:
        raise CatalogError("E_SCHEMA", f"{label} exceeds {maximum} characters")
    return value


def _sorted_unique_strings(
    value: Any,
    label: str,
    *,
    pattern: re.Pattern[str] | None = None,
    allowed: set[str] | None = None,
    nonempty: bool = False,
) -> list[str]:
    if not isinstance(value, list) or (nonempty and not value):
        raise CatalogError("E_SCHEMA", f"{label} must be a{' nonempty' if nonempty else ''} array")
    if not all(isinstance(item, str) and item for item in value):
        raise CatalogError("E_SCHEMA", f"{label} must contain strings")
    if len(value) != len(set(value)) or value != sorted(value):
        raise CatalogError("E_SCHEMA", f"{label} must be unique and sorted")
    if pattern is not None and any(not pattern.fullmatch(item) for item in value):
        raise CatalogError("E_SCHEMA", f"{label} contains a noncanonical value")
    if allowed is not None and any(item not in allowed for item in value):
        raise CatalogError("E_SCHEMA", f"{label} contains an unsupported value")
    return value


def _ordered_unique_strings(
    value: Any,
    label: str,
    *,
    pattern: re.Pattern[str] | None = None,
) -> list[str]:
    if not isinstance(value, list):
        raise CatalogError("E_SCHEMA", f"{label} must be an array")
    if not all(isinstance(item, str) and item for item in value):
        raise CatalogError("E_SCHEMA", f"{label} must contain strings")
    if len(value) != len(set(value)):
        raise CatalogError("E_SCHEMA", f"{label} must be unique")
    if pattern is not None and any(not pattern.fullmatch(item) for item in value):
        raise CatalogError("E_SCHEMA", f"{label} contains a noncanonical value")
    return value


def _read_canonical_json(path: Path, label: str) -> Mapping[str, Any]:
    if path.is_symlink() or not path.is_file():
        raise CatalogError("E_PATH", f"{label} is not a regular non-symlink file")
    raw = path.read_bytes()
    try:
        parsed = json.loads(raw)
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise CatalogError("E_JSON", f"{label} is not valid UTF-8 JSON: {exc}") from exc
    obj = _object(parsed, label)
    if raw != canonical_bytes(obj):
        raise CatalogError("E_CANONICAL", f"{label} is not canonical JSON")
    return obj


def _relative_path(value: Any, label: str, *, required_prefix: str | None = None) -> str:
    text = _string(value, label)
    pure = PurePosixPath(text)
    if pure.is_absolute() or text != pure.as_posix() or any(part in {"", ".", ".."} for part in pure.parts):
        raise CatalogError("E_PATH", f"{label} is not a safe canonical relative path")
    if required_prefix is not None and (not pure.parts or pure.parts[0] != required_prefix):
        raise CatalogError("E_PATH", f"{label} must be beneath {required_prefix!r}")
    return text


def _safe_entrypoint(skill_root: Path, relative: str) -> Path:
    root = skill_root.resolve(strict=True)
    candidate = root / relative
    current = root
    for part in PurePosixPath(relative).parts:
        current = current / part
        if current.is_symlink():
            raise CatalogError("E_PATH", f"entrypoint traverses symlink {relative!r}")
    try:
        resolved = candidate.resolve(strict=True)
    except FileNotFoundError as exc:
        raise CatalogError("E_ENTRYPOINT", f"entrypoint is missing: {relative!r}") from exc
    if resolved.parent != root and root not in resolved.parents:
        raise CatalogError("E_PATH", f"entrypoint escapes the skill root: {relative!r}")
    if not resolved.is_file():
        raise CatalogError("E_ENTRYPOINT", f"entrypoint is not a regular file: {relative!r}")
    return resolved


def _validate_source(value: Any) -> dict[str, Any]:
    source = dict(_object(value, "source"))
    _exact_keys(source, SOURCE_KEYS, "source")
    _id(source["source_id"], "source.source_id")
    url = _string(source["canonical_url"], "source.canonical_url")
    if not url.startswith("https://"):
        raise CatalogError("E_SCHEMA", "source.canonical_url must use https")
    if not HEX40.fullmatch(str(source["source_commit"])) or not HEX40.fullmatch(str(source["source_tree"])):
        raise CatalogError("E_SCHEMA", "source commit and tree must be lowercase 40-hex")
    _string(source["observed_at"], "source.observed_at")
    license_value = dict(_object(source["license"], "source.license"))
    _exact_keys(license_value, LICENSE_KEYS, "source.license")
    spdx = license_value["spdx"]
    if spdx is not None:
        _string(spdx, "source.license.spdx")
    evidence_path = license_value["evidence_path"]
    if evidence_path is not None:
        _relative_path(evidence_path, "source.license.evidence_path")
    if license_value["redistribution"] not in {"allowed", "unknown", "prohibited", "not_applicable"}:
        raise CatalogError("E_SCHEMA", "source.license.redistribution is unsupported")
    if source["disposition"] not in DISPOSITIONS:
        raise CatalogError("E_SCHEMA", "source.disposition is unsupported")
    _sorted_unique_strings(source["risk_flags"], "source.risk_flags", pattern=PERMISSION_RE)
    return source


def _validate_capability(value: Any, sources: Mapping[str, Mapping[str, Any]]) -> dict[str, Any]:
    capability = dict(_object(value, "capability"))
    _exact_keys(capability, CAPABILITY_KEYS, "capability")
    capability_id = _id(capability["capability_id"], "capability.capability_id")
    _string(capability["name"], f"capability {capability_id}.name", maximum=96)
    _string(capability["description"], f"capability {capability_id}.description", maximum=280)
    source_id = _id(capability["source_id"], f"capability {capability_id}.source_id")
    if source_id not in sources:
        raise CatalogError("E_SOURCE", f"capability {capability_id!r} references an unknown source")
    _relative_path(
        capability["upstream_skill_path"],
        f"capability {capability_id}.upstream_skill_path",
    )
    if not isinstance(capability["upstream_entrypoint_sha256"], str) or not HEX64.fullmatch(
        capability["upstream_entrypoint_sha256"]
    ):
        raise CatalogError("E_SCHEMA", f"capability {capability_id!r} upstream digest is invalid")
    if (
        not isinstance(capability["upstream_entrypoint_bytes"], int)
        or isinstance(capability["upstream_entrypoint_bytes"], bool)
        or capability["upstream_entrypoint_bytes"] <= 0
    ):
        raise CatalogError("E_SCHEMA", f"capability {capability_id!r} upstream size is invalid")
    entrypoint = capability["entrypoint"]
    digest = capability["entrypoint_sha256"]
    entrypoint_bytes = capability["entrypoint_bytes"]
    if entrypoint is None:
        if digest is not None or entrypoint_bytes != 0:
            raise CatalogError("E_SCHEMA", f"capability {capability_id!r} has inconsistent empty entrypoint metadata")
    else:
        _relative_path(entrypoint, f"capability {capability_id}.entrypoint", required_prefix="vendor")
        if not isinstance(digest, str) or not HEX64.fullmatch(digest):
            raise CatalogError("E_SCHEMA", f"capability {capability_id!r} entrypoint digest is invalid")
        if not isinstance(entrypoint_bytes, int) or isinstance(entrypoint_bytes, bool) or entrypoint_bytes <= 0:
            raise CatalogError("E_SCHEMA", f"capability {capability_id!r} entrypoint size is invalid")
    roles = _sorted_unique_strings(capability["roles"], f"capability {capability_id}.roles", allowed=ROLES, nonempty=True)
    _sorted_unique_strings(capability["domains"], f"capability {capability_id}.domains", pattern=PERMISSION_RE, nonempty=True)
    _sorted_unique_strings(capability["tags"], f"capability {capability_id}.tags", pattern=PERMISSION_RE, nonempty=True)
    trust = capability["trust_state"]
    if trust not in TRUST_STATES:
        raise CatalogError("E_SCHEMA", f"capability {capability_id!r} trust state is invalid")
    if not isinstance(capability["dispatchable"], bool):
        raise CatalogError("E_SCHEMA", f"capability {capability_id!r} dispatchable must be boolean")
    if capability["load_policy"] != "explicit":
        raise CatalogError("E_POLICY", f"capability {capability_id!r} must use explicit loading")
    _sorted_unique_strings(
        capability["required_permissions"],
        f"capability {capability_id}.required_permissions",
        pattern=PERMISSION_RE,
    )
    _sorted_unique_strings(capability["conflicts"], f"capability {capability_id}.conflicts", pattern=ID_RE)
    if capability_id in capability["conflicts"]:
        raise CatalogError("E_CONFLICT", f"capability {capability_id!r} conflicts with itself")
    if capability["dispatchable"]:
        source = sources[source_id]
        if trust != "approved" or entrypoint is None:
            raise CatalogError("E_TRUST", f"dispatchable capability {capability_id!r} is not approved and materialized")
        if source["disposition"] not in {"vendor_curated_subset", "extract_wrapper"}:
            raise CatalogError("E_TRUST", f"dispatchable capability {capability_id!r} has a blocked source disposition")
        if source["disposition"] == "vendor_curated_subset" and source["license"]["redistribution"] != "allowed":
            raise CatalogError("E_LICENSE", f"vendored capability {capability_id!r} lacks redistribution authority")
    elif trust == "approved" and entrypoint is not None:
        raise CatalogError("E_TRUST", f"approved materialized capability {capability_id!r} must be dispatchable")
    _ = roles
    return capability


def validate_catalog(catalog: Mapping[str, Any], skill_root: Path, *, verify_files: bool = True) -> dict[str, Any]:
    expected = {"$schema", "schema_version", "catalog_id", "policy", "sources", "capabilities"}
    _exact_keys(catalog, expected, "catalog")
    if catalog["$schema"] != CATALOG_SCHEMA or catalog["schema_version"] != 1:
        raise CatalogError("E_SCHEMA", "catalog schema/version is unsupported")
    _id(catalog["catalog_id"], "catalog.catalog_id")
    policy = dict(_object(catalog["policy"], "catalog.policy"))
    _exact_keys(policy, POLICY_KEYS, "catalog.policy")
    for key in POLICY_KEYS:
        value = policy[key]
        if not isinstance(value, int) or isinstance(value, bool) or value <= 0:
            raise CatalogError("E_SCHEMA", f"catalog.policy.{key} must be a positive integer")
    sources_list = catalog["sources"]
    capabilities_list = catalog["capabilities"]
    if not isinstance(sources_list, list) or not isinstance(capabilities_list, list):
        raise CatalogError("E_SCHEMA", "catalog sources and capabilities must be arrays")
    validated_sources = [_validate_source(item) for item in sources_list]
    if [item["source_id"] for item in validated_sources] != sorted(item["source_id"] for item in validated_sources):
        raise CatalogError("E_SCHEMA", "catalog sources must be sorted by source_id")
    sources = {item["source_id"]: item for item in validated_sources}
    if len(sources) != len(validated_sources):
        raise CatalogError("E_SCHEMA", "catalog source IDs must be unique")
    validated_capabilities = [_validate_capability(item, sources) for item in capabilities_list]
    ids = [item["capability_id"] for item in validated_capabilities]
    if ids != sorted(ids) or len(ids) != len(set(ids)):
        raise CatalogError("E_SCHEMA", "catalog capabilities must have unique sorted IDs")
    known_ids = set(ids)
    for capability in validated_capabilities:
        unknown = set(capability["conflicts"]) - known_ids
        if unknown:
            raise CatalogError("E_CONFLICT", f"capability {capability['capability_id']!r} has unknown conflicts {sorted(unknown)!r}")
        if verify_files and capability["entrypoint"] is not None:
            path = _safe_entrypoint(skill_root, capability["entrypoint"])
            raw = path.read_bytes()
            if len(raw) != capability["entrypoint_bytes"]:
                raise CatalogError("E_ENTRYPOINT", f"entrypoint size drift for {capability['capability_id']!r}")
            if hashlib.sha256(raw).hexdigest() != capability["entrypoint_sha256"]:
                raise CatalogError("E_ENTRYPOINT", f"entrypoint digest drift for {capability['capability_id']!r}")
    return {
        "$schema": CATALOG_SCHEMA,
        "catalog_id": catalog["catalog_id"],
        "catalog_sha256": canonical_digest(catalog),
        "source_count": len(validated_sources),
        "capability_count": len(validated_capabilities),
        "dispatchable_count": sum(1 for item in validated_capabilities if item["dispatchable"]),
    }


def validate_request(request: Mapping[str, Any], policy: Mapping[str, Any]) -> dict[str, Any]:
    _exact_keys(request, REQUEST_KEYS, "request")
    if request["$schema"] != REQUEST_SCHEMA:
        raise CatalogError("E_SCHEMA", "request schema is unsupported")
    for key in ("request_id", "program_id", "packet_id"):
        _id(request[key], f"request.{key}")
    if request["role"] not in ROLES:
        raise CatalogError("E_ROLE", "request role is unsupported")
    _sorted_unique_strings(request["domains"], "request.domains", pattern=PERMISSION_RE, nonempty=True)
    _sorted_unique_strings(request["authorized_permissions"], "request.authorized_permissions", pattern=PERMISSION_RE)
    requested = _sorted_unique_strings(
        request["requested_capability_ids"],
        "request.requested_capability_ids",
        pattern=ID_RE,
    )
    execution_order = _ordered_unique_strings(
        request["execution_order"],
        "request.execution_order",
        pattern=ID_RE,
    )
    if set(execution_order) != set(requested):
        raise CatalogError(
            "E_COMPOSITION",
            "execution_order must contain exactly the requested capability IDs",
        )
    rationale = _object(request["selection_rationale"], "request.selection_rationale")
    if set(rationale) != set(requested) or not all(isinstance(value, str) and value.strip() for value in rationale.values()):
        raise CatalogError("E_RATIONALE", "selection rationale must exactly cover requested capabilities")
    for key, policy_key in (
        ("max_skills", "max_skills_per_assignment"),
        ("max_entrypoint_bytes", "max_entrypoint_bytes_per_assignment"),
    ):
        value = request[key]
        if not isinstance(value, int) or isinstance(value, bool) or value <= 0:
            raise CatalogError("E_LIMIT", f"request.{key} must be positive")
        if value > policy[policy_key]:
            raise CatalogError("E_LIMIT", f"request.{key} exceeds catalog policy")
    if len(requested) > request["max_skills"]:
        raise CatalogError("E_LIMIT", "requested capabilities exceed the task-local skill limit")
    return dict(request)


def _assignment_unsigned(value: Mapping[str, Any]) -> dict[str, Any]:
    unsigned = copy.deepcopy(dict(value))
    binding = dict(_object(unsigned.get("binding"), "assignment.binding"))
    binding["canonical_sha256"] = None
    unsigned["binding"] = binding
    return unsigned


def resolve_assignment(catalog: Mapping[str, Any], request: Mapping[str, Any], skill_root: Path) -> dict[str, Any]:
    validate_catalog(catalog, skill_root, verify_files=True)
    policy = _object(catalog["policy"], "catalog.policy")
    request = validate_request(request, policy)
    indexed = {item["capability_id"]: item for item in catalog["capabilities"]}
    selected: list[dict[str, Any]] = []
    selected_ids = set(request["requested_capability_ids"])
    total_bytes = 0
    for capability_id in request["requested_capability_ids"]:
        capability = indexed.get(capability_id)
        if capability is None:
            raise CatalogError("E_CAPABILITY", f"unknown capability {capability_id!r}")
        if not capability["dispatchable"] or capability["trust_state"] != "approved":
            raise CatalogError("E_TRUST", f"capability {capability_id!r} is not dispatchable")
        if request["role"] not in capability["roles"]:
            raise CatalogError("E_ROLE", f"capability {capability_id!r} is not allowed for role {request['role']!r}")
        if not set(request["domains"]).intersection(capability["domains"]):
            raise CatalogError("E_DOMAIN", f"capability {capability_id!r} does not match the task domains")
        missing_permissions = set(capability["required_permissions"]) - set(request["authorized_permissions"])
        if missing_permissions:
            raise CatalogError("E_PERMISSION", f"capability {capability_id!r} would widen permissions {sorted(missing_permissions)!r}")
        conflicts = set(capability["conflicts"]).intersection(selected_ids)
        if conflicts:
            raise CatalogError("E_CONFLICT", f"capability {capability_id!r} conflicts with {sorted(conflicts)!r}")
        path = _safe_entrypoint(skill_root, capability["entrypoint"])
        raw = path.read_bytes()
        if hashlib.sha256(raw).hexdigest() != capability["entrypoint_sha256"] or len(raw) != capability["entrypoint_bytes"]:
            raise CatalogError("E_ENTRYPOINT", f"entrypoint drift for {capability_id!r}")
        total_bytes += capability["entrypoint_bytes"]
        source = next(item for item in catalog["sources"] if item["source_id"] == capability["source_id"])
        selected.append(
            {
                "capability_id": capability_id,
                "entrypoint": capability["entrypoint"],
                "entrypoint_bytes": capability["entrypoint_bytes"],
                "entrypoint_sha256": capability["entrypoint_sha256"],
                "required_permissions": copy.deepcopy(capability["required_permissions"]),
                "selection_rationale": request["selection_rationale"][capability_id],
                "source_commit": source["source_commit"],
                "source_id": capability["source_id"],
                "upstream_entrypoint_bytes": capability["upstream_entrypoint_bytes"],
                "upstream_entrypoint_sha256": capability["upstream_entrypoint_sha256"],
                "upstream_skill_path": capability["upstream_skill_path"],
                "workspace_locator": (
                    "workspace://skills/company-os/assign-capability-skills/"
                    + PurePosixPath(capability["entrypoint"]).parent.as_posix()
                ),
            }
        )
    if total_bytes > request["max_entrypoint_bytes"]:
        raise CatalogError("E_LIMIT", "selected entrypoints exceed the task-local byte limit")
    assignment = {
        "$schema": ASSIGNMENT_SCHEMA,
        "schema_version": 1,
        "assignment_id": request["request_id"],
        "program_id": request["program_id"],
        "packet_id": request["packet_id"],
        "role": request["role"],
        "domains": copy.deepcopy(request["domains"]),
        "execution_order": copy.deepcopy(request["execution_order"]),
        "catalog_sha256": canonical_digest(catalog),
        "request_sha256": canonical_digest(request),
        "skill_count": len(selected),
        "total_entrypoint_bytes": total_bytes,
        "skills": selected,
        "binding": {"algorithm": BINDING_ALGORITHM, "canonical_sha256": None},
    }
    assignment["binding"]["canonical_sha256"] = canonical_digest(_assignment_unsigned(assignment))
    return assignment


def validate_assignment(assignment: Mapping[str, Any]) -> None:
    expected = {
        "$schema",
        "schema_version",
        "assignment_id",
        "program_id",
        "packet_id",
        "role",
        "domains",
        "execution_order",
        "catalog_sha256",
        "request_sha256",
        "skill_count",
        "total_entrypoint_bytes",
        "skills",
        "binding",
    }
    _exact_keys(assignment, expected, "assignment")
    if assignment["$schema"] != ASSIGNMENT_SCHEMA or assignment["schema_version"] != 1:
        raise CatalogError("E_SCHEMA", "assignment schema/version is unsupported")
    for key in ("assignment_id", "program_id", "packet_id"):
        _id(assignment[key], f"assignment.{key}")
    if assignment["role"] not in ROLES:
        raise CatalogError("E_ROLE", "assignment role is unsupported")
    _sorted_unique_strings(assignment["domains"], "assignment.domains", pattern=PERMISSION_RE, nonempty=True)
    execution_order = _ordered_unique_strings(
        assignment["execution_order"],
        "assignment.execution_order",
        pattern=ID_RE,
    )
    for key in ("catalog_sha256", "request_sha256"):
        if not isinstance(assignment[key], str) or not HEX64.fullmatch(assignment[key]):
            raise CatalogError("E_SCHEMA", f"assignment.{key} is invalid")
    if not isinstance(assignment["skills"], list):
        raise CatalogError("E_SCHEMA", "assignment.skills must be an array")
    if not isinstance(assignment["skill_count"], int) or isinstance(assignment["skill_count"], bool) or assignment["skill_count"] < 0:
        raise CatalogError("E_SCHEMA", "assignment skill_count must be a nonnegative integer")
    if not isinstance(assignment["total_entrypoint_bytes"], int) or isinstance(assignment["total_entrypoint_bytes"], bool) or assignment["total_entrypoint_bytes"] < 0:
        raise CatalogError("E_SCHEMA", "assignment total_entrypoint_bytes must be a nonnegative integer")
    skill_ids: list[str] = []
    for index, raw_skill in enumerate(assignment["skills"]):
        skill = dict(_object(raw_skill, f"assignment.skills[{index}]"))
        _exact_keys(skill, ASSIGNMENT_SKILL_KEYS, f"assignment.skills[{index}]")
        capability_id = _id(skill["capability_id"], f"assignment.skills[{index}].capability_id")
        skill_ids.append(capability_id)
        entrypoint = _relative_path(
            skill["entrypoint"],
            f"assignment.skills[{index}].entrypoint",
            required_prefix="vendor",
        )
        if not isinstance(skill["entrypoint_bytes"], int) or isinstance(skill["entrypoint_bytes"], bool) or skill["entrypoint_bytes"] <= 0:
            raise CatalogError("E_SCHEMA", f"assignment skill {capability_id!r} has invalid entrypoint bytes")
        if not isinstance(skill["upstream_entrypoint_bytes"], int) or isinstance(skill["upstream_entrypoint_bytes"], bool) or skill["upstream_entrypoint_bytes"] <= 0:
            raise CatalogError("E_SCHEMA", f"assignment skill {capability_id!r} has invalid upstream bytes")
        for key in ("entrypoint_sha256", "upstream_entrypoint_sha256"):
            if not isinstance(skill[key], str) or not HEX64.fullmatch(skill[key]):
                raise CatalogError("E_SCHEMA", f"assignment skill {capability_id!r} has invalid {key}")
        if not isinstance(skill["source_commit"], str) or not HEX40.fullmatch(skill["source_commit"]):
            raise CatalogError("E_SCHEMA", f"assignment skill {capability_id!r} has invalid source commit")
        _id(skill["source_id"], f"assignment.skills[{index}].source_id")
        _relative_path(skill["upstream_skill_path"], f"assignment.skills[{index}].upstream_skill_path")
        _string(skill["selection_rationale"], f"assignment.skills[{index}].selection_rationale")
        _sorted_unique_strings(
            skill["required_permissions"],
            f"assignment.skills[{index}].required_permissions",
            pattern=PERMISSION_RE,
        )
        expected_locator = (
            "workspace://skills/company-os/assign-capability-skills/"
            + PurePosixPath(entrypoint).parent.as_posix()
        )
        if skill["workspace_locator"] != expected_locator:
            raise CatalogError("E_PATH", f"assignment skill {capability_id!r} workspace locator is not bound to its entrypoint")
    if skill_ids != sorted(skill_ids) or len(skill_ids) != len(set(skill_ids)):
        raise CatalogError("E_SCHEMA", "assignment skills must have unique sorted capability IDs")
    if set(execution_order) != set(skill_ids):
        raise CatalogError(
            "E_COMPOSITION",
            "assignment execution_order must contain exactly the assigned capability IDs",
        )
    if assignment["skill_count"] != len(assignment["skills"]):
        raise CatalogError("E_SCHEMA", "assignment skill_count does not match skills")
    if assignment["total_entrypoint_bytes"] != sum(item.get("entrypoint_bytes", -1) for item in assignment["skills"]):
        raise CatalogError("E_SCHEMA", "assignment total_entrypoint_bytes does not match skills")
    binding = _object(assignment["binding"], "assignment.binding")
    _exact_keys(binding, {"algorithm", "canonical_sha256"}, "assignment.binding")
    if binding["algorithm"] != BINDING_ALGORITHM or not isinstance(binding["canonical_sha256"], str) or not HEX64.fullmatch(binding["canonical_sha256"]):
        raise CatalogError("E_BINDING", "assignment binding is invalid")
    if binding["canonical_sha256"] != canonical_digest(_assignment_unsigned(assignment)):
        raise CatalogError("E_BINDING", "assignment canonical digest does not verify")


def augment_host_manifest(
    catalog: Mapping[str, Any],
    base_host: Mapping[str, Any],
    request_assignment_pairs: Sequence[tuple[Mapping[str, Any], Mapping[str, Any]]],
    skill_root: Path,
) -> dict[str, Any]:
    """Bind verified task-local skill assignments into a host manifest.

    The result contains references and digests only. Skill bodies remain lazy
    loaded from their exact workspace entrypoints by the assigned task.
    """

    evidence = validate_catalog(catalog, skill_root, verify_files=True)
    host = copy.deepcopy(dict(_object(base_host, "base host manifest")))
    if host.get("$id") != "company-os.host-capabilities.v1" or host.get("schema_version") != 1:
        raise CatalogError("E_HOST", "base host manifest schema/version is unsupported")
    program_id = _id(host.get("program_id"), "base host manifest.program_id")
    if not isinstance(host.get("runtimes"), list) or not isinstance(host.get("capabilities"), list):
        raise CatalogError("E_HOST", "base host manifest runtimes and capabilities must be arrays")
    if "skill_assignments" in host or any(
        isinstance(item, dict) and item.get("capability_kind") == "skill"
        for item in host["capabilities"]
    ):
        raise CatalogError(
            "E_HOST",
            "base host manifest already contains skill state; rebuild all assignments in one augmentation",
        )

    indexed_catalog = {item["capability_id"]: item for item in catalog["capabilities"]}
    runtimes = {item.get("runtime_id"): copy.deepcopy(item) for item in host["runtimes"] if isinstance(item, dict)}
    if len(runtimes) != len(host["runtimes"]) or None in runtimes:
        raise CatalogError("E_HOST", "base host manifest runtime IDs must be present and unique")
    capabilities = {
        item.get("capability_id"): copy.deepcopy(item)
        for item in host["capabilities"]
        if isinstance(item, dict)
    }
    if len(capabilities) != len(host["capabilities"]) or None in capabilities:
        raise CatalogError("E_HOST", "base host manifest capability IDs must be present and unique")

    selected_any = False
    assignment_records: list[dict[str, Any]] = []
    bound_packet_ids: set[str] = set()
    bound_packet_capabilities: set[tuple[str, str, str]] = set()
    for request, assignment in request_assignment_pairs:
        expected = resolve_assignment(catalog, request, skill_root)
        validate_assignment(assignment)
        if canonical_bytes(assignment) != canonical_bytes(expected):
            raise CatalogError("E_ASSIGNMENT_DRIFT", "assignment does not reproduce from its catalog and request")
        if assignment["program_id"] != program_id:
            raise CatalogError("E_HOST", "assignment program_id does not match the base host manifest")
        if assignment["packet_id"] in bound_packet_ids:
            raise CatalogError(
                "E_HOST",
                f"packet {assignment['packet_id']!r} has more than one capability assignment",
            )
        bound_packet_ids.add(assignment["packet_id"])
        if assignment["skills"]:
            assignment_records.append(
                {
                    "assignment": copy.deepcopy(dict(assignment)),
                    "request": copy.deepcopy(dict(request)),
                }
            )
        for skill in assignment["skills"]:
            selected_any = True
            capability_id = skill["capability_id"]
            identity = (assignment["packet_id"], assignment["role"], capability_id)
            if identity in bound_packet_capabilities:
                raise CatalogError("E_HOST", f"duplicate skill binding for packet capability {identity!r}")
            bound_packet_capabilities.add(identity)
            catalog_capability = indexed_catalog[capability_id]
            binding = {
                "assignment_id": assignment["assignment_id"],
                "assignment_sha256": assignment["binding"]["canonical_sha256"],
                "catalog_sha256": evidence["catalog_sha256"],
                "entrypoint_sha256": skill["entrypoint_sha256"],
                "packet_id": assignment["packet_id"],
                "request_sha256": assignment["request_sha256"],
                "role": assignment["role"],
                "source_commit": skill["source_commit"],
                "source_id": skill["source_id"],
                "upstream_entrypoint_sha256": skill["upstream_entrypoint_sha256"],
            }
            expected_capability = {
                "capability_id": capability_id,
                "available": True,
                "runtime_id": SKILL_RUNTIME_ID,
                "tool_locator": skill["workspace_locator"],
                "runtime_locator": SKILL_RUNTIME_LOCATOR,
                "capability_kind": "skill",
                "artifact_sha256": skill["entrypoint_sha256"],
                "skill_bindings": [binding],
            }
            current = capabilities.get(capability_id)
            if current is None:
                capabilities[capability_id] = expected_capability
                continue
            stable_keys = set(expected_capability) - {"skill_bindings"}
            if any(current.get(key) != expected_capability[key] for key in stable_keys):
                raise CatalogError("E_HOST", f"host capability {capability_id!r} conflicts with the assignment")
            bindings = current.get("skill_bindings")
            if not isinstance(bindings, list):
                raise CatalogError("E_HOST", f"host capability {capability_id!r} is not a skill capability")
            bindings.append(binding)
            current["skill_bindings"] = sorted(
                bindings,
                key=lambda item: (item["packet_id"], item["role"], item["assignment_id"]),
            )

    if not selected_any:
        return host

    required_runtime = {
        "runtime_id": SKILL_RUNTIME_ID,
        "runtime_type": SKILL_RUNTIME_TYPE,
        "available": True,
        "locator": SKILL_RUNTIME_LOCATOR,
    }
    existing_runtime = runtimes.get(SKILL_RUNTIME_ID)
    if existing_runtime is not None and existing_runtime != required_runtime:
        raise CatalogError("E_HOST", "the reserved skill runtime ID conflicts with the base host manifest")
    runtimes[SKILL_RUNTIME_ID] = required_runtime
    host["runtimes"] = sorted(runtimes.values(), key=lambda item: item["runtime_id"])
    host["capabilities"] = sorted(capabilities.values(), key=lambda item: item["capability_id"])
    host["skill_assignments"] = sorted(
        assignment_records,
        key=lambda item: item["assignment"]["assignment_id"],
    )
    return host


def search_catalog(
    catalog: Mapping[str, Any],
    query: str,
    *,
    role: str | None,
    domain: str | None,
    limit: int,
    dispatchable_only: bool = False,
) -> dict[str, Any]:
    tokens = set(TOKEN_RE.findall(query.lower()))
    if not tokens:
        raise CatalogError("E_QUERY", "search query must contain a word or number")
    if role is not None and role not in ROLES:
        raise CatalogError("E_ROLE", "search role is unsupported")
    maximum = catalog["policy"]["max_search_results"]
    if limit <= 0 or limit > maximum:
        raise CatalogError("E_LIMIT", f"search limit must be between 1 and {maximum}")
    matches: list[tuple[int, str, Mapping[str, Any]]] = []
    for capability in catalog["capabilities"]:
        if dispatchable_only and not capability["dispatchable"]:
            continue
        if role is not None and role not in capability["roles"]:
            continue
        if domain is not None and domain not in capability["domains"]:
            continue
        fields = {
            "id": set(TOKEN_RE.findall(capability["capability_id"].lower())),
            "name": set(TOKEN_RE.findall(capability["name"].lower())),
            "description": set(TOKEN_RE.findall(capability["description"].lower())),
            "tags": set(capability["tags"]),
            "domains": set(capability["domains"]),
        }
        score = (
            8 * len(tokens & fields["id"])
            + 6 * len(tokens & fields["name"])
            + 4 * len(tokens & fields["tags"])
            + 3 * len(tokens & fields["domains"])
            + len(tokens & fields["description"])
        )
        if score:
            matches.append((score, capability["capability_id"], capability))
    matches.sort(key=lambda item: (-item[0], item[1]))
    return {
        "$schema": "company-os.capability-search-results.v1",
        "catalog_sha256": canonical_digest(catalog),
        "query": query,
        "role": role,
        "domain": domain,
        "dispatchable_only": dispatchable_only,
        "results": [
            {
                "capability_id": capability["capability_id"],
                "description": capability["description"],
                "dispatchable": capability["dispatchable"],
                "domains": capability["domains"],
                "name": capability["name"],
                "roles": capability["roles"],
                "score": score,
                "source_id": capability["source_id"],
                "trust_state": capability["trust_state"],
            }
            for score, _, capability in matches[:limit]
        ],
    }


def _write_atomic(path: Path, value: Mapping[str, Any]) -> None:
    if path.exists() and path.is_symlink():
        raise CatalogError("E_PATH", "output path may not be a symlink")
    path.parent.mkdir(parents=True, exist_ok=True)
    data = canonical_bytes(value)
    descriptor, temporary_name = tempfile.mkstemp(prefix=f".{path.name}.", dir=path.parent)
    temporary = Path(temporary_name)
    try:
        with os.fdopen(descriptor, "wb") as handle:
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, path)
        directory_fd = os.open(path.parent, os.O_RDONLY)
        try:
            os.fsync(directory_fd)
        finally:
            os.close(directory_fd)
    finally:
        if temporary.exists():
            temporary.unlink()


def _print(value: Mapping[str, Any]) -> None:
    print(canonical_bytes(value).decode("utf-8"), end="")


def _parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(description=__doc__)
    sub = parser.add_subparsers(dest="command", required=True)
    validate = sub.add_parser("validate")
    validate.add_argument("--catalog", type=Path, required=True)
    validate.add_argument("--skill-root", type=Path, required=True)
    search = sub.add_parser("search")
    search.add_argument("--catalog", type=Path, required=True)
    search.add_argument("--skill-root", type=Path, required=True)
    search.add_argument("--query", required=True)
    search.add_argument("--role", choices=sorted(ROLES))
    search.add_argument("--domain")
    search.add_argument("--limit", type=int, default=5)
    search.add_argument("--dispatchable-only", action="store_true")
    resolve = sub.add_parser("resolve")
    resolve.add_argument("--catalog", type=Path, required=True)
    resolve.add_argument("--request", type=Path, required=True)
    resolve.add_argument("--skill-root", type=Path, required=True)
    resolve.add_argument("--output", type=Path, required=True)
    verify = sub.add_parser("verify")
    verify.add_argument("--catalog", type=Path, required=True)
    verify.add_argument("--request", type=Path, required=True)
    verify.add_argument("--assignment", type=Path, required=True)
    verify.add_argument("--skill-root", type=Path, required=True)
    augment = sub.add_parser("augment-host")
    augment.add_argument("--catalog", type=Path, required=True)
    augment.add_argument("--skill-root", type=Path, required=True)
    augment.add_argument("--base-host", type=Path, required=True)
    augment.add_argument("--request", type=Path, action="append", required=True)
    augment.add_argument("--assignment", type=Path, action="append", required=True)
    augment.add_argument("--output", type=Path, required=True)
    return parser


def main(argv: Sequence[str] | None = None) -> int:
    args = _parser().parse_args(argv)
    try:
        catalog = _read_canonical_json(args.catalog, "catalog")
        evidence = validate_catalog(catalog, args.skill_root, verify_files=True)
        if args.command == "validate":
            _print({"ok": True, **evidence})
            return 0
        if args.command == "search":
            _print(
                search_catalog(
                    catalog,
                    args.query,
                    role=args.role,
                    domain=args.domain,
                    limit=args.limit,
                    dispatchable_only=args.dispatchable_only,
                )
            )
            return 0
        if args.command == "augment-host":
            if len(args.request) != len(args.assignment):
                raise CatalogError("E_SCHEMA", "augment-host requires one assignment for each request")
            base_host = _read_canonical_json(args.base_host, "base host manifest")
            pairs = [
                (
                    _read_canonical_json(request_path, f"request[{index}]"),
                    _read_canonical_json(assignment_path, f"assignment[{index}]"),
                )
                for index, (request_path, assignment_path) in enumerate(zip(args.request, args.assignment))
            ]
            augmented = augment_host_manifest(catalog, base_host, pairs, args.skill_root)
            _write_atomic(args.output, augmented)
            _print(
                {
                    "ok": True,
                    "host_manifest": args.output.as_posix(),
                    "host_manifest_sha256": canonical_digest(augmented),
                    "assignment_count": len(pairs),
                    "skill_capability_count": sum(
                        1 for item in augmented["capabilities"] if item.get("capability_kind") == "skill"
                    ),
                }
            )
            return 0
        request = _read_canonical_json(args.request, "request")
        expected = resolve_assignment(catalog, request, args.skill_root)
        if args.command == "resolve":
            _write_atomic(args.output, expected)
            _print(
                {
                    "ok": True,
                    "assignment": args.output.as_posix(),
                    "assignment_sha256": expected["binding"]["canonical_sha256"],
                    "skill_count": expected["skill_count"],
                    "total_entrypoint_bytes": expected["total_entrypoint_bytes"],
                }
            )
            return 0
        assignment = _read_canonical_json(args.assignment, "assignment")
        validate_assignment(assignment)
        if canonical_bytes(assignment) != canonical_bytes(expected):
            raise CatalogError("E_ASSIGNMENT_DRIFT", "assignment does not reproduce from catalog and request")
        _print(
            {
                "ok": True,
                "assignment_sha256": assignment["binding"]["canonical_sha256"],
                "catalog_sha256": assignment["catalog_sha256"],
                "request_sha256": assignment["request_sha256"],
            }
        )
        return 0
    except CatalogError as exc:
        _print({"ok": False, "error": {"code": exc.code, "message": str(exc)}})
        return 1


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Join outcome understanding contracts into one deterministic scale authorization."""

from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path
from typing import Any, Mapping, Sequence

OUTCOME_SCHEMA = "company-os.outcome-contract.v1"
ARTIFACT_SCHEMA = "company-os.artifact-observation-contract.v1"
EVALUATOR_SCHEMA = "company-os.evaluator-runtime-contract.v1"
BENCHMARK_SCHEMA = "company-os.benchmark-contract.v1"
CALIBRATION_SCHEMA = "company-os.evaluator-calibration-receipt.v1"
AUTH_SCHEMA = "company-os.outcome-scale-authorization.v1"


class ScaleAuthorizationError(ValueError):
    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(f"{code}: {message}")


def canonical_bytes(value: Any) -> bytes:
    return json.dumps(
        value,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
        allow_nan=False,
    ).encode("utf-8")


def digest(value: Any) -> str:
    return hashlib.sha256(canonical_bytes(value)).hexdigest()


def read_json(path: Path) -> Any:
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except OSError as exc:
        raise ScaleAuthorizationError("E_READ", f"cannot read {path}: {exc}") from exc
    except json.JSONDecodeError as exc:
        raise ScaleAuthorizationError("E_JSON", f"invalid JSON at {path}: {exc}") from exc


def require_object(value: Any, label: str) -> Mapping[str, Any]:
    if not isinstance(value, Mapping):
        raise ScaleAuthorizationError("E_SCHEMA", f"{label} must be an object")
    return value


def require_schema(value: Mapping[str, Any], expected: str, label: str) -> None:
    if value.get("$schema") != expected:
        raise ScaleAuthorizationError(
            "E_SCHEMA", f"{label} $schema must equal {expected!r}"
        )


def objective_id(value: Mapping[str, Any], label: str) -> str:
    current = value.get("objective_id")
    if not isinstance(current, str) or not current.strip():
        raise ScaleAuthorizationError("E_SCHEMA", f"{label}.objective_id must be nonempty")
    return current


def string_set(value: Any, label: str) -> set[str]:
    if value is None:
        return set()
    if not isinstance(value, list) or not all(isinstance(item, str) and item for item in value):
        raise ScaleAuthorizationError("E_SCHEMA", f"{label} must be an array of nonempty strings")
    if len(value) != len(set(value)):
        raise ScaleAuthorizationError("E_DUPLICATE", f"{label} contains duplicates")
    return set(value)


def authorize(
    outcome: Mapping[str, Any],
    artifacts: Mapping[str, Any],
    evaluators: Mapping[str, Any],
    benchmarks: Mapping[str, Any],
    calibrations: Sequence[Mapping[str, Any]],
) -> dict[str, Any]:
    require_schema(outcome, OUTCOME_SCHEMA, "outcome")
    require_schema(artifacts, ARTIFACT_SCHEMA, "artifacts")
    require_schema(evaluators, EVALUATOR_SCHEMA, "evaluators")
    require_schema(benchmarks, BENCHMARK_SCHEMA, "benchmarks")

    expected_objective = objective_id(outcome, "outcome")
    bound_objectives = {
        "outcome": expected_objective,
        "artifacts": objective_id(artifacts, "artifacts"),
        "evaluators": objective_id(evaluators, "evaluators"),
        "benchmarks": objective_id(benchmarks, "benchmarks"),
    }
    mismatched = sorted(
        label for label, value in bound_objectives.items() if value != expected_objective
    )
    if mismatched:
        raise ScaleAuthorizationError(
            "E_OBJECTIVE_BINDING",
            f"objective mismatch in: {', '.join(mismatched)}",
        )

    blockers: list[dict[str, Any]] = []

    if outcome.get("scale_allowed") is not True:
        blockers.append({"code": "OUTCOME_NOT_SCALE_READY", "detail": "outcome"})
    if artifacts.get("ready") is not True:
        blockers.append({"code": "ARTIFACTS_NOT_READY", "detail": "artifacts"})
    if evaluators.get("ready") is not True:
        blockers.append({"code": "EVALUATORS_NOT_READY", "detail": "evaluators"})
    if benchmarks.get("ready") is not True:
        blockers.append({"code": "BENCHMARKS_NOT_READY", "detail": "benchmarks"})

    artifact_records = artifacts.get("artifact_classes")
    if not isinstance(artifact_records, list):
        raise ScaleAuthorizationError("E_SCHEMA", "artifact_classes must be an array")
    required_artifacts: set[str] = set()
    required_evidence_by_artifact: dict[str, set[str]] = {}
    for index, item in enumerate(artifact_records):
        if not isinstance(item, Mapping):
            raise ScaleAuthorizationError("E_SCHEMA", f"artifact_classes[{index}] must be an object")
        artifact_id = item.get("artifact_class_id")
        if not isinstance(artifact_id, str) or not artifact_id:
            raise ScaleAuthorizationError("E_SCHEMA", f"artifact_classes[{index}].artifact_class_id invalid")
        if item.get("required") is True:
            required_artifacts.add(artifact_id)
            required_evidence_by_artifact[artifact_id] = string_set(
                item.get("required_evidence", []),
                f"artifact {artifact_id}.required_evidence",
            )

    evaluator_records = evaluators.get("evaluators")
    if not isinstance(evaluator_records, list):
        raise ScaleAuthorizationError("E_SCHEMA", "evaluators.evaluators must be an array")
    required_evaluators: dict[str, set[str]] = {}
    artifact_coverage: set[str] = set()
    evidence_coverage_by_artifact: dict[str, set[str]] = {}
    for item in evaluator_records:
        if not isinstance(item, Mapping):
            raise ScaleAuthorizationError("E_SCHEMA", "evaluator record must be an object")
        evaluator_id = item.get("evaluator_id")
        if not isinstance(evaluator_id, str) or not evaluator_id:
            raise ScaleAuthorizationError("E_SCHEMA", "evaluator_id must be nonempty")
        covered = item.get("artifact_classes")
        if not isinstance(covered, list) or not all(isinstance(x, str) and x for x in covered):
            raise ScaleAuthorizationError("E_SCHEMA", f"{evaluator_id}.artifact_classes invalid")
        produces_evidence = string_set(
            item.get("produces_evidence", []),
            f"{evaluator_id}.produces_evidence",
        )
        if item.get("required") is True:
            required_evaluators[evaluator_id] = set(covered)
            artifact_coverage.update(covered)
            for artifact_id in covered:
                evidence_coverage_by_artifact.setdefault(artifact_id, set()).update(produces_evidence)

    uncovered = sorted(required_artifacts - artifact_coverage)
    for artifact_id in uncovered:
        blockers.append({"code": "ARTIFACT_WITHOUT_EVALUATOR", "detail": artifact_id})

    for artifact_id in sorted(required_artifacts):
        required_evidence = required_evidence_by_artifact.get(artifact_id, set())
        observed_coverage = evidence_coverage_by_artifact.get(artifact_id, set())
        missing_evidence = sorted(required_evidence - observed_coverage)
        if missing_evidence:
            blockers.append(
                {
                    "code": "ARTIFACT_OBSERVATION_EVIDENCE_UNCOVERED",
                    "detail": f"{artifact_id}:{','.join(missing_evidence)}",
                }
            )

    calibration_by_evaluator: dict[str, Mapping[str, Any]] = {}
    for receipt in calibrations:
        if not isinstance(receipt, Mapping):
            raise ScaleAuthorizationError("E_SCHEMA", "calibration receipt must be an object")
        require_schema(receipt, CALIBRATION_SCHEMA, "calibration")
        evaluator_id = receipt.get("evaluator_id")
        if not isinstance(evaluator_id, str) or not evaluator_id:
            raise ScaleAuthorizationError("E_SCHEMA", "calibration evaluator_id invalid")
        if evaluator_id in calibration_by_evaluator:
            raise ScaleAuthorizationError(
                "E_DUPLICATE", f"duplicate calibration receipt for {evaluator_id}"
            )
        calibration_by_evaluator[evaluator_id] = receipt

    for evaluator_id in sorted(required_evaluators):
        receipt = calibration_by_evaluator.get(evaluator_id)
        if receipt is None:
            blockers.append({"code": "EVALUATOR_UNCALIBRATED", "detail": evaluator_id})
        elif receipt.get("passed") is not True:
            blockers.append({"code": "EVALUATOR_CALIBRATION_FAILED", "detail": evaluator_id})

    blockers = sorted(blockers, key=lambda item: (item["code"], item["detail"]))
    authorized = not blockers

    result: dict[str, Any] = {
        "$schema": AUTH_SCHEMA,
        "schema_version": 1,
        "objective_id": expected_objective,
        "authorized": authorized,
        "blockers": blockers,
        "required_artifact_classes": sorted(required_artifacts),
        "required_evaluator_ids": sorted(required_evaluators),
        "required_observation_evidence": {
            artifact_id: sorted(required_evidence_by_artifact.get(artifact_id, set()))
            for artifact_id in sorted(required_artifacts)
        },
        "input_bindings": {
            "outcome_sha256": digest(outcome),
            "artifacts_sha256": digest(artifacts),
            "evaluators_sha256": digest(evaluators),
            "benchmarks_sha256": digest(benchmarks),
            "calibrations_sha256": digest(
                sorted(
                    [dict(item) for item in calibrations],
                    key=lambda item: str(item.get("evaluator_id", "")),
                )
            ),
        },
    }
    result["authorization_sha256"] = digest(
        {**result, "authorization_sha256": None}
    )
    return result


def main() -> None:
    parser = argparse.ArgumentParser()
    sub = parser.add_subparsers(dest="command", required=True)
    authorize_parser = sub.add_parser("authorize")
    authorize_parser.add_argument("--outcome", required=True, type=Path)
    authorize_parser.add_argument("--artifacts", required=True, type=Path)
    authorize_parser.add_argument("--evaluators", required=True, type=Path)
    authorize_parser.add_argument("--benchmarks", required=True, type=Path)
    authorize_parser.add_argument("--calibrations", required=True, type=Path)
    authorize_parser.add_argument("--output", required=True, type=Path)
    args = parser.parse_args()

    calibrations_raw = read_json(args.calibrations)
    if not isinstance(calibrations_raw, list):
        raise ScaleAuthorizationError("E_SCHEMA", "calibrations file must be an array")
    receipt = authorize(
        require_object(read_json(args.outcome), "outcome"),
        require_object(read_json(args.artifacts), "artifacts"),
        require_object(read_json(args.evaluators), "evaluators"),
        require_object(read_json(args.benchmarks), "benchmarks"),
        calibrations_raw,
    )
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(json.dumps(receipt, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    print(
        f"outcome scale authorized={receipt['authorized']} "
        f"blockers={len(receipt['blockers'])}"
    )


if __name__ == "__main__":
    main()

{
  "$schema": "company-os.evaluator-calibration.v2",
  "objective_id": "viral-game",
  "evaluator_id": "gameplay",
  "required_dimensions": [
    "fun",
    "polish"
  ],
  "candidates": [
    {
      "candidate_id": "negative",
      "expected_rank": 1,
      "execution_receipt_path": "evidence/evaluator/negative.json"
    },
    {
      "candidate_id": "intermediate",
      "expected_rank": 2,
      "execution_receipt_path": "evidence/evaluator/intermediate.json"
    },
    {
      "candidate_id": "exemplar",
      "expected_rank": 3,
      "execution_receipt_path": "evidence/evaluator/exemplar.json"
    }
  ]
}

#!/usr/bin/env python3
"""Calibrate an outcome evaluator from verified execution receipts."""

from __future__ import annotations

import argparse
import hashlib
import importlib.util
import json
import math
from pathlib import Path, PurePosixPath
from typing import Any, Mapping

REQUEST_SCHEMA = "company-os.evaluator-calibration.v2"
RECEIPT_SCHEMA = "company-os.evaluator-calibration-receipt.v1"


class CalibrationError(ValueError):
    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(f"{code}: {message}")


def canonical_bytes(value: Any) -> bytes:
    try:
        return json.dumps(
            value,
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=False,
            allow_nan=False,
        ).encode("utf-8")
    except (TypeError, ValueError) as exc:
        raise CalibrationError("E_CANONICAL", f"value is not canonical JSON: {exc}") from exc


def digest(value: Any) -> str:
    return hashlib.sha256(canonical_bytes(value)).hexdigest()


def file_digest(path: Path) -> str:
    value = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            value.update(chunk)
    return value.hexdigest()


def _reject_constant(value: str) -> None:
    raise CalibrationError("E_JSON", f"non finite JSON value is forbidden: {value}")


def _object(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
    result: dict[str, Any] = {}
    for key, value in pairs:
        if key in result:
            raise CalibrationError("E_JSON", f"duplicate JSON key is forbidden: {key}")
        result[key] = value
    return result


def read_json(path: Path, label: str) -> Any:
    try:
        return json.loads(
            path.read_text(encoding="utf-8"),
            object_pairs_hook=_object,
            parse_constant=_reject_constant,
        )
    except CalibrationError:
        raise
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise CalibrationError("E_JSON", f"invalid JSON in {label}: {path}") from exc


def require_object(value: Any, label: str) -> Mapping[str, Any]:
    if not isinstance(value, Mapping):
        raise CalibrationError("E_SCHEMA", f"{label} must be an object")
    return value


def require_text(value: Any, label: str) -> str:
    if not isinstance(value, str) or not value.strip() or "\x00" in value:
        raise CalibrationError("E_SCHEMA", f"{label} must be a nonempty string")
    return value


def require_sha256(value: Any, label: str) -> str:
    text = require_text(value, label)
    if len(text) != 64 or any(character not in "0123456789abcdef" for character in text):
        raise CalibrationError("E_SCHEMA", f"{label} must be a lowercase sha256")
    return text


def require_dimensions(value: Any) -> list[str]:
    if not isinstance(value, list) or not value:
        raise CalibrationError("E_SCHEMA", "required_dimensions must be a nonempty array")
    result = [require_text(item, "required_dimensions[]") for item in value]
    if len(result) != len(set(result)):
        raise CalibrationError("E_DUPLICATE", "required_dimensions contains duplicates")
    return sorted(result)


def safe_file(project_root: Path, value: Any, label: str) -> tuple[Path, str]:
    raw = require_text(value, label)
    if "\\" in raw:
        raise CalibrationError("E_PATH", f"{label} must use slash separated paths")
    pure = PurePosixPath(raw)
    if pure.is_absolute() or not pure.parts or any(part in {"", ".", ".."} for part in pure.parts):
        raise CalibrationError("E_PATH", f"{label} must be a safe project relative path")
    root = project_root.resolve()
    current = root
    for part in pure.parts:
        current = current / part
        if current.is_symlink():
            raise CalibrationError("E_PATH", f"{label} may not traverse a symlink")
    try:
        resolved = (root / Path(*pure.parts)).resolve(strict=True)
    except OSError as exc:
        raise CalibrationError("E_PATH", f"{label} does not resolve to a file") from exc
    if resolved != root and root not in resolved.parents:
        raise CalibrationError("E_PATH", f"{label} escapes the project root")
    if not resolved.is_file() or resolved.is_symlink():
        raise CalibrationError("E_PATH", f"{label} must reference a regular file")
    return resolved, pure.as_posix()


def runtime_module() -> Any:
    path = (
        Path(__file__).resolve().parents[2]
        / "execute-outcome-evaluator"
        / "scripts"
        / "execute_evaluator.py"
    )
    spec = importlib.util.spec_from_file_location("company_os_execute_outcome_evaluator", path)
    if spec is None or spec.loader is None:
        raise CalibrationError("E_RUNTIME", "evaluator execution runtime cannot be loaded")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def verify_self_digest(value: Mapping[str, Any], field: str, label: str) -> str:
    observed = require_sha256(value.get(field), f"{label}.{field}")
    candidate = dict(value)
    candidate[field] = None
    if digest(candidate) != observed:
        raise CalibrationError("E_DIGEST", f"{label}.{field} does not match exact content")
    return observed


def clean_scores(value: Any, dimensions: list[str], label: str) -> dict[str, float]:
    scores = require_object(value, label)
    if set(scores) != set(dimensions):
        raise CalibrationError(
            "E_SCORE",
            f"{label} dimensions are invalid; expected={dimensions} observed={sorted(scores)}",
        )
    result: dict[str, float] = {}
    for dimension in dimensions:
        score = scores.get(dimension)
        if (
            not isinstance(score, (int, float))
            or isinstance(score, bool)
            or not math.isfinite(float(score))
            or float(score) < 0.0
            or float(score) > 10.0
        ):
            raise CalibrationError("E_SCORE", f"{label}.{dimension} is invalid")
        result[dimension] = float(score)
    return result


def pairwise_failures(candidates: list[dict[str, Any]], dimensions: list[str]) -> list[dict[str, Any]]:
    by_rank = sorted(candidates, key=lambda item: item["expected_rank"])
    failures: list[dict[str, Any]] = []
    for dimension in dimensions:
        for lower, higher in zip(by_rank, by_rank[1:]):
            lower_score = lower["scores"][dimension]
            higher_score = higher["scores"][dimension]
            if not lower_score < higher_score:
                failures.append(
                    {
                        "dimension": dimension,
                        "lower_candidate": lower["candidate_id"],
                        "higher_candidate": higher["candidate_id"],
                        "lower_score": lower_score,
                        "higher_score": higher_score,
                    }
                )
    return sorted(
        failures,
        key=lambda item: (
            item["dimension"],
            item["lower_candidate"],
            item["higher_candidate"],
        ),
    )


def _source_identity(receipt: Mapping[str, Any]) -> dict[str, Any]:
    sources = require_object(receipt.get("source_bindings"), "execution receipt source_bindings")
    return {
        key: dict(require_object(sources.get(key), f"source_bindings.{key}"))
        for key in (
            "evaluator_contract",
            "benchmark_contract",
            "adapter_registry",
            "adapter_entrypoint",
        )
    }


def calibrate(project_root: Path, request: Mapping[str, Any]) -> dict[str, Any]:
    project_root = project_root.resolve()
    if not project_root.is_dir() or project_root.is_symlink():
        raise CalibrationError("E_PATH", "project_root must be a real directory")
    expected_keys = {
        "$schema",
        "objective_id",
        "evaluator_id",
        "required_dimensions",
        "candidates",
    }
    if set(request) != expected_keys:
        raise CalibrationError("E_SCHEMA", "calibration request keys are invalid")
    if request.get("$schema") != REQUEST_SCHEMA:
        raise CalibrationError("E_SCHEMA", f"calibration request must use {REQUEST_SCHEMA}")
    objective_id = require_text(request.get("objective_id"), "objective_id")
    evaluator_id = require_text(request.get("evaluator_id"), "evaluator_id")
    dimensions = require_dimensions(request.get("required_dimensions"))
    raw_candidates = request.get("candidates")
    if not isinstance(raw_candidates, list) or len(raw_candidates) < 3:
        raise CalibrationError("E_SCHEMA", "at least three calibration candidates are required")

    runtime = runtime_module()
    candidates: list[dict[str, Any]] = []
    candidate_ids: set[str] = set()
    receipt_digests: set[str] = set()
    artifact_sets: set[str] = set()
    expected_source_identity: dict[str, Any] | None = None
    for index, raw in enumerate(raw_candidates):
        item = require_object(raw, f"candidates[{index}]")
        if set(item) != {"candidate_id", "expected_rank", "execution_receipt_path"}:
            raise CalibrationError("E_SCHEMA", f"candidates[{index}] keys are invalid")
        candidate_id = require_text(item.get("candidate_id"), f"candidates[{index}].candidate_id")
        if candidate_id in candidate_ids:
            raise CalibrationError("E_DUPLICATE", f"duplicate candidate_id {candidate_id}")
        candidate_ids.add(candidate_id)
        expected_rank = item.get("expected_rank")
        if not isinstance(expected_rank, int) or isinstance(expected_rank, bool) or expected_rank < 1:
            raise CalibrationError("E_SCHEMA", f"{candidate_id}.expected_rank is invalid")
        receipt_path, relative = safe_file(
            project_root,
            item.get("execution_receipt_path"),
            f"{candidate_id}.execution_receipt_path",
        )
        receipt = dict(require_object(read_json(receipt_path, f"{candidate_id} execution receipt"), "execution receipt"))
        try:
            verified = runtime.verify_receipt(project_root, receipt)
        except Exception as exc:
            code = getattr(exc, "code", "E_EXECUTION")
            raise CalibrationError(code, f"{candidate_id} execution receipt is invalid: {exc}") from exc
        if verified.get("objective_id") != objective_id:
            raise CalibrationError("E_BINDING", f"{candidate_id} objective_id does not match")
        if verified.get("evaluator_id") != evaluator_id:
            raise CalibrationError("E_BINDING", f"{candidate_id} evaluator_id does not match")
        receipt_sha256 = require_sha256(
            verified.get("receipt_sha256"),
            f"{candidate_id}.receipt_sha256",
        )
        if receipt_sha256 in receipt_digests:
            raise CalibrationError("E_DUPLICATE", "calibration candidates cannot reuse an execution receipt")
        receipt_digests.add(receipt_sha256)
        artifact_bindings = receipt.get("artifact_bindings")
        if not isinstance(artifact_bindings, list) or not artifact_bindings:
            raise CalibrationError("E_EXECUTION", f"{candidate_id} has no artifact bindings")
        artifact_set_sha256 = runtime.digest(artifact_bindings)
        if artifact_set_sha256 in artifact_sets:
            raise CalibrationError("E_DUPLICATE", "calibration candidates must use distinct artifact sets")
        artifact_sets.add(artifact_set_sha256)
        source_identity = _source_identity(receipt)
        if expected_source_identity is None:
            expected_source_identity = source_identity
        elif source_identity != expected_source_identity:
            raise CalibrationError(
                "E_BINDING",
                "all calibration candidates must use the same evaluator, benchmark, registry, and adapter bytes",
            )
        scores = clean_scores(receipt.get("scores"), dimensions, f"{candidate_id}.scores")
        candidates.append(
            {
                "candidate_id": candidate_id,
                "expected_rank": expected_rank,
                "execution_receipt_path": relative,
                "execution_receipt_file_sha256": file_digest(receipt_path),
                "execution_receipt_sha256": receipt_sha256,
                "artifact_set_sha256": artifact_set_sha256,
                "scores": scores,
            }
        )

    ranks = [item["expected_rank"] for item in candidates]
    if len(ranks) != len(set(ranks)) or sorted(ranks) != list(range(1, len(ranks) + 1)):
        raise CalibrationError("E_SCHEMA", "expected ranks must be unique and contiguous")
    candidates.sort(key=lambda item: item["expected_rank"])
    failures = pairwise_failures(candidates, dimensions)
    source_identity = expected_source_identity or {}
    output: dict[str, Any] = {
        "$schema": RECEIPT_SCHEMA,
        "schema_version": 2,
        "objective_id": objective_id,
        "evaluator_id": evaluator_id,
        "execution_bound": True,
        "candidate_count": len(candidates),
        "required_dimensions": dimensions,
        "source_bindings": source_identity,
        "source_bindings_sha256": digest(source_identity),
        "candidates": candidates,
        "pairwise_failures": failures,
        "passed": not failures,
    }
    output["receipt_sha256"] = digest({**output, "receipt_sha256": None})
    return output


def verify_receipt(project_root: Path, receipt: Mapping[str, Any]) -> dict[str, Any]:
    if receipt.get("$schema") != RECEIPT_SCHEMA:
        raise CalibrationError("E_SCHEMA", f"calibration receipt must use {RECEIPT_SCHEMA}")
    if receipt.get("schema_version") != 2 or receipt.get("execution_bound") is not True:
        raise CalibrationError("E_CALIBRATION", "calibration receipt is not execution bound")
    receipt_sha256 = verify_self_digest(receipt, "receipt_sha256", "calibration receipt")
    objective_id = require_text(receipt.get("objective_id"), "objective_id")
    evaluator_id = require_text(receipt.get("evaluator_id"), "evaluator_id")
    dimensions = require_dimensions(receipt.get("required_dimensions"))
    source_bindings = dict(require_object(receipt.get("source_bindings"), "source_bindings"))
    if receipt.get("source_bindings_sha256") != digest(source_bindings):
        raise CalibrationError("E_DIGEST", "source_bindings_sha256 does not match")
    raw_candidates = receipt.get("candidates")
    if not isinstance(raw_candidates, list) or len(raw_candidates) < 3:
        raise CalibrationError("E_CALIBRATION", "calibration receipt requires three candidates")
    runtime = runtime_module()
    candidates: list[dict[str, Any]] = []
    receipt_digests: set[str] = set()
    artifact_sets: set[str] = set()
    candidate_ids: set[str] = set()
    for index, raw in enumerate(raw_candidates):
        item = dict(require_object(raw, f"candidates[{index}]"))
        candidate_id = require_text(item.get("candidate_id"), f"candidates[{index}].candidate_id")
        if candidate_id in candidate_ids:
            raise CalibrationError("E_DUPLICATE", f"duplicate candidate_id {candidate_id}")
        candidate_ids.add(candidate_id)
        rank = item.get("expected_rank")
        if not isinstance(rank, int) or isinstance(rank, bool) or rank < 1:
            raise CalibrationError("E_SCHEMA", f"{candidate_id}.expected_rank is invalid")
        path, relative = safe_file(
            project_root,
            item.get("execution_receipt_path"),
            f"{candidate_id}.execution_receipt_path",
        )
        if relative != item.get("execution_receipt_path"):
            raise CalibrationError("E_PATH", f"{candidate_id} receipt path is not canonical")
        if file_digest(path) != require_sha256(
            item.get("execution_receipt_file_sha256"),
            f"{candidate_id}.execution_receipt_file_sha256",
        ):
            raise CalibrationError("E_DIGEST", f"{candidate_id} execution receipt file drifted")
        execution = dict(require_object(read_json(path, f"{candidate_id} execution receipt"), "execution receipt"))
        try:
            verified = runtime.verify_receipt(project_root, execution)
        except Exception as exc:
            code = getattr(exc, "code", "E_EXECUTION")
            raise CalibrationError(code, f"{candidate_id} execution receipt is invalid: {exc}") from exc
        observed_receipt = require_sha256(verified.get("receipt_sha256"), f"{candidate_id}.receipt_sha256")
        if observed_receipt != item.get("execution_receipt_sha256"):
            raise CalibrationError("E_DIGEST", f"{candidate_id} execution receipt digest drifted")
        if observed_receipt in receipt_digests:
            raise CalibrationError("E_DUPLICATE", "execution receipt is reused")
        receipt_digests.add(observed_receipt)
        if verified.get("objective_id") != objective_id or verified.get("evaluator_id") != evaluator_id:
            raise CalibrationError("E_BINDING", f"{candidate_id} execution identity drifted")
        artifact_set_sha256 = runtime.digest(execution.get("artifact_bindings"))
        if artifact_set_sha256 != item.get("artifact_set_sha256"):
            raise CalibrationError("E_DIGEST", f"{candidate_id} artifact set drifted")
        if artifact_set_sha256 in artifact_sets:
            raise CalibrationError("E_DUPLICATE", "artifact set is reused")
        artifact_sets.add(artifact_set_sha256)
        if _source_identity(execution) != source_bindings:
            raise CalibrationError("E_BINDING", f"{candidate_id} source bindings drifted")
        scores = clean_scores(execution.get("scores"), dimensions, f"{candidate_id}.scores")
        if scores != item.get("scores"):
            raise CalibrationError("E_DIGEST", f"{candidate_id} retained scores drifted")
        candidates.append({**item, "scores": scores})
    ranks = [item["expected_rank"] for item in candidates]
    if len(ranks) != len(set(ranks)) or sorted(ranks) != list(range(1, len(ranks) + 1)):
        raise CalibrationError("E_SCHEMA", "expected ranks must be unique and contiguous")
    failures = pairwise_failures(candidates, dimensions)
    if failures != receipt.get("pairwise_failures"):
        raise CalibrationError("E_DIGEST", "pairwise failures do not match current executions")
    passed = not failures
    if receipt.get("passed") is not passed:
        raise CalibrationError("E_DIGEST", "calibration decision does not match current executions")
    if receipt.get("candidate_count") != len(candidates):
        raise CalibrationError("E_SCHEMA", "candidate_count does not match")
    return {
        "receipt_sha256": receipt_sha256,
        "objective_id": objective_id,
        "evaluator_id": evaluator_id,
        "passed": passed,
        "execution_bound": True,
        "candidate_count": len(candidates),
    }


def main() -> None:
    parser = argparse.ArgumentParser()
    subparsers = parser.add_subparsers(dest="command", required=True)
    calibrate_parser = subparsers.add_parser("calibrate")
    calibrate_parser.add_argument("--project-root", required=True, type=Path)
    calibrate_parser.add_argument("--request", required=True, type=Path)
    calibrate_parser.add_argument("--output", required=True, type=Path)
    verify_parser = subparsers.add_parser("verify")
    verify_parser.add_argument("--project-root", required=True, type=Path)
    verify_parser.add_argument("--receipt", required=True, type=Path)
    args = parser.parse_args()
    if args.command == "calibrate":
        request = require_object(read_json(args.request, "calibration request"), "calibration request")
        receipt = calibrate(args.project_root, request)
        args.output.parent.mkdir(parents=True, exist_ok=True)
        args.output.write_text(json.dumps(receipt, indent=2, sort_keys=True) + "\n", encoding="utf-8")
        print(f"calibration passed={receipt['passed']} failures={len(receipt['pairwise_failures'])}")
        return
    receipt = require_object(read_json(args.receipt, "calibration receipt"), "calibration receipt")
    print(json.dumps(verify_receipt(args.project_root, receipt), sort_keys=True))


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""Compile bounded calibration laboratories for required Company OS evaluators."""
from __future__ import annotations

import argparse
import importlib.util
import json
from pathlib import Path, PurePosixPath
from typing import Any, Mapping

EVALUATOR_SCHEMA = "company-os.evaluator-runtime-contract.v1"
ARTIFACT_SCHEMA = "company-os.artifact-observation-contract.v1"
BENCHMARK_SCHEMA = "company-os.benchmark-contract.v1"
REGISTRY_SCHEMA = "company-os.evaluator-adapter-registry.v1"
PHASES = ["charter", "discovery", "design", "execution", "verification", "integration"]
MAX_EVALUATORS_PER_BATCH = 1


class CalibrationFabricError(ValueError):
    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(f"{code}: {message}")


def text(value: Any, label: str) -> str:
    if not isinstance(value, str) or not value.strip() or "\x00" in value:
        raise CalibrationFabricError("E_SCHEMA", f"{label} must be nonempty")
    return value.strip()


def obj(value: Any, label: str) -> Mapping[str, Any]:
    if not isinstance(value, Mapping):
        raise CalibrationFabricError("E_SCHEMA", f"{label} must be an object")
    return value


def read_json(path: Path, label: str) -> dict[str, Any]:
    try:
        raw = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise CalibrationFabricError("E_JSON", f"cannot read {label}: {path}") from exc
    return dict(obj(raw, label))


def load_module(path: Path, name: str):
    spec = importlib.util.spec_from_file_location(name, path)
    if spec is None or spec.loader is None:
        raise CalibrationFabricError("E_RUNTIME", f"cannot load {name}")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def company_root() -> Path:
    return Path(__file__).resolve().parents[2]


def repo_root() -> Path:
    return Path(__file__).resolve().parents[4]


def control_store_module():
    return load_module(
        company_root() / "elastic-company-os/scripts/control_store.py",
        "company_os_calibration_store",
    )


def fabric_module():
    return load_module(
        repo_root() / "skills/autonomy-suite/orchestration/luna-execution-fabric/scripts/validate_fabric.py",
        "company_os_calibration_fabric",
    )


def verify_ready(raw: Mapping[str, Any], schema: str, label: str) -> dict[str, Any]:
    value = dict(raw)
    if value.get("$schema") != schema:
        raise CalibrationFabricError("E_SCHEMA", f"{label} must use {schema}")
    if value.get("ready") is not True:
        raise CalibrationFabricError("E_NOT_READY", f"{label} is not ready")
    return value


def verify_registry(raw: Mapping[str, Any]) -> dict[str, Any]:
    value = dict(raw)
    if value.get("$schema") != REGISTRY_SCHEMA:
        raise CalibrationFabricError("E_SCHEMA", f"adapter registry must use {REGISTRY_SCHEMA}")
    adapters = value.get("adapters")
    if not isinstance(adapters, list) or not adapters:
        raise CalibrationFabricError("E_SCHEMA", "adapter registry has no adapters")
    return value


def required_artifact_map(contract: Mapping[str, Any]) -> dict[str, dict[str, Any]]:
    records = contract.get("artifact_classes")
    if not isinstance(records, list):
        raise CalibrationFabricError("E_SCHEMA", "artifact_classes must be an array")
    result = {}
    for raw in records:
        if not isinstance(raw, Mapping):
            raise CalibrationFabricError("E_SCHEMA", "artifact class must be an object")
        artifact_id = text(raw.get("artifact_class_id"), "artifact_class_id")
        result[artifact_id] = dict(raw)
    return result


def positive_negative_anchors(contract: Mapping[str, Any]) -> dict[str, list[dict[str, Any]]]:
    dimensions = contract.get("dimensions")
    if not isinstance(dimensions, list):
        raise CalibrationFabricError("E_SCHEMA", "benchmark dimensions must be an array")
    negative: list[dict[str, Any]] = []
    positive: list[dict[str, Any]] = []
    for dimension in dimensions:
        if not isinstance(dimension, Mapping) or dimension.get("required") is not True:
            continue
        for reference in dimension.get("references", []):
            if not isinstance(reference, Mapping):
                continue
            record = dict(reference)
            record["dimension_id"] = dimension.get("dimension_id")
            tier = reference.get("quality_tier")
            if tier in {"negative", "baseline"}:
                negative.append(record)
            if tier in {"strong", "exemplar"}:
                positive.append(record)
    if not negative or not positive:
        raise CalibrationFabricError(
            "E_BENCHMARK",
            "calibration requires at least one negative or baseline anchor and one strong or exemplar anchor",
        )
    return {
        "negative": sorted(negative, key=lambda item: (str(item.get("dimension_id")), str(item.get("reference_id")))),
        "positive": sorted(positive, key=lambda item: (str(item.get("dimension_id")), str(item.get("reference_id")))),
    }


def adapter_for(registry: Mapping[str, Any], locator: str) -> Mapping[str, Any]:
    matches = [
        item
        for item in registry.get("adapters", [])
        if isinstance(item, Mapping) and item.get("adapter_locator") == locator
    ]
    if len(matches) != 1:
        raise CalibrationFabricError(
            "E_ADAPTER",
            f"evaluator adapter registry does not contain exactly one adapter for {locator}",
        )
    return matches[0]


def candidate_task(
    evaluator: Mapping[str, Any],
    artifact_definitions: list[dict[str, Any]],
    anchors: dict[str, list[dict[str, Any]]],
    rank: int,
    output_root: str,
) -> str:
    if rank == 1:
        tier_instruction = (
            "Materialize a deliberately weak but valid candidate. Use the negative or baseline anchors as evidence for the expected low quality state. "
            "The candidate must still be observable by the evaluator; do not make it invalid merely to force a low score."
        )
    elif rank == 2:
        tier_instruction = (
            "Materialize a materially intermediate candidate between the negative and positive anchors. Deliberately preserve some strengths and some clear deficiencies so it should rank strictly between the other two candidates."
        )
    else:
        tier_instruction = (
            "Materialize a strong candidate aligned with the strong or exemplar anchors. It must exhibit the relevant high quality properties in actual behavior, not just source structure."
        )
    return (
        f"Build calibration candidate rank {rank} for evaluator {evaluator['evaluator_id']!r}. {tier_instruction} "
        f"Required artifact definitions: {json.dumps(artifact_definitions, sort_keys=True)}. "
        f"Negative anchors: {json.dumps(anchors['negative'], sort_keys=True)}. Positive anchors: {json.dumps(anchors['positive'], sort_keys=True)}. "
        f"Write all candidate artifacts under {output_root!r}. Produce a candidate-manifest.json in that directory with schema company-os.calibration-candidate.v1, expected_rank {rank}, every artifact_id, artifact_class_id, path, and sha256. "
        "Use real artifacts that the registered evaluator can exercise. If an external runtime or referenced asset cannot be obtained, return the exact blocker instead of fabricating a candidate."
    )


def manager_integration_instruction(
    evaluator: Mapping[str, Any],
    *,
    evaluator_contract_path: str,
    benchmark_contract_path: str,
    adapter_registry_path: str,
    manager_root: str,
) -> str:
    evaluator_id = evaluator["evaluator_id"]
    return (
        f"After all three ranked candidate manifests are verified, run the registered evaluator {evaluator_id!r} independently against each candidate using the exact same evaluator contract {evaluator_contract_path!r}, benchmark contract {benchmark_contract_path!r}, and adapter registry {adapter_registry_path!r}. "
        f"Write three execution receipts under {manager_root!r}. Then write a company-os.evaluator-calibration.v2 request with evaluator_id {evaluator_id!r}, required_dimensions {sorted(evaluator.get('score_dimensions', []))}, candidate IDs rank-1, rank-2, rank-3, expected ranks 1, 2, 3, and the three execution receipt paths. "
        "Run skills/company-os/calibrate-outcome-evaluator/scripts/calibrate_evaluator.py against that request. The manager is accepted only if the resulting execution bound calibration receipt has passed true. If any score dimension ties or inverts, reject the evaluator capability and report the precise dimension. Do not change expected ranks after seeing scores."
    )


def compile_manifest(
    project_root: Path,
    evaluator_contract_path: str,
    artifact_contract_path: str,
    benchmark_contract_path: str,
    adapter_registry_path: str,
    already_calibrated: set[str] | None = None,
) -> dict[str, Any]:
    project_root = project_root.resolve()
    evaluator_contract = verify_ready(
        read_json(project_root / evaluator_contract_path, "evaluator contract"),
        EVALUATOR_SCHEMA,
        "evaluator contract",
    )
    artifact_contract = verify_ready(
        read_json(project_root / artifact_contract_path, "artifact contract"),
        ARTIFACT_SCHEMA,
        "artifact contract",
    )
    benchmark_contract = verify_ready(
        read_json(project_root / benchmark_contract_path, "benchmark contract"),
        BENCHMARK_SCHEMA,
        "benchmark contract",
    )
    registry = verify_registry(read_json(project_root / adapter_registry_path, "adapter registry"))
    objective_id = text(evaluator_contract.get("objective_id"), "objective_id")
    if artifact_contract.get("objective_id") != objective_id or benchmark_contract.get("objective_id") != objective_id:
        raise CalibrationFabricError("E_BINDING", "outcome runtime contracts do not share one objective")
    artifact_map = required_artifact_map(artifact_contract)
    anchors = positive_negative_anchors(benchmark_contract)
    calibrated = already_calibrated or set()
    evaluators = [
        dict(raw)
        for raw in evaluator_contract.get("evaluators", [])
        if isinstance(raw, Mapping)
        and raw.get("required") is True
        and raw.get("evaluator_id") not in calibrated
    ]
    evaluators.sort(key=lambda item: str(item.get("evaluator_id", "")))
    batch = evaluators[:MAX_EVALUATORS_PER_BATCH]
    remaining = [item["evaluator_id"] for item in evaluators[MAX_EVALUATORS_PER_BATCH:]]
    if not batch:
        return {
            "complete": True,
            "objective_id": objective_id,
            "calibration_evaluator_ids": [],
            "remaining_evaluator_ids": [],
            "fabric": None,
        }
    try:
        _, state = control_store_module().load(project_root)
    except Exception as exc:
        raise CalibrationFabricError(
            "E_STATE",
            f"Company OS transactional control store is required: {exc}",
        ) from exc
    strategy = obj(state.get("strategy"), "strategy")
    instance = obj(state.get("instance"), "instance")
    project_id = text(instance.get("project_id"), "project_id")
    program_version = strategy.get("program_version")
    if not isinstance(program_version, int) or isinstance(program_version, bool) or program_version < 1:
        raise CalibrationFabricError("E_STATE", "strategy.program_version is invalid")

    program_outcome = f"Calibrate required independent evaluators for objective {objective_id}"
    managers = []
    for manager_index, evaluator in enumerate(batch, 1):
        evaluator_id = text(evaluator.get("evaluator_id"), "evaluator_id")
        locator = text(evaluator.get("adapter_locator"), f"{evaluator_id}.adapter_locator")
        adapter_for(registry, locator)
        covered = evaluator.get("artifact_classes")
        if not isinstance(covered, list) or not covered:
            raise CalibrationFabricError("E_SCHEMA", f"{evaluator_id} covers no artifact classes")
        definitions = []
        for artifact_id in covered:
            if artifact_id not in artifact_map:
                raise CalibrationFabricError(
                    "E_BINDING",
                    f"{evaluator_id} references unknown artifact class {artifact_id}",
                )
            definitions.append(artifact_map[artifact_id])
        manager_id = f"calibration-manager-{manager_index:02d}-{evaluator_id}"
        manager_root = f".company-os/calibration/{evaluator_id}"
        manager_outcome = f"Prove evaluator {evaluator_id} strictly discriminates three known quality ranks"
        workers = []
        for rank in (1, 2, 3):
            output_root = f"{manager_root}/rank-{rank}"
            workers.append(
                {
                    "id": f"{manager_id}-candidate-{rank}",
                    "model": "gpt-5.6-luna",
                    "task": candidate_task(
                        evaluator,
                        definitions,
                        anchors,
                        rank,
                        output_root,
                    ),
                    "acceptance": [
                        f"Candidate manifest exists at {output_root}/candidate-manifest.json",
                        "Candidate contains real artifacts for every evaluator artifact class",
                        "Candidate artifacts are distinct from the other calibration ranks",
                        "Candidate quality intent is fixed before evaluator scores are observed",
                    ],
                    "write_scope": [output_root],
                    "risk": "low",
                    "budget": {
                        "time_minutes": 30.0,
                        "token_limit": 8000,
                        "cost_usd": 8.0,
                        "max_concurrency": 1,
                        "max_retries": 1,
                    },
                    "outcome_context": {
                        "program_version": program_version,
                        "north_star": strategy.get("north_star") or "Produce independently verified outcomes",
                        "user_value": f"A trustworthy independent evaluator for {objective_id}",
                        "program_outcome": program_outcome,
                        "manager_outcome": manager_outcome,
                        "roadmap_position": "verification",
                        "dependencies": [
                            evaluator_contract_path,
                            artifact_contract_path,
                            benchmark_contract_path,
                            adapter_registry_path,
                        ],
                        "non_goals": ["Production candidate modification", "Changing evaluator expectations after scoring"],
                        "constraints": [
                            "Candidate rank is fixed before scoring",
                            "Calibration candidates must use distinct artifact sets",
                            "Unavailable external evidence cannot be fabricated",
                        ],
                    },
                    "stop_condition": "A real ranked candidate is materialized, or a concrete prerequisite blocker is proven.",
                }
            )
        integration_instruction = manager_integration_instruction(
            evaluator,
            evaluator_contract_path=evaluator_contract_path,
            benchmark_contract_path=benchmark_contract_path,
            adapter_registry_path=adapter_registry_path,
            manager_root=manager_root,
        )
        managers.append(
            {
                "id": manager_id,
                "model": "gpt-5.6-sol",
                "outcome": manager_outcome,
                "acceptance": [
                    "Three distinct ranked candidate artifact sets are materialized",
                    "The same evaluator contract, benchmark contract, registry, and adapter bytes are used for all three executions",
                    "Three verified evaluator execution receipts exist",
                    "Execution bound calibration receipt exists and passed is true",
                    integration_instruction,
                ],
                "phase_ids": PHASES,
                "budget": {
                    "time_minutes": 120.0,
                    "token_limit": 30000,
                    "cost_usd": 30.0,
                    "max_concurrency": 1,
                    "max_retries": 1,
                },
                "write_scope": [manager_root],
                "workers": workers,
            }
        )
    worker_count = sum(len(manager["workers"]) for manager in managers)
    mission_path = project_root / ".company-os" / "outcomes" / objective_id / "mission-execution-state.json"
    remaining_minutes = 60.0
    if mission_path.is_file():
        try:
            mission = read_json(mission_path, "mission execution state")
            from datetime import datetime, timezone
            expires_at = datetime.fromisoformat(str(mission["expires_at"]).replace("Z", "+00:00"))
            remaining_minutes = max(10.0, (expires_at - datetime.now(timezone.utc)).total_seconds() / 60.0)
        except Exception:
            remaining_minutes = 60.0
    calibration_budget_minutes = max(10.0, min(30.0, remaining_minutes * 0.10))
    per_manager_minutes = calibration_budget_minutes / max(1, len(managers))
    per_manager_tokens = max(3000, int(18000 / max(1, len(managers))))
    for manager in managers:
        manager["budget"] = {
            "time_minutes": per_manager_minutes,
            "token_limit": per_manager_tokens,
            "cost_usd": max(3.0, 18.0 / max(1, len(managers))),
            "max_concurrency": 1,
            "max_retries": 1,
        }
        for worker in manager["workers"]:
            worker["budget"] = {
                "time_minutes": per_manager_minutes / 3.0,
                "token_limit": max(1000, per_manager_tokens // 3),
                "cost_usd": max(1.0, 6.0 / max(1, len(managers))),
                "max_concurrency": 1,
                "max_retries": 0,
            }
    fabric = {
        "program_id": project_id,
        "program_version": program_version,
        "outcome": program_outcome,
        "acceptance": [
            "Every evaluator in this batch has an execution bound calibration receipt",
            "Every calibration receipt passed strict pairwise ordering across every required score dimension",
            "No expected rank changed after evaluator output was observed",
        ],
        "program_contract": {
            "north_star": strategy.get("north_star") or "Produce independently verified outcomes",
            "user_value": f"A trustworthy independent evaluator set for {objective_id}",
            "rationale": "Production must not scale before the evaluator system proves it can distinguish poor from excellent artifacts.",
            "architecture": "Three real calibration candidate workers feed one independent evaluator manager per evaluator capability.",
            "roadmap": PHASES,
            "dependencies": [
                evaluator_contract_path,
                artifact_contract_path,
                benchmark_contract_path,
                adapter_registry_path,
            ],
            "non_goals": ["Production artifact delivery", "Changing quality expectations after scoring"],
            "constraints": ["Strict score ordering required", "Exact evaluator bytes are fixed during calibration"],
        },
        "max_managers": len(managers),
        "max_manager_concurrency": len(managers),
        "max_workers_per_manager": 3,
        "max_total_workers": worker_count,
        "max_depth": 2,
        "max_worker_retries": 1,
        "max_manager_rework_rounds": 2,
        "budget": {
            "time_minutes": calibration_budget_minutes,
            "token_limit": 18000,
            "cost_usd": 18.0,
            "max_concurrency": len(managers),
            "max_retries": 1,
        },
        "luna_token_share_target": 0.75,
        "external_effects_allowed": False,
        "managers": managers,
    }
    validation = fabric_module().validate(fabric)
    if not validation.get("valid"):
        raise CalibrationFabricError("E_FABRIC", "; ".join(validation.get("errors", [])))
    return {
        "complete": False,
        "objective_id": objective_id,
        "calibration_evaluator_ids": [item["evaluator_id"] for item in batch],
        "remaining_evaluator_ids": remaining,
        "fabric": fabric,
    }


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--project-root", type=Path, required=True)
    parser.add_argument("--evaluator-contract", required=True)
    parser.add_argument("--artifact-contract", required=True)
    parser.add_argument("--benchmark-contract", required=True)
    parser.add_argument("--adapter-registry", required=True)
    parser.add_argument("--already-calibrated", action="append", default=[])
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    try:
        result = compile_manifest(
            args.project_root,
            args.evaluator_contract,
            args.artifact_contract,
            args.benchmark_contract,
            args.adapter_registry,
            set(args.already_calibrated),
        )
        args.output.parent.mkdir(parents=True, exist_ok=True)
        args.output.write_text(json.dumps(result, indent=2, sort_keys=True) + "\n", encoding="utf-8")
        print(
            json.dumps(
                {
                    "ok": True,
                    "complete": result["complete"],
                    "calibration_evaluator_ids": result["calibration_evaluator_ids"],
                    "remaining_evaluator_ids": result["remaining_evaluator_ids"],
                },
                sort_keys=True,
            )
        )
        return 0
    except CalibrationFabricError as exc:
        print(json.dumps({"ok": False, "code": exc.code, "error": exc.message}, sort_keys=True))
        return 2


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Apply cited domain discovery evidence to an outcome request."""

from __future__ import annotations

import argparse
import copy
import hashlib
import json
from pathlib import Path
from typing import Any, Mapping

REPORT_SCHEMA = "company-os.outcome-discovery-report.v1"
REQUEST_SCHEMA = "company-os.outcome-request.v1"


class DiscoveryError(ValueError):
    def __init__(self, code: str, message: str) -> None:
        self.code = code
        super().__init__(f"{code}: {message}")


def canonical_bytes(value: Any) -> bytes:
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False).encode()


def digest(value: Any) -> str:
    return hashlib.sha256(canonical_bytes(value)).hexdigest()


def read_json(path: Path) -> dict[str, Any]:
    value = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(value, dict):
        raise DiscoveryError("E_SCHEMA", f"{path} must contain an object")
    return value


def text(value: Any, label: str) -> str:
    if not isinstance(value, str) or not value.strip():
        raise DiscoveryError("E_SCHEMA", f"{label} must be non-empty")
    return value


def unique_strings(value: Any, label: str) -> list[str]:
    if not isinstance(value, list):
        raise DiscoveryError("E_SCHEMA", f"{label} must be an array")
    result = [text(item, f"{label}[]") for item in value]
    if len(result) != len(set(result)):
        raise DiscoveryError("E_DUPLICATE", f"{label} contains duplicates")
    return sorted(result)


def validate_report(report: Mapping[str, Any]) -> dict[str, Any]:
    if report.get("$schema") != REPORT_SCHEMA:
        raise DiscoveryError("E_SCHEMA", f"$schema must be {REPORT_SCHEMA}")
    allowed = {"$schema", "objective_id", "request_sha256", "resolutions", "domain_hypotheses"}
    extra = sorted(set(report) - allowed)
    if extra:
        raise DiscoveryError("E_SCHEMA", f"unknown report keys: {', '.join(extra)}")
    objective_id = text(report.get("objective_id"), "objective_id")
    request_sha256 = text(report.get("request_sha256"), "request_sha256")
    if len(request_sha256) != 64:
        raise DiscoveryError("E_SCHEMA", "request_sha256 must be sha256")

    resolutions = report.get("resolutions")
    if not isinstance(resolutions, list):
        raise DiscoveryError("E_SCHEMA", "resolutions must be an array")
    seen: set[str] = set()
    normalized_resolutions = []
    for item in resolutions:
        if not isinstance(item, dict):
            raise DiscoveryError("E_SCHEMA", "resolution must be an object")
        unknown_id = text(item.get("unknown_id"), "resolution.unknown_id")
        if unknown_id in seen:
            raise DiscoveryError("E_DUPLICATE", f"duplicate resolution {unknown_id}")
        seen.add(unknown_id)
        conclusion = text(item.get("conclusion"), f"{unknown_id}.conclusion")
        citations = unique_strings(item.get("citations"), f"{unknown_id}.citations")
        if not citations:
            raise DiscoveryError("E_EVIDENCE", f"{unknown_id} cannot resolve without citations")
        counterevidence = unique_strings(item.get("counterevidence", []), f"{unknown_id}.counterevidence")
        reconciliation = item.get("reconciliation")
        if counterevidence:
            reconciliation = text(reconciliation, f"{unknown_id}.reconciliation")
        elif reconciliation is not None:
            reconciliation = text(reconciliation, f"{unknown_id}.reconciliation")
        closure_evidence = unique_strings(item.get("closure_evidence"), f"{unknown_id}.closure_evidence")
        if not closure_evidence:
            raise DiscoveryError("E_EVIDENCE", f"{unknown_id} requires closure evidence")
        normalized_resolutions.append({
            "unknown_id": unknown_id,
            "conclusion": conclusion,
            "citations": citations,
            "counterevidence": counterevidence,
            "reconciliation": reconciliation,
            "closure_evidence": closure_evidence,
        })

    hypotheses = report.get("domain_hypotheses", [])
    if not isinstance(hypotheses, list):
        raise DiscoveryError("E_SCHEMA", "domain_hypotheses must be an array")
    normalized_hypotheses = []
    hseen: set[str] = set()
    for item in hypotheses:
        if not isinstance(item, dict):
            raise DiscoveryError("E_SCHEMA", "domain hypothesis must be an object")
        domain_id = text(item.get("domain_id"), "domain_id")
        if domain_id in hseen:
            raise DiscoveryError("E_DUPLICATE", f"duplicate domain hypothesis {domain_id}")
        hseen.add(domain_id)
        hypothesis = text(item.get("hypothesis"), f"{domain_id}.hypothesis")
        status = item.get("status")
        if status not in {"hypothesis", "supported", "refuted"}:
            raise DiscoveryError("E_SCHEMA", f"{domain_id}.status invalid")
        sources = unique_strings(item.get("source_bindings"), f"{domain_id}.source_bindings")
        if not sources:
            raise DiscoveryError("E_EVIDENCE", f"{domain_id} requires source bindings")
        normalized_hypotheses.append({
            "domain_id": domain_id,
            "hypothesis": hypothesis,
            "status": status,
            "source_bindings": sources,
        })

    return {
        "$schema": REPORT_SCHEMA,
        "objective_id": objective_id,
        "request_sha256": request_sha256,
        "resolutions": sorted(normalized_resolutions, key=lambda item: item["unknown_id"]),
        "domain_hypotheses": sorted(normalized_hypotheses, key=lambda item: item["domain_id"]),
    }


def apply_report(request: Mapping[str, Any], raw_report: Mapping[str, Any]) -> dict[str, Any]:
    if request.get("$schema") != REQUEST_SCHEMA:
        raise DiscoveryError("E_SCHEMA", f"request $schema must be {REQUEST_SCHEMA}")
    original = copy.deepcopy(dict(request))
    report = validate_report(raw_report)
    if report["objective_id"] != request.get("objective_id"):
        raise DiscoveryError("E_BINDING", "objective_id mismatch")
    if report["request_sha256"] != digest(request):
        raise DiscoveryError("E_BINDING", "report is not bound to the exact request")

    unknowns = request.get("unknowns")
    if not isinstance(unknowns, list):
        raise DiscoveryError("E_SCHEMA", "request unknowns must be an array")
    unknown_map = {
        text(item.get("unknown_id"), "unknown.unknown_id"): copy.deepcopy(item)
        for item in unknowns
        if isinstance(item, dict)
    }

    for resolution in report["resolutions"]:
        unknown_id = resolution["unknown_id"]
        if unknown_id not in unknown_map:
            raise DiscoveryError("E_UNKNOWN", f"report resolves unknown id not in request: {unknown_id}")
        required = set(unknown_map[unknown_id].get("closure_evidence", []))
        supplied = set(resolution["closure_evidence"])
        if required and not required.issubset(supplied):
            missing = ", ".join(sorted(required - supplied))
            raise DiscoveryError("E_EVIDENCE", f"{unknown_id} missing required closure evidence: {missing}")
        unknown_map[unknown_id]["resolved"] = True
        unknown_map[unknown_id]["resolution"] = resolution["conclusion"]
        unknown_map[unknown_id]["resolution_citations"] = resolution["citations"]
        unknown_map[unknown_id]["resolution_counterevidence"] = resolution["counterevidence"]
        if resolution["reconciliation"] is not None:
            unknown_map[unknown_id]["resolution_reconciliation"] = resolution["reconciliation"]

    updated = copy.deepcopy(dict(request))
    updated["unknowns"] = sorted(unknown_map.values(), key=lambda item: item["unknown_id"])

    existing_domains = {
        item["domain_id"]: copy.deepcopy(item)
        for item in request.get("domain_hypotheses", [])
        if isinstance(item, dict) and isinstance(item.get("domain_id"), str)
    }
    for hypothesis in report["domain_hypotheses"]:
        existing_domains[hypothesis["domain_id"]] = hypothesis
    updated["domain_hypotheses"] = sorted(existing_domains.values(), key=lambda item: item["domain_id"])

    if updated.get("objective") != original.get("objective"):
        raise DiscoveryError("E_OBJECTIVE_DRIFT", "discovery may not alter original objective")
    return updated


def main() -> None:
    parser = argparse.ArgumentParser()
    sub = parser.add_subparsers(dest="command", required=True)
    apply_parser = sub.add_parser("apply")
    apply_parser.add_argument("--request", required=True, type=Path)
    apply_parser.add_argument("--report", required=True, type=Path)
    apply_parser.add_argument("--output", required=True, type=Path)
    args = parser.parse_args()

    request = read_json(args.request)
    report = read_json(args.report)
    updated = apply_report(request, report)
    args.output.parent.mkdir(parents=True, exist_ok=True)
    args.output.write_text(json.dumps(updated, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    print(f"applied discovery objective={updated['objective_id']} request={digest(updated)}")


if __name__ == "__main__":
    main()

