        "external_effects_allowed": False,
        "managers": managers,
        "outcome_control": control,
        "outcome_loop": loop_binding,
    }

def validate_manifest_binding(project_root: Path, manifest: Mapping[str, Any]) -> dict[str, Any]:
    if manifest.get("topology_mode") != TOPOLOGY_MODE:
        raise OrganizationError("E_MODE", "manifest is not outcome closed loop topology")
    goal_module = _goal_route_module()
    route_binding = dict(_object(manifest.get("goal_route"), "goal_route"))
    if route_binding.get("embedded") is True:
        route_state = goal_module.verify_state(_object(manifest.get("goal_route_state"), "goal_route_state"))
    else:
        route_path, route_relative = _safe(project_root, route_binding.get("path"), "goal_route.path")
        route_state = goal_module.verify_state(_object(_read(route_path, "goal route"), "goal route"))
        if route_relative != route_binding.get("path") or file_digest(route_path) != route_binding.get("file_sha256"):
            raise OrganizationError("E_GOAL_ROUTE", "goal route file binding is stale")
    if (
        route_binding.get("state_sha256") != route_state["state_sha256"]
        or route_binding.get("route_version") != route_state["route_version"]
        or route_binding.get("root_goal_id") != route_state["root_goal_id"]
        or route_binding.get("root_goal_sha256") != route_state["root_goal_sha256"]
    ):
        raise OrganizationError("E_GOAL_ROUTE", "goal route state binding is stale")
    mission_binding = dict(_object(manifest.get("mission_control"), "mission_control"))
    mission_path, mission_relative = _safe(project_root, mission_binding.get("state_path"), "mission_control.state_path")
    mission = _mission_module().verify_state(_object(_read(mission_path, "mission execution state"), "mission execution state"))
    if mission_relative != mission_binding.get("state_path") or mission.get("state_sha256") != mission_binding.get("state_sha256"):
        raise OrganizationError("E_GOVERNOR", "mission execution binding is stale")
    if mission.get("status") != "active" or mission.get("generation") != mission_binding.get("generation"):
        raise OrganizationError("E_GOVERNOR", "mission is inactive or generation changed")
    decision = _object(mission.get("governor_decision"), "governor decision")
    if decision.get("decision_sha256") != mission_binding.get("governor_decision_sha256"):
        raise OrganizationError("E_GOVERNOR", "governor decision changed")
    admission = _mission_module().verify_admission(_object(manifest.get("work_admission"), "work_admission"))
    if admission.get("admitted") is not True or admission.get("mission_state_sha256") != mission["state_sha256"] or admission.get("governor_decision_sha256") != decision.get("decision_sha256"):
        raise OrganizationError("E_GOVERNOR", "work admission is stale or rejected")
    if admission.get("work_class") not in set(decision.get("allowed_work_classes", [])) or admission.get("work_class") in set(decision.get("paused_work_classes", [])):
        raise OrganizationError("E_GOVERNOR", "admitted work class is no longer allowed")
    binding = dict(_object(manifest.get("outcome_loop"), "outcome_loop"))
    expected_fields = {"$schema", "state_path", "state_file_sha256", "state_sha256", "phase", "iteration", "next_action", "organization_sha256", "lane_sha256s"}
    if set(binding) != expected_fields or binding.get("$schema") != BINDING_SCHEMA:
        raise OrganizationError("E_SCHEMA", "outcome_loop binding shape is invalid")
    state_path, state_relative = _safe(project_root, binding.get("state_path"), "outcome_loop.state_path")
    if state_relative != binding["state_path"] or file_digest(state_path) != _sha(binding.get("state_file_sha256"), "state_file_sha256"):
        raise OrganizationError("E_DIGEST", "outcome loop state file changed")
    state = verify_loop_state(_object(_read(state_path, "outcome loop state"), "outcome loop state"))
    expected = {"state_sha256": state["state_sha256"], "phase": state["phase"], "iteration": state["iteration"], "next_action": state["next_action"]["action"], "organization_sha256": digest(state["organization_plan"])}
    for field, value in expected.items():
        if binding.get(field) != value:
            raise OrganizationError("E_BINDING", f"outcome_loop.{field} is stale")
    lanes = expected_lanes(state)
    expected_lane_digests = {lane["lane_id"]: digest(lane) for lane in lanes}
    if binding.get("lane_sha256s") != expected_lane_digests:
        raise OrganizationError("E_BINDING", "outcome loop lane bindings are stale")
    managers = manifest.get("managers")
    if not isinstance(managers, list) or len(managers) != len(lanes):
        raise OrganizationError("E_ORGANIZATION", "manifest manager count does not match outcome loop lanes")
    manager_by_lane: dict[str, Mapping[str, Any]] = {}
    for manager in managers:
        manager = _object(manager, "manager")
        lane_id = _text(manager.get("outcome_loop_lane_id"), "manager.outcome_loop_lane_id")
        if lane_id in manager_by_lane:
            raise OrganizationError("E_ORGANIZATION", f"duplicate manager lane {lane_id}")
        manager_by_lane[lane_id] = manager
    if set(manager_by_lane) != set(expected_lane_digests):
        raise OrganizationError("E_ORGANIZATION", "manifest manager lanes do not match outcome loop")
    lane_by_id = {lane["lane_id"]: lane for lane in lanes}
    for lane_id, manager in manager_by_lane.items():
        lane = lane_by_id[lane_id]
        if manager.get("outcome_loop_lane_sha256") != expected_lane_digests[lane_id]:
            raise OrganizationError("E_BINDING", f"manager lane digest changed: {lane_id}")
        if manager.get("outcome") != lane["mandate"]:
            raise OrganizationError("E_ORGANIZATION", f"manager outcome drifted from lane mandate: {lane_id}")
        if manager.get("mission_control") != mission_binding or manager.get("work_admission") != admission:
            raise OrganizationError("E_GOVERNOR", f"manager {lane_id} lost mission admission")
        if manager.get("goal_route") != route_binding:
            raise OrganizationError("E_GOAL_ROUTE", f"manager {lane_id} lost goal route binding")
        try:
            assignment = goal_module.verify_assignment(_object(manager.get("goal_assignment"), "manager.goal_assignment"), route_state)
        except Exception as exc:
            raise OrganizationError("E_GOAL_ROUTE", f"manager {lane_id} goal assignment is invalid: {exc}") from exc
        if manager.get("goal_contract") != assignment["manager_goal"]:
            raise OrganizationError("E_GOAL_ROUTE", f"manager {lane_id} goal contract changed")
        workers = manager.get("workers")
        if not isinstance(workers, list) or not workers:
            raise OrganizationError("E_ORGANIZATION", f"manager {lane_id} has no worker")
        for worker in workers:
            worker = _object(worker, "worker")
            if worker.get("mission_control") != mission_binding or worker.get("work_admission") != admission:
                raise OrganizationError("E_GOVERNOR", f"worker {lane_id} lost mission admission")
            if worker.get("goal_route") != route_binding or worker.get("goal_assignment") != assignment:
                raise OrganizationError("E_GOAL_ROUTE", f"worker {lane_id} lost goal route assignment")
            if worker.get("goal_contract") != assignment["worker_goal"]:
                raise OrganizationError("E_GOAL_ROUTE", f"worker {lane_id} goal contract changed")
            if worker.get("outcome_loop_lane_id") != lane_id or worker.get("outcome_loop_lane_sha256") != expected_lane_digests[lane_id]:
                raise OrganizationError("E_BINDING", f"worker lane binding changed: {lane_id}")
    control = _object(manifest.get("outcome_control"), "outcome_control")
    if control.get("objective_id") != state.get("objective_id"):
        raise OrganizationError("E_BINDING", "manifest outcome control and loop objective differ")
    return {"state_path": state_relative, "state_file_sha256": binding["state_file_sha256"], "state_sha256": state["state_sha256"], "phase": state["phase"], "iteration": state["iteration"], "next_action": state["next_action"]["action"], "organization_sha256": binding["organization_sha256"], "lane_sha256s": expected_lane_digests, "goal_route_state_sha256": route_state["state_sha256"]}

def main() -> int:
    parser = argparse.ArgumentParser()
    sub = parser.add_subparsers(dest="command", required=True)
    compile_parser = sub.add_parser("compile")
    compile_parser.add_argument("--project-root", type=Path, required=True)
    compile_parser.add_argument("--loop-state", required=True)
    compile_parser.add_argument("--request", type=Path, required=True)
    compile_parser.add_argument("--output", type=Path, required=True)
    verify_parser = sub.add_parser("verify")
    verify_parser.add_argument("--project-root", type=Path, required=True)
    verify_parser.add_argument("--manifest", type=Path, required=True)
    args = parser.parse_args()
    try:
        if args.command == "compile":
            request = _object(_read(args.request, "organization request"), "organization request")
            manifest = compile_manifest(args.project_root, args.loop_state, request)
            args.output.parent.mkdir(parents=True, exist_ok=True)
            args.output.write_text(json.dumps(manifest, indent=2, sort_keys=True) + "\n", encoding="utf-8")
            result = validate_manifest_binding(args.project_root, manifest)
        else:
            manifest = _object(_read(args.manifest, "manifest"), "manifest")
            result = validate_manifest_binding(args.project_root, manifest)
        print(json.dumps({"ok": True, **result}, sort_keys=True))
        return 0
    except OrganizationError as exc:
        print(json.dumps({"ok": False, "code": exc.code, "error": exc.message}, sort_keys=True))
        return 2

if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Compile rich artifact observation contracts."""

from __future__ import annotations
import argparse, hashlib, json
from pathlib import Path
from typing import Any, Mapping

SCHEMA="company-os.artifact-observation-request.v1"
OUT="company-os.artifact-observation-contract.v1"
RICH_MODALITIES={"interactive","visual","audio","executable","service","database","model","physical","composite"}
WEAK_METHODS={"file_exists","nonempty","normalized_nonempty","hash_matches","build_succeeds","text_review"}

class ArtifactError(ValueError):
    def __init__(self, code:str, message:str)->None:
        self.code=code
        super().__init__(f"{code}: {message}")

def canonical(v:Any)->bytes:
    return json.dumps(v,sort_keys=True,separators=(",",":"),ensure_ascii=False,allow_nan=False).encode()

def digest(v:Any)->str:
    return hashlib.sha256(canonical(v)).hexdigest()

def text(v:Any,label:str)->str:
    if not isinstance(v,str) or not v.strip(): raise ArtifactError("E_SCHEMA",f"{label} must be non-empty")
    return v

def strings(v:Any,label:str)->list[str]:
    if not isinstance(v,list): raise ArtifactError("E_SCHEMA",f"{label} must be an array")
    out=[text(x,f"{label}[]") for x in v]
    if len(out)!=len(set(out)): raise ArtifactError("E_DUPLICATE",f"{label} contains duplicates")
    return sorted(out)

def compile_contract(req:Mapping[str,Any])->dict[str,Any]:
    if req.get("$schema")!=SCHEMA: raise ArtifactError("E_SCHEMA",f"$schema must be {SCHEMA}")
    objective_id=text(req.get("objective_id"),"objective_id")
    items=req.get("artifact_classes")
    if not isinstance(items,list) or not items: raise ArtifactError("E_SCHEMA","artifact_classes must be nonempty")
    seen=set(); normalized=[]; blockers=[]
    for raw in items:
        if not isinstance(raw,dict): raise ArtifactError("E_SCHEMA","artifact class must be object")
        aid=text(raw.get("artifact_class_id"),"artifact_class_id")
        if aid in seen: raise ArtifactError("E_DUPLICATE",aid)
        seen.add(aid)
        label=text(raw.get("label"),f"{aid}.label")
        modalities=strings(raw.get("modalities"),f"{aid}.modalities")
        if not modalities: raise ArtifactError("E_SCHEMA",f"{aid} needs modalities")
        methods=strings(raw.get("observation_methods"),f"{aid}.observation_methods")
        evidence=strings(raw.get("required_evidence"),f"{aid}.required_evidence")
        required=raw.get("required",True)
        if not isinstance(required,bool): raise ArtifactError("E_SCHEMA",f"{aid}.required must be boolean")
        rich=bool(set(modalities)&RICH_MODALITIES)
        strong=[m for m in methods if m not in WEAK_METHODS]
        if required and not methods:
            blockers.append({"artifact_class_id":aid,"code":"NO_OBSERVATION_METHOD"})
        if required and rich and not strong:
            blockers.append({"artifact_class_id":aid,"code":"RICH_ARTIFACT_TEXT_ONLY"})
        if required and not evidence:
            blockers.append({"artifact_class_id":aid,"code":"NO_CAPTURED_EVIDENCE"})
        normalized.append({
            "artifact_class_id":aid,"label":label,"required":required,
            "modalities":modalities,"observation_methods":methods,
            "required_evidence":evidence,"rich":rich,
        })
    blockers=sorted(blockers,key=lambda x:(x["artifact_class_id"],x["code"]))
    result={"$schema":OUT,"schema_version":1,"objective_id":objective_id,
            "artifact_classes":sorted(normalized,key=lambda x:x["artifact_class_id"]),
            "blockers":blockers,"ready":not blockers}
    result["contract_sha256"]=digest({**result,"contract_sha256":None})
    return result

def main()->None:
    p=argparse.ArgumentParser(); p.add_argument("--request",type=Path,required=True); p.add_argument("--output",type=Path,required=True)
    a=p.parse_args(); req=json.loads(a.request.read_text()); out=compile_contract(req)
    a.output.parent.mkdir(parents=True,exist_ok=True); a.output.write_text(json.dumps(out,indent=2,sort_keys=True)+"\n")
    print(f"compiled artifact contract ready={out['ready']} blockers={len(out['blockers'])}")
if __name__=="__main__": main()

#!/usr/bin/env python3
"""Durable director for the Company OS objective lifecycle."""
from __future__ import annotations

import argparse
import hashlib
import importlib.util
import json
import re
from datetime import timedelta
from pathlib import Path
from typing import Any, Mapping

STATE_SCHEMA = "company-os.objective-director-state.v1"


class DirectorError(ValueError):
    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(f"{code}: {message}")


def canonical(value: Any) -> bytes:
    return json.dumps(
        value,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
        allow_nan=False,
    ).encode("utf-8")


def digest(value: Any) -> str:
    return hashlib.sha256(canonical(value)).hexdigest()


def file_digest(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def text(value: Any, label: str) -> str:
    if not isinstance(value, str) or not value.strip() or "\x00" in value:
        raise DirectorError("E_SCHEMA", f"{label} must be nonempty")
    return value.strip()


def obj(value: Any, label: str) -> Mapping[str, Any]:
    if not isinstance(value, Mapping):
        raise DirectorError("E_SCHEMA", f"{label} must be an object")
    return value


def slug(value: str) -> str:
    result = re.sub(r"[^a-z0-9]+", "-", value.lower()).strip("-")
    if not result:
        raise DirectorError("E_SCHEMA", "objective_id cannot normalize to an empty path")
    return result[:64]


def company_root() -> Path:
    return Path(__file__).resolve().parents[2]


def load_module(relative: str, name: str):
    path = company_root() / relative
    spec = importlib.util.spec_from_file_location(name, path)
    if spec is None or spec.loader is None:
        raise DirectorError("E_RUNTIME", f"cannot load Company OS module {relative}")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


