    save_goal_route(project_root, route)


def checkpoint_candidate(
    project_root: Path,
    objective_id: str,
    candidate: Mapping[str, Any],
) -> dict[str, Any]:
    mission_module = mission_control_module()
    mission = load_mission_state(project_root, objective_id)
    verification_receipts = [
        {"path": item["path"], "sha256": item["sha256"]}
        for item in candidate.get("observations", [])
        if isinstance(item, Mapping) and isinstance(item.get("path"), str) and isinstance(item.get("sha256"), str)
    ]
    try:
        checkpoint = checkpoint_product_module().checkpoint(
            project_root,
            mission,
            candidate,
            verification_receipts,
            commit=(project_root / ".git").is_dir(),
            message=f"checkpoint(company-os): {candidate['candidate_id']}",
        )
    except Exception as exc:
        raise DirectorError("E_CHECKPOINT", f"product checkpoint failed: {exc}") from exc
    checkpoint_path = workspace(project_root, objective_id) / "runtime" / f"{candidate['candidate_id']}-checkpoint.json"
    write_json(checkpoint_path, checkpoint)
    stamp = mission_module.format_time(mission_module.now_utc())
    mission = mission_module.record_event(
        mission,
        mission_module.make_event(
            f"{candidate['candidate_id']}:checkpoint",
            "checkpoint_recorded",
            occurred_at=stamp,
            work_class="checkpoint",
            checkpoint=checkpoint,
        ),
    )
    save_mission_state(project_root, mission)
    return {
        "path": relative(project_root, checkpoint_path),
        "file_sha256": file_digest(checkpoint_path),
        "checkpoint_sha256": checkpoint["checkpoint_sha256"],
        "git_commit": checkpoint.get("git_commit"),
    }


def finalize_mission_acceptance(
    project_root: Path,
    objective_id: str,
    loop: Mapping[str, Any],
    receipt_path: Path,
    receipt: Mapping[str, Any],
) -> None:
    if receipt.get("accepted") is not True:
        return
    module = mission_control_module()
    state = load_mission_state(project_root, objective_id)
    candidate = loop.get("candidates", [])[-1]
    stamp = module.format_time(module.now_utc())
    for capability in list(state["capabilities"]):
        if capability["state"] != "connected":
            continue
        state = module.record_event(
            state,
            module.make_event(
                f"{candidate['candidate_id']}:{capability['capability_id']}:accepted",
                "independent_accepted",
                occurred_at=stamp,
                work_class="evaluation",
                capability_id=capability["capability_id"],
                evidence={"kind": "reality_acceptance", "path": relative(project_root, receipt_path), "sha256": file_digest(receipt_path), "capability_id": capability["capability_id"]},
            ),
        )
    checkpoint = module.create_checkpoint(
        state,
        candidate_id=candidate["candidate_id"],
        capability_ids=[item["capability_id"] for item in state["capabilities"]],
        artifacts=[{"path": item["path"], "sha256": item["sha256"]} for item in candidate.get("artifact_bindings", candidate.get("artifacts", []))],
        verification_receipts=[{"path": relative(project_root, receipt_path), "sha256": file_digest(receipt_path)}],
    )
    state = module.record_event(
        state,
        module.make_event(
            f"{candidate['candidate_id']}:checkpoint",
            "checkpoint_recorded",
            occurred_at=stamp,
            work_class="checkpoint",
            checkpoint=checkpoint,
        ),
    )
    save_mission_state(project_root, state)
    route = load_goal_route(project_root, objective_id)
    route = goal_route_module().accept_route(route, receipt_path=relative(project_root, receipt_path), receipt_sha256=file_digest(receipt_path))
    save_goal_route(project_root, route)


def seal(state: Mapping[str, Any]) -> dict[str, Any]:
    result = dict(state)
    result["director_sha256"] = None
    result["director_sha256"] = digest(result)
    return result


def verify_state(raw: Mapping[str, Any]) -> dict[str, Any]:
    value = dict(raw)
    if value.get("$schema") != STATE_SCHEMA:
        raise DirectorError("E_SCHEMA", "objective director state schema is invalid")
    observed = text(value.get("director_sha256"), "director_sha256")
    if len(observed) != 64 or digest({**value, "director_sha256": None}) != observed:
        raise DirectorError("E_DIGEST", "objective director state changed")
    return value


def load_state(project_root: Path, objective_id: str) -> dict[str, Any]:
    path = state_path(project_root, objective_id)
    return verify_state(obj(read_json(path, "director state"), "director state"))


def _attach_scheduler_wake(project_root: Path, state: Mapping[str, Any]) -> dict[str, Any]:
    candidate = dict(state)
    next_action = candidate.get("next_action")
    mission_path = mission_state_path(project_root, candidate["objective_id"])
    if not isinstance(next_action, Mapping) or next_action.get("action") != "execute_fabric" or not mission_path.is_file():
        return candidate
    mission = load_mission_state(project_root, candidate["objective_id"])
    if mission.get("status") != "active":
        return candidate
    decision = obj(mission.get("governor_decision"), "governor decision")
    interval = {"normal": 8, "compression": 4, "critical_path": 3, "reality_closure": 2}.get(decision.get("mode"), 5)
    if next_action.get("stage") in {"loop", "build_candidate", "rework", "evaluate"}:
        interval = min(interval, 5)
    not_before = mission_control_module().now_utc() + timedelta(minutes=interval)
    wake_id = f"{candidate['objective_id']}:{candidate.get('stage')}:{len(candidate.get('history', []))}:{mission['generation']}"
    wake = mission_control_module().make_wake(
        mission,
        wake_id=wake_id,
        not_before=mission_control_module().format_time(not_before),
        reason=str(next_action.get("reason") or "Continue the current Company OS critical path."),
        expected_state_sha256=mission["state_sha256"],
    )
    wake_path = workspace(project_root, candidate["objective_id"]) / "scheduler" / f"wake-{slug(wake_id)}.json"
    write_json(wake_path, wake)
    updated_action = dict(next_action)
    updated_action["scheduler_wake"] = {
        "path": relative(project_root, wake_path),
        "file_sha256": file_digest(wake_path),
        "wake_sha256": wake["wake_sha256"],
        "not_before": wake["not_before"],
        "expires_at": wake["expires_at"],
        "generation": wake["generation"],
        "idempotency_key": wake["idempotency_key"],
    }
    candidate["next_action"] = updated_action
    return candidate


def save_state(project_root: Path, state: Mapping[str, Any]) -> dict[str, Any]:
    result = seal(_attach_scheduler_wake(project_root, state))
    write_json(state_path(project_root, result["objective_id"]), result)
    return result


def next_execute_fabric(stage: str, path: str, *, reason: str) -> dict[str, Any]:
    return {
        "action": "execute_fabric",
        "stage": stage,
        "fabric_path": path,
        "reason": reason,
        "after_completion": "advance_director",
    }


def start(project_root: Path, objective_id: str, objective: str, *, kickoff_profile: Mapping[str, Any] | None = None, autonomy_mode: str | None = None) -> dict[str, Any]:
    project_root = project_root.resolve()
    objective_id = text(objective_id, "objective_id")
    objective = text(objective, "objective")
    path = state_path(project_root, objective_id)
    if path.exists():
        existing = load_state(project_root, objective_id)
        if existing.get("original_objective") != objective:
            raise DirectorError("E_CONFLICT", "objective director already exists with a different original objective")
        return existing
    try:
        receipt = bootstrap_module().bootstrap(project_root, objective_id, objective)
    except Exception as exc:
        raise DirectorError(getattr(exc, "code", "E_BOOTSTRAP"), f"outcome bootstrap failed: {exc}") from exc
    discovery_fabric = receipt["paths"]["discovery_fabric"]
    mission = mission_control_module().initialize_state(objective_id, objective)
    save_mission_state(project_root, mission)
    route = goal_route_module().compile_goal_route(objective_id, objective, mission_class=mission["mission_class"], kickoff_profile=kickoff_profile, autonomy_mode=autonomy_mode)
    save_goal_route(project_root, route)
    discovery_binding = bind_discovery_fabric(project_root, objective_id, discovery_fabric)
    state = {
        "$schema": STATE_SCHEMA,
        "schema_version": 1,
        "objective_id": objective_id,
        "original_objective": objective,
        "workspace": relative(project_root, workspace(project_root, objective_id)),
        "stage": "discovery",
        "artifacts": {
            "bootstrap_receipt": receipt["paths"]["receipt"],
            "outcome_request": receipt["paths"]["request"],
            "discovery_contract": receipt["paths"]["contract"],
            "outcome_loop": receipt["paths"]["loop_state"],
            "discovery_fabric": discovery_fabric,
            "mission_execution_state": relative(project_root, mission_state_path(project_root, objective_id)),
            "goal_route": relative(project_root, goal_route_path(project_root, objective_id)),
        },
        "next_action": next_execute_fabric(
            "discovery",
            discovery_fabric,
            reason="Close the universal blocking unknowns with cited independent research.",
        ),
        "history": [
            {
                "event": "objective_started",
                "bootstrap_receipt_sha256": receipt["receipt_sha256"],
            }
        ],
        "director_sha256": None,
    }
    state["next_action"].update(discovery_binding)
    return save_state(project_root, state)


def ingest_reality_spike_if_present(project_root: Path, objective_id: str) -> None:
    receipt_path = workspace(project_root, objective_id) / "reality-spike/reality-spike-receipt.json"
    if not receipt_path.is_file():
        return
    mission = load_mission_state(project_root, objective_id)
    receipt = obj(read_json(receipt_path, "reality spike receipt"), "reality spike receipt")
    updated = mission_control_module().ingest_reality_spike(mission, project_root, receipt)
    save_mission_state(project_root, updated)


def proposal_paths(base: Path) -> list[Path]:
    return [
        base / "discovery/domain-truth/proposal.json",
        base / "discovery/artifact-quality/proposal.json",
    ]


def load_contracts(base: Path) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any], dict[str, Any]]:
    outcome = obj(read_json(base / "measurable-outcome-contract.json", "outcome contract"), "outcome contract")
    runtime = base / "runtime"
    artifacts = obj(read_json(runtime / "artifact-contract.json", "artifact contract"), "artifact contract")
    evaluators = obj(read_json(runtime / "evaluator-contract.json", "evaluator contract"), "evaluator contract")
    benchmarks = obj(read_json(runtime / "benchmark-contract.json", "benchmark contract"), "benchmark contract")
    return dict(outcome), dict(artifacts), dict(evaluators), dict(benchmarks)


def verified_calibrations(project_root: Path, base: Path, evaluator_contract: Mapping[str, Any]) -> tuple[list[dict[str, Any]], set[str]]:
    required = {
        item["evaluator_id"]
        for item in evaluator_contract.get("evaluators", [])
        if isinstance(item, Mapping) and item.get("required") is True
    }
    receipts: dict[str, dict[str, Any]] = {}
    calibration_root = project_root / ".company-os" / "calibration"
    if calibration_root.is_dir():
        for path in sorted(calibration_root.rglob("*.json")):
            try:
                raw = read_json(path, "calibration candidate")
            except DirectorError:
                continue
            if not isinstance(raw, Mapping) or raw.get("$schema") != "company-os.evaluator-calibration-receipt.v1":
                continue
            try:
                verified = calibration_module().verify_receipt(project_root, raw)
            except Exception:
                continue
            evaluator_id = verified.get("evaluator_id")
            if evaluator_id not in required or verified.get("passed") is not True or verified.get("execution_bound") is not True:
                continue
            if evaluator_id in receipts:
                raise DirectorError("E_DUPLICATE", f"multiple valid calibration receipts exist for {evaluator_id}")
            receipts[evaluator_id] = dict(raw)
    ordered = [receipts[key] for key in sorted(receipts)]
    return ordered, set(receipts)


def build_outcome_control(
    project_root: Path,
    state: Mapping[str, Any],
    outcome: Mapping[str, Any],
    artifacts: Mapping[str, Any],
    evaluators: Mapping[str, Any],
    benchmarks: Mapping[str, Any],
    calibrations: list[dict[str, Any]],
    *,
    force_lane: str | None = None,
    artifact_contract_file: Path | None = None,
) -> tuple[dict[str, Any], dict[str, Any]]:
    base = workspace(project_root, state["objective_id"])
    runtime = base / "runtime"
    required_artifact_count = sum(1 for item in artifacts.get("artifact_classes", []) if isinstance(item, Mapping) and item.get("required") is True)
    if required_artifact_count < 1:
        raise DirectorError("E_ARTIFACT", "outcome requires at least one real artifact class")
    lane = force_lane or ("pilot" if required_artifact_count <= 2 else "production_scale")
    if lane not in {"pilot", "production_scale"}:
        raise DirectorError("E_SCHEMA", "force_lane must be pilot or production_scale")
    scale_path = runtime / "scale-authorization.json"
    if lane == "production_scale":
        scale = scale_module().authorize(outcome, artifacts, evaluators, benchmarks, calibrations)
        if scale.get("authorized") is not True:
            raise DirectorError("E_SCALE", "outcome stack is not scale authorized: " + json.dumps(scale.get("blockers", []), sort_keys=True))
        write_json(scale_path, scale)
    try:
        _, control_state = control_store_module().load(project_root)
    except Exception as exc:
        raise DirectorError("E_STATE", f"control store unavailable: {exc}") from exc
    project_id = text(obj(control_state.get("instance"), "instance").get("project_id"), "project_id")
    strategy = obj(control_state.get("strategy"), "strategy")
    program_version = strategy.get("program_version")
    if not isinstance(program_version, int) or isinstance(program_version, bool) or program_version < 1:
        raise DirectorError("E_STATE", "strategy.program_version is invalid")
    work_id = f"outcome-delivery-{slug(state['objective_id'])}"
    calibrations_path = runtime / "calibrations.json"
    write_json(calibrations_path, calibrations)
    active_artifact_contract = artifact_contract_file or (runtime / "artifact-contract.json")
    binding = {
        "$schema": "company-os.outcome-control-binding.v1",
        "execution_lane": lane,
        "project_id": project_id,
        "program_version": program_version,
        "work_id": work_id,
        "governed_outcome": state["original_objective"],
        "objective_id": state["objective_id"],
        "outcome_contract_path": relative(project_root, base / "measurable-outcome-contract.json"),
        "artifact_contract_path": relative(project_root, active_artifact_contract),
        "evaluator_contract_path": relative(project_root, runtime / "evaluator-contract.json"),
        "benchmark_contract_path": relative(project_root, runtime / "benchmark-contract.json"),
        "calibration_receipts_path": relative(project_root, calibrations_path),
        "scale_authorization_path": None if lane == "pilot" else relative(project_root, scale_path),
    }
    # Initial pilots stay inside the legacy two-manager ceiling even when the final
    # product has many required artifact classes. outcome_loop bundles classes into
    # those lanes; the candidate must still cover every required class.
    manager_count = min(2, required_artifact_count) if lane == "pilot" else max(1, min(required_artifact_count, 2))
    probe_manifest = {"outcome": state["original_objective"], "max_managers": manager_count, "max_manager_concurrency": manager_count, "max_workers_per_manager": 1, "max_total_workers": manager_count, "managers": [{"workers": [{}]} for _ in range(manager_count)], "outcome_control": binding}
    try:
        portable = outcome_control_module().validate_manifest_binding(project_root=project_root, manifest=probe_manifest, project_id=project_id, program_version=program_version, work_id=work_id, governed_outcome=state["original_objective"])
    except Exception as exc:
        raise DirectorError(getattr(exc, "code", "E_CONTROL"), f"outcome control binding failed: {exc}") from exc
    write_json(runtime / "outcome-control-state.json", portable)
    return binding, portable

def organization_request(
    project_root: Path,
    state: Mapping[str, Any],
    binding: Mapping[str, Any],
) -> dict[str, Any]:
    _, control_state = control_store_module().load(project_root)
    strategy = obj(control_state.get("strategy"), "strategy")
    instance = obj(control_state.get("instance"), "instance")
    return {
        "$schema": "company-os.outcome-organization-request.v1",
        "mission_control": mission_binding(project_root, state["objective_id"]),
        "project_id": text(instance.get("project_id"), "project_id"),
        "program_version": strategy["program_version"],
        "work_id": binding["work_id"],
        "governed_outcome": state["original_objective"],
        "north_star": strategy.get("north_star") or state["original_objective"],
        "user_value": state["original_objective"],
        "rationale": "Materialize and improve the real artifact until independent evidence accepts the original objective.",
        "architecture": "Outcome closed loop organization compiled from current artifact requirements or dominant bottleneck.",
        "dependencies": ["Current Company OS outcome contracts and evaluator capabilities"],
        "non_goals": ["Treat process completion as product acceptance"],
        "constraints": ["Production narratives are inadmissible for final acceptance", "Passing dimensions must be preserved during rework"],
        "outcome_control": dict(binding),
        "goal_route": goal_route_binding(project_root, state["objective_id"]),
    }


def compile_current_fabric(project_root: Path, state: Mapping[str, Any], binding: Mapping[str, Any]) -> str:
    base = workspace(project_root, state["objective_id"])
    loop_path = base / "outcome-loop.json"
    phase = read_json(loop_path, "outcome loop").get("phase")
    work_class = {"build_candidate": "implementation", "rework": "repair", "evaluate": "evaluation"}.get(phase)
    if work_class is None:
        raise DirectorError("E_PHASE", f"cannot compile execution fabric for phase {phase!r}")
    admission = admit_mission_work(
        project_root,
        state["objective_id"],
        work_class=work_class,
        task_id=f"outcome-{phase}",
        manager_id="outcome-director",
    )
    request = organization_request(project_root, state, binding)
    request["work_admission"] = admission
    request_path = base / "runtime/outcome-organization-request.json"
    write_json(request_path, request)
    try:
        manifest = organization_module().compile_manifest(
            project_root,
            relative(project_root, loop_path),
            request,
        )
    except Exception as exc:
        raise DirectorError(getattr(exc, "code", "E_ORGANIZATION"), f"outcome organization failed: {exc}") from exc
    phase = read_json(loop_path, "outcome loop").get("phase")
    manifest_path = base / f"runtime/{phase}-fabric.json"
    write_json(manifest_path, manifest)
    return relative(project_root, manifest_path)


def advance(project_root: Path, objective_id: str) -> dict[str, Any]:
    project_root = project_root.resolve()
    state = load_state(project_root, objective_id)
    base = workspace(project_root, objective_id)
    ingest_reality_spike_if_present(project_root, objective_id)
    refresh_mission_state(project_root, objective_id)
    stage = state["stage"]

    if stage == "discovery":
        proposals = proposal_paths(base)
        missing = [relative(project_root, path) for path in proposals if not path.is_file()]
        if missing:
            discovery_binding = bind_discovery_fabric(project_root, objective_id, state["artifacts"]["discovery_fabric"])
            verify_bound_discovery_fabric(project_root, objective_id, state["artifacts"]["discovery_fabric"])
            state["next_action"] = next_execute_fabric(
                "discovery",
                state["artifacts"]["discovery_fabric"],
                reason="Discovery proposals are still missing: " + ", ".join(missing),
            )
            state["next_action"].update(discovery_binding)
            return save_state(project_root, state)
        base_request = obj(
            read_json(base / "outcome-request.json", "outcome request"),
            "outcome request",
        )
        proposal_values = [obj(read_json(path, "discovery proposal"), "discovery proposal") for path in proposals]
        try:
            measurable_request, measurable_contract = synthesis_module().synthesize(
                base_request,
                proposal_values,
            )
        except Exception as exc:
            raise DirectorError(getattr(exc, "code", "E_SYNTHESIS"), f"outcome synthesis failed: {exc}") from exc
        write_json(base / "measurable-outcome-request.json", measurable_request)
        write_json(base / "measurable-outcome-contract.json", measurable_contract)
        stack_module().materialize(
            base / "measurable-outcome-request.json",
            base / "runtime",
        )
        final_artifact_contract = obj(read_json(base / "runtime/artifact-contract.json", "artifact contract"), "artifact contract")
        mission = mission_control_module().update_scope(load_mission_state(project_root, objective_id), final_artifact_contract)
        save_mission_state(project_root, mission)
        first_reality_path = base / "first-reality-contract.json"
        write_json(first_reality_path, mission["first_reality"])
        first_artifact_contract = compile_first_reality_artifact_contract(final_artifact_contract, mission["first_reality"])
        first_artifact_path = base / "runtime/first-reality-artifact-contract.json"
        write_json(first_artifact_path, first_artifact_contract)
        state["stage"] = "control"
        state["artifacts"].update(
            {
                "measurable_outcome_request": relative(project_root, base / "measurable-outcome-request.json"),
                "measurable_outcome_contract": relative(project_root, base / "measurable-outcome-contract.json"),
                "artifact_contract": relative(project_root, base / "runtime/artifact-contract.json"),
                "evaluator_contract": relative(project_root, base / "runtime/evaluator-contract.json"),
                "benchmark_contract": relative(project_root, base / "runtime/benchmark-contract.json"),
                "first_reality_contract": relative(project_root, first_reality_path),
                "first_reality_artifact_contract": relative(project_root, first_artifact_path),
            }
        )
        state["history"].append({"event": "discovery_synthesized"})
        state = save_state(project_root, state)
        return advance(project_root, objective_id)

    if stage == "evaluator_capability":
        evaluator_contract = obj(
            read_json(base / "runtime/evaluator-contract.json", "evaluator contract"),
            "evaluator contract",
        )
        registry_path = base / "runtime/evaluator-adapter-registry.json"
        try:
            registry = registry_module().build_registry(project_root, evaluator_contract)
        except Exception as exc:
            if getattr(exc, "code", None) != "E_ADAPTER_MISSING":
                raise DirectorError(getattr(exc, "code", "E_ADAPTER"), f"evaluator registration failed: {exc}") from exc
            build = evaluator_build_module().compile_manifest(
                project_root,
                relative(project_root, base / "runtime/evaluator-contract.json"),
                relative(project_root, base / "runtime/artifact-contract.json"),
                relative(project_root, base / "runtime/benchmark-contract.json"),
            )
            if build.get("complete") is True:
                raise DirectorError("E_ADAPTER", "evaluator registry reported missing adapter but build compiler found no missing capability")
            build_path = base / "runtime/evaluator-build-fabric.json"
            write_json(build_path, build["fabric"])
            state["next_action"] = next_execute_fabric(
                "evaluator_capability",
                relative(project_root, build_path),
                reason="Required evaluator adapter bytes are missing.",
            )
            return save_state(project_root, state)
        write_json(registry_path, registry)
        state["artifacts"]["evaluator_adapter_registry"] = relative(project_root, registry_path)
        state["stage"] = "calibration"
        state["history"].append({"event": "evaluator_adapters_registered", "registry_sha256": registry["registry_sha256"]})
        state = save_state(project_root, state)
        return advance(project_root, objective_id)

    if stage == "calibration":
        evaluator_contract = obj(
            read_json(base / "runtime/evaluator-contract.json", "evaluator contract"),
            "evaluator contract",
        )
        receipts, calibrated = verified_calibrations(project_root, base, evaluator_contract)
        required = {
            item["evaluator_id"]
            for item in evaluator_contract.get("evaluators", [])
            if isinstance(item, Mapping) and item.get("required") is True
        }
        if not required.issubset(calibrated):
            result = calibration_fabric_module().compile_manifest(
                project_root,
                relative(project_root, base / "runtime/evaluator-contract.json"),
                relative(project_root, base / "runtime/artifact-contract.json"),
                relative(project_root, base / "runtime/benchmark-contract.json"),
                relative(project_root, base / "runtime/evaluator-adapter-registry.json"),
                calibrated,
            )
            if result.get("complete") is True:
                raise DirectorError("E_CALIBRATION", "required calibration receipts are missing but calibration compiler found no work")
            calibration_path = base / "runtime/calibration-fabric.json"
            write_json(calibration_path, result["fabric"])
            state["next_action"] = next_execute_fabric(
                "calibration",
                relative(project_root, calibration_path),
                reason="Required evaluators have not yet proven strict quality discrimination.",
            )
            return save_state(project_root, state)
        state["stage"] = "control"
        state["history"].append({"event": "evaluators_calibrated", "evaluator_ids": sorted(calibrated)})
        state = save_state(project_root, state)
        return advance(project_root, objective_id)

    if stage == "control":
        outcome, artifacts, evaluators, benchmarks = load_contracts(base)
        loop_path = base / "outcome-loop.json"
        loop = obj(read_json(loop_path, "outcome loop"), "outcome loop")
        phase = loop.get("phase")
        if phase == "discovery":
            # Build the first real candidate before spending the mission on evaluator
            # construction/calibration. Empty calibration bindings are valid for a
            # bounded, reversible pilot.
            pilot_artifacts = obj(read_json(base / "runtime/first-reality-artifact-contract.json", "first reality artifact contract"), "first reality artifact contract")
            binding, portable = build_outcome_control(
                project_root,
                state,
                outcome,
                pilot_artifacts,
                evaluators,
                benchmarks,
                [],
                force_lane="pilot",
                artifact_contract_file=base / "runtime/first-reality-artifact-contract.json",
            )
            try:
                bound_loop = outcome_loop_module().bind_control(project_root, loop, portable)
            except Exception as exc:
                raise DirectorError(getattr(exc, "code", "E_LOOP"), f"outcome loop pilot binding failed: {exc}") from exc
            write_json(loop_path, bound_loop)
            state["history"].append({"event": "first_reality_pilot_bound", "execution_lane": "pilot"})
        elif phase == "evaluate":
            calibrations, calibrated = verified_calibrations(project_root, base, evaluators)
            required = {item["evaluator_id"] for item in evaluators.get("evaluators", []) if isinstance(item, Mapping) and item.get("required") is True}
            if not required.issubset(calibrated):
                state["stage"] = "calibration"
                return save_state(project_root, state)
            binding, portable = build_outcome_control(project_root, state, outcome, artifacts, evaluators, benchmarks, calibrations, force_lane="production_scale")
            try:
                refreshed = outcome_loop_module().refresh_control(project_root, loop, portable)
            except Exception as exc:
                raise DirectorError(getattr(exc, "code", "E_LOOP"), f"outcome loop control refresh failed: {exc}") from exc
            write_json(loop_path, refreshed)
            state["history"].append({"event": "outcome_control_promoted_after_candidate", "execution_lane": "production_scale"})
        else:
            raise DirectorError("E_PHASE", f"control stage cannot bind loop phase {phase!r}")
        state["stage"] = "loop"
        state["artifacts"]["outcome_control_state"] = relative(project_root, base / "runtime/outcome-control-state.json")
        if portable["execution_lane"] == "production_scale":
            state["artifacts"]["scale_authorization"] = relative(project_root, base / "runtime/scale-authorization.json")
        state = save_state(project_root, state)
        return advance(project_root, objective_id)

    if stage == "loop":
        loop_path = base / "outcome-loop.json"
        loop = obj(read_json(loop_path, "outcome loop"), "outcome loop")
        phase = loop.get("phase")
        if phase == "accepted":
            state["stage"] = "accepted"
            state["next_action"] = {"action": "complete", "stage": "accepted", "candidate_id": loop.get("acceptance", {}).get("candidate_id"), "receipt_sha256": loop.get("acceptance", {}).get("receipt_sha256")}
            state["history"].append({"event": "objective_accepted"})
            return save_state(project_root, state)
        if phase == "reality":
            template = obj(obj(loop.get("next_action"), "loop.next_action").get("request_template"), "reality request template")
            request_path = base / "runtime/reality-request.json"; receipt_path = base / "runtime/reality-receipt.json"
            write_json(request_path, template)
            try: receipt = reality_module().accept(project_root, template)
            except Exception as exc: raise DirectorError(getattr(exc, "code", "E_REALITY"), f"reality acceptance failed: {exc}") from exc
            write_json(receipt_path, receipt)
            try: updated_loop = outcome_loop_module().record_reality(project_root, loop, relative(project_root, receipt_path))
            except Exception as exc: raise DirectorError(getattr(exc, "code", "E_LOOP"), f"outcome loop rejected reality receipt: {exc}") from exc
            write_json(loop_path, updated_loop)
            finalize_mission_acceptance(project_root, objective_id, updated_loop, receipt_path, receipt)
            return advance(project_root, objective_id)
        if phase not in {"build_candidate", "rework", "evaluate"}:
            raise DirectorError("E_PHASE", f"unsupported outcome loop phase: {phase}")

        # Evaluator capability is just-in-time. Until a real candidate exists the
        # organization spends its scarce budget on product reality, not on building
        # and auditing hypothetical judges.
        if phase == "evaluate":
            control_state = obj(read_json(base / "runtime/outcome-control-state.json", "outcome control state"), "outcome control state")
            if control_state.get("execution_lane") == "pilot":
                mission = refresh_mission_state(project_root, objective_id)
                if not mission_control_module().reality_signals(mission)["connected_vertical_slice"]:
                    raise DirectorError("E_FIRST_REALITY", "pilot candidate reached evaluation without connected First Reality evidence")
                state["stage"] = "control"
                state["history"].append({"event": "first_reality_connected", "mission_state_sha256": mission["state_sha256"]})
                state = save_state(project_root, state)
                return advance(project_root, objective_id)
            evaluator_contract = obj(read_json(base / "runtime/evaluator-contract.json", "evaluator contract"), "evaluator contract")
            registry_path = base / "runtime/evaluator-adapter-registry.json"
            try:
                registry = registry_module().build_registry(project_root, evaluator_contract)
            except Exception as exc:
                if getattr(exc, "code", None) != "E_ADAPTER_MISSING":
                    raise DirectorError(getattr(exc, "code", "E_ADAPTER"), f"evaluator registration failed: {exc}") from exc
                state["stage"] = "evaluator_capability"
                state["history"].append({"event": "evaluator_capability_deferred_until_candidate"})
                state = save_state(project_root, state)
                return advance(project_root, objective_id)
            write_json(registry_path, registry)
            state["artifacts"]["evaluator_adapter_registry"] = relative(project_root, registry_path)
            receipts, calibrated = verified_calibrations(project_root, base, evaluator_contract)
            required = {item["evaluator_id"] for item in evaluator_contract.get("evaluators", []) if isinstance(item, Mapping) and item.get("required") is True}
            if not required.issubset(calibrated):
                state["stage"] = "calibration"
                state = save_state(project_root, state)
                return advance(project_root, objective_id)
            control_state = obj(read_json(base / "runtime/outcome-control-state.json", "outcome control state"), "outcome control state")
            if control_state.get("execution_lane") == "pilot":
                state["stage"] = "control"
                state = save_state(project_root, state)
                return advance(project_root, objective_id)

        control_state = obj(read_json(base / "runtime/outcome-control-state.json", "outcome control state"), "outcome control state")
        binding = {"$schema": "company-os.outcome-control-binding.v1", "execution_lane": control_state["execution_lane"], "project_id": control_state["project_id"], "program_version": control_state["program_version"], "work_id": control_state["work_id"], "governed_outcome": control_state["governed_outcome"], "objective_id": control_state["objective_id"], "outcome_contract_path": control_state["outcome"]["path"], "artifact_contract_path": control_state["artifacts"]["path"], "evaluator_contract_path": control_state["evaluators"]["path"], "benchmark_contract_path": control_state["benchmarks"]["path"], "calibration_receipts_path": control_state["calibrations"]["path"], "scale_authorization_path": control_state["scale_authorization"]["path"]}
        manifest_path = compile_current_fabric(project_root, state, binding)
        fabric = obj(read_json(project_root / Path(*manifest_path.split("/")), "outcome fabric"), "outcome fabric")

        if phase in {"build_candidate", "rework"}:
            candidate_id = f"candidate-{int(loop.get('iteration', 0)) + 1:03d}"
            try: candidate = candidate_assembler_module().assemble(project_root, fabric, candidate_id)
            except Exception as exc:
                if getattr(exc, "code", None) != "E_MANIFEST_MISSING": raise DirectorError(getattr(exc, "code", "E_CANDIDATE_HANDOFF"), f"production artifact handoff is invalid: {exc}") from exc
            else:
                candidate_path = base / f"runtime/{candidate_id}.json"; write_json(candidate_path, candidate)
                record_candidate_mission_evidence(project_root, objective_id, candidate)
                record_candidate_goal_evidence(project_root, objective_id, candidate)
                checkpoint = checkpoint_candidate(project_root, objective_id, candidate)
                try: updated_loop = outcome_loop_module().record_candidate(project_root, loop, candidate)
                except Exception as exc: raise DirectorError(getattr(exc, "code", "E_CANDIDATE"), f"assembled candidate was rejected by outcome loop: {exc}") from exc
                write_json(loop_path, updated_loop)
                state["history"].append({"event": "candidate_auto_assembled", "candidate_id": candidate_id, "candidate_path": relative(project_root, candidate_path), "checkpoint": checkpoint})
                save_state(project_root, state); return advance(project_root, objective_id)

        if phase == "evaluate":
            candidates = loop.get("candidates")
            if not isinstance(candidates, list) or not candidates: raise DirectorError("E_EVALUATION", "evaluate phase has no current candidate")
            candidate_id = text(candidates[-1].get("candidate_id"), "current candidate_id")
            try: batch = evaluation_assembler_module().assemble(project_root, fabric, candidate_id)
            except Exception as exc:
                if getattr(exc, "code", None) != "E_RECEIPT_MISSING": raise DirectorError(getattr(exc, "code", "E_EVALUATION_HANDOFF"), f"independent evaluation handoff is invalid: {exc}") from exc
            else:
                batch_path = base / f"runtime/{candidate_id}-evaluations.json"; write_json(batch_path, batch)
                try: updated_loop = outcome_loop_module().record_evaluations(project_root, loop, batch)
                except Exception as exc: raise DirectorError(getattr(exc, "code", "E_EVALUATION"), f"assembled evaluation batch was rejected by outcome loop: {exc}") from exc
                write_json(loop_path, updated_loop)
                state["history"].append({"event": "evaluations_auto_assembled", "candidate_id": candidate_id, "batch_path": relative(project_root, batch_path)})
                save_state(project_root, state); return advance(project_root, objective_id)

        state["next_action"] = next_execute_fabric(phase, manifest_path, reason=f"The outcome loop is waiting for real {phase} work against the current content bound state.")
        state["next_action"]["loop_state_path"] = relative(project_root, loop_path); state["next_action"]["loop_phase"] = phase; state["next_action"]["loop_next_action"] = loop.get("next_action")
        state["next_action"]["required_handoff"] = "Each production worker must write artifact-manifest.json in its exact write scope." if phase in {"build_candidate", "rework"} else "Each independent evaluator worker must write execution-receipt.json in its exact write scope."
        return save_state(project_root, state)

    if stage == "accepted":
        return state

    raise DirectorError("E_STAGE", f"unsupported director stage: {stage}")


def record_candidate(project_root: Path, objective_id: str, candidate_path: Path) -> dict[str, Any]:
    state = load_state(project_root, objective_id)
    if state.get("stage") != "loop":
        raise DirectorError("E_STAGE", "candidate can only be recorded during the outcome loop")
    base = workspace(project_root, objective_id)
    loop_path = base / "outcome-loop.json"
    loop = obj(read_json(loop_path, "outcome loop"), "outcome loop")
    candidate = obj(read_json(candidate_path, "candidate"), "candidate")
    try:
        updated = outcome_loop_module().record_candidate(project_root, loop, candidate)
    except Exception as exc:
        raise DirectorError(getattr(exc, "code", "E_CANDIDATE"), f"candidate rejected: {exc}") from exc
    write_json(loop_path, updated)
    state["history"].append({"event": "candidate_recorded", "candidate_id": candidate.get("candidate_id")})
    save_state(project_root, state)
    return advance(project_root, objective_id)


def record_evaluations(project_root: Path, objective_id: str, batch_path: Path) -> dict[str, Any]:
    state = load_state(project_root, objective_id)
    if state.get("stage") != "loop":
        raise DirectorError("E_STAGE", "evaluations can only be recorded during the outcome loop")
    base = workspace(project_root, objective_id)
    loop_path = base / "outcome-loop.json"
    loop = obj(read_json(loop_path, "outcome loop"), "outcome loop")
    batch = obj(read_json(batch_path, "evaluation batch"), "evaluation batch")
    try:
        updated = outcome_loop_module().record_evaluations(project_root, loop, batch)
    except Exception as exc:
        raise DirectorError(getattr(exc, "code", "E_EVALUATION"), f"evaluation batch rejected: {exc}") from exc
    write_json(loop_path, updated)
    state["history"].append({"event": "evaluations_recorded", "candidate_id": batch.get("candidate_id")})
    save_state(project_root, state)
    return advance(project_root, objective_id)


def status(project_root: Path, objective_id: str) -> dict[str, Any]:
    state = load_state(project_root, objective_id)
    mission = load_mission_state(project_root, objective_id)
    return {
        "objective_id": state["objective_id"],
        "original_objective": state["original_objective"],
        "stage": state["stage"],
        "next_action": state["next_action"],
        "director_sha256": state["director_sha256"],
        "goal_route": goal_route_module().summary(load_goal_route(project_root, objective_id)),
        "mission_execution": {
            "status": mission["status"],
            "mission_class": mission["mission_class"],
            "reality": mission_control_module().reality_signals(mission),
            "governor_decision": mission["governor_decision"],
            "deadline_status": mission["deadline_status"],
            "checkpoint": mission.get("checkpoint"),
        },
    }


def main() -> int:
    parser = argparse.ArgumentParser()
    sub = parser.add_subparsers(dest="command", required=True)
    start_parser = sub.add_parser("start")
    start_parser.add_argument("--project-root", type=Path, required=True)
    start_parser.add_argument("--objective-id", required=True)
    start_parser.add_argument("--objective", required=True)
    start_parser.add_argument("--kickoff-profile", type=Path)
    start_parser.add_argument("--autonomy-mode", choices=["guided_interview", "guided_defaults", "autonomous_research"])
    advance_parser = sub.add_parser("advance")
    advance_parser.add_argument("--project-root", type=Path, required=True)
    advance_parser.add_argument("--objective-id", required=True)
    status_parser = sub.add_parser("status")
    status_parser.add_argument("--project-root", type=Path, required=True)
    status_parser.add_argument("--objective-id", required=True)
    candidate_parser = sub.add_parser("record-candidate")
    candidate_parser.add_argument("--project-root", type=Path, required=True)
    candidate_parser.add_argument("--objective-id", required=True)
    candidate_parser.add_argument("--candidate", type=Path, required=True)
    evaluation_parser = sub.add_parser("record-evaluations")
    evaluation_parser.add_argument("--project-root", type=Path, required=True)
    evaluation_parser.add_argument("--objective-id", required=True)
    evaluation_parser.add_argument("--batch", type=Path, required=True)
    args = parser.parse_args()
    try:
        if args.command == "start":
            kickoff = obj(read_json(args.kickoff_profile, "kickoff profile"), "kickoff profile") if args.kickoff_profile else None
            result = start(args.project_root, args.objective_id, args.objective, kickoff_profile=kickoff, autonomy_mode=args.autonomy_mode)
        elif args.command == "advance":
            result = advance(args.project_root, args.objective_id)
        elif args.command == "status":
            print(json.dumps({"ok": True, **status(args.project_root, args.objective_id)}, sort_keys=True))
            return 0
        elif args.command == "record-candidate":
            result = record_candidate(args.project_root, args.objective_id, args.candidate)
        else:
            result = record_evaluations(args.project_root, args.objective_id, args.batch)
        print(
            json.dumps(
                {
                    "ok": True,
                    "objective_id": result["objective_id"],
                    "stage": result["stage"],
                    "next_action": result["next_action"],
                    "director_sha256": result["director_sha256"],
                },
                sort_keys=True,
            )
        )
        return 0
    except DirectorError as exc:
        print(json.dumps({"ok": False, "code": exc.code, "error": exc.message}, sort_keys=True))
        return 2


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Project-isolated transactional control store for Company OS.

SQLite is authoritative. JSON and JSONL are deterministic compatibility
exports and may always be rebuilt from committed database truth.
"""

from __future__ import annotations

import hashlib
import json
import os
import sqlite3
import sys
import uuid
from copy import deepcopy
from pathlib import Path
from typing import Any


STORE_SCHEMA_VERSION = 1
DATABASE_NAME = "control.db"


class StoreError(ValueError):
    pass


def canonical_json(value: Any) -> str:
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=True, allow_nan=False)


def json_bytes(value: Any, *, pretty: bool = False) -> bytes:
    if pretty:
        return (json.dumps(value, indent=2, allow_nan=False) + "\n").encode("utf-8")
    return (canonical_json(value) + "\n").encode("utf-8")


def sha256_bytes(value: bytes) -> str:
    return hashlib.sha256(value).hexdigest()


def governance_digest(state: dict[str, Any]) -> str:
    """Hash governable state under the controller's stable exclusion contract."""
    payload = deepcopy(state)
    controller = payload.get("controller", {})
    for field in (
        "validation", "validated", "lease", "lease_generation", "last_cycle_at",
        "schedule_enabled", "consumed_grant_nonces",
    ):
        controller.pop(field, None)
    payload.get("instance", {}).pop("status", None)
    return sha256_bytes(canonical_json(payload).encode("utf-8"))


def _store_layout(project: Path, *, require_database: bool = False) -> tuple[Path, Path]:
    """Bind one project to a real, non-symlink control directory and database."""
    project = project.resolve()
    directory = project / ".company-os"
    if directory.is_symlink():
        raise StoreError("control store directory must not be a symlink")
    path = directory / DATABASE_NAME
    if path.is_symlink():
        raise StoreError("transactional control store path must not be a symlink")
    if require_database and not path.is_file():
        raise StoreError("transactional control store does not exist")
    return directory, path


def database_path(project: Path) -> Path:
    return _store_layout(project)[1]


def exists(project: Path) -> bool:
    return _store_layout(project)[1].is_file()


def connect(project: Path) -> sqlite3.Connection:
    path = _store_layout(project, require_database=True)[1]
    connection = sqlite3.connect(f"file:{path}?mode=rw", uri=True, timeout=10.0)
    return _configure_connection(connection, journal_mode="WAL")


def _configure_connection(
    connection: sqlite3.Connection,
    *,
    journal_mode: str,
) -> sqlite3.Connection:
    connection.row_factory = sqlite3.Row
    connection.execute("PRAGMA foreign_keys = ON")
    connection.execute("PRAGMA busy_timeout = 10000")
    connection.execute("PRAGMA synchronous = FULL")
    connection.execute(f"PRAGMA journal_mode = {journal_mode}")
    return connection


SCHEMA_SQL = """
CREATE TABLE IF NOT EXISTS store_metadata (
  singleton INTEGER PRIMARY KEY CHECK (singleton = 1),
  schema_version INTEGER NOT NULL,
  project_id TEXT NOT NULL,
  project_root TEXT NOT NULL,
  created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS state_revisions (
  revision INTEGER PRIMARY KEY CHECK (revision > 0),
  project_id TEXT NOT NULL,
  state_json TEXT NOT NULL,
  state_sha256 TEXT NOT NULL,
  event_id TEXT NOT NULL UNIQUE,
  created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS events (
  sequence INTEGER PRIMARY KEY AUTOINCREMENT,
  event_id TEXT NOT NULL UNIQUE,
  project_id TEXT NOT NULL,
  program_version INTEGER NOT NULL,
  event_type TEXT NOT NULL,
  payload_json TEXT NOT NULL,
  payload_sha256 TEXT NOT NULL,
  state_revision INTEGER NOT NULL UNIQUE REFERENCES state_revisions(revision)
);
CREATE TABLE IF NOT EXISTS legacy_events (
  sequence INTEGER PRIMARY KEY,
  project_id TEXT NOT NULL,
  payload_json TEXT NOT NULL,
  payload_sha256 TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS entities (
  project_id TEXT NOT NULL,
  entity_type TEXT NOT NULL,
  entity_id TEXT NOT NULL,
  program_version INTEGER,
  status TEXT,
  record_json TEXT NOT NULL,
  record_sha256 TEXT NOT NULL,
  state_revision INTEGER NOT NULL REFERENCES state_revisions(revision),
  PRIMARY KEY (project_id, entity_type, entity_id)
);
CREATE TABLE IF NOT EXISTS inbox_messages (
  project_id TEXT NOT NULL,
  channel TEXT NOT NULL,
  message_key TEXT NOT NULL,
  payload_sha256 TEXT NOT NULL,
  payload_json TEXT NOT NULL,
  status TEXT NOT NULL,
  state_revision INTEGER NOT NULL REFERENCES state_revisions(revision),
  PRIMARY KEY (project_id, channel, message_key)
);
CREATE TABLE IF NOT EXISTS outbox_messages (
  project_id TEXT NOT NULL,
  channel TEXT NOT NULL,
  message_key TEXT NOT NULL,
  payload_sha256 TEXT NOT NULL,
  payload_json TEXT NOT NULL,
  status TEXT NOT NULL CHECK (status IN ('pending','leased','succeeded','failed','cancelled')),
  attempt_count INTEGER NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
  not_before TEXT,
  created_revision INTEGER NOT NULL REFERENCES state_revisions(revision),
  updated_revision INTEGER NOT NULL REFERENCES state_revisions(revision),
  PRIMARY KEY (project_id, channel, message_key)
);
CREATE TABLE IF NOT EXISTS command_idempotency (
  project_id TEXT NOT NULL,
  command_scope TEXT NOT NULL,
  command_key TEXT NOT NULL,
  command_name TEXT NOT NULL,
  payload_sha256 TEXT NOT NULL,
  result_json TEXT NOT NULL,
  result_sha256 TEXT NOT NULL,
  state_revision INTEGER NOT NULL REFERENCES state_revisions(revision),
  created_at TEXT NOT NULL,
  PRIMARY KEY (project_id, command_scope, command_key)
);
CREATE INDEX IF NOT EXISTS entities_revision_idx ON entities(project_id, state_revision);
CREATE INDEX IF NOT EXISTS inbox_revision_idx ON inbox_messages(project_id, state_revision);
CREATE INDEX IF NOT EXISTS outbox_status_idx ON outbox_messages(project_id, status, not_before);
"""


def _metadata(connection: sqlite3.Connection) -> sqlite3.Row:
    row = connection.execute("SELECT * FROM store_metadata WHERE singleton = 1").fetchone()
    if row is None:
        raise StoreError("transactional control store metadata is missing")
    return row


def _assert_binding(connection: sqlite3.Connection, project: Path, state: dict[str, Any] | None = None) -> sqlite3.Row:
    metadata = _metadata(connection)
    expected_root = str(project.resolve())
    if metadata["schema_version"] != STORE_SCHEMA_VERSION:
        raise StoreError("transactional control store schema is unsupported")
    if metadata["project_root"] != expected_root:
        raise StoreError("transactional control store belongs to a different project root")
    if state is not None and metadata["project_id"] != state.get("instance", {}).get("project_id"):
        raise StoreError("transactional control store belongs to a different project ID")
    return metadata


def _load_latest(connection: sqlite3.Connection) -> tuple[int, dict[str, Any]]:
    row = connection.execute(
        "SELECT revision, state_json, state_sha256 FROM state_revisions ORDER BY revision DESC LIMIT 1"
    ).fetchone()
    if row is None:
        raise StoreError("transactional control store has no state revision")
    raw = row["state_json"].encode("utf-8")
    if sha256_bytes(raw) != row["state_sha256"]:
        raise StoreError("transactional control state revision hash is invalid")
    try:
        state = json.loads(row["state_json"])
    except json.JSONDecodeError as exc:
        raise StoreError(f"transactional control state JSON is invalid: {exc}") from None
    if not isinstance(state, dict):
        raise StoreError("transactional control state must be an object")
    return int(row["revision"]), state


def load(project: Path) -> tuple[int, dict[str, Any]]:
    connection = connect(project)
    try:
        _assert_binding(connection, project)
        revision, state = _load_latest(connection)
        _assert_binding(connection, project, state)
        return revision, state
    finally:
        connection.close()


def load_revision(project: Path, revision: int) -> dict[str, Any]:
    """Load one hash-verified historical revision for read-only comparison."""
    if not isinstance(revision, int) or isinstance(revision, bool) or revision < 1:
        raise StoreError("historical revision must be a positive integer")
    connection = connect(project)
    try:
        _assert_binding(connection, project)
        row = connection.execute(
            "SELECT state_json,state_sha256 FROM state_revisions WHERE revision=?",
            (revision,),
        ).fetchone()
        if row is None:
            raise StoreError("historical revision does not exist")
        raw = row["state_json"].encode("utf-8")
        if sha256_bytes(raw) != row["state_sha256"]:
            raise StoreError("historical state revision hash is invalid")
        try:
            state = json.loads(row["state_json"])
        except json.JSONDecodeError as exc:
            raise StoreError(f"historical state revision JSON is invalid: {exc}") from None
        if not isinstance(state, dict):
            raise StoreError("historical state revision must be an object")
        _assert_binding(connection, project, state)
        return state
    finally:
        connection.close()


def load_change_events(project: Path, after_revision: int, through_revision: int) -> list[dict[str, Any]]:
    """Return hash-verified, safely attributable governed events for a revision window."""
    if (
        not isinstance(after_revision, int) or isinstance(after_revision, bool)
        or not isinstance(through_revision, int) or isinstance(through_revision, bool)
        or after_revision < 0 or through_revision <= after_revision
    ):
        raise StoreError("event comparison revisions are invalid")
    connection = connect(project)
    try:
        metadata = _assert_binding(connection, project)
        rows = connection.execute(
            """
            SELECT e.state_revision,e.event_id,e.event_type,e.payload_json,e.payload_sha256,
                   i.command_name,i.command_key
            FROM events e
            LEFT JOIN command_idempotency i
              ON i.project_id=e.project_id AND i.state_revision=e.state_revision
            WHERE e.project_id=? AND e.state_revision>? AND e.state_revision<=?
            ORDER BY e.state_revision
            """,
            (metadata["project_id"], after_revision, through_revision),
        ).fetchall()
        events: list[dict[str, Any]] = []
        safe_reference_fields = (
            "evidence_id", "predecessor_evidence_id", "outcome_id", "work_id",
            "from_phase", "to_phase", "reviewer", "manager_id", "attempt_id",
        )
        for row in rows:
            raw = row["payload_json"].encode("utf-8")
            if sha256_bytes(raw) != row["payload_sha256"]:
                raise StoreError("change event payload hash is invalid")
            payload = json.loads(row["payload_json"])
            if not isinstance(payload, dict) or payload.get("event_id") != row["event_id"]:
                raise StoreError("change event identity is invalid")
            references = {
                field: payload[field]
                for field in safe_reference_fields
                if isinstance(payload.get(field), str) and payload[field]
            }
            events.append({
                "revision": int(row["state_revision"]),
                "event_type": row["event_type"],
                "command": row["command_name"],
                "command_key": row["command_key"],
                "references": references,
            })
        return events
    finally:
        connection.close()


def _entity_records(state: dict[str, Any]) -> list[tuple[str, str, int | None, str | None, dict[str, Any]]]:
    program_version = state.get("strategy", {}).get("program_version")
    records: list[tuple[str, str, int | None, str | None, dict[str, Any]]] = [
        ("program", f"program-{program_version}", program_version, state.get("instance", {}).get("status"), state.get("strategy", {})),
    ]
    portfolio = state.get("portfolio", {})
    for collection, entity_type in (
        ("committed_outcomes", "outcome"),
        ("active_work", "work"),
        ("completed_work", "work"),
        ("cancelled_work", "work"),
    ):
        for item in portfolio.get(collection, []):
            if isinstance(item, dict) and isinstance(item.get("id"), str):
                records.append((entity_type, item["id"], item.get("program_version"), item.get("status"), item))
    for item in state.get("feedback", {}).get("cycles", []):
        if isinstance(item, dict) and isinstance(item.get("id"), str):
            records.append(("cycle", item["id"], item.get("program_version"), item.get("status"), item))
    lease = state.get("controller", {}).get("lease")
    if isinstance(lease, dict) and isinstance(lease.get("lease_id"), str):
        records.append(("lease", lease["lease_id"], lease.get("program_version"), "active", lease))
    for item in state.get("runtime_adapter", {}).get("attempts", []):
        if isinstance(item, dict) and isinstance(item.get("attempt_id"), str):
            records.append(("runtime_attempt", item["attempt_id"], item.get("program_version"), item.get("status"), item))
    for bucket, items in state.get("evidence", {}).items():
        for item in items if isinstance(items, list) else []:
            if isinstance(item, dict) and isinstance(item.get("id"), str):
                records.append((f"evidence:{bucket}", item["id"], item.get("program_version"), "recorded", item))
    for collection in ("pending_adaptations", "applied_adaptations"):
        for item in state.get("feedback", {}).get(collection, []):
            if isinstance(item, dict) and isinstance(item.get("id"), str):
                records.append(("adaptation", item["id"], item.get("program_version"), item.get("status"), item))
    for collection, entity_type in (
        ("archived_adaptations", "adaptation_archive"),
        ("archived_quality_scorecards", "quality_archive"),
        ("archived_runtime_adapters", "runtime_archive"),
        ("program_transition_repairs", "program_transition_repair"),
    ):
        for item in state.get("feedback", {}).get(collection, []):
            if isinstance(item, dict) and isinstance(item.get("transition_id"), str):
                records.append(
                    (
                        entity_type,
                        item["transition_id"],
                        item.get("source_program_version"),
                        item.get("trigger", "repaired"),
                        item,
                    )
                )
    return records


def _replace_projections(connection: sqlite3.Connection, state: dict[str, Any], revision: int) -> None:
    project_id = state["instance"]["project_id"]
    connection.execute("DELETE FROM entities WHERE project_id = ?", (project_id,))
    for entity_type, entity_id, program_version, status, record in _entity_records(state):
        encoded = canonical_json(record)
        connection.execute(
            "INSERT INTO entities VALUES (?,?,?,?,?,?,?,?)",
            (project_id, entity_type, entity_id, program_version, status, encoded, sha256_bytes(encoded.encode()), revision),
        )
    connection.execute("DELETE FROM inbox_messages WHERE project_id = ?", (project_id,))
    inboxes = state.get("runtime_adapter", {}).get("observation_inboxes", {})
    if isinstance(inboxes, dict):
        for attempt_id, inbox in inboxes.items():
            if not isinstance(inbox, dict):
                continue
            for observation in inbox.get("trusted_observations", []):
                if not isinstance(observation, dict) or not isinstance(observation.get("event_key"), str):
                    continue
                encoded = canonical_json(observation)
                connection.execute(
                    "INSERT INTO inbox_messages VALUES (?,?,?,?,?,?,?)",
                    (
                        project_id,
                        f"runtime:{attempt_id}",
                        observation["event_key"],
                        sha256_bytes(encoded.encode()),
                        encoded,
                        "accepted",
                        revision,
                    ),
                )


def _insert_revision(connection: sqlite3.Connection, state: dict[str, Any], event: dict[str, Any]) -> int:
    metadata = _assert_binding(connection, Path(state["instance"]["project_root"]), state)
    current = connection.execute("SELECT COALESCE(MAX(revision), 0) AS value FROM state_revisions").fetchone()["value"]
    revision = int(current) + 1
    event_id = str(event.get("event_id") or uuid.uuid4().hex)
    event_payload = {**event, "event_id": event_id, "state_revision": revision}
    state_text = canonical_json(state)
    event_text = canonical_json(event_payload)
    connection.execute(
        "INSERT INTO state_revisions VALUES (?,?,?,?,?,?)",
        (revision, metadata["project_id"], state_text, sha256_bytes(state_text.encode()), event_id, event_payload.get("at")),
    )
    connection.execute(
        "INSERT INTO events(event_id,project_id,program_version,event_type,payload_json,payload_sha256,state_revision) VALUES (?,?,?,?,?,?,?)",
        (event_id, metadata["project_id"], event_payload.get("program_version"), event_payload.get("type"), event_text, sha256_bytes(event_text.encode()), revision),
    )
    _replace_projections(connection, state, revision)
    return revision


def _read_legacy_events(project: Path, project_id: str) -> list[tuple[int, str, str, str]]:
    path = project.resolve() / ".company-os" / "events.jsonl"
    if not path.exists():
        return []
    records: list[tuple[int, str, str, str]] = []
    for sequence, line in enumerate(path.read_text(encoding="utf-8").splitlines(), start=1):
        if not line.strip():
            continue
        try:
            value = json.loads(line)
        except json.JSONDecodeError as exc:
            raise StoreError(f"legacy event log line {sequence} is invalid: {exc}") from None
        if not isinstance(value, dict) or value.get("project_id") != project_id:
            raise StoreError(f"legacy event log line {sequence} is not bound to this project")
        encoded = canonical_json(value)
        records.append((sequence, project_id, encoded, sha256_bytes(encoded.encode())))
    return records


def initialize(project: Path, state: dict[str, Any], event: dict[str, Any]) -> int:
    project = project.resolve()
    directory, path = _store_layout(project)
    if path.is_file():
        revision, existing = load(project)
        if canonical_json(existing) != canonical_json(state):
            raise StoreError("transactional control store already exists with different state")
        repair_exports(project)
        return revision
    project_id = state.get("instance", {}).get("project_id")
    if not isinstance(project_id, str) or not project_id:
        raise StoreError("cannot initialize a control store without a project ID")
    if state.get("instance", {}).get("project_root") != str(project):
        raise StoreError("cannot initialize a control store for a different project root")
    if directory.exists() and not directory.is_dir():
        raise StoreError("control store directory must be a real directory")
    directory.mkdir(parents=True, exist_ok=True)
    if directory.is_symlink() or not directory.is_dir():
        raise StoreError("control store directory must be a real directory")
    legacy = _read_legacy_events(project, project_id)
    temporary = path.with_name(f".{path.name}.{uuid.uuid4().hex}.initializing")
    connection = _configure_connection(
        sqlite3.connect(temporary, timeout=10.0),
        journal_mode="DELETE",
    )
    try:
        connection.executescript(SCHEMA_SQL)
        connection.execute("BEGIN IMMEDIATE")
        connection.execute(
            "INSERT INTO store_metadata VALUES (1,?,?,?,?)",
            (STORE_SCHEMA_VERSION, project_id, str(project), event.get("at")),
        )
        connection.executemany("INSERT INTO legacy_events VALUES (?,?,?,?)", legacy)
        revision = _insert_revision(connection, state, event)
        connection.commit()
        with temporary.open("rb") as handle:
            os.fsync(handle.fileno())
        os.replace(temporary, path)
        directory_fd = os.open(path.parent, os.O_RDONLY)
        try:
            os.fsync(directory_fd)
        finally:
            os.close(directory_fd)
    except Exception:
        connection.rollback()
        connection.close()
        for suffix in ("", "-journal", "-wal", "-shm"):
            candidate = Path(str(temporary) + suffix)
            if candidate.exists():
                candidate.unlink()
        raise
    else:
        connection.close()
    repair_exports(project)
    return revision


class Transaction:
    def __init__(self, project: Path):
        self.project = project.resolve()
        self.connection = connect(self.project)
        self.connection.execute("BEGIN IMMEDIATE")
        _assert_binding(self.connection, self.project)
        self.base_revision, self.state = _load_latest(self.connection)
        _assert_binding(self.connection, self.project, self.state)
        self.staged_revision: int | None = None

    def load_revision(self, revision: int) -> dict[str, Any]:
        """Read one hash-verified prior state inside the governing write lock."""
        if not isinstance(revision, int) or isinstance(revision, bool) or revision < 1:
            raise StoreError("historical revision must be a positive integer")
        row = self.connection.execute(
            "SELECT state_json,state_sha256 FROM state_revisions WHERE revision=?",
            (revision,),
        ).fetchone()
        if row is None:
            raise StoreError("historical revision does not exist")
        raw = row["state_json"].encode("utf-8")
        if sha256_bytes(raw) != row["state_sha256"]:
            raise StoreError("transactional control state revision hash is invalid")
        try:
            state = json.loads(row["state_json"])
        except json.JSONDecodeError as exc:
            raise StoreError(f"transactional control state JSON is invalid: {exc}") from None
        if not isinstance(state, dict):
            raise StoreError("transactional control state must be an object")
        _assert_binding(self.connection, self.project, state)
        return state

    def load_event(self, revision: int) -> dict[str, Any]:
        """Read one fully verified historical event inside the governing lock."""
        if not isinstance(revision, int) or isinstance(revision, bool) or revision < 1:
            raise StoreError("historical event revision must be a positive integer")
        row = self.connection.execute(
            """
            SELECT event_id,project_id,program_version,event_type,payload_json,
                   payload_sha256,state_revision
            FROM events WHERE state_revision=?
            """,
            (revision,),
        ).fetchone()
        if row is None:
            raise StoreError("historical event does not exist")
        raw = row["payload_json"].encode("utf-8")
        if sha256_bytes(raw) != row["payload_sha256"]:
            raise StoreError("historical event payload hash is invalid")
        try:
            event = json.loads(row["payload_json"])
        except json.JSONDecodeError as exc:
            raise StoreError(f"historical event JSON is invalid: {exc}") from None
        if (
            not isinstance(event, dict)
            or event.get("event_id") != row["event_id"]
            or event.get("project_id") != row["project_id"]
            or event.get("program_version") != row["program_version"]
            or event.get("type") != row["event_type"]
            or event.get("state_revision") != row["state_revision"]
        ):
            raise StoreError("historical event does not match its authoritative row")
        return {
            "event": event,
            "payload_sha256": row["payload_sha256"],
        }

    def stage(self, state: dict[str, Any], event: dict[str, Any]) -> int:
        if self.staged_revision is not None:
            raise StoreError("one controller transaction may stage only one state/event pair")
        self.staged_revision = _insert_revision(self.connection, state, event)
        self.state = state
        return self.staged_revision

    def idempotency_lookup(
        self,
        *,
        scope: str,
        key: str,
        payload_sha256: str,
    ) -> dict[str, Any] | None:
        return idempotency_lookup(
            self.connection,
            self.state["instance"]["project_id"],
            scope,
            key,
            payload_sha256,
        )

    def record_idempotency(
        self,
        *,
        scope: str,
        key: str,
        command_name: str,
        payload_sha256: str,
        result: dict[str, Any],
        created_at: str,
    ) -> None:
        if self.staged_revision is None:
            raise StoreError("idempotency result requires a staged state/event revision")
        idempotency_record(
            self.connection,
            project_id=self.state["instance"]["project_id"],
            scope=scope,
            key=key,
            command_name=command_name,
            payload_sha256=payload_sha256,
            result=result,
            state_revision=self.staged_revision,
            created_at=created_at,
        )

    def outbox_lookup(
        self,
        *,
        channel: str,
        key: str,
        payload_sha256: str,
    ) -> dict[str, Any] | None:
        return outbox_lookup(
            self.connection,
            self.state["instance"]["project_id"],
            channel,
            key,
            payload_sha256,
        )

    def enqueue_outbox(
        self,
        *,
        channel: str,
        key: str,
        payload: dict[str, Any],
        not_before: str | None = None,
    ) -> dict[str, Any]:
        if self.staged_revision is None:
            raise StoreError("outbox enqueue requires a staged state/event revision")
        return outbox_enqueue(
            self.connection,
            project_id=self.state["instance"]["project_id"],
            channel=channel,
            key=key,
            payload=payload,
            state_revision=self.staged_revision,
            not_before=not_before,
        )

    def transition_outbox(
        self,
        *,
        channel: str,
        key: str,
        status: str,
    ) -> dict[str, Any]:
        if self.staged_revision is None:
            raise StoreError("outbox transition requires a staged state/event revision")
        return outbox_transition(
            self.connection,
            project_id=self.state["instance"]["project_id"],
            channel=channel,
            key=key,
            status=status,
            state_revision=self.staged_revision,
        )

    def reconcile_outbox(
        self,
        *,
        channel: str,
        key: str,
        status: str,
        expected_status: str | None = None,
        payload_sha256: str | None = None,
    ) -> dict[str, Any]:
        """Apply one provider/restart observation under the staged revision.

        Reconciliation is deliberately not a convenience auto-commit: callers
        must stage the corresponding state and event first, so the observation
        and outbox transition commit atomically.
        """
        if self.staged_revision is None:
            raise StoreError("outbox reconciliation requires a staged state/event revision")
        return outbox_reconcile(
            self.connection,
            project_id=self.state["instance"]["project_id"],
            channel=channel,
            key=key,
            status=status,
            state_revision=self.staged_revision,
            expected_status=expected_status,
            payload_sha256=payload_sha256,
        )

    def close(self, success: bool) -> None:
        try:
            if success and self.staged_revision is not None:
                self.connection.commit()
            else:
                self.connection.rollback()
        finally:
            self.connection.close()
        if success and self.staged_revision is not None:
            try:
                repair_exports(self.project)
            except Exception as exc:
                # Authority is already committed. Reporting command failure here
                # would invite a duplicate retry; export drift is observable and
                # repaired on the next governed open.
                print(
                    json.dumps(
                        {
                            "warning": "transaction committed but compatibility exports could not be published",
                            "revision": self.staged_revision,
                            "error": str(exc),
                        }
                    ),
                    file=sys.stderr,
                )


def begin(project: Path) -> Transaction:
    return Transaction(project)


def _export_values(connection: sqlite3.Connection) -> tuple[bytes, bytes, int]:
    revision, state = _load_latest(connection)
    state_export = json_bytes(state, pretty=True)
    event_lines: list[str] = []
    for row in connection.execute("SELECT payload_json FROM legacy_events ORDER BY sequence"):
        event_lines.append(row["payload_json"])
    for row in connection.execute("SELECT payload_json FROM events ORDER BY sequence"):
        event_lines.append(row["payload_json"])
    events_export = (("\n".join(event_lines) + "\n") if event_lines else "").encode("utf-8")
    return state_export, events_export, revision


def _atomic_bytes(path: Path, value: bytes) -> None:
    if path.is_symlink():
        raise StoreError(f"refusing to write through symlink: {path.name}")
    temporary = path.with_name(f".{path.name}.{uuid.uuid4().hex}.tmp")
    try:
        with temporary.open("xb") as handle:
            handle.write(value)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, path)
        directory_fd = os.open(path.parent, os.O_RDONLY)
        try:
            os.fsync(directory_fd)
        finally:
            os.close(directory_fd)
    finally:
        if temporary.exists():
            temporary.unlink()


def repair_exports(project: Path) -> dict[str, Any]:
    project = project.resolve()
    directory, _ = _store_layout(project, require_database=True)
    connection = connect(project)
    try:
        _assert_binding(connection, project)
        state_bytes, events_bytes, revision = _export_values(connection)
    finally:
        connection.close()
    for name in ("control.json", "events.jsonl"):
        if (directory / name).is_symlink():
            raise StoreError(f"{name} must not be a symlink")
    _atomic_bytes(directory / "control.json", state_bytes)
    _atomic_bytes(directory / "events.jsonl", events_bytes)
    return {"revision": revision, "state_sha256": sha256_bytes(state_bytes), "events_sha256": sha256_bytes(events_bytes)}


def _audit_program_transition_repair_events(
    revision_rows: list[sqlite3.Row],
    event_rows: list[sqlite3.Row],
    errors: list[str],
) -> None:
    """Replay the exact historical state bound by each transition repair grant."""
    revisions = {int(row["revision"]): row for row in revision_rows}
    repair_event_counts: dict[str, int] = {}
    for event_row in event_rows:
        if event_row["event_type"] != "program_transition_repaired":
            continue
        label = f"program transition repair event at revision {event_row['state_revision']}"
        try:
            event = json.loads(event_row["payload_json"])
        except json.JSONDecodeError:
            errors.append(f"{label} contains invalid JSON")
            continue
        repair_revision = int(event_row["state_revision"])
        source_revision = event.get("source_state_revision")
        transition_revision = event.get("transition_state_revision")
        if (
            not isinstance(source_revision, int)
            or not isinstance(transition_revision, int)
            or transition_revision != source_revision + 1
            or repair_revision != transition_revision + 1
        ):
            errors.append(f"{label} does not bind three contiguous revisions")
            continue
        source_row = revisions.get(source_revision)
        transition_row = revisions.get(transition_revision)
        repair_row = revisions.get(repair_revision)
        if source_row is None or transition_row is None or repair_row is None:
            errors.append(f"{label} references missing state history")
            continue
        if (
            event.get("source_state_digest") != source_row["state_sha256"]
            or event.get("transition_state_digest") != transition_row["state_sha256"]
        ):
            errors.append(f"{label} historical state digest does not match")
        try:
            source_state = json.loads(source_row["state_json"])
            transition_state = json.loads(transition_row["state_json"])
            repair_state = json.loads(repair_row["state_json"])
        except json.JSONDecodeError:
            errors.append(f"{label} cannot reconstruct retained state")
            continue
        transition_id = event.get("transition_id")
        if isinstance(transition_id, str):
            repair_event_counts[transition_id] = repair_event_counts.get(transition_id, 0) + 1
        adaptation_archive = next(
            (
                item for item in repair_state.get("feedback", {}).get("archived_adaptations", [])
                if isinstance(item, dict) and item.get("transition_id") == transition_id
            ),
            None,
        )
        quality_archive = next(
            (
                item for item in repair_state.get("feedback", {}).get("archived_quality_scorecards", [])
                if isinstance(item, dict) and item.get("transition_id") == transition_id
            ),
            None,
        )
        runtime_archive = next(
            (
                item for item in repair_state.get("feedback", {}).get("archived_runtime_adapters", [])
                if isinstance(item, dict) and item.get("transition_id") == transition_id
            ),
            None,
        )
        repair_record = next(
            (
                item for item in repair_state.get("feedback", {}).get("program_transition_repairs", [])
                if isinstance(item, dict) and item.get("transition_id") == transition_id
            ),
            None,
        )
        if not all(
            isinstance(item, dict)
            for item in (adaptation_archive, quality_archive, runtime_archive, repair_record)
        ):
            errors.append(f"{label} lacks its retained transition records")
            continue
        transition_event_row = next(
            (
                row for row in event_rows
                if int(row["state_revision"]) == transition_revision
            ),
            None,
        )
        retained_payload = repair_record.get("payload")
        transition_binding = (
            retained_payload.get("transition_event")
            if isinstance(retained_payload, dict)
            else None
        )
        if transition_event_row is None or not isinstance(transition_binding, dict):
            errors.append(f"{label} lacks its exact retained replace-program event")
        else:
            try:
                transition_event = json.loads(transition_event_row["payload_json"])
            except json.JSONDecodeError:
                transition_event = None
            strategy_transition = transition_binding.get("strategy_transition")
            expected_strategy_transition = {
                "source_strategy": source_state.get("strategy"),
                "replacement_strategy": transition_state.get("strategy"),
            }
            if (
                not isinstance(transition_event, dict)
                or transition_event_row["event_type"] != "program_replaced"
                or transition_binding.get("event_id") != transition_event_row["event_id"]
                or transition_binding.get("event_type") != transition_event_row["event_type"]
                or transition_binding.get("project_id") != transition_event_row["project_id"]
                or transition_binding.get("program_version") != transition_event_row["program_version"]
                or transition_binding.get("state_revision") != transition_revision
                or transition_binding.get("old_program_version")
                != source_state.get("strategy", {}).get("program_version")
                or transition_binding.get("reason") != transition_event.get("reason")
                or transition_binding.get("event_payload_sha256")
                != transition_event_row["payload_sha256"]
                or strategy_transition != expected_strategy_transition
                or transition_binding.get("strategy_transition_digest")
                != sha256_bytes(canonical_json(expected_strategy_transition).encode())
            ):
                errors.append(f"{label} retained replace-program event binding is not replay-valid")
        if (
            adaptation_archive.get("source_strategy") != source_state.get("strategy")
            or adaptation_archive.get("pending_adaptations")
            != transition_state.get("feedback", {}).get("pending_adaptations")
            or adaptation_archive.get("applied_adaptations")
            != transition_state.get("feedback", {}).get("applied_adaptations")
            or quality_archive.get("quality") != transition_state.get("quality")
            or runtime_archive.get("runtime_adapter") != source_state.get("runtime_adapter")
        ):
            errors.append(f"{label} archives do not exactly preserve the source transition")
        if (
            event.get("adaptation_archive_digest") != adaptation_archive.get("archive_digest")
            or event.get("quality_archive_digest") != quality_archive.get("archive_digest")
            or event.get("runtime_archive_digest") != runtime_archive.get("archive_digest")
            or event.get("repair_grant_digest")
            != repair_record.get("repair_grant", {}).get("grant_digest")
            or event.get("transition_event_id") != transition_binding.get("event_id")
            or event.get("transition_event_payload_sha256")
            != transition_binding.get("event_payload_sha256")
            or event.get("strategy_transition_digest")
            != transition_binding.get("strategy_transition_digest")
        ):
            errors.append(f"{label} event does not bind its retained authority")
        for field in (
            "candidate_state_digest", "source_state_revision", "source_state_digest",
            "transition_state_revision", "transition_state_digest", "transition_event",
        ):
            event_value = (
                {
                    "event_id": event.get("transition_event_id"),
                    "event_payload_sha256": event.get("transition_event_payload_sha256"),
                    "strategy_transition_digest": event.get("strategy_transition_digest"),
                }
                if field == "transition_event"
                else event.get(field)
            )
            payload_value = retained_payload.get(field) if isinstance(retained_payload, dict) else None
            if field == "transition_event":
                payload_value = {
                    "event_id": (payload_value or {}).get("event_id"),
                    "event_payload_sha256": (payload_value or {}).get("event_payload_sha256"),
                    "strategy_transition_digest": (payload_value or {}).get("strategy_transition_digest"),
                }
            if payload_value != event_value:
                errors.append(f"{label} signed payload does not match event field {field}")
        candidate = deepcopy(repair_state)
        candidate["feedback"]["program_transition_repairs"] = [
            item
            for item in candidate.get("feedback", {}).get("program_transition_repairs", [])
            if not isinstance(item, dict) or item.get("transition_id") != transition_id
        ]
        if governance_digest(candidate) != event.get("candidate_state_digest"):
            errors.append(f"{label} candidate state digest is not replay-valid")
        if (
            candidate.get("feedback", {}).get("pending_adaptations") != []
            or candidate.get("feedback", {}).get("applied_adaptations") != []
            or any(
                isinstance(item, dict) and item.get("score") is not None
                for item in candidate.get("quality", {}).get("dimensions", {}).values()
            )
        ):
            errors.append(f"{label} candidate state did not clear stale live authority")
    if revision_rows:
        try:
            latest_state = json.loads(revision_rows[-1]["state_json"])
        except json.JSONDecodeError:
            return
        retained_counts: dict[str, int] = {}
        for repair in latest_state.get("feedback", {}).get("program_transition_repairs", []):
            if isinstance(repair, dict) and isinstance(repair.get("transition_id"), str):
                transition_id = repair["transition_id"]
                retained_counts[transition_id] = retained_counts.get(transition_id, 0) + 1
        if retained_counts != repair_event_counts or any(count != 1 for count in retained_counts.values()):
            errors.append(
                "program transition repair records and atomic repair events are not one-to-one"
            )


def audit(project: Path) -> dict[str, Any]:
    project = project.resolve()
    errors: list[str] = []
    connection = connect(project)
    try:
        metadata = _assert_binding(connection, project)
        integrity = connection.execute("PRAGMA integrity_check").fetchone()[0]
        if integrity != "ok":
            errors.append(f"SQLite integrity check failed: {integrity}")
        revision, state = _load_latest(connection)
        _assert_binding(connection, project, state)
        for table in (
            "state_revisions",
            "events",
            "legacy_events",
            "entities",
            "inbox_messages",
            "outbox_messages",
            "command_idempotency",
        ):
            foreign_projects = connection.execute(
                f"SELECT DISTINCT project_id FROM {table} WHERE project_id <> ?",
                (metadata["project_id"],),
            ).fetchall()
            if foreign_projects:
                errors.append(f"{table} contains records for a foreign project")
        revision_rows = connection.execute(
            "SELECT revision,project_id,state_json,state_sha256,event_id FROM state_revisions ORDER BY revision"
        ).fetchall()
        revision_count = len(revision_rows)
        revision_bounds = connection.execute(
            "SELECT MIN(revision) AS minimum, MAX(revision) AS maximum FROM state_revisions"
        ).fetchone()
        event_rows = connection.execute(
            "SELECT sequence,event_id,project_id,program_version,event_type,payload_json,payload_sha256,state_revision FROM events ORDER BY sequence"
        ).fetchall()
        event_count = len(event_rows)
        paired_count = connection.execute(
            "SELECT COUNT(*) FROM state_revisions r JOIN events e ON e.state_revision = r.revision AND e.event_id = r.event_id"
        ).fetchone()[0]
        if revision_count != event_count or paired_count != revision_count:
            errors.append("state revisions and audit events are not one-to-one")
        if revision_bounds["minimum"] != 1 or revision_bounds["maximum"] != revision_count:
            errors.append("state revision sequence is not contiguous from one")
        for expected_revision, row in enumerate(revision_rows, start=1):
            if row["revision"] != expected_revision:
                errors.append("state revision sequence is not ordered contiguously")
                break
            if row["project_id"] != metadata["project_id"]:
                errors.append("state revision belongs to a different project")
                break
            if sha256_bytes(row["state_json"].encode()) != row["state_sha256"]:
                errors.append("a retained state revision hash is invalid")
                break
            try:
                retained_state = json.loads(row["state_json"])
            except json.JSONDecodeError:
                errors.append("a retained state revision contains invalid JSON")
                break
            if retained_state.get("instance", {}).get("project_id") != metadata["project_id"]:
                errors.append("a retained state revision is not bound to this project")
                break
        revisions_by_number = {row["revision"]: row for row in revision_rows}
        for expected_sequence, row in enumerate(event_rows, start=1):
            if row["sequence"] != expected_sequence or row["state_revision"] != expected_sequence:
                errors.append("audit event order does not match state revision order")
                break
            if row["project_id"] != metadata["project_id"]:
                errors.append("an audit event belongs to a different project")
                break
            if sha256_bytes(row["payload_json"].encode()) != row["payload_sha256"]:
                errors.append("a retained audit event hash is invalid")
                break
            try:
                payload = json.loads(row["payload_json"])
            except json.JSONDecodeError:
                errors.append("a retained audit event contains invalid JSON")
                break
            paired_revision = revisions_by_number.get(row["state_revision"])
            if (
                paired_revision is None
                or paired_revision["event_id"] != row["event_id"]
                or payload.get("event_id") != row["event_id"]
                or payload.get("state_revision") != row["state_revision"]
                or payload.get("project_id") != row["project_id"]
                or payload.get("program_version") != row["program_version"]
                or payload.get("type") != row["event_type"]
            ):
                errors.append("an audit event does not exactly bind its state revision")
                break
        _audit_program_transition_repair_events(revision_rows, event_rows, errors)
        for row in connection.execute(
            "SELECT project_id,payload_json,payload_sha256 FROM legacy_events ORDER BY sequence"
        ):
            if (
                row["project_id"] != metadata["project_id"]
                or sha256_bytes(row["payload_json"].encode()) != row["payload_sha256"]
            ):
                errors.append("a retained legacy event is corrupt or cross-project")
                break
        state_bytes, events_bytes, _ = _export_values(connection)
        entity_rows = connection.execute(
            "SELECT entity_type,entity_id,record_json,record_sha256,state_revision FROM entities WHERE project_id = ?",
            (metadata["project_id"],),
        ).fetchall()
        expected_entities = {
            (kind, identifier): canonical_json(record)
            for kind, identifier, _, _, record in _entity_records(state)
        }
        actual_entities = {
            (row["entity_type"], row["entity_id"]): row["record_json"]
            for row in entity_rows
            if row["state_revision"] == revision
            and sha256_bytes(row["record_json"].encode()) == row["record_sha256"]
        }
        if actual_entities != expected_entities:
            errors.append("transactional entity projections do not match authoritative state")
        expected_inbox: dict[tuple[str, str], str] = {}
        for attempt_id, inbox in state.get("runtime_adapter", {}).get("observation_inboxes", {}).items():
            if not isinstance(inbox, dict):
                continue
            for observation in inbox.get("trusted_observations", []):
                if isinstance(observation, dict) and isinstance(observation.get("event_key"), str):
                    encoded = canonical_json(observation)
                    expected_inbox[(f"runtime:{attempt_id}", observation["event_key"])] = sha256_bytes(
                        encoded.encode()
                    )
        inbox_rows = connection.execute(
            "SELECT channel,message_key,payload_json,payload_sha256,state_revision FROM inbox_messages WHERE project_id = ?",
            (metadata["project_id"],),
        ).fetchall()
        actual_inbox = {
            (row["channel"], row["message_key"]): row["payload_sha256"]
            for row in inbox_rows
            if row["state_revision"] == revision
            and sha256_bytes(row["payload_json"].encode()) == row["payload_sha256"]
        }
        if actual_inbox != expected_inbox:
            errors.append("transactional inbox projections do not match authoritative state")
        pending_outbox = connection.execute(
            "SELECT COUNT(*) FROM outbox_messages WHERE project_id = ? AND status IN ('pending','leased')",
            (metadata["project_id"],),
        ).fetchone()[0]
        for row in connection.execute(
            "SELECT payload_json,payload_sha256,created_revision,updated_revision FROM outbox_messages WHERE project_id = ?",
            (metadata["project_id"],),
        ):
            if (
                sha256_bytes(row["payload_json"].encode()) != row["payload_sha256"]
                or row["created_revision"] > row["updated_revision"]
                or row["updated_revision"] > revision
            ):
                errors.append("transactional outbox contains an invalid retained record")
                break
        events_by_revision: dict[int, dict[str, Any]] = {}
        for event_row in event_rows:
            if sha256_bytes(event_row["payload_json"].encode()) != event_row["payload_sha256"]:
                continue
            try:
                retained_event = json.loads(event_row["payload_json"])
            except json.JSONDecodeError:
                continue
            if isinstance(retained_event, dict):
                events_by_revision[event_row["state_revision"]] = retained_event
        for row in connection.execute(
            "SELECT command_scope,command_key,command_name,payload_sha256,result_json,result_sha256,state_revision "
            "FROM command_idempotency WHERE project_id = ?",
            (metadata["project_id"],),
        ):
            try:
                result_value = json.loads(row["result_json"])
            except json.JSONDecodeError:
                errors.append("command idempotency contains invalid result JSON")
                break
            if (
                not isinstance(result_value, dict)
                or sha256_bytes(row["result_json"].encode()) != row["result_sha256"]
                or not isinstance(row["payload_sha256"], str)
                or len(row["payload_sha256"]) != 64
                or row["state_revision"] > revision
            ):
                errors.append("command idempotency contains an invalid retained record")
                break
            if row["command_scope"] == "controller-cli":
                event_payload = events_by_revision.get(row["state_revision"])
                if event_payload is None:
                    errors.append("controller command replay is missing its paired audit event")
                    break
                event_fields = {
                    key: value
                    for key, value in event_payload.items()
                    if key
                    not in {
                        "at",
                        "type",
                        "project_id",
                        "program_version",
                        "event_id",
                        "state_revision",
                        "command_envelope",
                    }
                }
                expected_command_envelope = {
                    "name": row["command_name"],
                    "key": row["command_key"],
                    "payload_sha256": row["payload_sha256"],
                }
                if event_payload.get("command_envelope") != expected_command_envelope:
                    errors.append("controller command identity does not match its paired audit event")
                    break
                expected_result = {
                    "ok": True,
                    "command": row["command_name"],
                    "command_key": row["command_key"],
                    "event_type": event_payload.get("type"),
                    "state_revision": row["state_revision"],
                    "event": event_fields,
                }
                if result_value != expected_result:
                    errors.append("controller command replay result does not match its paired audit event")
                    break
    finally:
        connection.close()
    state_path = project / ".company-os" / "control.json"
    events_path = project / ".company-os" / "events.jsonl"
    state_export_match = state_path.is_file() and state_path.read_bytes() == state_bytes
    events_export_match = events_path.is_file() and events_path.read_bytes() == events_bytes
    return {
        "ok": not errors,
        "errors": errors,
        "backend": "sqlite",
        "store_schema_version": STORE_SCHEMA_VERSION,
        "revision": revision,
        "project_id": metadata["project_id"],
        "state_export_match": state_export_match,
        "events_export_match": events_export_match,
        "pending_outbox": pending_outbox,
    }


def idempotency_lookup(
    connection: sqlite3.Connection,
    project_id: str,
    scope: str,
    key: str,
    payload_sha256: str,
) -> dict[str, Any] | None:
    row = connection.execute(
        "SELECT payload_sha256,result_json,result_sha256,state_revision FROM command_idempotency WHERE project_id=? AND command_scope=? AND command_key=?",
        (project_id, scope, key),
    ).fetchone()
    if row is None:
        return None
    if row["payload_sha256"] != payload_sha256:
        raise StoreError("command idempotency key conflicts with a different payload digest")
    if sha256_bytes(row["result_json"].encode()) != row["result_sha256"]:
        raise StoreError("command idempotency result integrity is invalid")
    try:
        result = json.loads(row["result_json"])
    except json.JSONDecodeError:
        raise StoreError("command idempotency result JSON is invalid") from None
    if not isinstance(result, dict):
        raise StoreError("command idempotency result must be an object")
    return {"result": result, "state_revision": row["state_revision"]}


def idempotency_record(
    connection: sqlite3.Connection,
    *,
    project_id: str,
    scope: str,
    key: str,
    command_name: str,
    payload_sha256: str,
    result: dict[str, Any],
    state_revision: int,
    created_at: str,
) -> dict[str, Any] | None:
    existing = idempotency_lookup(connection, project_id, scope, key, payload_sha256)
    if existing is not None:
        return {**existing, "idempotent": True}
    encoded_result = canonical_json(result)
    connection.execute(
        "INSERT INTO command_idempotency VALUES (?,?,?,?,?,?,?,?,?)",
        (
            project_id,
            scope,
            key,
            command_name,
            payload_sha256,
            encoded_result,
            sha256_bytes(encoded_result.encode()),
            state_revision,
            created_at,
        ),
    )
    return {"result": result, "state_revision": state_revision, "idempotent": False}


def outbox_lookup(
    connection: sqlite3.Connection,
    project_id: str,
    channel: str,
    key: str,
    payload_sha256: str,
) -> dict[str, Any] | None:
    row = connection.execute(
        "SELECT payload_sha256,payload_json,status,attempt_count,not_before,created_revision,updated_revision "
        "FROM outbox_messages WHERE project_id=? AND channel=? AND message_key=?",
        (project_id, channel, key),
    ).fetchone()
    if row is None:
        return None
    if row["payload_sha256"] != payload_sha256:
        raise StoreError("outbox message key conflicts with a different payload digest")
    if sha256_bytes(row["payload_json"].encode()) != row["payload_sha256"]:
        raise StoreError("outbox message payload integrity is invalid")
    try:
        payload = json.loads(row["payload_json"])
    except json.JSONDecodeError:
        raise StoreError("outbox message payload JSON is invalid") from None
    if not isinstance(payload, dict):
        raise StoreError("outbox message payload must be an object")
    return {
        "payload": payload,
        "payload_sha256": row["payload_sha256"],
        "status": row["status"],
        "attempt_count": row["attempt_count"],
        "not_before": row["not_before"],
        "created_revision": row["created_revision"],
        "updated_revision": row["updated_revision"],
    }


def outbox_enqueue(
    connection: sqlite3.Connection,
    *,
    project_id: str,
    channel: str,
    key: str,
    payload: dict[str, Any],
    state_revision: int,
    not_before: str | None = None,
) -> dict[str, Any]:
    if not channel or not key:
        raise StoreError("outbox channel and message key must be non-empty")
    encoded = canonical_json(payload)
    payload_sha256 = sha256_bytes(encoded.encode())
    retained = outbox_lookup(connection, project_id, channel, key, payload_sha256)
    if retained is not None:
        return {**retained, "idempotent": True}
    connection.execute(
        "INSERT INTO outbox_messages(project_id,channel,message_key,payload_sha256,payload_json,status,attempt_count,not_before,created_revision,updated_revision) "
        "VALUES (?,?,?,?,?,'pending',0,?,?,?)",
        (
            project_id,
            channel,
            key,
            payload_sha256,
            encoded,
            not_before,
            state_revision,
            state_revision,
        ),
    )
    return {
        "payload": payload,
        "payload_sha256": payload_sha256,
        "status": "pending",
        "attempt_count": 0,
        "not_before": not_before,
        "created_revision": state_revision,
        "updated_revision": state_revision,
        "idempotent": False,
    }


OUTBOX_TRANSITIONS = {
    "pending": {"leased", "cancelled"},
    "leased": {"succeeded", "failed", "cancelled"},
    "failed": {"leased", "cancelled"},
    "succeeded": set(),
    "cancelled": set(),
}


def outbox_transition(
    connection: sqlite3.Connection,
    *,
    project_id: str,
    channel: str,
    key: str,
    status: str,
    state_revision: int,
) -> dict[str, Any]:
    row = connection.execute(
        "SELECT status,attempt_count FROM outbox_messages WHERE project_id=? AND channel=? AND message_key=?",
        (project_id, channel, key),
    ).fetchone()
    if row is None:
        raise StoreError("outbox message does not exist")
    current = row["status"]
    if status == current:
        return {"status": current, "attempt_count": row["attempt_count"], "idempotent": True}
    if status not in OUTBOX_TRANSITIONS.get(current, set()):
        raise StoreError(f"outbox transition {current}->{status} is not allowed")
    attempt_count = row["attempt_count"] + (1 if status == "leased" else 0)
    connection.execute(
        "UPDATE outbox_messages SET status=?,attempt_count=?,updated_revision=? "
        "WHERE project_id=? AND channel=? AND message_key=?",
        (status, attempt_count, state_revision, project_id, channel, key),
    )
    return {"status": status, "attempt_count": attempt_count, "idempotent": False}


def outbox_reconcile(
    connection: sqlite3.Connection,
    *,
    project_id: str,
    channel: str,
    key: str,
    status: str,
    state_revision: int,
    expected_status: str | None = None,
    payload_sha256: str | None = None,
) -> dict[str, Any]:
    """Reconcile one retained outbox row with explicit compare-and-set guards."""
    if not isinstance(state_revision, int) or isinstance(state_revision, bool) or state_revision < 1:
        raise StoreError("outbox reconciliation revision must be a positive integer")
    row = connection.execute(
        "SELECT payload_sha256,status,attempt_count,not_before,created_revision,updated_revision "
        "FROM outbox_messages WHERE project_id=? AND channel=? AND message_key=?",
        (project_id, channel, key),
    ).fetchone()
    if row is None:
        raise StoreError("outbox message does not exist")
    if payload_sha256 is not None and row["payload_sha256"] != payload_sha256:
        raise StoreError("outbox message key conflicts with a different payload digest")
    current = row["status"]
    if expected_status is not None and current != expected_status:
        raise StoreError(f"outbox reconciliation expected {expected_status}, found {current}")
    result = outbox_transition(
        connection, project_id=project_id, channel=channel, key=key,
        status=status, state_revision=state_revision,
    )
    return {
        **result,
        "channel": channel,
        "message_key": key,
        "payload_sha256": row["payload_sha256"],
        "updated_revision": state_revision if not result["idempotent"] else row["updated_revision"],
    }


def inspect_outbox(
    project: Path,
    *,
    channel: str | None = None,
    statuses: tuple[str, ...] | list[str] | None = None,
) -> list[dict[str, Any]]:
    """Return hash-verified outbox rows scoped to exactly one project store."""
    project = project.resolve()
    _store_layout(project, require_database=True)
    connection = connect(project)
    try:
        metadata = _assert_binding(connection, project)
        allowed = set(statuses or ())
        if allowed - set(OUTBOX_TRANSITIONS) - {"pending", "leased", "succeeded", "failed", "cancelled"}:
            raise StoreError("outbox inspection status is invalid")
        query = (
            "SELECT channel,message_key,payload_sha256,payload_json,status,attempt_count,"
            "not_before,created_revision,updated_revision FROM outbox_messages WHERE project_id=?"
        )
        params: list[Any] = [metadata["project_id"]]
        if channel is not None:
            query += " AND channel=?"; params.append(channel)
        if allowed:
            query += " AND status IN (" + ",".join("?" for _ in allowed) + ")"
            params.extend(sorted(allowed))
        query += " ORDER BY created_revision,channel,message_key"
        rows = connection.execute(query, params).fetchall()
        records = []
        for row in rows:
            payload_record = outbox_lookup(
                connection, metadata["project_id"], row["channel"],
                row["message_key"], row["payload_sha256"],
            )
            records.append({"channel": row["channel"], "message_key": row["message_key"], **payload_record})
        return records
    finally:
        connection.close()


# Explicit name for callers that prefer noun-first inspection semantics.
outbox_inspect = inspect_outbox

"""Pure feature-off state machine for host-operated native Codex tasks.

This module performs no I/O and has no Codex app-tool integration. The
interactive host executes native operations; the controller persists only
explicit desired state and returned host observations.
"""

from __future__ import annotations

from copy import deepcopy
import hashlib
import json
from typing import Any, Mapping


SCHEMA = "company-os.native-task-runtime.v2"
LEGACY_SCHEMA = "company-os.native-task-runtime.v1"
DOWNGRADE_ASSESSMENT_SCHEMA = "company-os.native-task-runtime-downgrade-assessment.v1"
DISPATCH_RECEIPT_SCHEMA = "company-os.native-task-dispatch-admission.v1"
TERMINAL_STATUSES = {
    "succeeded",
    "failed",
    "cancelled",
    "blocked_model_unavailable",
    "cancelled_before_launch",
}
ACTIVE_STATUSES = {
    "dispatch_intent_recorded",
    "dispatch_claimed",
    "host_created",
    "running",
    "cancel_requested",
    "cancel_acknowledged",
}
HARD_CANCELLATION_STATUSES = {"acknowledged", "refused", "failed"}
ACKNOWLEDGEMENT_STATUSES = {"acknowledged", "not_acknowledged"}
LEGAL_CANCELLATION_EVIDENCE = {
    ("acknowledged", "acknowledged"),
    ("refused", "not_acknowledged"),
    ("failed", "not_acknowledged"),
}


class RuntimeStateError(ValueError):
    """Raised when a native lifecycle transition fails closed."""


def _validate_cancellation_evidence(hard_status: Any, acknowledgement_status: Any) -> None:
    if (hard_status, acknowledgement_status) not in LEGAL_CANCELLATION_EVIDENCE:
        raise RuntimeStateError(
            "hard cancellation and acknowledgement statuses form an illegal pair"
        )


def canonical_digest(value: Any) -> str:
    try:
        encoded = json.dumps(
            value,
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=True,
            allow_nan=False,
        ).encode("utf-8")
    except (TypeError, ValueError, UnicodeError) as exc:
        raise RuntimeStateError("native runtime value is not canonical JSON") from exc
    return hashlib.sha256(encoded).hexdigest()


def unavailable(reason: str) -> dict[str, Any]:
    return {"status": "unavailable", "value": None, "reason": reason}


def _text(value: Any, field: str) -> str:
    if not isinstance(value, str) or not value or value != value.strip():
        raise RuntimeStateError(f"{field} must be a non-empty trimmed string")
    return value


def _validate_state_header(state: Mapping[str, Any]) -> None:
    if not isinstance(state, Mapping) or state.get("schema") != SCHEMA:
        raise RuntimeStateError("invalid native runtime state")
    if state.get("status") not in ACTIVE_STATUSES | TERMINAL_STATUSES:
        raise RuntimeStateError("invalid native runtime status")


def _event_payload(state: Mapping[str, Any], event: str, payload: Mapping[str, Any]) -> dict[str, Any]:
    normalized = deepcopy(dict(payload))
    identity = state.get("native_identity")
    if event == "dispatch_claimed":
        allowed = {"dispatch_key", "payload_sha256"}
        if set(normalized) != allowed:
            raise RuntimeStateError("dispatch claim payload shape is invalid")
        _text(normalized.get("dispatch_key"), "dispatch_key")
        _text(normalized.get("payload_sha256"), "payload_sha256")
    elif event == "cancel_requested":
        allowed = {"reason", "requested_by", "dispatch"}
        if not {"reason", "requested_by"}.issubset(normalized) or set(normalized) - allowed:
            raise RuntimeStateError("cancellation intent payload shape is invalid")
        _text(normalized.get("reason"), "reason")
        _text(normalized.get("requested_by"), "requested_by")
        dispatch = normalized.get("dispatch")
        if dispatch is not None and (
            not isinstance(dispatch, Mapping)
            or set(dispatch) != {"status", "key", "payload_sha256"}
            or dispatch.get("status") != "pending"
            or dispatch.get("key") != state.get("attempt_id")
            or not isinstance(dispatch.get("payload_sha256"), str)
            or len(dispatch.get("payload_sha256")) != 64
        ):
            raise RuntimeStateError("cancellation dispatch payload is invalid")
    elif event == "cancellation_dispatch_claimed":
        if set(normalized) != {"key", "payload_sha256"}:
            raise RuntimeStateError("cancellation dispatch claim payload shape is invalid")
        _text(normalized.get("key"), "key")
        _text(normalized.get("payload_sha256"), "payload_sha256")
    elif event == "cancelled_before_launch":
        if normalized != {
            "source": "controller_reconciliation",
            "next_action": "finalize_cancelled_before_launch",
        }:
            raise RuntimeStateError("pre-launch cancellation requires controller reconciliation")
    elif event in {
        "host_created",
        "running",
        "cooperative_stop_delivered",
        "hard_cancellation_observed",
        "terminal",
    }:
        common = {"source", "tool", "task_id", "thread_id"}
        optional = {"host_id"}
        required = set(common)
        if event == "host_created":
            required.add("host_id")
        elif event == "running":
            optional.add("current_status")
        elif event == "hard_cancellation_observed":
            required.update({"hard_status", "acknowledgement_status"})
        elif event == "terminal":
            required.add("status")
            optional.update({"terminal_message_digest", "artifact_digests", "artifact_bindings", "evaluation_receipt_path"})
        if not required.issubset(normalized) or set(normalized) - required - optional:
            raise RuntimeStateError(f"{event} host observation payload shape is invalid")
        if normalized.get("source") != "host_observation":
            raise RuntimeStateError(f"{event} requires a returned host observation")
        for field in ("tool", "task_id", "thread_id"):
            _text(normalized.get(field), field)
        if "host_id" in normalized:
            _text(normalized.get("host_id"), "host_id")
        if identity is not None and (
            normalized.get("task_id") != identity.get("task_id")
            or normalized.get("thread_id") != identity.get("thread_id")
            or (
                "host_id" in normalized
                and normalized.get("host_id") != identity.get("host_id")
            )
        ):
            raise RuntimeStateError("host observation identity conflicts with the bound native task")
        if event == "hard_cancellation_observed":
            if normalized.get("hard_status") not in HARD_CANCELLATION_STATUSES:
                raise RuntimeStateError("hard cancellation status is invalid")
            if normalized.get("acknowledgement_status") not in ACKNOWLEDGEMENT_STATUSES:
                raise RuntimeStateError("cancellation acknowledgement status is invalid")
            _validate_cancellation_evidence(
                normalized.get("hard_status"), normalized.get("acknowledgement_status")
            )
        if event == "terminal":
            if normalized.get("status") not in TERMINAL_STATUSES - {"cancelled_before_launch"}:
                raise RuntimeStateError("terminal status is invalid")
            artifact_digests = normalized.get("artifact_digests")
            if artifact_digests is not None and (
                not isinstance(artifact_digests, list)
                or any(not isinstance(item, str) or not item for item in artifact_digests)
            ):
                raise RuntimeStateError("terminal artifact digests are invalid")
            artifact_bindings = normalized.get("artifact_bindings")
            if artifact_bindings is not None:
                if not isinstance(artifact_bindings, list) or not artifact_bindings:
                    raise RuntimeStateError("terminal artifact bindings are invalid")
                normalized_bindings = []
                seen_ids = set()
                for index, binding in enumerate(artifact_bindings):
                    if not isinstance(binding, Mapping) or set(binding) != {
                        "artifact_id", "artifact_class_id", "path", "sha256"
                    }:
                        raise RuntimeStateError("terminal artifact binding shape is invalid")
                    artifact_id = _text(binding.get("artifact_id"), f"artifact_bindings[{index}].artifact_id")
                    artifact_class_id = _text(binding.get("artifact_class_id"), f"artifact_bindings[{index}].artifact_class_id")
                    artifact_path = _text(binding.get("path"), f"artifact_bindings[{index}].path")
                    artifact_sha = _text(binding.get("sha256"), f"artifact_bindings[{index}].sha256")
                    if artifact_id in seen_ids:
                        raise RuntimeStateError("terminal artifact binding IDs must be unique")
                    if len(artifact_sha) != 64 or any(ch not in "0123456789abcdef" for ch in artifact_sha):
                        raise RuntimeStateError("terminal artifact binding sha256 is invalid")
                    if artifact_path.startswith("/") or "\\" in artifact_path or any(
                        part in {"", ".", ".."} for part in artifact_path.split("/")
                    ):
                        raise RuntimeStateError("terminal artifact binding path is invalid")
                    seen_ids.add(artifact_id)
                    normalized_bindings.append({
                        "artifact_id": artifact_id,
                        "artifact_class_id": artifact_class_id,
                        "path": artifact_path,
                        "sha256": artifact_sha,
                    })
                normalized_bindings.sort(key=lambda item: item["artifact_id"])
                normalized["artifact_bindings"] = normalized_bindings
                binding_digests = [item["sha256"] for item in normalized_bindings]
                if artifact_digests is not None and sorted(artifact_digests) != sorted(binding_digests):
                    raise RuntimeStateError("terminal artifact digests conflict with artifact bindings")
                if artifact_digests is None:
                    normalized["artifact_digests"] = binding_digests
            evaluation_receipt_path = normalized.get("evaluation_receipt_path")
            if evaluation_receipt_path is not None:
                evaluation_receipt_path = _text(evaluation_receipt_path, "evaluation_receipt_path")
                if evaluation_receipt_path.startswith("/") or "\\" in evaluation_receipt_path or any(
                    part in {"", ".", ".."} for part in evaluation_receipt_path.split("/")
                ):
                    raise RuntimeStateError("terminal evaluation receipt path is invalid")
                normalized["evaluation_receipt_path"] = evaluation_receipt_path
    else:
        raise RuntimeStateError(f"unsupported native runtime event: {event}")
    canonical_digest(normalized)
    return normalized


def _has_event(state: Mapping[str, Any], event: str, payload: Mapping[str, Any]) -> bool:
    return any(
        isinstance(item, Mapping)
        and item.get("event") == event
        and item.get("payload") == payload
        for item in state.get("events", [])
    )


def _append_event(state: dict[str, Any], event: str, payload: dict[str, Any]) -> None:
    state["sequence"] += 1
    retained = {
        "sequence": state["sequence"],
        "event": event,
        "payload": deepcopy(payload),
        "payload_sha256": canonical_digest(payload),
    }
    state["events"].append(retained)
    if payload.get("source") == "host_observation":
        state["host_observations"].append(deepcopy(retained))


def _receipt_payload(state: Mapping[str, Any]) -> dict[str, Any]:
    return {
        "admission_digest": state.get("admission_digest"),
        "dispatch": state.get("dispatch"),
        "native_identity": state.get("native_identity"),
        "host_observations": state.get("host_observations"),
        "cancellation": state.get("cancellation"),
        "terminal": state.get("terminal"),
        "observed_model": state.get("observed_model"),
        "provider_usage": state.get("provider_usage"),
        "cost": state.get("cost"),
        "authority_history": state.get("authority_history"),
    }


def admit(
    *,
    attempt_id: str,
    idempotency_key: str,
    requested_model: str,
    project_id: str,
    work_id: str,
    cycle_id: str,
    parent_runtime_id: str,
    role: str,
    scope: Any,
    budget: Mapping[str, Any],
    metadata: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Return a content-bound, pre-create admission and dispatch receipt."""
    admission = {
        "attempt_id": _text(attempt_id, "attempt_id"),
        "idempotency_key": _text(idempotency_key, "idempotency_key"),
        "requested_model": _text(requested_model, "requested_model"),
        "project_id": _text(project_id, "project_id"),
        "work_id": _text(work_id, "work_id"),
        "cycle_id": _text(cycle_id, "cycle_id"),
        "parent_runtime_id": _text(parent_runtime_id, "parent_runtime_id"),
        "role": _text(role, "role"),
        "scope": deepcopy(scope),
        "budget": deepcopy(dict(budget)),
        "metadata": deepcopy(dict(metadata or {})),
    }
    admission_digest = canonical_digest(admission)
    dispatch_receipt = {
        "schema": DISPATCH_RECEIPT_SCHEMA,
        "status": "admitted_pre_create",
        "attempt_id": attempt_id,
        "dispatch_key": idempotency_key,
        "admission_digest": admission_digest,
    }
    state = {
        "schema": SCHEMA,
        "status": "dispatch_intent_recorded",
        "attempt_id": attempt_id,
        "requested_model": requested_model,
        "admission": admission,
        "admission_digest": admission_digest,
        "dispatch_receipt": dispatch_receipt,
        "dispatch": {
            "status": "intent_recorded",
            "key": idempotency_key,
            "payload_sha256": canonical_digest(dispatch_receipt),
        },
        "native_identity": None,
        "host_observations": [],
        "observed_model": unavailable("native_host_did_not_expose_observed_model"),
        "provider_usage": unavailable("native_host_did_not_expose_provider_usage"),
        "cost": unavailable("native_host_did_not_expose_cost"),
        "authority_history": [],
        "cancellation": {
            "desired_intent": "run",
            "intent_status": "not_requested",
            "intent": None,
            "cooperative_stop_delivery": "not_requested",
            "hard_cancellation_status": "unavailable",
            "acknowledgement_status": "unavailable",
        },
        "sequence": 1,
        "events": [
            {
                "sequence": 1,
                "event": "dispatch_intent_recorded",
                "payload": deepcopy(dispatch_receipt),
                "payload_sha256": canonical_digest(dispatch_receipt),
            }
        ],
        "terminal": None,
        "receipt": None,
        "reconciliation": {"status": "pending", "next_action": "claim_dispatch"},
    }
    errors = audit_state(state)
    if errors:
        raise RuntimeStateError("invalid admitted native runtime state: " + "; ".join(errors))
    return state


def _reduce_event(
    state: Mapping[str, Any], event: str, normalized: dict[str, Any]
) -> dict[str, Any]:
    """Reduce one already-normalized event without auditing retained history."""
    out = deepcopy(dict(state))
    status = out["status"]
    if event == "dispatch_claimed":
        if out["dispatch"]["status"] != "intent_recorded" or status != "dispatch_intent_recorded":
            raise RuntimeStateError("dispatch claim is out of order")
        if normalized["dispatch_key"] != out["dispatch"]["key"]:
            raise RuntimeStateError("dispatch claim key conflicts with admission")
        if normalized["payload_sha256"] != out["dispatch"]["payload_sha256"]:
            raise RuntimeStateError("dispatch claim payload conflicts with admission")
        out["dispatch"]["status"] = "claimed_create_in_flight"
        out["status"] = "dispatch_claimed"
    elif event == "host_created":
        if out["dispatch"]["status"] != "claimed_create_in_flight" or status != "dispatch_claimed":
            raise RuntimeStateError("host creation requires a durable dispatch claim")
        identity = {
            "task_id": normalized["task_id"],
            "thread_id": normalized["thread_id"],
            "host_id": normalized["host_id"],
        }
        if out["native_identity"] not in (None, identity):
            raise RuntimeStateError("native task identity is immutable")
        out["native_identity"] = identity
        out["dispatch"]["status"] = "bound"
        out["status"] = "host_created"
    elif event == "running":
        if status != "host_created" or out.get("native_identity") is None:
            raise RuntimeStateError("running observation is out of order")
        out["status"] = "running"
    elif event == "cancel_requested":
        if out["cancellation"]["desired_intent"] == "cancel":
            raise RuntimeStateError("cancellation intent conflicts with an earlier request")
        out["cancellation"].update(
            {
                "desired_intent": "cancel",
                "intent_status": "requested",
                "intent": deepcopy(normalized),
                "cooperative_stop_delivery": (
                    "pending" if out.get("native_identity") is not None else "not_applicable"
                ),
            }
        )
        if normalized.get("dispatch") is not None:
            out["cancellation"]["dispatch"] = deepcopy(normalized["dispatch"])
        out["status"] = "cancel_requested"
    elif event == "cancellation_dispatch_claimed":
        dispatch = out["cancellation"].get("dispatch")
        if (
            not isinstance(dispatch, Mapping)
            or dispatch.get("status") != "pending"
            or normalized["key"] != dispatch.get("key")
            or normalized["payload_sha256"] != dispatch.get("payload_sha256")
        ):
            raise RuntimeStateError("cancellation dispatch claim is out of order")
        out["cancellation"]["dispatch"]["status"] = "claimed"
    elif event == "cooperative_stop_delivered":
        if out["cancellation"]["desired_intent"] != "cancel" or out.get("native_identity") is None:
            raise RuntimeStateError("cooperative stop delivery is out of order")
        cancellation_dispatch = out["cancellation"].get("dispatch")
        if isinstance(cancellation_dispatch, Mapping):
            if cancellation_dispatch.get("status") != "claimed":
                raise RuntimeStateError("cooperative stop requires a claimed cancellation dispatch")
            out["cancellation"]["dispatch"]["status"] = "delivered"
        out["cancellation"]["cooperative_stop_delivery"] = "delivered"
        out["status"] = "cancel_requested"
    elif event == "hard_cancellation_observed":
        if out["cancellation"]["desired_intent"] != "cancel" or out.get("native_identity") is None:
            raise RuntimeStateError("hard cancellation observation is out of order")
        hard_status = normalized["hard_status"]
        acknowledgement_status = normalized["acknowledgement_status"]
        _validate_cancellation_evidence(hard_status, acknowledgement_status)
        out["cancellation"]["hard_cancellation_status"] = hard_status
        out["cancellation"]["acknowledgement_status"] = acknowledgement_status
        out["status"] = (
            "cancel_acknowledged"
            if (hard_status, acknowledgement_status) == ("acknowledged", "acknowledged")
            else "cancel_requested"
        )
    elif event == "cancelled_before_launch":
        if (
            out["cancellation"]["desired_intent"] != "cancel"
            or out.get("native_identity") is not None
            or out["dispatch"]["status"] != "intent_recorded"
        ):
            raise RuntimeStateError("pre-launch cancellation cannot resolve ambiguous creation")
        out["dispatch"]["status"] = "cancelled"
        out["status"] = "cancelled_before_launch"
        out["terminal"] = {"status": "cancelled_before_launch", "observation": normalized}
    elif event == "terminal":
        if status not in {"running", "cancel_requested", "cancel_acknowledged"}:
            raise RuntimeStateError("terminal observation requires ordered create and start evidence")
        terminal_status = normalized["status"]
        if (
            out["cancellation"]["desired_intent"] == "cancel"
            and terminal_status != "cancelled"
        ):
            raise RuntimeStateError("post-cancellation success or failure is rejected")
        out["status"] = terminal_status
        out["terminal"] = {"status": terminal_status, "observation": normalized}

    _append_event(out, event, normalized)
    if out["status"] in TERMINAL_STATUSES:
        receipt_payload = _receipt_payload(out)
        out["receipt"] = {
            "status": (
                "cancelled"
                if out["status"].startswith("cancelled")
                else "complete" if out["status"] == "succeeded" else "failed"
            ),
            "terminal_status": out["status"],
            "payload_sha256": canonical_digest(receipt_payload),
        }
        out["reconciliation"] = {"status": "terminal", "next_action": "none"}
    else:
        out = reconcile_restart(out)
    return out


def record_event(
    state: Mapping[str, Any],
    event: str,
    *,
    payload: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    """Apply one monotonic event; an exact repeated observation is a no-op."""
    retained_errors = audit_state(state)
    if retained_errors:
        raise RuntimeStateError("native runtime retained state failed audit: " + "; ".join(retained_errors))
    normalized = _event_payload(state, event, payload or {})
    if _has_event(state, event, normalized):
        return deepcopy(dict(state))
    if state.get("status") in TERMINAL_STATUSES:
        raise RuntimeStateError("terminal native runtime state is immutable")
    out = _reduce_event(state, event, normalized)
    errors = audit_state(out)
    if errors:
        raise RuntimeStateError("native runtime transition failed audit: " + "; ".join(errors))
    return out


def claim_dispatch(state: Mapping[str, Any]) -> dict[str, Any]:
    dispatch = state.get("dispatch", {})
    return record_event(
        state,
        "dispatch_claimed",
        payload={
            "dispatch_key": dispatch.get("key"),
            "payload_sha256": dispatch.get("payload_sha256"),
        },
    )


def bind_host_identity(
    state: Mapping[str, Any],
    *,
    task_id: str,
    thread_id: str,
    tool: str,
    host_id: str | None = None,
) -> dict[str, Any]:
    payload = {
        "source": "host_observation",
        "tool": tool,
        "task_id": task_id,
        "thread_id": thread_id,
    }
    if host_id is not None:
        payload["host_id"] = host_id
    return record_event(state, "host_created", payload=payload)


def request_cancellation(
    state: Mapping[str, Any], *, reason: str, requested_by: str,
    dispatch: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    payload = {"reason": reason, "requested_by": requested_by}
    if dispatch is not None:
        payload["dispatch"] = deepcopy(dict(dispatch))
    return record_event(
        state,
        "cancel_requested",
        payload=payload,
    )


def claim_cancellation_dispatch(state: Mapping[str, Any]) -> dict[str, Any]:
    dispatch = state.get("cancellation", {}).get("dispatch", {})
    return record_event(
        state,
        "cancellation_dispatch_claimed",
        payload={"key": dispatch.get("key"), "payload_sha256": dispatch.get("payload_sha256")},
    )


def attach_authority(
    state: Mapping[str, Any], authority: Mapping[str, Any]
) -> dict[str, Any]:
    """Atomically bind one controller authority record to an already-retained event."""
    retained_errors = audit_state(state)
    if retained_errors:
        raise RuntimeStateError(
            "native runtime retained state failed audit: " + "; ".join(retained_errors)
        )
    out = deepcopy(dict(state))
    out["authority_history"].append(deepcopy(dict(authority)))
    if out["status"] in TERMINAL_STATUSES:
        out["receipt"]["payload_sha256"] = canonical_digest(_receipt_payload(out))
    errors = audit_state(out)
    if errors:
        raise RuntimeStateError("native runtime authority binding failed audit: " + "; ".join(errors))
    return out


def reconcile_restart(state: Mapping[str, Any]) -> dict[str, Any]:
    """Derive the next host action without binding identity or relaunching work."""
    _validate_state_header(state)
    out = deepcopy(dict(state))
    if out["status"] in TERMINAL_STATUSES:
        next_action = "none"
        reconciliation_status = "terminal"
    elif out["cancellation"]["desired_intent"] == "cancel":
        if out.get("native_identity") is not None:
            if out["cancellation"]["cooperative_stop_delivery"] == "pending":
                next_action = "deliver_cooperative_stop"
            else:
                next_action = "await_cancellation_observation"
        elif out["dispatch"]["status"] == "intent_recorded":
            next_action = "finalize_cancelled_before_launch"
        else:
            next_action = "reconcile_host_listing"
        reconciliation_status = "pending"
    elif out.get("native_identity") is None:
        if out["dispatch"]["status"] == "intent_recorded":
            next_action = "claim_dispatch"
        else:
            next_action = "reconcile_host_listing"
        reconciliation_status = "pending"
    elif out["status"] == "host_created":
        next_action = "await_started_observation"
        reconciliation_status = "pending"
    else:
        next_action = "await_terminal_observation"
        reconciliation_status = "pending"
    out["reconciliation"] = {
        "status": reconciliation_status,
        "next_action": next_action,
    }
    return out


def _replay_lifecycle(state: Mapping[str, Any]) -> dict[str, Any]:
    """Derive all lifecycle-controlled fields from admission and retained events."""
    dispatch_receipt = deepcopy(state["dispatch_receipt"])
    replay = {
        "schema": SCHEMA,
        "status": "dispatch_intent_recorded",
        "attempt_id": state["attempt_id"],
        "requested_model": state["requested_model"],
        "admission": deepcopy(state["admission"]),
        "admission_digest": state["admission_digest"],
        "dispatch_receipt": dispatch_receipt,
        "dispatch": {
            "status": "intent_recorded",
            "key": dispatch_receipt["dispatch_key"],
            "payload_sha256": canonical_digest(dispatch_receipt),
        },
        "native_identity": None,
        "host_observations": [],
        "observed_model": deepcopy(state["observed_model"]),
        "provider_usage": deepcopy(state["provider_usage"]),
        "cost": deepcopy(state["cost"]),
        "authority_history": deepcopy(state["authority_history"]),
        "cancellation": {
            "desired_intent": "run",
            "intent_status": "not_requested",
            "intent": None,
            "cooperative_stop_delivery": "not_requested",
            "hard_cancellation_status": "unavailable",
            "acknowledgement_status": "unavailable",
        },
        "sequence": 1,
        "events": [deepcopy(state["events"][0])],
        "terminal": None,
        "receipt": None,
        "reconciliation": {"status": "pending", "next_action": "claim_dispatch"},
    }
    for retained in state["events"][1:]:
        normalized = _event_payload(replay, retained["event"], retained["payload"])
        replay = _reduce_event(replay, retained["event"], normalized)
    return replay


def downgrade_assessment(
    state: Mapping[str, Any], target_schema: str = LEGACY_SCHEMA
) -> dict[str, Any]:
    """Truthfully report whether persisted v2 state can be represented by a target."""
    current_errors = audit_state(state)
    if current_errors:
        return {
            "schema": DOWNGRADE_ASSESSMENT_SCHEMA,
            "source_schema": state.get("schema") if isinstance(state, Mapping) else None,
            "target_schema": target_schema,
            "status": "blocked",
            "compatible": False,
            "reason": "source_state_failed_audit",
            "errors": current_errors,
        }
    if target_schema == SCHEMA:
        return {
            "schema": DOWNGRADE_ASSESSMENT_SCHEMA,
            "source_schema": SCHEMA,
            "target_schema": target_schema,
            "status": "safe",
            "compatible": True,
            "reason": "target_preserves_exact_v2_state",
            "errors": [],
        }
    reason = (
        "v2_lifecycle_replay_and_authority_bindings_are_not_representable"
        if target_schema in {LEGACY_SCHEMA, "controller-schema-9-pre-native-task-runtime"}
        else "unsupported_target_schema"
    )
    return {
        "schema": DOWNGRADE_ASSESSMENT_SCHEMA,
        "source_schema": SCHEMA,
        "target_schema": target_schema,
        "status": "blocked",
        "compatible": False,
        "reason": reason,
        "errors": [],
    }


def audit_state(state: Mapping[str, Any]) -> list[str]:
    """Return deterministic retained-state integrity errors."""
    errors: list[str] = []
    try:
        _validate_state_header(state)
    except RuntimeStateError as exc:
        return [str(exc)]
    expected_fields = {
        "schema", "status", "attempt_id", "requested_model", "admission",
        "admission_digest", "dispatch_receipt", "dispatch", "native_identity",
        "host_observations", "observed_model", "provider_usage", "cost",
        "authority_history", "cancellation", "sequence", "events", "terminal",
        "receipt", "reconciliation",
    }
    if set(state) != expected_fields:
        errors.append("native runtime state fields are invalid")
    admission = state.get("admission")
    admission_fields = {
        "attempt_id", "idempotency_key", "requested_model", "project_id",
        "work_id", "cycle_id", "parent_runtime_id", "role", "scope", "budget",
        "metadata",
    }
    if (
        not isinstance(admission, Mapping)
        or set(admission) != admission_fields
        or canonical_digest(admission) != state.get("admission_digest")
        or state.get("attempt_id") != admission.get("attempt_id")
        or state.get("requested_model") != admission.get("requested_model")
    ):
        errors.append("native runtime admission digest is invalid")
    dispatch_receipt = state.get("dispatch_receipt")
    expected_dispatch_receipt = {
        "schema": DISPATCH_RECEIPT_SCHEMA,
        "status": "admitted_pre_create",
        "attempt_id": state.get("attempt_id"),
        "dispatch_key": admission.get("idempotency_key") if isinstance(admission, Mapping) else None,
        "admission_digest": state.get("admission_digest"),
    }
    if dispatch_receipt != expected_dispatch_receipt:
        errors.append("native runtime dispatch admission receipt is invalid")
    dispatch = state.get("dispatch")
    if (
        not isinstance(dispatch, Mapping)
        or set(dispatch) != {"status", "key", "payload_sha256"}
        or dispatch.get("status") not in {
            "intent_recorded", "claimed_create_in_flight", "bound", "cancelled",
        }
        or dispatch.get("key") != expected_dispatch_receipt["dispatch_key"]
        or dispatch.get("payload_sha256") != canonical_digest(expected_dispatch_receipt)
    ):
        errors.append("native runtime dispatch state is invalid")
    events = state.get("events")
    if not isinstance(events, list) or not events:
        errors.append("native runtime events are missing")
    else:
        for expected, event in enumerate(events, start=1):
            if (
                not isinstance(event, Mapping)
                or event.get("sequence") != expected
                or canonical_digest(event.get("payload")) != event.get("payload_sha256")
            ):
                errors.append("native runtime event order or digest is invalid")
                break
            if expected > 1:
                try:
                    _event_payload(state, event.get("event"), event.get("payload"))
                except (RuntimeStateError, TypeError):
                    errors.append("native runtime retained event payload is invalid")
                    break
        if state.get("sequence") != len(events):
            errors.append("native runtime sequence does not match retained events")
        if events[0].get("event") != "dispatch_intent_recorded" or events[0].get("payload") != dispatch_receipt:
            errors.append("native runtime first event does not bind pre-create admission")
    identity = state.get("native_identity")
    if identity is not None and (
        not isinstance(identity, Mapping)
        or not identity.get("task_id")
        or not identity.get("thread_id")
        or not identity.get("host_id")
    ):
        errors.append("native runtime identity binding is invalid")
    if isinstance(dispatch, Mapping):
        status = state.get("status")
        if (
            (status == "dispatch_intent_recorded" and dispatch.get("status") != "intent_recorded")
            or (status == "dispatch_claimed" and dispatch.get("status") != "claimed_create_in_flight")
            or (status == "cancelled_before_launch" and dispatch.get("status") != "cancelled")
            or (
                status not in {"dispatch_intent_recorded", "dispatch_claimed", "cancel_requested", "cancelled_before_launch"}
                and dispatch.get("status") != "bound"
            )
            or (identity is not None and dispatch.get("status") != "bound")
        ):
            errors.append("native runtime status conflicts with dispatch state")
    host_observations = state.get("host_observations")
    expected_host_observations = [
        deepcopy(event) for event in events or []
        if isinstance(event, Mapping)
        and isinstance(event.get("payload"), Mapping)
        and event["payload"].get("source") == "host_observation"
    ]
    if host_observations != expected_host_observations:
        errors.append("native runtime host observation chain is invalid")
    for field in ("observed_model", "provider_usage", "cost"):
        value = state.get(field)
        if (
            not isinstance(value, Mapping)
            or set(value) != {"status", "value", "reason"}
            or value.get("status") != "unavailable"
            or value.get("value") is not None
            or not isinstance(value.get("reason"), str)
            or not value.get("reason")
        ):
            errors.append(f"native runtime {field} must remain unavailable")
    cancellation = state.get("cancellation")
    cancellation_fields = {
        "desired_intent", "intent_status", "intent", "cooperative_stop_delivery",
        "hard_cancellation_status", "acknowledgement_status",
    }
    if not isinstance(cancellation, Mapping) or frozenset(cancellation) not in {
        frozenset(cancellation_fields), frozenset(cancellation_fields | {"dispatch"})
    } or cancellation.get("desired_intent") not in {"run", "cancel"}:
        errors.append("native runtime cancellation state is invalid")
    elif cancellation.get("desired_intent") == "run":
        if (
            cancellation.get("intent_status") != "not_requested"
            or cancellation.get("intent") is not None
            or "dispatch" in cancellation
        ):
            errors.append("native runtime cancellation intent is inconsistent")
    else:
        if cancellation.get("intent_status") != "requested" or not isinstance(cancellation.get("intent"), Mapping):
            errors.append("native runtime cancellation intent is inconsistent")
        cancellation_dispatch = cancellation.get("dispatch")
        if cancellation_dispatch is not None and (
            not isinstance(cancellation_dispatch, Mapping)
            or set(cancellation_dispatch) != {"status", "key", "payload_sha256"}
            or cancellation_dispatch.get("status") not in {"pending", "claimed", "delivered"}
            or cancellation_dispatch.get("key") != state.get("attempt_id")
            or not isinstance(cancellation_dispatch.get("payload_sha256"), str)
            or len(cancellation_dispatch.get("payload_sha256")) != 64
        ):
            errors.append("native runtime cancellation dispatch is invalid")
        hard_status = cancellation.get("hard_cancellation_status")
        acknowledgement_status = cancellation.get("acknowledgement_status")
        if hard_status == "unavailable" or acknowledgement_status == "unavailable":
            if hard_status != "unavailable" or acknowledgement_status != "unavailable":
                errors.append("native runtime cancellation evidence is incomplete")
        else:
            try:
                _validate_cancellation_evidence(hard_status, acknowledgement_status)
            except RuntimeStateError:
                errors.append("native runtime cancellation evidence pair is invalid")
            if state.get("status") == "cancel_acknowledged" and (
                hard_status, acknowledgement_status
            ) != ("acknowledged", "acknowledged"):
                errors.append("native runtime cancellation acknowledgement is contradictory")
            if state.get("status") not in {"cancel_acknowledged", "cancelled"} and (
                hard_status, acknowledgement_status
            ) == ("acknowledged", "acknowledged"):
                errors.append("native runtime cancellation acknowledgement is not projected")
    authority_history = state.get("authority_history")
    if not isinstance(authority_history, list) or any(
        not isinstance(item, Mapping)
        or set(item) != {
            "action", "actor", "decision", "event", "details", "payload_hash",
            "lifecycle_sequence", "grant",
        }
        or not isinstance(item.get("details"), Mapping)
        or not isinstance(item.get("lifecycle_sequence"), int)
        or item.get("lifecycle_sequence", 0) < 2
        for item in authority_history
    ):
        errors.append("native runtime authority history is invalid")
    elif isinstance(events, list):
        events_by_sequence = {
            item.get("sequence"): item
            for item in events
            if isinstance(item, Mapping) and isinstance(item.get("sequence"), int)
        }
        authority_sequences: list[int] = []
        for authority in authority_history:
            sequence = authority["lifecycle_sequence"]
            authority_sequences.append(sequence)
            retained = events_by_sequence.get(sequence)
            details = authority["details"]
            payload = {
                "attempt_id": state.get("attempt_id"),
                "work_id": admission.get("work_id") if isinstance(admission, Mapping) else None,
                "cycle_id": admission.get("cycle_id") if isinstance(admission, Mapping) else None,
                "parent_runtime_id": (
                    admission.get("parent_runtime_id") if isinstance(admission, Mapping) else None
                ),
                "action": authority["action"],
                "details": details,
            }
            expected_hash = canonical_digest({
                "command": authority["action"],
                "payload": payload,
            })
            exact_details = (
                {
                    "event": retained.get("event"),
                    "observation": retained.get("payload"),
                }
                if isinstance(retained, Mapping)
                and authority["action"] == "record-native-task-observation"
                else retained.get("payload") if isinstance(retained, Mapping) else None
            )
            if (
                not isinstance(retained, Mapping)
                or retained.get("event") != authority["event"]
                or details != exact_details
                or authority["payload_hash"] != expected_hash
            ):
                errors.append(
                    "native runtime authority payload hash does not bind exact retained transition"
                )
        if (
            authority_sequences != sorted(authority_sequences)
            or len(authority_sequences) != len(set(authority_sequences))
        ):
            errors.append("native runtime authority history order is invalid")
    if state.get("status") in TERMINAL_STATUSES:
        terminal = state.get("terminal")
        if not isinstance(terminal, Mapping) or terminal.get("status") != state.get("status"):
            errors.append("native runtime terminal state is invalid")
        receipt = state.get("receipt")
        if not isinstance(receipt, Mapping) or receipt.get("payload_sha256") != canonical_digest(
            _receipt_payload(state)
        ):
            errors.append("native runtime terminal receipt is invalid")
    elif state.get("receipt") is not None:
        errors.append("active native runtime state cannot contain a terminal receipt")
    elif state.get("terminal") is not None:
        errors.append("active native runtime state cannot contain terminal observation")
    try:
        expected_reconciliation = reconcile_restart(state)["reconciliation"]
        if state.get("reconciliation") != expected_reconciliation:
            errors.append("native runtime reconciliation state is invalid")
    except RuntimeStateError:
        errors.append("native runtime reconciliation state is invalid")
    if isinstance(events, list) and events:
        try:
            replay = _replay_lifecycle(state)
            lifecycle_fields = {
                "status", "dispatch", "native_identity", "host_observations",
                "cancellation", "sequence", "events", "terminal", "receipt",
                "reconciliation",
            }
            if any(state.get(field) != replay.get(field) for field in lifecycle_fields):
                errors.append("native runtime lifecycle does not replay from admission")
        except (KeyError, TypeError, RuntimeStateError):
            errors.append("native runtime lifecycle does not replay from admission")
    return errors


def apply_event(state: Mapping[str, Any], event: str, **payload: Any) -> dict[str, Any]:
    return record_event(state, event, payload=payload)

#!/usr/bin/env python3
"""Fixture-only, feature-off adapter for the OpenAI Responses boundary.

This deliberately contains no provider client or network implementation.  The
only effect boundary is the injected, explicitly-marked fixture transport.
"""

from __future__ import annotations

import base64
import fcntl
import hashlib
import importlib.util
import json
import math
import os
import re
import stat
import subprocess
import tempfile
import uuid
from datetime import datetime, timedelta, timezone
from pathlib import Path
from typing import Any


COMMAND_SCHEMA = "company-os.openai-responses-gateway-command.v1"
REQUEST_KEYRING_SCHEMA = "company-os.openai-responses-request-keyring.v1"
RESULT_SCHEMA = "company-os.runtime-gateway-result.v1"
RECEIPT_SCHEMA = "company-os.runtime-receipt-attestation.v1"
FIXED_INPUT = "Return exactly READY. Do not call tools or perform external actions."
PROVIDER_FIXTURE_SCHEMA = "responses-fixture-no-tools-v1"
PROVIDER_BASE_FIELDS = {"id", "object", "created_at", "status", "model"}
PROVIDER_TERMINAL_FIELDS = PROVIDER_BASE_FIELDS | {"completed_at", "usage"}
PROVIDER_USAGE_FIELDS = {
    "input_tokens", "input_tokens_details", "output_tokens",
    "output_tokens_details", "total_tokens",
}
PROVIDER_INPUT_DETAIL_FIELDS = {"cached_tokens", "cache_write_tokens"}
PROVIDER_OUTPUT_DETAIL_FIELDS = {"reasoning_tokens"}
PROVIDER_USAGE_NUMERIC_PATHS = (
    ("input_tokens",),
    ("input_tokens_details", "cached_tokens"),
    ("input_tokens_details", "cache_write_tokens"),
    ("output_tokens",),
    ("output_tokens_details", "reasoning_tokens"),
    ("total_tokens",),
)
COMMAND_FIELDS = {
    "schema", "request_key_id", "gateway_request", "gateway_request_digest",
    "nonce", "issued_at", "expires_at",
}


class _ResponsesGatewayErrorType(type):
    """Treat the local verifier's fail-closed error as the same boundary error.

    The verifier is deliberately loaded by path in independent consumers, so
    its ``GatewayError`` class can have a distinct Python identity while still
    denoting this adapter's verification boundary.
    """

    def __subclasscheck__(cls, candidate: type[object]) -> bool:
        return (
            getattr(candidate, "__name__", None) == "GatewayError"
            and str(getattr(candidate, "__module__", "")).endswith("runtime_gateway")
        ) or super().__subclasscheck__(candidate)


class ResponsesGatewayError(ValueError, metaclass=_ResponsesGatewayErrorType):
    """A fixture-gateway command which must fail closed."""


def _module(name: str) -> Any:
    path = Path(__file__).resolve().with_name(f"{name}.py")
    spec = importlib.util.spec_from_file_location(f"company_os_{name}", path)
    if spec is None or spec.loader is None:
        raise ResponsesGatewayError("required local verifier is unavailable")
    value = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(value)
    return value


runtime_gateway = _module("runtime_gateway")
observations = _module("runtime_observations")
runtime_lifecycle = _module("runtime_lifecycle")


def _canonical(value: Any) -> str:
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=True, allow_nan=False)


def _digest(value: Any) -> str:
    return hashlib.sha256(_canonical(value).encode("utf-8")).hexdigest()


def _bytes_digest(value: bytes) -> str:
    return hashlib.sha256(value).hexdigest()


def _time(value: Any, field: str) -> datetime:
    if not isinstance(value, str) or not value or value != value.strip():
        raise ResponsesGatewayError(f"{field} is invalid")
    try:
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError:
        raise ResponsesGatewayError(f"{field} is invalid") from None
    if parsed.tzinfo is None:
        raise ResponsesGatewayError(f"{field} is invalid")
    return parsed.astimezone(timezone.utc)


def _iso(value: datetime) -> str:
    return value.astimezone(timezone.utc).isoformat()


def _text(value: Any, field: str) -> str:
    if not isinstance(value, str) or not value or value != value.strip():
        raise ResponsesGatewayError(f"{field} is invalid")
    return value


def _sha(value: Any, field: str) -> str:
    value = _text(value, field)
    if len(value) != 64 or any(item not in "0123456789abcdef" for item in value):
        raise ResponsesGatewayError(f"{field} is invalid")
    return value


def _owner_file(path: Path) -> None:
    try:
        mode = path.stat().st_mode
    except OSError:
        raise ResponsesGatewayError("protected fixture path is unavailable") from None
    if path.is_symlink() or not stat.S_ISREG(mode) or mode & 0o077:
        raise ResponsesGatewayError("protected fixture file is unsafe")


def _owner_only(path: Path, *, mode: int, kind: int | None = None) -> os.stat_result:
    """Validate ownership and exact private permissions without following links."""
    try:
        value = path.lstat()
    except OSError:
        raise ResponsesGatewayError("protected fixture path is unavailable") from None
    if path.is_symlink() or value.st_uid != os.getuid() or value.st_mode & 0o777 != mode:
        raise ResponsesGatewayError("protected fixture path is unsafe")
    if kind is not None and not kind(value.st_mode):
        raise ResponsesGatewayError("protected fixture path is unsafe")
    return value


def _has_symlink_component(path: Path) -> bool:
    """Check the supplied spelling, rather than resolving through a symlink."""
    current = Path(path).absolute()
    parts = current.parts
    probe = Path(parts[0])
    for component in parts[1:]:
        probe /= component
        try:
            if probe.is_symlink():
                return True
        except OSError:
            return True
    return False


def _public_key_fingerprint(path: Path) -> str:
    """Compare normalized DER public material rather than path or PEM spelling."""
    try:
        result = subprocess.run(
            ["openssl", "pkey", "-pubin", "-in", str(path), "-outform", "DER"],
            capture_output=True,
            check=False,
        )
    except OSError:
        raise ResponsesGatewayError("public-key verification support is unavailable") from None
    if result.returncode != 0 or not result.stdout:
        raise ResponsesGatewayError("public-key material is invalid")
    return _bytes_digest(result.stdout)


_SAFE_PROVIDER_TOKEN_PATHS = {
    ("usage", "input_tokens"),
    ("usage", "output_tokens"),
    ("usage", "total_tokens"),
    ("usage", "input_tokens_details"),
    ("usage", "output_tokens_details"),
    ("usage", "input_tokens_details", "cached_tokens"),
    ("usage", "input_tokens_details", "cache_write_tokens"),
    ("usage", "output_tokens_details", "reasoning_tokens"),
}


def _normalized_key(value: object) -> str:
    return re.sub(r"(?<!^)(?=[A-Z])", "_", str(value)).casefold().replace("-", "_")


def _contains_secret(value: Any, *, key: str = "", path: tuple[str, ...] = ()) -> bool:
    """Reject authority-bearing input without ever reflecting it in diagnostics."""
    lowered = _normalized_key(key)
    current_path = (*path, lowered) if key else path
    safe_token_count = current_path in _SAFE_PROVIDER_TOKEN_PATHS
    if key != "admission_grant_token" and (
        any(word in lowered for word in (
            "secret", "credential", "password", "api_key", "private_key",
            "authorization", "access_token", "refresh_token", "bearer_token",
        ))
        or ((lowered == "token" or lowered.endswith("_token")) and not safe_token_count)
    ):
        return True
    if isinstance(value, dict):
        return any(
            _contains_secret(item, key=str(name), path=current_path)
            for name, item in value.items()
        )
    if isinstance(value, list):
        return any(_contains_secret(item, path=current_path) for item in value)
    if isinstance(value, str):
        sample = value.casefold()
        return bool(
            sample.startswith("sk-")
            or re.search(r"(?:authorization\s*:\s*)?(?:bearer|basic)\s+[^\s]{4,}", sample)
        )
    return False


def _provider_contains_credential(
    value: Any, *, key: str = "", path: tuple[str, ...] = ()
) -> bool:
    """Aggressive defense-in-depth for the accepted provider fixture shape."""
    lowered = _normalized_key(key)
    current_path = (*path, lowered) if key else path
    safe_token_count = current_path in _SAFE_PROVIDER_TOKEN_PATHS
    if key and not safe_token_count and (
        any(word in lowered for word in (
            "secret", "credential", "password", "authorization", "auth",
            "token", "jwt", "private_key", "signing_key", "api_key",
            "access_key", "client_key", "provider_key", "bearer",
        ))
        or lowered == "key"
        or lowered.endswith("_key")
        or lowered.endswith("_keys")
    ):
        return True
    if isinstance(value, dict):
        return any(
            _provider_contains_credential(item, key=str(name), path=current_path)
            for name, item in value.items()
        )
    if isinstance(value, list):
        return any(_provider_contains_credential(item, path=current_path) for item in value)
    if isinstance(value, str):
        sample = value.strip()
        return bool(
            sample.casefold().startswith("sk-")
            or re.search(
                r"(?:authorization\s*:\s*)?(?:bearer|basic)\s+[^\s]{4,}",
                sample,
                re.I,
            )
            or re.fullmatch(r"eyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+", sample)
        )
    return False


def _validated_provider_usage(source: Any) -> dict[str, Any]:
    """Validate the complete versioned usage schema and all count provenance."""
    if (
        not isinstance(source, dict)
        or set(source) != PROVIDER_USAGE_FIELDS
        or not isinstance(source.get("input_tokens_details"), dict)
        or set(source["input_tokens_details"]) != PROVIDER_INPUT_DETAIL_FIELDS
        or not isinstance(source.get("output_tokens_details"), dict)
        or set(source["output_tokens_details"]) != PROVIDER_OUTPUT_DETAIL_FIELDS
    ):
        raise ResponsesGatewayError("provider terminal usage is invalid")

    numbers: dict[tuple[str, ...], int] = {}
    for path in PROVIDER_USAGE_NUMERIC_PATHS:
        value: Any = source
        for component in path:
            if not isinstance(value, dict):
                raise ResponsesGatewayError("provider terminal usage is invalid")
            value = value.get(component)
        if not isinstance(value, int) or isinstance(value, bool) or value < 0:
            raise ResponsesGatewayError("provider terminal usage is invalid")
        numbers[path] = value

    input_tokens = numbers[("input_tokens",)]
    cached_tokens = numbers[("input_tokens_details", "cached_tokens")]
    cache_write_tokens = numbers[("input_tokens_details", "cache_write_tokens")]
    output_tokens = numbers[("output_tokens",)]
    reasoning_tokens = numbers[("output_tokens_details", "reasoning_tokens")]
    total_tokens = numbers[("total_tokens",)]
    if (
        total_tokens != input_tokens + output_tokens
        or cached_tokens + cache_write_tokens > input_tokens
        or reasoning_tokens > output_tokens
    ):
        raise ResponsesGatewayError("provider terminal usage is invalid")
    return source


class FixtureResponsesGateway:
    def __init__(
        self,
        *,
        socket_path: Path,
        state_path: Path,
        artifact_root: Path,
        request_keyring_path: Path,
        gateway_keyring_path: Path,
        gateway_key_id: str,
        gateway_private_key_path: Path,
        decision_public_key_path: Path,
        now: datetime,
    ) -> None:
        self.socket_path = Path(socket_path)
        self.state_path = Path(state_path)
        self.artifact_root = Path(artifact_root)
        self.request_keyring_path = Path(request_keyring_path)
        self.gateway_keyring_path = Path(gateway_keyring_path)
        self.gateway_key_id = gateway_key_id
        self.gateway_private_key_path = Path(gateway_private_key_path)
        self.decision_public_key_path = Path(decision_public_key_path)
        if not isinstance(now, datetime) or now.tzinfo is None:
            raise ResponsesGatewayError("fixture clock is invalid")
        self.now = now.astimezone(timezone.utc)

    def _boundary(self) -> Path:
        """Return the dedicated fixture root after rejecting all path escapes."""
        try:
            socket_mode = self.socket_path.lstat().st_mode
        except OSError:
            raise ResponsesGatewayError("fixture socket is unavailable") from None
        if _has_symlink_component(self.socket_path) or not stat.S_ISSOCK(socket_mode):
            raise ResponsesGatewayError("fixture socket is unsafe")
        _owner_only(self.socket_path, mode=0o600, kind=stat.S_ISSOCK)
        if _has_symlink_component(self.artifact_root) or not self.artifact_root.is_dir():
            raise ResponsesGatewayError("fixture artifact root is unsafe")
        try:
            artifact_mode = self.artifact_root.stat().st_mode
        except OSError:
            raise ResponsesGatewayError("fixture artifact root is unavailable") from None
        _owner_only(self.artifact_root, mode=0o700, kind=stat.S_ISDIR)
        root = self.socket_path.resolve().parent
        if _has_symlink_component(self.state_path) or self.state_path.resolve().parent != root:
            raise ResponsesGatewayError("fixture state path escapes its root")
        if self.artifact_root.resolve().parent != root:
            raise ResponsesGatewayError("fixture artifact root escapes its root")
        if self.state_path.exists():
            _owner_only(self.state_path, mode=0o600, kind=stat.S_ISREG)
        if (
            _has_symlink_component(self.decision_public_key_path)
            or not self.decision_public_key_path.is_file()
        ):
            raise ResponsesGatewayError("decision issuer public key is unavailable")
        lock = self.state_path.with_name(self.state_path.name + ".lock")
        if lock.exists():
            _owner_file(lock)
        return root

    def _load_request_key(self, key_id: str, valid_at: datetime) -> Path:
        try:
            keyring = observations.load_json_strict(self.request_keyring_path.resolve())
        except ValueError as exc:
            raise ResponsesGatewayError("request keyring is invalid") from exc
        if not isinstance(keyring, dict) or set(keyring) != {"schema", "keys"} or keyring.get("schema") != REQUEST_KEYRING_SCHEMA:
            raise ResponsesGatewayError("request keyring is invalid")
        if not isinstance(keyring["keys"], list):
            raise ResponsesGatewayError("request keyring is invalid")
        selected: dict[str, Any] | None = None
        for item in keyring["keys"]:
            required = {"key_id", "algorithm", "public_key_path", "status", "not_before", "not_after"}
            if not isinstance(item, dict) or set(item) != required:
                raise ResponsesGatewayError("request keyring is invalid")
            if item.get("key_id") == key_id:
                if selected is not None:
                    raise ResponsesGatewayError("request keyring is invalid")
                selected = item
        if selected is None or selected.get("algorithm") != "rsa-sha256" or selected.get("status") != "active":
            raise ResponsesGatewayError("request signing key is not active")
        not_before, not_after = _time(selected.get("not_before"), "not_before"), _time(selected.get("not_after"), "not_after")
        if not_before > valid_at or not_after <= valid_at or not_after <= not_before:
            raise ResponsesGatewayError("request signing key is outside its validity window")
        public = Path(_text(selected.get("public_key_path"), "public_key_path"))
        if not public.is_absolute():
            public = self.request_keyring_path.resolve().parent / public
        public = public.resolve()
        if not public.is_file() or public.is_symlink():
            raise ResponsesGatewayError("request public key is unavailable")
        return public

    def _verify_command(self, envelope: Any) -> tuple[dict[str, Any], dict[str, Any], str, str, str]:
        if not isinstance(envelope, dict) or set(envelope) != {"claims", "signature"}:
            raise ResponsesGatewayError("command envelope is invalid")
        claims = envelope.get("claims")
        if not isinstance(claims, dict) or set(claims) != COMMAND_FIELDS or claims.get("schema") != COMMAND_SCHEMA:
            raise ResponsesGatewayError("command claims are invalid")
        if _contains_secret({key: value for key, value in claims.items() if key != "gateway_request"}):
            raise ResponsesGatewayError("command contains forbidden authority")
        issued_at, expires_at = _time(claims.get("issued_at"), "issued_at"), _time(claims.get("expires_at"), "expires_at")
        if issued_at > self.now + timedelta(seconds=30) or expires_at <= self.now or expires_at <= issued_at or expires_at - issued_at > timedelta(minutes=5):
            raise ResponsesGatewayError("command validity window is invalid")
        request = self._request(claims.get("gateway_request"))
        request_digest = _sha(claims.get("gateway_request_digest"), "gateway_request_digest")
        if request_digest != _digest(request):
            raise ResponsesGatewayError("command request digest is invalid")
        public = self._load_request_key(_text(claims.get("request_key_id"), "request_key_id"), issued_at)
        try:
            observations.verify_signature(claims, envelope.get("signature"), public)
        except ValueError as exc:
            raise ResponsesGatewayError("command signature is invalid") from exc
        return claims, request, request_digest, _digest(claims), _public_key_fingerprint(public)

    def _request(self, request: Any) -> dict[str, Any]:
        if not isinstance(request, dict):
            raise ResponsesGatewayError("gateway request is invalid")
        fields = {"schema", "operation", "attempt", "provider_task_id", "admission_grant_token", "admission_grant_digest", "lease_fence", "external_effects_allowed", "request_digest"}
        if set(request) != fields or request.get("schema") != runtime_gateway.REQUEST_SCHEMA:
            raise ResponsesGatewayError("gateway request is invalid")
        unsigned = {key: value for key, value in request.items() if key != "request_digest"}
        if request.get("request_digest") != _digest(unsigned):
            raise ResponsesGatewayError("gateway request digest is invalid")
        operation = request.get("operation")
        if operation not in {"launch", "query", "observe", "cancel"} or request.get("external_effects_allowed") is not False:
            raise ResponsesGatewayError("gateway request is invalid")
        attempt = request.get("attempt")
        required_attempt = set(runtime_gateway.IMMUTABLE_ATTEMPT_FIELDS)
        if not isinstance(attempt, dict) or set(attempt) != required_attempt:
            raise ResponsesGatewayError("gateway request attempt is invalid")
        if attempt.get("provider") != "openai" or attempt.get("surface") != "responses-api" or attempt.get("requested_model") not in {"gpt-5.6-sol", "gpt-5.6-luna"}:
            raise ResponsesGatewayError("gateway request is outside the fixture canary")
        for field in ("attempt_id", "project_id", "work_id", "cycle_id", "parent_runtime_id", "role", "account", "idempotency_key"):
            _text(attempt.get(field), field)
        _sha(attempt.get("fabric_manifest_digest"), "fabric_manifest_digest")
        _sha(attempt.get("phase2_contract_digest"), "phase2_contract_digest")
        if attempt.get("capabilities") != ["emit_artifact", "read_project"]:
            raise ResponsesGatewayError("gateway request exceeds the fixture capabilities")
        if not isinstance(attempt.get("scope"), list) or attempt.get("scope_digest") != _digest(attempt["scope"]):
            raise ResponsesGatewayError("gateway request scope binding is invalid")
        if attempt.get("role") == "manager":
            if attempt.get("requested_model") != "gpt-5.6-sol" or attempt.get("parent_runtime_id") != "master":
                raise ResponsesGatewayError("gateway request manager identity is invalid")
        elif attempt.get("role") == "worker":
            if attempt.get("requested_model") != "gpt-5.6-luna" or attempt.get("parent_runtime_id") == "master":
                raise ResponsesGatewayError("gateway request worker identity is invalid")
        else:
            raise ResponsesGatewayError("gateway request role is invalid")
        budget = attempt.get("budget")
        expected_budget = {"time_minutes", "token_limit", "cost_usd", "max_concurrency", "max_retries"}
        if not isinstance(budget, dict) or set(budget) != expected_budget:
            raise ResponsesGatewayError("gateway request budget is invalid")
        if any(not isinstance(budget.get(name), int) or isinstance(budget[name], bool) or budget[name] < 0 for name in ("token_limit", "max_concurrency", "max_retries")):
            raise ResponsesGatewayError("gateway request budget is invalid")
        if any(not isinstance(budget.get(name), (int, float)) or isinstance(budget[name], bool) or not math.isfinite(budget[name]) or budget[name] < 0 for name in ("time_minutes", "cost_usd")) or budget["max_concurrency"] != 1 or budget["max_retries"] != 0:
            raise ResponsesGatewayError("gateway request budget is invalid")
        fence = request.get("lease_fence")
        if not isinstance(fence, dict) or any(fence.get(name) in (None, "") for name in ("lease_id", "generation", "owner", "program_version", "expires_at")):
            raise ResponsesGatewayError("gateway request lease fence is invalid")
        if not isinstance(fence.get("generation"), int) or isinstance(fence["generation"], bool) or fence["generation"] < 0 or fence.get("program_version") != attempt.get("program_version") or _time(fence["expires_at"], "lease_fence.expires_at") <= self.now:
            raise ResponsesGatewayError("gateway request lease fence is invalid")
        _sha(request.get("admission_grant_digest"), "admission_grant_digest")
        _text(request.get("admission_grant_token"), "admission_grant_token")
        if _contains_secret({key: value for key, value in request.items() if key != "admission_grant_token"}):
            raise ResponsesGatewayError("gateway request contains forbidden authority")
        task = request.get("provider_task_id")
        if operation in {"observe", "cancel"} and not isinstance(task, str):
            raise ResponsesGatewayError("gateway request lacks provider task identity")
        if operation in {"launch", "query"} and task is not None:
            raise ResponsesGatewayError("gateway request has invalid provider task identity")
        return request

    def _gateway_key(self) -> tuple[Path, str]:
        try:
            public = observations.load_gateway_key(self.gateway_keyring_path, _text(self.gateway_key_id, "gateway_key_id"), self.now)
        except ValueError as exc:
            raise ResponsesGatewayError("gateway signing key is unavailable") from exc
        _owner_only(self.gateway_private_key_path, mode=0o600, kind=stat.S_ISREG)
        # Compare only public material derived by OpenSSL; private key bytes are never read into Python or state.
        try:
            derived = subprocess.run(["openssl", "pkey", "-in", str(self.gateway_private_key_path), "-pubout"], capture_output=True, check=False)
        except OSError:
            raise ResponsesGatewayError("gateway signing support is unavailable") from None
        if derived.returncode != 0 or derived.stdout != public.read_bytes():
            raise ResponsesGatewayError("gateway private key does not match active public key")
        return public, _public_key_fingerprint(public)

    def _sign(self, claims: dict[str, Any]) -> dict[str, Any]:
        self._gateway_key()
        try:
            with tempfile.NamedTemporaryFile() as payload, tempfile.NamedTemporaryFile() as signature:
                payload.write(_canonical(claims).encode("utf-8"))
                payload.flush()
                result = subprocess.run(["openssl", "dgst", "-sha256", "-sign", str(self.gateway_private_key_path), "-out", signature.name, payload.name], capture_output=True, check=False)
                if result.returncode != 0:
                    raise ResponsesGatewayError("gateway signing failed")
                signature.seek(0)
                encoded = base64.urlsafe_b64encode(signature.read()).decode("ascii").rstrip("=")
        except OSError:
            raise ResponsesGatewayError("gateway signing support is unavailable") from None
        return {"claims": claims, "signature": encoded}

    def _empty_state(self) -> dict[str, Any]:
        return {"schema": "company-os.fixture-responses-gateway-state.v1", "commands": {}, "attempts": {}, "nonces": {}}

    def _load_state(self) -> dict[str, Any]:
        if not self.state_path.exists():
            return self._empty_state()
        _owner_file(self.state_path)
        try:
            state = observations.load_json_strict(self.state_path)
        except ValueError as exc:
            raise ResponsesGatewayError("fixture state is invalid") from exc
        if not isinstance(state, dict) or set(state) != {"schema", "commands", "attempts", "nonces"} or state.get("schema") != self._empty_state()["schema"]:
            raise ResponsesGatewayError("fixture state is invalid")
        if not all(isinstance(state[key], dict) for key in ("commands", "attempts", "nonces")):
            raise ResponsesGatewayError("fixture state is invalid")
        return state

    def _write_state(self, state: dict[str, Any]) -> None:
        data = _canonical(state).encode("utf-8")
        temporary = self.state_path.with_name(self.state_path.name + ".tmp-" + uuid.uuid4().hex)
        try:
            descriptor = os.open(str(temporary), os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
            with os.fdopen(descriptor, "wb") as handle:
                handle.write(data)
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(temporary, self.state_path)
            os.chmod(self.state_path, 0o600)
            directory = os.open(str(self.state_path.parent), os.O_RDONLY)
            try:
                os.fsync(directory)
            finally:
                os.close(directory)
        except OSError as exc:
            try:
                temporary.unlink(missing_ok=True)
            except OSError:
                pass
            raise ResponsesGatewayError("fixture state cannot be persisted") from exc

    def _raw_path(self, label: str, digest: str) -> tuple[Path, str]:
        relative = f"{label}-{digest}.json"
        path = self.artifact_root / relative
        if path.resolve().parent != self.artifact_root.resolve():
            raise ResponsesGatewayError("fixture artifact path escapes its root")
        return path, relative

    def _write_artifact(self, label: str, value: bytes) -> str:
        digest = _bytes_digest(value)
        path, relative = self._raw_path(label, digest)
        if path.exists():
            _owner_file(path)
            if path.read_bytes() != value:
                raise ResponsesGatewayError("fixture artifact collision")
            return relative
        temporary = path.with_name(path.name + ".tmp-" + uuid.uuid4().hex)
        try:
            descriptor = os.open(str(temporary), os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
            with os.fdopen(descriptor, "wb") as handle:
                handle.write(value)
                handle.flush()
                os.fsync(handle.fileno())
            os.replace(temporary, path)
            os.chmod(path, 0o600)
            directory = os.open(str(self.artifact_root), os.O_RDONLY)
            try:
                os.fsync(directory)
            finally:
                os.close(directory)
        except OSError as exc:
            try:
                temporary.unlink(missing_ok=True)
            except OSError:
                pass
            raise ResponsesGatewayError("fixture artifact cannot be persisted") from exc
        return relative

    def _artifact_snapshot(self) -> set[str]:
        """Capture the serialized fixture artifact namespace under the gateway lock."""
        return {
            item.name
            for item in self.artifact_root.iterdir()
            if item.is_file() and not item.is_symlink()
        }

    def _cleanup_attempt_artifacts(self, before: set[str]) -> bool:
        """Remove only files created by the current serialized attempt."""
        clean = True
        try:
            candidates = list(self.artifact_root.iterdir())
        except OSError:
            return False
        for item in candidates:
            if item.name in before:
                continue
            try:
                if item.is_symlink() or not item.is_file():
                    clean = False
                    continue
                _owner_only(item, mode=0o600, kind=stat.S_ISREG)
                item.unlink()
            except (OSError, ResponsesGatewayError):
                clean = False
        try:
            directory = os.open(str(self.artifact_root), os.O_RDONLY)
            try:
                os.fsync(directory)
            finally:
                os.close(directory)
        except OSError:
            clean = False
        return clean

    def _persist_launch_unknown_after_effect(
        self,
        *,
        state: dict[str, Any],
        entry: dict[str, Any],
        artifact_snapshot: set[str],
    ) -> None:
        """Best-effort durable ambiguity boundary after a possible create effect."""
        for field in ("model", "raw_retained", "result"):
            entry.pop(field, None)
        entry.update({
            "status": "launch_unknown",
            "provider_task_id": None,
            "terminal": False,
            "sequence": 1,
        })
        try:
            self._write_state(state)
        except ResponsesGatewayError:
            raise ResponsesGatewayError(
                "launch_state_unpersisted: provider create may have taken effect; "
                "the retained launch tombstone or raw identity forbids automatic relaunch"
            ) from None
        cleanup_complete = self._cleanup_attempt_artifacts(artifact_snapshot)
        if not cleanup_complete:
            raise ResponsesGatewayError(
                "provider create outcome is ambiguous and attempt artifact cleanup is incomplete"
            )

    def _provider(
        self,
        raw_bytes: bytes,
        request: dict[str, Any],
        operation: str,
        retained_task: str | None,
        *,
        retain: bool = True,
    ) -> dict[str, Any]:
        if not isinstance(raw_bytes, bytes):
            raise ResponsesGatewayError("fixture transport must return raw bytes")
        try:
            provider = observations.load_json_bytes_strict(raw_bytes)
        except ValueError as exc:
            raise ResponsesGatewayError("provider fixture JSON is invalid") from exc
        if (
            not isinstance(provider, dict)
            or _contains_secret(provider)
            or _provider_contains_credential(provider)
        ):
            raise ResponsesGatewayError("provider fixture is invalid")
        raw_status = provider.get("status")
        terminal = raw_status in {"completed", "failed", "cancelled", "incomplete"}
        expected_fields = PROVIDER_TERMINAL_FIELDS if terminal else PROVIDER_BASE_FIELDS
        if set(provider) != expected_fields or provider.get("object") != "response":
            raise ResponsesGatewayError("provider fixture schema is invalid")
        task_id = _text(provider.get("id"), "provider response id")
        model = _text(provider.get("model"), "provider response model")
        status = _text(provider.get("status"), "provider response status")
        if model != request["attempt"]["requested_model"]:
            raise ResponsesGatewayError("provider response model is not admitted")
        if retained_task is not None and task_id != retained_task:
            raise ResponsesGatewayError("provider response changes task identity")
        created_at = provider.get("created_at")
        if not isinstance(created_at, (int, float)) or isinstance(created_at, bool) or not math.isfinite(created_at):
            raise ResponsesGatewayError("provider response timestamp is invalid")
        try:
            provider_time = datetime.fromtimestamp(created_at, timezone.utc)
        except (OverflowError, OSError, ValueError):
            raise ResponsesGatewayError("provider response timestamp is invalid") from None
        if terminal:
            completed_at = provider.get("completed_at")
            if not isinstance(completed_at, (int, float)) or isinstance(completed_at, bool) or not math.isfinite(completed_at) or completed_at < created_at:
                raise ResponsesGatewayError("provider terminal timestamp is invalid")
            try:
                provider_time = datetime.fromtimestamp(completed_at, timezone.utc)
            except (OverflowError, OSError, ValueError):
                raise ResponsesGatewayError("provider terminal timestamp is invalid") from None
        if provider_time > self.now + runtime_gateway.MAX_FUTURE_SKEW:
            raise ResponsesGatewayError("provider response timestamp exceeds allowed clock skew")
        provider_usage: dict[str, Any] | None = None
        if terminal:
            source = _validated_provider_usage(provider.get("usage"))
            # Preserve the exact provider object.  Responses usage does not
            # establish a dollar cost, so it is intentionally not projected as
            # lifecycle telemetry until separately priced evidence exists.
            provider_usage = source
        if status not in {"in_progress", "queued", "completed", "failed", "cancelled", "incomplete"}:
            raise ResponsesGatewayError("provider response status is unsupported")
        normalized_status = {"completed": "succeeded", "failed": "failed", "cancelled": "cancelled", "incomplete": "failed"}.get(status)
        payload: dict[str, Any] = {
            "provider_status": status,
            "status": normalized_status,
            "usage": None,
            "fixed_input_sha256": _bytes_digest(FIXED_INPUT.encode("utf-8")),
            "provider_fixture_schema": PROVIDER_FIXTURE_SCHEMA,
        }
        if terminal:
            payload["provider_usage"] = provider_usage
            payload["cost_status"] = "unavailable"
        info = {
            "task_id": task_id,
            "model": model,
            "status": status,
            "terminal": terminal,
            "provider_time": _iso(provider_time),
            "payload": payload,
            "raw_sha": _bytes_digest(raw_bytes),
        }
        return self._retain_provider(info, raw_bytes) if retain else info

    def _retain_provider(self, info: dict[str, Any], raw_bytes: bytes) -> dict[str, Any]:
        """Retain exact bytes only after every positive-schema/identity check."""
        retained = {
            **info,
            "payload": dict(info["payload"]),
        }
        raw_source_path = self._write_artifact("provider", raw_bytes)
        retained["raw_source_path"] = raw_source_path
        retained["payload"].update({
            "provider_raw_artifact_path": raw_source_path,
            "provider_raw_sha256": _bytes_digest(raw_bytes),
            "provider_raw_size": len(raw_bytes),
        })
        return retained

    def _record(self, request: dict[str, Any], request_digest: str, event: str, info: dict[str, Any], sequence: int) -> tuple[dict[str, Any], dict[str, Any]]:
        attempt = request["attempt"]
        task = info.get("task_id")
        raw = {
            "provider": attempt["provider"], "surface": attempt["surface"], "account": attempt["account"],
            "provider_task_id": task, "provider_event_id": f"fixture-{_digest([request_digest, event, sequence, info.get('raw_sha', '')])}",
            "event_type": event, "provider_sequence": sequence, "provider_timestamp": info["provider_time"],
            "observed_model": info.get("model"), "payload": info["payload"],
        }
        raw_bytes = _canonical(raw).encode("utf-8")
        raw_path = self._write_artifact("observation", raw_bytes)
        issued = self.now
        received_at = max(self.now, _time(info["provider_time"], "provider_time"))
        claims = {
            "schema": RESULT_SCHEMA, "gateway_key_id": self.gateway_key_id, "request_digest": request["request_digest"],
            "operation": request["operation"], "provider": attempt["provider"], "surface": attempt["surface"], "account": attempt["account"],
            "provider_task_id": task, "provider_event_id": raw["provider_event_id"], "event_type": event,
            "provider_sequence": sequence, "provider_timestamp": info["provider_time"], "gateway_received_at": _iso(received_at),
            "observed_model": info.get("model"), "raw_artifact_path": raw_path, "raw_artifact_sha256": _bytes_digest(raw_bytes),
            "payload_sha256": _digest(raw["payload"]),
            "project_id": attempt["project_id"], "program_version": attempt["program_version"], "work_id": attempt["work_id"],
            "cycle_id": attempt["cycle_id"], "attempt_id": attempt["attempt_id"], "parent_runtime_id": attempt["parent_runtime_id"],
            "role": attempt["role"], "requested_model": attempt["requested_model"], "fabric_manifest_digest": attempt["fabric_manifest_digest"],
            "phase2_contract_digest": attempt["phase2_contract_digest"], "nonce": uuid.uuid4().hex,
            "issued_at": _iso(issued), "expires_at": _iso(issued + timedelta(minutes=4)),
        }
        return self._sign(claims), {"raw_path": raw_path, "raw_sha": _bytes_digest(raw_bytes), "event": event, "task_id": task, "model": info.get("model"), "provider_time": info["provider_time"], "payload": info["payload"], "sequence": sequence, "terminal": bool(info.get("terminal"))}

    def _unknown(self, request: dict[str, Any], request_digest: str, sequence: int) -> tuple[dict[str, Any], dict[str, Any]]:
        info = {"task_id": None, "model": None, "provider_time": _iso(self.now), "raw_sha": "", "payload": {"provider_status": "launch_unknown", "usage": None}}
        return self._record(request, request_digest, "launch_unknown", info, sequence)

    def handle(self, signed_command: dict[str, object], *, transport: object) -> dict[str, object]:
        self._boundary()
        if getattr(transport, "fixture_only", None) is not True or any(not callable(getattr(transport, name, None)) for name in ("create", "retrieve", "cancel")):
            raise ResponsesGatewayError("fixture transport is not explicitly fixture-only")
        claims, request, request_digest, command_digest, request_key_fingerprint = self._verify_command(signed_command)
        # Validate the distinct signing authority before creating a tombstone
        # or crossing the fixture transport boundary.
        _, gateway_key_fingerprint = self._gateway_key()
        if request_key_fingerprint == gateway_key_fingerprint:
            raise ResponsesGatewayError("request verification and result signing keys must be distinct")
        lock_path = self.state_path.with_name(self.state_path.name + ".lock")
        lock_flags = os.O_WRONLY | os.O_CREAT | getattr(os, "O_NOFOLLOW", 0)
        try:
            descriptor = os.open(str(lock_path), lock_flags, 0o600)
            lock_stat = os.fstat(descriptor)
        except OSError:
            raise ResponsesGatewayError("fixture lock is unsafe") from None
        if not stat.S_ISREG(lock_stat.st_mode) or lock_stat.st_uid != os.getuid() or lock_stat.st_mode & 0o777 != 0o600:
            os.close(descriptor)
            raise ResponsesGatewayError("fixture lock is unsafe")
        try:
            os.chmod(lock_path, 0o600)
            with os.fdopen(descriptor, "r+b") as lock:
                fcntl.flock(lock.fileno(), fcntl.LOCK_EX)
                state = self._load_state()
                nonce = claims["nonce"]
                prior_nonce = state["nonces"].get(nonce)
                if prior_nonce is not None and prior_nonce != command_digest:
                    raise ResponsesGatewayError("command nonce was already used")
                command = state["commands"].get(request_digest)
                if command is not None:
                    if command.get("command_digest") != command_digest:
                        raise ResponsesGatewayError("changed duplicate command conflicts")
                    if isinstance(command.get("result"), dict):
                        return command["result"]
                attempt_id = request["attempt"]["attempt_id"]
                entry = state["attempts"].get(attempt_id)
                operation = request["operation"]
                if entry is not None and (
                    entry.get("attempt_identity") != request["attempt"]
                    or entry.get("attempt_identity_digest") != _digest(request["attempt"])
                ):
                    raise ResponsesGatewayError("runtime attempt identity conflicts with retained admission")
                if operation == "launch":
                    if entry is not None:
                        if entry.get("request_digest") != request_digest:
                            raise ResponsesGatewayError("attempt launch conflicts")
                        if entry.get("status") == "raw_retained":
                            result, details = self._finish_retained(request, request_digest, entry)
                        elif entry.get("status") in {"launching", "launch_unknown"}:
                            result, details = self._unknown(request, request_digest, int(entry.get("sequence", 0)) + 1)
                            entry["status"] = "launch_unknown"
                        else:
                            raise ResponsesGatewayError("attempt launch state is invalid")
                    else:
                        entry = {"request_digest": request_digest, "status": "launching", "sequence": 0, "provider_task_id": None, "terminal": False, "attempt_identity": request["attempt"], "attempt_identity_digest": _digest(request["attempt"])}
                        state["attempts"][attempt_id] = entry
                        state["nonces"][nonce] = command_digest
                        self._write_state(state)  # durable pre-effect launch tombstone
                        try:
                            raw = transport.create(_canonical({"background": True, "input": FIXED_INPUT, "model": request["attempt"]["requested_model"], "store": False, "tools": []}).encode("utf-8"))
                        except Exception:
                            result, details = self._unknown(request, request_digest, 1)
                            entry["status"] = "launch_unknown"
                        else:
                            artifact_snapshot = self._artifact_snapshot()
                            try:
                                info = self._provider(
                                    raw, request, operation, None, retain=False
                                )
                                if any(
                                    other_id != attempt_id and other.get("provider_task_id") == info["task_id"]
                                    for other_id, other in state["attempts"].items()
                                    if isinstance(other, dict)
                                ):
                                    raise ResponsesGatewayError("provider task is already bound")
                                info = self._retain_provider(info, raw)
                                result, details = self._record(request, request_digest, "launch", info, 1)
                            except Exception as exc:
                                # The provider effect may already exist even when its
                                # returned identity or retained evidence is invalid.
                                # Persist the terminal transport ambiguity now; a
                                # later exact replay must never call create again.
                                self._persist_launch_unknown_after_effect(
                                    state=state,
                                    entry=entry,
                                    artifact_snapshot=artifact_snapshot,
                                )
                                if isinstance(exc, ResponsesGatewayError):
                                    raise
                                raise ResponsesGatewayError(
                                    "provider create outcome is ambiguous"
                                ) from None
                            # Persist identity and exact raw evidence first.  The optional fault
                            # seam deliberately leaves this state without a signed result.
                            entry.update({"status": "raw_retained", "provider_task_id": info["task_id"], "model": info["model"], "sequence": 1, "raw_retained": details, "terminal": bool(info["terminal"])})
                            try:
                                self._write_state(state)
                            except ResponsesGatewayError:
                                self._persist_launch_unknown_after_effect(
                                    state=state,
                                    entry=entry,
                                    artifact_snapshot=artifact_snapshot,
                                )
                                raise ResponsesGatewayError(
                                    "provider create outcome is ambiguous after identity retention failure"
                                ) from None
                            fault = getattr(transport, "fixture_fault_after_raw_retain", None)
                            if isinstance(fault, BaseException):
                                raise fault
                            entry["status"] = "terminal" if info["terminal"] else "active"
                    entry["sequence"] = details["sequence"]
                elif operation == "query":
                    if entry is None or entry.get("status") not in {"launching", "launch_unknown"}:
                        raise ResponsesGatewayError("query cannot reconcile this fixture attempt")
                    result, details = self._unknown(request, request_digest, int(entry.get("sequence", 0)) + 1)
                    entry["status"] = "launch_unknown"
                    entry["sequence"] = details["sequence"]
                else:
                    if entry is None or entry.get("provider_task_id") != request.get("provider_task_id"):
                        raise ResponsesGatewayError("operation task binding is invalid")
                    if operation == "cancel" and entry.get("cancel_unknown"):
                        raise ResponsesGatewayError("fixture cancellation remains terminally ambiguous")
                    if operation == "cancel" and entry.get("cancel_intent") and entry.get("cancel_result") is None:
                        # The process may have stopped after persisting intent and
                        # before a durable response.  A second provider cancel is
                        # unsafe because the first may already have taken effect.
                        entry["status"] = "cancel_unknown"
                        entry["cancel_unknown"] = True
                        entry["cancel_request_digest"] = request_digest
                        self._write_state(state)
                        raise ResponsesGatewayError("fixture cancellation remains terminally ambiguous")
                    if operation == "cancel" and entry.get("cancel_result") is not None:
                        if entry.get("cancel_request_digest") != request_digest:
                            raise ResponsesGatewayError("changed duplicate cancellation conflicts")
                        return entry["cancel_result"]
                    if operation == "observe" and command is not None and isinstance(command.get("result"), dict):
                        return command["result"]
                    if operation == "observe" and entry.get("terminal"):
                        result, details = self._finish_retained(request, request_digest, entry)
                        state["nonces"][nonce] = command_digest
                        state["commands"][request_digest] = {"command_digest": command_digest, "result": result}
                        self._write_state(state)
                        return result
                    if operation == "cancel":
                        entry["cancel_intent"] = True
                        entry["cancel_command_digest"] = command_digest
                        self._write_state(state)
                        try:
                            raw = transport.cancel(entry["provider_task_id"])
                            info = self._provider(raw, request, operation, entry["provider_task_id"])
                            event = "terminal" if info["terminal"] else "cancel_acknowledged"
                            result, details = self._record(request, request_digest, event, info, int(entry.get("sequence", 0)) + 1)
                        except BaseException:
                            # A cancel may have reached the provider; do not retry or
                            # serialize transport diagnostics (which may contain secrets).
                            entry["status"] = "cancel_unknown"
                            entry["cancel_unknown"] = True
                            entry["cancel_request_digest"] = request_digest
                            self._write_state(state)
                            raise ResponsesGatewayError("fixture cancellation outcome is ambiguous") from None
                    else:
                        raw = transport.retrieve(entry["provider_task_id"])
                        info = self._provider(raw, request, operation, entry["provider_task_id"])
                        event = "terminal" if info["terminal"] else "running"
                        result, details = self._record(request, request_digest, event, info, int(entry.get("sequence", 0)) + 1)
                    entry.update({"sequence": details["sequence"], "raw_retained": details, "terminal": bool(info["terminal"])})
                    if operation == "cancel":
                        entry["cancel_result"] = result
                        entry["cancel_request_digest"] = request_digest
                state["nonces"][nonce] = command_digest
                state["commands"][request_digest] = {"command_digest": command_digest, "result": result}
                entry["result"] = result
                self._write_state(state)
                return result
        finally:
            # fdopen owns descriptor on the normal path; only close it if opening the wrapper failed.
            try:
                os.close(descriptor)
            except OSError:
                pass

    def _finish_retained(self, request: dict[str, Any], request_digest: str, entry: dict[str, Any]) -> tuple[dict[str, Any], dict[str, Any]]:
        details = entry.get("raw_retained")
        if not isinstance(details, dict):
            raise ResponsesGatewayError("retained raw fixture evidence is invalid")
        raw_path = self.artifact_root / str(details.get("raw_path", ""))
        if raw_path.resolve().parent != self.artifact_root.resolve() or not raw_path.is_file() or raw_path.is_symlink():
            raise ResponsesGatewayError("retained raw fixture evidence is missing")
        _owner_only(raw_path, mode=0o600, kind=stat.S_ISREG)
        try:
            raw_bytes = raw_path.read_bytes()
            raw = observations.load_json_bytes_strict(raw_bytes)
        except (OSError, ValueError) as exc:
            raise ResponsesGatewayError("retained normalized fixture evidence is invalid") from exc
        if _bytes_digest(raw_bytes) != details.get("raw_sha") or not isinstance(raw, dict) or set(raw) != runtime_gateway.RAW_FIELDS:
            raise ResponsesGatewayError("retained normalized fixture evidence is invalid")
        payload = details.get("payload")
        attempt = entry.get("attempt_identity")
        expected = {
            "provider": attempt.get("provider") if isinstance(attempt, dict) else None,
            "surface": attempt.get("surface") if isinstance(attempt, dict) else None,
            "account": attempt.get("account") if isinstance(attempt, dict) else None,
            "provider_task_id": details.get("task_id"),
            "event_type": details.get("event"),
            "provider_sequence": details.get("sequence"),
            "provider_timestamp": details.get("provider_time"),
            "observed_model": details.get("model"),
            "payload": payload,
        }
        if any(raw.get(field) != value for field, value in expected.items()):
            raise ResponsesGatewayError("retained normalized fixture evidence is invalid")
        if isinstance(payload, dict) and "provider_raw_artifact_path" in payload:
            source_path = self.artifact_root / str(payload.get("provider_raw_artifact_path"))
            if source_path.resolve().parent != self.artifact_root.resolve() or not source_path.is_file() or source_path.is_symlink():
                raise ResponsesGatewayError("retained provider fixture evidence is missing")
            _owner_only(source_path, mode=0o600, kind=stat.S_ISREG)
            try:
                source_bytes = source_path.read_bytes()
                source_value = observations.load_json_bytes_strict(source_bytes)
            except (OSError, ValueError) as exc:
                raise ResponsesGatewayError("retained provider fixture evidence is invalid") from exc
            if not isinstance(source_value, dict) or _bytes_digest(source_bytes) != payload.get("provider_raw_sha256") or len(source_bytes) != payload.get("provider_raw_size"):
                raise ResponsesGatewayError("retained provider fixture evidence is invalid")
        # Reconstruct only from byte-audited normalized facts.
        info = {"task_id": details.get("task_id"), "model": details.get("model"), "provider_time": details.get("provider_time"), "payload": payload, "raw_sha": details.get("raw_sha"), "terminal": bool(details.get("terminal"))}
        event = details.get("event")
        if event not in {"launch", "running", "terminal", "cancel_acknowledged"}:
            raise ResponsesGatewayError("retained raw fixture evidence is invalid")
        sequence = int(details.get("sequence", 0))
        if request.get("operation") == "observe" and details.get("terminal"):
            # The original create remains a launch fact.  A later observation
            # of the retained terminal raw evidence is a distinct terminal
            # fact, without another transport call.
            event = "terminal"
            sequence += 1
        result, new_details = self._record(request, request_digest, event, info, sequence)
        entry["status"] = "terminal" if details.get("terminal") else "active"
        entry["terminal"] = bool(details.get("terminal"))
        entry["result"] = result
        return result, new_details

    def attest_receipt(self, *, attempt: dict[str, object], provider_task_id: str, receipt_payload_hash: str) -> dict[str, object]:
        self._boundary()
        _sha(receipt_payload_hash, "receipt_payload_hash")
        _text(provider_task_id, "provider_task_id")
        if not isinstance(attempt, dict):
            raise ResponsesGatewayError("attempt is invalid")
        entry = self._load_state().get("attempts", {}).get(attempt.get("attempt_id"))
        if not isinstance(entry, dict) or entry.get("provider_task_id") != provider_task_id or not entry.get("terminal"):
            raise ResponsesGatewayError("terminal provider evidence is required before receipt attestation")
        identity = entry.get("attempt_identity")
        if not isinstance(identity, dict) or any(attempt.get(field) != identity.get(field) for field in runtime_gateway.IMMUTABLE_ATTEMPT_FIELDS):
            raise ResponsesGatewayError("receipt attempt identity differs from retained admission")
        lifecycle = attempt.get("lifecycle")
        if (
            not entry.get("cancel_intent")
            or not isinstance(entry.get("cancel_command_digest"), str)
            or not entry["cancel_command_digest"]
            or not isinstance(lifecycle, dict)
            or set(lifecycle) != set(runtime_lifecycle.empty_lifecycle())
            or lifecycle.get("status") != "cancelled"
            or lifecycle.get("terminal_status") != "cancelled"
            or lifecycle.get("provider_task_id") != provider_task_id
            or lifecycle.get("terminal_authority") != "provider_observation"
            or not isinstance(lifecycle.get("cancellation"), dict)
        ):
            raise ResponsesGatewayError("receipt attribution is not eligible")
        try:
            lifecycle_errors = runtime_lifecycle.audit_attempt(
                attempt,
                keyring_path=self.gateway_keyring_path,
                decision_public_key_path=self.decision_public_key_path,
            )
        except ValueError as exc:
            raise ResponsesGatewayError("cancelled lifecycle authority is invalid") from exc
        if lifecycle_errors:
            raise ResponsesGatewayError("cancelled lifecycle authority is invalid")
        terminal_result = entry.get("result")
        terminal_claims = (
            terminal_result.get("claims")
            if isinstance(terminal_result, dict)
            else None
        )
        if (
            not isinstance(terminal_claims, dict)
            or terminal_claims.get("event_type") != "terminal"
            or terminal_claims.get("provider_task_id") != provider_task_id
            or lifecycle.get("terminal_observation_digest") != _digest(terminal_claims)
            or lifecycle.get("terminal_provider_event_id")
            != terminal_claims.get("provider_event_id")
        ):
            raise ResponsesGatewayError("cancelled lifecycle does not bind terminal gateway evidence")
        details = entry.get("raw_retained")
        if not isinstance(details, dict):
            raise ResponsesGatewayError("terminal raw evidence is missing")
        raw_path = self.artifact_root / str(details.get("raw_path", ""))
        if raw_path.resolve().parent != self.artifact_root.resolve() or not raw_path.is_file() or raw_path.is_symlink():
            raise ResponsesGatewayError("terminal raw evidence is invalid")
        _owner_only(raw_path, mode=0o600, kind=stat.S_ISREG)
        try:
            raw_bytes = raw_path.read_bytes()
            raw = observations.load_json_bytes_strict(raw_bytes)
        except (OSError, ValueError) as exc:
            raise ResponsesGatewayError("terminal raw evidence is invalid") from exc
        if not isinstance(raw, dict) or set(raw) != runtime_gateway.RAW_FIELDS or _bytes_digest(raw_bytes) != details.get("raw_sha") or raw.get("provider_task_id") != provider_task_id or raw.get("payload") != details.get("payload"):
            raise ResponsesGatewayError("terminal raw evidence is invalid")
        payload = raw["payload"]
        if not isinstance(payload, dict):
            raise ResponsesGatewayError("terminal raw evidence is invalid")
        source_path = self.artifact_root / str(payload.get("provider_raw_artifact_path", ""))
        if source_path.resolve().parent != self.artifact_root.resolve() or not source_path.is_file() or source_path.is_symlink():
            raise ResponsesGatewayError("terminal provider raw evidence is invalid")
        _owner_only(source_path, mode=0o600, kind=stat.S_ISREG)
        try:
            source_bytes = source_path.read_bytes()
            source_value = observations.load_json_bytes_strict(source_bytes)
        except (OSError, ValueError) as exc:
            raise ResponsesGatewayError("terminal provider raw evidence is invalid") from exc
        if not isinstance(source_value, dict) or _bytes_digest(source_bytes) != payload.get("provider_raw_sha256") or len(source_bytes) != payload.get("provider_raw_size"):
            raise ResponsesGatewayError("terminal provider raw evidence is invalid")
        claims = {"schema": RECEIPT_SCHEMA, "gateway_key_id": self.gateway_key_id, "action": "attest-runtime-receipt", "project_id": attempt.get("project_id"), "attempt_id": attempt.get("attempt_id"), "provider_task_id": provider_task_id, "receipt_payload_hash": receipt_payload_hash, "nonce": uuid.uuid4().hex, "issued_at": _iso(self.now), "expires_at": _iso(self.now + timedelta(minutes=4))}
        return self._sign(claims)

#!/usr/bin/env python3
"""Safe, deterministic operator view for one Company OS project."""

from __future__ import annotations

import html
import math
from pathlib import PurePosixPath
from typing import Any, Iterable
from urllib.parse import quote

BRIEF_SCHEMA = "company-os.operator-brief.v1"
SPECIAL_LABELS = {"sqlite": "SQLite", "json": "JSON", "api": "API", "p0": "P0"}


def _objects(value: Any) -> list[dict[str, Any]]:
    return [item for item in value if isinstance(item, dict)] if isinstance(value, list) else []


def _integer(value: Any) -> int:
    return int(value) if isinstance(value, int) and not isinstance(value, bool) and value >= 0 else 0


def _metric(cycles: list[dict[str, Any]], field: str, *, integer: bool, unit: str) -> dict[str, Any]:
    known: list[int | float] = []
    unknown = 0
    invalid = 0
    for cycle in cycles:
        if field not in cycle or cycle.get(field) is None:
            unknown += 1
            continue
        value = cycle.get(field)
        valid = (
            isinstance(value, int) and not isinstance(value, bool) and value >= 0
            if integer
            else isinstance(value, (int, float))
            and not isinstance(value, bool)
            and math.isfinite(value)
            and value >= 0
        )
        if valid:
            known.append(int(value) if integer else float(value))
        else:
            invalid += 1
    total = len(cycles)
    return {
        "value": (sum(known) if known else None),
        "unit": unit,
        "known_sources": len(known),
        "unknown_sources": unknown,
        "invalid_sources": invalid,
        "total_sources": total,
        "complete": total > 0 and len(known) == total,
    }


def _label(value: Any) -> str:
    words = str(value or "unknown").replace("_", " ").strip().split()
    return " ".join(SPECIAL_LABELS.get(word.lower(), word.title()) for word in words)


def _markdown(value: Any) -> str:
    """Render project text as inert one-line Markdown, not active markup/HTML."""
    text = html.escape(str(value or ""), quote=True).replace("\r", " ").replace("\n", " ")
    for character in ("\\", "`", "*", "_", "{", "}", "[", "]", "#", "|"):
        text = text.replace(character, f"\\{character}")
    return " ".join(text.split()) or "—"


def _safe_project_reference(value: Any) -> str | None:
    """Return a display-safe project-relative reference, never an authority path."""
    if not isinstance(value, str) or not value.strip() or "\\" in value:
        return None
    candidate = PurePosixPath(value.strip())
    if candidate.is_absolute() or ".." in candidate.parts:
        return None
    return candidate.as_posix()


def _blocker_kind(message: str) -> str:
    lowered = message.lower()
    if "control store" in lowered or "revision" in lowered or "projection" in lowered:
        return "control"
    if "quality" in lowered:
        return "quality"
    if any(term in lowered for term in ("scheduler", "launcher", "issuer", "certif", "grant", "validation")):
        return "authority"
    if "fabric" in lowered or "runtime" in lowered or "manager" in lowered or "worker" in lowered:
        return "execution"
    if "evidence" in lowered or "artifact" in lowered or "snapshot" in lowered:
        return "evidence"
    return "program"


def _next_action(
    state: dict[str, Any],
    report: dict[str, Any],
    blockers: list[dict[str, str]],
    missing_quality: list[str],
    below_quality: list[str],
    invalid_quality: list[str],
) -> dict[str, str]:
    status = state.get("instance", {}).get("status")
    phase = str(state.get("phase") or "unknown")
    kinds = {item["kind"] for item in blockers}
    action = lambda kind, title, instruction, signal, owner, artifact, verify: {
        "kind": kind,
        "title": title,
        "instruction": instruction,
        "success_signal": signal,
        "owner": owner,
        "artifact": artifact,
        "verification": verify,
    }
    if status == "cancelled":
        return action("stop", "Keep cancellation authoritative",
            "Do not restart work. Version a replacement program only after an explicit new mandate.",
            "The instance remains cancelled with no lease, schedule, or active work.",
            "Program owner", "Replacement mandate or no artifact", "Run the strict brief and confirm cancellation remains the only terminal state.")
    if "control" in kinds:
        return action("repair_control", "Repair control authority",
            "Restore the transactional project record or its readable copies before any program decision.",
            "The control audit is clean and readable copies match committed authority.",
            "Control owner", ".company-os/control.db and deterministic exports", "Run audit; require a clean control-store report before continuing.")
    if not report.get("actor_issuer_ready"):
        return action("configure_issuer", "Restore decision authority",
            "Connect the externally controlled decision-issuer public key; do not create a project-local bypass.",
            "Governed commands can verify independent grants without exposing issuer secrets.",
            "Authority owner", "External issuer public-key attestation", "Run the strict brief and confirm decision authority is available.")
    if "evidence" in kinds:
        current = _objects(state.get("evidence", {}).get("reality" if phase == "reality_audit" else phase, []))
        only_missing = all("requires valid evidence" in item["message"] for item in blockers if item["kind"] == "evidence")
        if only_missing and not current:
            return action("record_evidence", f"Record {_label(phase)} evidence",
                "Capture the current product reality in one decision-grade artifact and have an independent reviewer challenge it.",
                "One immutable, current evidence record names the finding, decision impact, author, and independent reviewer.",
                "Product auditor + independent reviewer", f"{_label(phase)} evidence report",
                "Run the strict brief; the stage-evidence blocker must clear without weakening any gate.")
        return action("repair_evidence", f"Restore {_label(phase)} evidence",
            "Replace only the invalid named evidence through signed supersession, then re-audit.",
            "Every phase-required evidence item is current, immutable, and independently reviewed.",
            "Evidence owner + independent reviewer", f"Current {_label(phase)} evidence artifact", "Run the strict brief; the evidence blocker must disappear without a new error.")
    if "program" in kinds:
        return action("repair_program", "Restore program coherence",
            "Resolve the first program or work-contract violation before quality review or execution.",
            "The north star, current outcome, primary work, and program version agree.",
            "Program owner", "Versioned program contract", "Run audit and confirm no program blocker remains.")
    if "quality" in kinds or missing_quality or below_quality or invalid_quality:
        names = missing_quality + below_quality + invalid_quality
        detail = ", ".join(_label(name) for name in names[:4])
        if len(names) > 4:
            detail += f", and {len(names) - 4} more"
        bucket = "reality" if phase == "reality_audit" else phase
        current_evidence = _objects(state.get("evidence", {}).get(bucket, []))
        primary = next((item for item in _objects(state.get("portfolio", {}).get("active_work", [])) if item.get("primary")), {})
        artifact = next(
            (
                item.get("source_artifact_path") or item.get("artifact_path")
                for item in reversed(current_evidence)
                if item.get("work_id") == primary.get("id") and item.get("outcome_id") == primary.get("outcome_id")
            ),
            None,
        )
        if missing_quality and not below_quality and not invalid_quality:
            return action("audit_quality", f"Run the {_label(phase)} acceptance review",
                f"Have an independent product reviewer test the actual rendered journey against the acceptance matrix and score all {len(missing_quality)} required dimensions; do not score the specification.",
                "Every required dimension has independently authenticated, checkpoint-bound evidence; any score below its gate becomes the next concrete rework target.",
                "Independent product scorer + conflict-free reviewer", str(artifact or f"New {_label(phase)} acceptance report"),
                "Record the acceptance artifact, then run brief --strict; missing rows must become audit-valid scores or explicit below-gate rework.")
        if invalid_quality:
            target = _label(invalid_quality[0])
            return action("repair_quality_proof", f"Repair {target} proof",
                f"Replace the invalid {target} score contract with evidence and independent grants bound to the current checkpoint.",
                f"{target} is audit-valid; no numeric score is trusted before its full contract passes.",
                "Quality evidence owner + independent reviewer", str(artifact or f"Corrected {target} acceptance evidence"),
                "Run brief --strict and confirm the row is no longer Invalid before addressing another dimension.")
        if below_quality:
            target = _label(below_quality[0])
            return action("improve_quality", f"Raise {target}",
                f"Address the accepted review's highest-priority {target} defect, rerun that journey, and independently rescore only after the experience changes.",
                f"{target} reaches its required gate with new checkpoint-bound evidence.",
                "Feature owner + independent product reviewer", str(artifact or f"Updated {target} acceptance evidence"),
                "Re-run the named acceptance case and strict brief; the row must pass without invalidating another gate.")
        return action("close_quality", f"Close the {_label(phase)} quality gate",
            f"Improve the actual experience and independently rescore: {detail or 'all applicable dimensions'}.",
            "Every applicable critical score is at least 9 and every noncritical score is at least 8 with audit-valid proof.",
            "Feature owner + independent quality reviewer", str(artifact or f"New {_label(phase)} acceptance artifact"),
            "Run brief --strict; every required row must be audit-valid and at or above its gate.")
    if "execution" in kinds:
        message = next(item["message"] for item in blockers if item["kind"] == "execution")
        return action("resolve_execution", "Resolve the agent-team exception",
            f"Stop advancement and resolve this exact exception: {message}",
            "The affected manager or run has an attributable state, evidence, and explicit decision.",
            "Owning manager + master reviewer", "Manager phase report or runtime receipt", "Re-run the strict brief and require the execution blocker to clear.")
    if "authority" in kinds:
        return action("certify", "Obtain independent certification",
            "Have a conflict-free reviewer certify the exact current governance digest.",
            "Validation is current and signed without changing the program.",
            "Independent certifier", "Signed certification for the current digest", "Run brief --strict and confirm validation is current.")
    active = _objects(state.get("portfolio", {}).get("active_work", []))
    if not active:
        return action("choose_outcome", "Choose one visible outcome",
            "Commit one user-visible capability or bounded innovation bet and make it the primary lane.",
            "Exactly one ready primary work item names the user-visible outcome.",
            "Program owner", "Committed outcome and primary work contract", "Run brief and confirm one ready primary lane.")
    if not report.get("validation_valid"):
        return action("certify", "Obtain independent certification",
            "Have a conflict-free reviewer certify the exact current governance digest.",
            "Validation is current and signed without changing the program.",
            "Independent certifier", "Signed certification for the current digest", "Run brief --strict and confirm validation is current.")
    if status == "paused":
        return action("activate", "Activate the accepted program",
            "Activate only the certified instance; keep recurring scheduling off until launcher protection is proven.",
            "The instance is active and still unscheduled.",
            "Program owner", "Activation event", "Run brief and confirm active status with scheduling still off.")
    if not report.get("protected_launcher_ready"):
        return action("protect_launcher", "Establish external launcher authority",
            "Deploy an independently protected issuer and launcher outside the managed project.",
            "The external prerequisite is independently attested; no local bypass is used.",
            "Platform authority owner", "Protected launcher attestation", "Run audit from the protected launcher boundary.")
    if not state.get("controller", {}).get("schedule_enabled"):
        return action("arm_schedule", "Arm one bounded wake",
            "Enable one fenced project schedule and require an empty wake to stop without model work.",
            "The scheduler is ready with exactly one primary work item and no active lease.",
            "Protected launcher", "Fenced schedule record", "Observe one empty wake and one bounded work wake.")
    return action("begin_cycle", "Begin one bounded cycle",
        "Acquire the current program lease and execute only the next accepted outcome.",
        "One attributable cycle returns evidence, usage, review, and a terminal disposition.",
        "Primary work owner", "Cycle evidence and terminal review", "Finish the cycle with signed evidence and usage coverage.")


def _describe_changes(
    prior: dict[str, Any] | None,
    current: dict[str, Any],
    prior_revision: int | None,
    current_revision: int | None,
) -> list[dict[str, str]]:
    if prior is None:
        return [{
            "kind": "baseline",
            "summary": "No earlier authoritative revision is available for comparison.",
        }]
    changes: list[dict[str, str]] = []
    prior_strategy = prior.get("strategy", {})
    strategy = current.get("strategy", {})
    if prior_strategy.get("program_version") != strategy.get("program_version"):
        changes.append({
            "kind": "program",
            "summary": f"Program version changed from {prior_strategy.get('program_version')} to {strategy.get('program_version')}.",
        })
    if prior_strategy.get("current_outcome") != strategy.get("current_outcome"):
        changes.append({"kind": "direction", "summary": f"Current outcome changed to: {strategy.get('current_outcome')}."})
    if prior.get("phase") != current.get("phase"):
        changes.append({"kind": "phase", "summary": f"Stage moved from {_label(prior.get('phase'))} to {_label(current.get('phase'))}."})
    if prior.get("instance", {}).get("status") != current.get("instance", {}).get("status"):
        changes.append({"kind": "control", "summary": f"Project status changed to {_label(current.get('instance', {}).get('status'))}."})
    prior_work = {item.get("id"): item for item in _objects(prior.get("portfolio", {}).get("active_work", [])) if item.get("id")}
    current_work = {item.get("id"): item for item in _objects(current.get("portfolio", {}).get("active_work", [])) if item.get("id")}
    added_work = [str(item.get("title") or key) for key, item in current_work.items() if key not in prior_work]
    removed_work = [str(item.get("title") or key) for key, item in prior_work.items() if key not in current_work]
    if added_work:
        changes.append({"kind": "work", "summary": "Work added: " + ", ".join(added_work) + "."})
    if removed_work:
        changes.append({"kind": "work", "summary": "Work closed or removed: " + ", ".join(removed_work) + "."})
    prior_evidence = {str(item.get("id")) for items in prior.get("evidence", {}).values() for item in _objects(items) if item.get("id")}
    current_evidence = {str(item.get("id")) for items in current.get("evidence", {}).values() for item in _objects(items) if item.get("id")}
    if len(current_evidence - prior_evidence):
        changes.append({"kind": "evidence", "summary": f"{len(current_evidence - prior_evidence)} evidence record(s) became current."})
    if len(prior_evidence - current_evidence):
        changes.append({"kind": "evidence", "summary": f"{len(prior_evidence - current_evidence)} evidence record(s) left the current program."})
    prior_cycles = len(_objects(prior.get("feedback", {}).get("cycles", [])))
    current_cycles = len(_objects(current.get("feedback", {}).get("cycles", [])))
    if current_cycles != prior_cycles:
        changes.append({"kind": "feedback", "summary": f"Cycle count changed from {prior_cycles} to {current_cycles}."})
    if not changes:
        changes.append({"kind": "unchanged", "summary": "No operator-relevant governed field changed."})
    if prior_revision is not None and current_revision is not None:
        for item in changes:
            item["comparison"] = f"revision {prior_revision} → {current_revision}"
    return changes


def build_operator_brief(
    state: dict[str, Any],
    report: dict[str, Any],
    store_report: dict[str, Any] | None,
    *,
    phases: Iterable[str],
    critical_dimensions: dict[str, bool],
    prior_state: dict[str, Any] | None = None,
    prior_revision: int | None = None,
    change_events: list[dict[str, Any]] | None = None,
) -> dict[str, Any]:
    phase_list = list(phases)
    phase = str(state.get("phase") or "unknown")
    phase_index = phase_list.index(phase) if phase in phase_list else -1
    errors = [str(item) for item in report.get("errors", []) if isinstance(item, str)]
    blockers = [{"kind": _blocker_kind(message), "message": message} for message in dict.fromkeys(errors)]
    if state.get("instance", {}).get("status") != "cancelled" and not report.get("actor_issuer_ready"):
        blockers.append({"kind": "authority", "message": "external decision issuer is unavailable"})
    required = [str(item) for item in report.get("applicable_quality_dimensions", [])]
    global_quality_errors = [
        error for error in errors
        if error.startswith("quality.") or error.startswith("quality threshold")
    ]
    dimensions = state.get("quality", {}).get("dimensions", {})
    quality_rows: list[dict[str, Any]] = []
    missing_quality: list[str] = []
    below_quality: list[str] = []
    invalid_quality: list[str] = []
    for name in required:
        item = dimensions.get(name, {}) if isinstance(dimensions, dict) else {}
        score = item.get("score") if isinstance(item, dict) else None
        threshold = 9 if critical_dimensions.get(name, True) else 8
        dimension_errors = [error for error in errors if f"quality dimension {name}" in error] + global_quality_errors
        if not isinstance(score, (int, float)) or isinstance(score, bool) or not math.isfinite(score):
            status = "missing"
            score = None
            missing_quality.append(name)
        elif dimension_errors:
            status = "invalid"
            invalid_quality.append(name)
        elif score < threshold:
            status = "below_gate"
            below_quality.append(name)
        else:
            status = "pass"
        quality_rows.append({
            "dimension": name,
            "critical": bool(critical_dimensions.get(name, True)),
            "score": score,
            "threshold": threshold,
            "status": status,
            "audit_valid": not dimension_errors and status == "pass",
            "issues": dimension_errors,
            "evidence_count": len(item.get("evidence", [])) if isinstance(item, dict) and isinstance(item.get("evidence"), list) else 0,
        })

    active_work = []
    for item in _objects(state.get("portfolio", {}).get("active_work", [])):
        active_work.append({key: item.get(key) for key in (
            "id", "title", "type", "status", "primary", "owner", "user_visible_outcome", "execution_mode"
        )})
    evidence = state.get("evidence", {}) if isinstance(state.get("evidence"), dict) else {}
    evidence_rows = [
        {
            "bucket": bucket,
            "count": len(_objects(items)),
            "ids": [str(item.get("id")) for item in _objects(items) if item.get("id")],
            "references": list(dict.fromkeys(
                reference
                for item in _objects(items)
                if (reference := _safe_project_reference(item.get("source_artifact_path")))
            )),
        }
        for bucket, items in evidence.items()
    ]
    cycles = _objects(state.get("feedback", {}).get("cycles", []))
    runtime_adapter = state.get("runtime_adapter", {}) if isinstance(state.get("runtime_adapter"), dict) else {}
    attempts = _objects(runtime_adapter.get("attempts", []))
    inboxes = runtime_adapter.get("observation_inboxes", {}) if isinstance(runtime_adapter.get("observation_inboxes"), dict) else {}
    budget_errors = [error for error in errors if "budget" in error.lower()]

    def attempt_observation(attempt: dict[str, Any]) -> dict[str, Any] | None:
        inbox = inboxes.get(attempt.get("attempt_id"), {})
        observations = _objects(inbox.get("trusted_observations", [])) if isinstance(inbox, dict) else []
        trusted = [item for item in observations if item.get("trust") == "gateway_verified" and isinstance(item.get("claims"), dict)]
        return trusted[-1] if trusted else None

    def budget_exception(identity: str | None, attempt_id: str | None = None) -> bool:
        for error in budget_errors:
            lowered = error.lower()
            if (identity and identity in error) or (attempt_id and attempt_id in error):
                return True
            if lowered.startswith("runtime attempt budget") or "manifest" in lowered or "oversub" in lowered:
                return True
        return False
    fabric = state.get("execution_fabric", {}) if isinstance(state.get("execution_fabric"), dict) else {}
    managers = fabric.get("managers", {}) if isinstance(fabric.get("managers"), dict) else {}
    manager_rows = []
    for manager_id, manager in managers.items():
        if not isinstance(manager, dict):
            continue
        reports = _objects(manager.get("reports", []))
        decisions = _objects(manager.get("decisions", []))
        manager_attempt = next(
            (
                item for item in reversed(attempts)
                if item.get("role") == "manager" and item.get("manifest_identity_id") == manager_id
            ),
            {},
        )
        observation = attempt_observation(manager_attempt)
        observed_model = observation.get("claims", {}).get("observed_model") if observation else None
        last_decision = decisions[-1].get("decision") if decisions else None
        if manager.get("status") == "accepted":
            operating_state = "accepted"
        elif manager.get("status") == "terminated":
            operating_state = "terminated"
        elif manager.get("status") == "paused":
            operating_state = "paused"
        elif last_decision == "rework":
            operating_state = "in_rework"
        elif manager.get("status") == "awaiting_decision":
            operating_state = "awaiting_decision"
        elif reports:
            operating_state = "reporting"
        else:
            operating_state = manager.get("status") or "pending"
        manager_rows.append({
            "id": manager_id,
            "model": manager.get("model"),
            "outcome": manager.get("outcome"),
            "status": operating_state,
            "source_status": manager.get("status"),
            "next_phase": manager.get("next_phase"),
            "report_count": len(reports),
            "latest_report_phase": reports[-1].get("phase") if reports else None,
            "rework_rounds": _integer(manager.get("rework_rounds")),
            "decision_required": reports[-1].get("phase") if manager.get("status") == "awaiting_decision" and reports else None,
            "requested_model": manager_attempt.get("requested_model") or manager.get("model"),
            "observed_model": observed_model,
            "model_evidence": "gateway_verified" if observation and observed_model else "provider_unknown" if observation else "unverified",
            "budget_evidence": "exception" if budget_exception(manager_id, manager_attempt.get("attempt_id")) else "declared_only" if manager_attempt.get("budget") else "unknown",
        })
    safe_attempts = []
    for item in attempts:
        observation = attempt_observation(item)
        observed_model = observation.get("claims", {}).get("observed_model") if observation else None
        safe_attempts.append({
            key: item.get(key) for key in (
                "attempt_id", "manifest_identity_id", "role", "status", "requested_model",
                "provider", "parent_runtime_id",
            )
        } | {
            "observed_model": observed_model,
            "model_evidence": "gateway_verified" if observation and observed_model else "provider_unknown" if observation else "unverified",
            "budget_evidence": "exception" if budget_exception(item.get("manifest_identity_id"), item.get("attempt_id")) else "declared_only" if item.get("budget") else "unknown",
        })
    status = "ready" if report.get("ok") else "blocked"
    if state.get("instance", {}).get("status") == "cancelled":
        status = "cancelled"
    elif any(item["kind"] == "control" for item in blockers):
        status = "control_failure"
    elif not report.get("actor_issuer_ready"):
        status = "needs_authority"
    elif any(item["kind"] == "evidence" for item in blockers):
        status = "needs_evidence"
    elif any(item["kind"] == "quality" for item in blockers) or missing_quality or below_quality or invalid_quality:
        status = "needs_quality"
    elif any(item["kind"] == "authority" for item in blockers):
        status = "needs_authority"

    current_revision = store_report.get("revision") if isinstance(store_report, dict) else None
    changes = _describe_changes(prior_state, state, prior_revision, current_revision)
    change_kinds = {item["kind"] for item in changes}
    if {"program", "direction"}.intersection(change_kinds):
        impact = "Direction changed. Prior work and proof are historical; this program must establish its own evidence before execution."
    elif blockers:
        impact = f"The project cannot leave {_label(phase)} until the first governed blocker is resolved."
    else:
        impact = f"The {_label(phase)} gate is clear for its next governed decision."

    brief = {
        "schema": BRIEF_SCHEMA,
        "project": {
            "id": state.get("instance", {}).get("project_id"),
            "name": state.get("instance", {}).get("name"),
            "type": state.get("instance", {}).get("project_type"),
            "status": state.get("instance", {}).get("status"),
        },
        "program": {
            "version": state.get("strategy", {}).get("program_version"),
            "north_star": state.get("strategy", {}).get("north_star"),
            "current_outcome": state.get("strategy", {}).get("current_outcome"),
            "success_metric": state.get("strategy", {}).get("success_metric"),
        },
        "gate": {
            "status": status,
            "phase": phase,
            "phase_number": phase_index + 1 if phase_index >= 0 else None,
            "phase_count": len(phase_list),
            "comparison_window": {
                "from_revision": prior_revision,
                "to_revision": current_revision,
                "event_count": len(change_events or []),
            },
            "phase_track": [
                {
                    "phase": item,
                    "status": "complete" if index < phase_index else "current" if index == phase_index else "future",
                }
                for index, item in enumerate(phase_list)
            ],
            "changes": changes,
            "change_events": list(change_events or []),
            "impact": impact,
            "blockers": blockers,
            "warnings": [str(item) for item in report.get("warnings", []) if isinstance(item, str)],
            "next_action": _next_action(state, report, blockers, missing_quality, below_quality, invalid_quality),
        },
        "portfolio": {"active_work": active_work, "active_count": len(active_work)},
        "quality": {
            "ready": bool(report.get("quality_ready")),
            "passed": sum(1 for item in quality_rows if item["status"] == "pass"),
            "required": len(quality_rows),
            "missing": missing_quality,
            "below_gate": below_quality,
            "invalid": invalid_quality,
            "dimensions": quality_rows,
        },
        "evidence": {
            "valid_count": _integer(report.get("valid_evidence_count")),
            "buckets": evidence_rows,
        },
        "execution": {
            "fabric_status": report.get("execution_fabric_status"),
            "fabric_ready": bool(report.get("execution_fabric_ready")),
            "manager_count": len(managers),
            "manager_reports": sum(
                len(_objects(manager.get("reports", [])))
                for manager in managers.values() if isinstance(manager, dict)
            ),
            "managers": manager_rows,
            "runtime_attempts": safe_attempts,
            "schedule_enabled": bool(state.get("controller", {}).get("schedule_enabled")),
            "scheduler_ready": bool(report.get("scheduler_ready")),
            "protected_launcher_ready": bool(report.get("protected_launcher_ready")),
            "lease_active": state.get("controller", {}).get("lease") is not None,
            "cancellation_requested": bool(state.get("controller", {}).get("cancellation_requested")),
        },
        "feedback": {
            "cycles": len(cycles),
            "accepted_cycles": sum(1 for item in cycles if item.get("reviewer_decision") == "accepted"),
            "visible_cycles": sum(1 for item in cycles if item.get("user_visible_movement") is True),
            "metrics": {
                "cost": _metric(cycles, "cost_usd", integer=False, unit="USD"),
                "lead_time": _metric(cycles, "latency_minutes", integer=False, unit="minutes"),
                "tokens": _metric(cycles, "token_usage", integer=True, unit="tokens"),
            },
            "pending_adaptations": _integer(report.get("pending_adaptations")),
        },
        "authority": {
            "backend": store_report.get("backend") if isinstance(store_report, dict) else "legacy-json",
            "revision": store_report.get("revision") if isinstance(store_report, dict) else None,
            "store_ok": bool(store_report and store_report.get("ok")),
            "exports_match": bool(store_report and store_report.get("state_export_match") and store_report.get("events_export_match")),
            "validation_valid": bool(report.get("validation_valid")),
            "issuer_ready": bool(report.get("actor_issuer_ready")),
        },
        "non_claims": [
            "Requested model identity is not provider-observed identity.",
            "A clean local audit is not provider-runtime or production evidence.",
            "Scheduling is not ready until an external protected launcher is independently proven.",
        ],
    }
    return brief


def render_markdown(brief: dict[str, Any]) -> str:
    gate = brief["gate"]
    program = brief["program"]
    project = brief["project"]
    quality = brief["quality"]
    execution = brief["execution"]
    authority = brief["authority"]
    feedback = brief["feedback"]
    evidence = brief["evidence"]
    phase_bucket = "reality" if gate["phase"] == "reality_audit" else gate["phase"]
    phase_evidence = next((item for item in evidence["buckets"] if item["bucket"] == phase_bucket), {})
    decision_references = phase_evidence.get("references", []) if isinstance(phase_evidence, dict) else []
    decision_reference = next(
        (item for item in decision_references if "acceptance" in item.lower()),
        decision_references[0] if decision_references else "No current project reference",
    )
    def metric_text(metric: dict[str, Any], *, money: bool = False) -> str:
        total = metric["total_sources"]
        if total == 0:
            return "No observations"
        value = metric["value"]
        measured = "No usable observations" if value is None else (
            f"${value:,.2f}" if money else f"{value:,.0f}" if metric["unit"] == "tokens" else f"{value:,.1f} {metric['unit']}"
        )
        coverage = f"{metric['known_sources']}/{total} recorded"
        exceptions = []
        if metric["unknown_sources"]:
            exceptions.append(f"{metric['unknown_sources']} unknown")
        if metric["invalid_sources"]:
            exceptions.append(f"{metric['invalid_sources']} invalid")
        return " · ".join([measured, coverage, *exceptions])

    track = " → ".join(
        f"{_label(item['phase'])} [{_label(item['status'])}]" for item in gate["phase_track"]
    )
    quality_exceptions = [item for item in quality["dimensions"] if item["status"] != "pass"]
    lines = [
        f"# Company OS — {_markdown(project['name'])}",
        "",
        f"> **{_markdown(_label(gate['status']))}** · {_markdown(_label(gate['phase']))} · Program v{_markdown(program['version'])}",
        "",
        "## Latest governed change",
        "",
    ]
    for item in gate["changes"]:
        suffix = f" ({item['comparison']})" if item.get("comparison") else ""
        lines.append(f"- {_markdown(item['summary'] + suffix)}")
    comparison = gate["comparison_window"]
    comparison_label = (
        f"Update {comparison['from_revision']} → {comparison['to_revision']}"
        if comparison["from_revision"] is not None and comparison["to_revision"] is not None
        else "No revision comparison"
    )
    if gate["change_events"]:
        lines.extend(["", f"### Governed command trail · {_markdown(comparison_label)}", "", "| Update | Governed change | Command identity | Reference |", "| ---: | --- | --- | --- |"])
        for item in gate["change_events"]:
            references = ", ".join(f"{_label(key)}: {value}" for key, value in item.get("references", {}).items()) or "—"
            command = item.get("command") or "unkeyed"
            if item.get("command_key"):
                command = f"{command} · {item['command_key']}"
            lines.append(
                f"| {item.get('revision', '—')} | {_markdown(_label(item.get('event_type')))} | {_markdown(command)} | {_markdown(references)} |"
            )
    lines.extend([
        "",
        f"**Why it matters:** {_markdown(gate['impact'])}",
        "",
        f"## One move now — {_markdown(gate['next_action']['title'])}",
        "",
        _markdown(gate["next_action"]["instruction"]),
        "",
        f"- **Owner:** {_markdown(gate['next_action']['owner'])}",
        f"- **Output:** {_markdown(gate['next_action']['artifact'])}",
        f"- **Acceptance reference:** `{_markdown(decision_reference)}`",
        f"- **Done when:** {_markdown(gate['next_action']['success_signal'])}",
        f"- **Verify:** {_markdown(gate['next_action']['verification'])}",
        "",
        "## Direction",
        "",
        f"- **North star:** {_markdown(program['north_star'])}",
        f"- **Current outcome:** {_markdown(program['current_outcome'])}",
        f"- **Success metric:** {_markdown(program['success_metric'])}",
        "",
        "## Stage",
        "",
        f"{_markdown(track)}",
        f"Stage {gate['phase_number'] or '—'} of {gate['phase_count']}",
        "",
        "## Quality exceptions",
        "",
        f"**{quality['passed']} / {quality['required']} passed**" if quality["required"] else "**No quality gate applies until primary work is committed.**",
        "",
    ])
    if quality_exceptions:
        lines.extend(["| Dimension | Score | Gate | State |", "| --- | ---: | ---: | --- |"])
        for item in quality_exceptions:
            score = "—" if item["score"] is None else f"{item['score']:.1f}"
            lines.append(f"| {_markdown(_label(item['dimension']))} | {score} | {item['threshold']} | {_markdown(_label(item['status']))} |")
    elif quality["required"]:
        lines.append("- No quality exceptions. Passing dimensions are collapsed.")
    lines.extend(["", "## Active work", ""])
    if brief["portfolio"]["active_work"]:
        for item in brief["portfolio"]["active_work"]:
            primary = "Primary" if item.get("primary") else "Secondary"
            lines.append(
                f"- **{_markdown(item.get('title'))}** — {_markdown(primary)}, {_markdown(_label(item.get('status')))} · {_markdown(item.get('user_visible_outcome'))}"
            )
    else:
        lines.append("- No active work.")
    lines.extend([
        "",
        "## Agent team",
        "",
        f"- Team state: **{_markdown(_label(execution['fabric_status']))}** · **{execution['manager_count']} managers** · **{execution['manager_reports']} phase reports**",
    ])
    if execution["managers"]:
        lines.extend(["", "| Manager | State | Last report | Next decision | Requested / observed | Budget | Rework |", "| --- | --- | --- | --- | --- | --- | ---: |"])
        for item in execution["managers"]:
            lines.append(
                f"| {_markdown(item.get('id'))} | {_markdown(_label(item.get('status')))} | {_markdown(_label(item.get('latest_report_phase')))} | {_markdown(_label(item.get('decision_required') or item.get('next_phase')))} | {_markdown(item.get('requested_model'))} / {_markdown(item.get('observed_model'))} ({_markdown(_label(item.get('model_evidence')))}) | {_markdown(_label(item.get('budget_evidence')))} | {item.get('rework_rounds', 0)} |"
            )
    else:
        lines.append("- No manager is currently assigned.")
    lines.extend(["", "### Agent runs", ""])
    if execution["runtime_attempts"]:
        lines.extend(["| Run | Role | State | Requested | Observed | Model proof | Budget |", "| --- | --- | --- | --- | --- | --- | --- |"])
        for item in execution["runtime_attempts"]:
            lines.append(
                f"| {_markdown(item.get('attempt_id'))} | {_markdown(_label(item.get('role')))} | {_markdown(_label(item.get('status')))} | {_markdown(item.get('requested_model'))} | {_markdown(item.get('observed_model'))} | {_markdown(_label(item.get('model_evidence')))} | {_markdown(_label(item.get('budget_evidence')))} |"
            )
    else:
        lines.append("- No agent run has started for this program.")
    lines.extend([
        "",
        "## Trust and control",
        "",
        f"- Schedule: **{'on' if execution['schedule_enabled'] else 'off'}** · Lease: **{'active' if execution['lease_active'] else 'none'}** · Cancellation: **{'requested' if execution['cancellation_requested'] else 'clear'}**",
        f"- Project record: **{'protected local database' if authority['backend'] == 'sqlite' else 'legacy project file'} · update {_markdown(authority['revision'])}** · Integrity: **{'clean' if authority['store_ok'] else 'blocked'}** · Readable copies: **{'exact' if authority['exports_match'] else 'drifted'}**",
        f"- Decision authority: **{'available' if authority['issuer_ready'] else 'unavailable'}** · Independent certification: **{'current' if authority['validation_valid'] else 'not current'}**",
        f"- Evidence: **{brief['evidence']['valid_count']} valid records** across **{sum(1 for item in brief['evidence']['buckets'] if item['count'])} populated stages**",
        "",
        "## Feedback economy",
        "",
        f"- Cycles: **{feedback['cycles']}** · Accepted: **{feedback['accepted_cycles']}** · Visible: **{feedback['visible_cycles']}**",
        f"- Tokens: **{_markdown(metric_text(feedback['metrics']['tokens']))}**",
        f"- Cost: **{_markdown(metric_text(feedback['metrics']['cost'], money=True))}**",
        f"- Lead time: **{_markdown(metric_text(feedback['metrics']['lead_time']))}**",
        "",
        "## Blockers",
        "",
    ])
    if gate["blockers"]:
        for item in gate["blockers"]:
            lines.append(f"- **{_markdown(_label(item['kind']))}:** {_markdown(item['message'])}")
    else:
        lines.append("- No controller blocker.")
    if gate["warnings"]:
        lines.extend(["", "## Trust notes", ""])
        for warning in gate["warnings"]:
            lines.append(f"- {_markdown(warning)}")
    lines.extend(["", "## Evidence boundary", ""])
    for statement in brief["non_claims"]:
        lines.append(f"- {_markdown(statement)}")
    return "\n".join(lines) + "\n"


def render_html(brief: dict[str, Any]) -> str:
    """Render a self-contained, accessible, read-only command center."""
    gate = brief["gate"]
    program = brief["program"]
    project = brief["project"]
    quality = brief["quality"]
    execution = brief["execution"]
    authority = brief["authority"]
    feedback = brief["feedback"]
    evidence = brief["evidence"]

    def h(value: Any) -> str:
        return html.escape(" ".join(str(value if value not in (None, "") else "—").replace("\r", " ").replace("\n", " ").split()), quote=True)

    def metric(metric_value: dict[str, Any], *, money: bool = False) -> tuple[str, str]:
        total = metric_value["total_sources"]
        if total == 0:
            return "No observations", "0 sources"
        value = metric_value["value"]
        if value is None:
            primary = "No usable observations"
        elif money:
            primary = f"${value:,.2f}"
        elif metric_value["unit"] == "tokens":
            primary = f"{value:,.0f}"
        else:
            primary = f"{value:,.1f} {metric_value['unit']}"
        detail = f"{metric_value['known_sources']}/{total} recorded"
        if metric_value["unknown_sources"]:
            detail += f" · {metric_value['unknown_sources']} unknown"
        if metric_value["invalid_sources"]:
            detail += f" · {metric_value['invalid_sources']} invalid"
        return primary, detail

    changes = gate["changes"]
    lead_change = changes[0]["summary"] if changes else "No operator-relevant governed field changed."
    supporting_changes = changes[1:]
    change_facts = "".join(
        f'<li><span>{h(item["kind"])}</span><strong>{h(item["summary"])}</strong></li>'
        for item in supporting_changes
    ) or '<li><span>State</span><strong>No additional governed change.</strong></li>'
    def trail_item(item: dict[str, Any]) -> str:
        return (
            '<li>'
            f'<span class="trail-revision">Update {h(item.get("revision"))}</span>'
            f'<strong>{h(_label(item.get("event_type")))}</strong>'
            f'<span>{h(item.get("command") or "Unkeyed")} · {h(item.get("command_key") or "No command key")}</span>'
            f'<small>{h(", ".join(f"{_label(key)}: {value}" for key, value in item.get("references", {}).items()) or "No public reference")}</small>'
            '</li>'
        )

    def recent_trail_item(item: dict[str, Any]) -> str:
        references = item.get("references", {})
        reference = next(iter(references.values()), "No public reference") if isinstance(references, dict) else "No public reference"
        return (
            '<li>'
            f'<span class="trail-revision">Update {h(item.get("revision"))}</span>'
            f'<strong>{h(_label(item.get("event_type")))}</strong>'
            f'<span>{h(reference)}</span>'
            '</li>'
        )

    change_events = gate["change_events"]
    comparison = gate["comparison_window"]
    comparison_label = (
        f"Update {comparison['from_revision']} → {comparison['to_revision']}"
        if comparison["from_revision"] is not None and comparison["to_revision"] is not None
        else "No revision comparison"
    )
    event_word = "update" if len(change_events) == 1 else "updates"
    comparison_summary = f"View {len(change_events)} {event_word} in this comparison"
    recent_trail = "".join(recent_trail_item(item) for item in reversed(change_events[-4:]))
    if not recent_trail:
        recent_trail = '<li><strong>No governed event in this comparison window.</strong></li>'
    trail = "".join(
        trail_item(item)
        for item in change_events
    ) or '<li><strong>No governed event in this comparison window.</strong></li>'
    phases = "".join(
        f'<li class="stage stage--{h(item["status"])}" aria-label="{h(_label(item["phase"]))}: {h(_label(item["status"]))}">'
        f'<span class="stage-number">{index}</span><strong>{h(_label(item["phase"]))}</strong>'
        f'<span class="stage-state">{h(_label(item["status"]))}</span></li>'
        for index, item in enumerate(gate["phase_track"], 1)
    )
    quality_exceptions = [item for item in quality["dimensions"] if item["status"] != "pass"]
    def quality_score(item: dict[str, Any]) -> str:
        return "—" if item["score"] is None else f"{item['score']:.1f}"
    quality_rows = "".join(
        '<tr>'
        f'<th scope="row">{h(_label(item["dimension"]))}</th>'
        f'<td>{h(quality_score(item))}</td>'
        f'<td>{h(item["threshold"])}</td><td>{h(_label(item["status"]))}</td>'
        '</tr>'
        for item in quality_exceptions
    ) or '<tr><th scope="row">No exception</th><td colspan="3">All applicable rows pass.</td></tr>'
    quality_preview = "".join(
        f'<li><span class="exception-dot" aria-hidden="true"></span><strong>{h(_label(item["dimension"]))}</strong><span>{h(_label(item["status"]))}</span></li>'
        for item in quality_exceptions[:4]
    )
    if len(quality_exceptions) > 4:
        quality_preview += f'<li class="more">and {len(quality_exceptions) - 4} more exceptions</li>'
    elif not quality_exceptions:
        quality_preview = '<li class="more">No quality exceptions.</li>'
    active_work = "".join(
        '<article class="work-item">'
        f'<h2>{h(item.get("title"))}</h2><p>{h(item.get("user_visible_outcome"))}</p>'
        f'<dl><div><dt>Owner</dt><dd>{h(item.get("owner"))}</dd></div><div><dt>State</dt><dd>{h(_label(item.get("status")))}</dd></div></dl>'
        '</article>'
        for item in brief["portfolio"]["active_work"]
    ) or '<p class="empty">No active work.</p>'
    manager_rows = "".join(
        '<tr>'
        f'<th scope="row">{h(item.get("id"))}</th><td>{h(_label(item.get("status")))}</td>'
        f'<td>{h(_label(item.get("latest_report_phase")))}</td><td>{h(_label(item.get("decision_required") or item.get("next_phase")))}</td>'
        f'<td>{h(item.get("requested_model"))} / {h(item.get("observed_model"))}<small>{h(_label(item.get("model_evidence")))}</small></td>'
        f'<td>{h(_label(item.get("budget_evidence")))}</td></tr>'
        for item in execution["managers"]
    ) or '<tr><td colspan="6">No manager is currently assigned.</td></tr>'
    run_rows = "".join(
        '<tr>'
        f'<th scope="row">{h(item.get("attempt_id"))}</th><td>{h(_label(item.get("role")))}</td><td>{h(_label(item.get("status")))}</td>'
        f'<td>{h(item.get("requested_model"))}</td><td>{h(item.get("observed_model"))}<small>{h(_label(item.get("model_evidence")))}</small></td>'
        f'<td>{h(_label(item.get("budget_evidence")))}</td></tr>'
        for item in execution["runtime_attempts"]
    ) or '<tr><td colspan="6">No agent run has started for this program.</td></tr>'
    blocker_items = "".join(
        f'<li><strong>{h(_label(item["kind"]))}</strong><span>{h(item["message"])}</span></li>'
        for item in gate["blockers"]
    ) or '<li><span>No controller blocker.</span></li>'
    warning_items = "".join(f'<li>{h(item)}</li>' for item in gate["warnings"]) or '<li>No trust warning.</li>'
    non_claims = "".join(f'<li>{h(item)}</li>' for item in brief["non_claims"])
    token_value, token_detail = metric(feedback["metrics"]["tokens"])
    cost_value, cost_detail = metric(feedback["metrics"]["cost"], money=True)
    lead_value, lead_detail = metric(feedback["metrics"]["lead_time"])
    status_class = "blocked" if gate["status"] not in {"ready", "cancelled"} else gate["status"]
    certification_class = "good" if authority["validation_valid"] else "bad"
    if execution["schedule_enabled"]:
        schedule_class = "good" if execution["scheduler_ready"] else "bad"
        schedule_label = "On"
        schedule_detail = "Lease active" if execution["lease_active"] else "No lease"
    else:
        schedule_class = "safe"
        schedule_label = "Off — safe default"
        schedule_detail = "Launcher protected" if execution["protected_launcher_ready"] else "Launcher proof required"
    phase_bucket = "reality" if gate["phase"] == "reality_audit" else gate["phase"]
    phase_evidence = next((item for item in evidence["buckets"] if item["bucket"] == phase_bucket), {})
    decision_references = phase_evidence.get("references", []) if isinstance(phase_evidence, dict) else []
    decision_reference = next(
        (item for item in decision_references if "acceptance" in item.lower()),
        decision_references[0] if decision_references else "No current project reference",
    )
    decision_reference_href = (
        "/" + quote(decision_reference, safe="/")
        if decision_reference != "No current project reference"
        else None
    )
    handoff_work = next(
        (item for item in brief["portfolio"]["active_work"] if item.get("primary")),
        brief["portfolio"]["active_work"][0] if brief["portfolio"]["active_work"] else {},
    )
    decision_success = gate["next_action"]["success_signal"]
    decision_verification = gate["next_action"]["verification"]
    if gate["next_action"]["kind"] == "audit_quality":
        decision_success = f'{quality["required"]} / {quality["required"]} dimensions independently accepted at their gates.'
        decision_verification = "Record the report, then pass brief --strict."

    return f'''<!doctype html>
