)


class GatewayError(ValueError):
    """A gateway request or signed result that must fail closed."""


_VERIFICATION_SEAL = object()


class VerifiedGatewayRecord(Mapping[str, Any]):
    """In-memory proof object; ordinary/deserialized dictionaries are rejected."""

    __slots__ = ("_value",)

    def __init__(self, value: dict[str, Any], *, _seal: object) -> None:
        if _seal is not _VERIFICATION_SEAL:
            raise GatewayError("verified gateway records can only be created by cryptographic verification")
        self._value = deepcopy(value)

    def __getitem__(self, key: str) -> Any:
        return self._value[key]

    def __iter__(self) -> Iterator[str]:
        return iter(self._value)

    def __len__(self) -> int:
        return len(self._value)

    def retained_record(self) -> dict[str, Any]:
        return deepcopy(self._value)


class VerifiedReceiptAttestation(Mapping[str, Any]):
    """In-memory receipt proof created only after gateway signature verification."""

    __slots__ = ("_value",)

    def __init__(self, value: dict[str, Any], *, _seal: object) -> None:
        if _seal is not _VERIFICATION_SEAL:
            raise GatewayError("verified receipt attestations require cryptographic verification")
        self._value = deepcopy(value)

    def __getitem__(self, key: str) -> Any:
        return self._value[key]

    def __iter__(self) -> Iterator[str]:
        return iter(self._value)

    def __len__(self) -> int:
        return len(self._value)

    def retained_record(self) -> dict[str, Any]:
        return deepcopy(self._value)


def observation_module() -> Any:
    module_path = Path(__file__).resolve().with_name("runtime_observations.py")
    spec = importlib.util.spec_from_file_location("company_os_runtime_observations", module_path)
    if spec is None or spec.loader is None:
        raise GatewayError("runtime observation verifier could not be loaded")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def canonical_json(value: Any) -> str:
    return json.dumps(
        value,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=True,
        allow_nan=False,
    )


def sha256_json(value: Any) -> str:
    return hashlib.sha256(canonical_json(value).encode("utf-8")).hexdigest()


def _text(value: Any, field: str) -> str:
    if not isinstance(value, str) or not value or value != value.strip():
        raise GatewayError(f"{field} must be a non-empty trimmed string")
    return value


def _sha(value: Any, field: str) -> str:
    value = _text(value, field)
    if len(value) != 64 or any(character not in "0123456789abcdef" for character in value):
        raise GatewayError(f"{field} must be a lowercase SHA-256 digest")
    return value


def _time(value: Any, field: str) -> datetime:
    value = _text(value, field)
    try:
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError:
        raise GatewayError(f"{field} must be timezone-aware ISO-8601") from None
    if parsed.tzinfo is None:
        raise GatewayError(f"{field} must be timezone-aware ISO-8601")
    return parsed.astimezone(timezone.utc)


def _forbidden_material(value: Any, *, path: str = "request") -> None:
    if isinstance(value, dict):
        for key, item in value.items():
            if any(part in str(key).casefold() for part in ("private_key", "credential", "api_key", "secret")):
                raise GatewayError(f"{path} contains forbidden private authority or credentials")
            _forbidden_material(item, path=f"{path}.{key}")
    elif isinstance(value, list):
        for index, item in enumerate(value):
            _forbidden_material(item, path=f"{path}[{index}]")


def validate_vertical_slice_manifest(manifest: Any) -> dict[str, Any]:
    """Apply the stricter first-dogfood envelope after the general validator."""
    errors: list[str] = []
    if not isinstance(manifest, dict):
        return {"valid": False, "errors": ["fabric manifest must be an object"]}
    managers = manifest.get("managers")
    if not isinstance(managers, list) or len(managers) != 1:
        return {"valid": False, "errors": ["first runtime slice requires exactly one manager"]}
    manager = managers[0]
    workers = manager.get("workers") if isinstance(manager, dict) else None
    if not isinstance(workers, list) or len(workers) != 1:
        errors.append("first runtime slice requires exactly one worker")
        workers = []
    if isinstance(manager, dict) and manager.get("model") != "gpt-5.6-sol":
        errors.append("runtime manager must use exact gpt-5.6-sol")
    worker = workers[0] if workers else {}
    if worker.get("model") != "gpt-5.6-luna":
        errors.append("runtime worker must use exact gpt-5.6-luna")
    if manifest.get("external_effects_allowed") is not False:
        errors.append("runtime vertical slice must prohibit external effects")
    if worker.get("write_scope") != []:
        errors.append("first Luna task must be read-only")
    if worker.get("capabilities") != ["emit_artifact", "read_project"]:
        errors.append("first Luna task must use the exact read-only capability set")
    if worker.get("may_delegate", False) is not False:
        errors.append("Luna worker may not delegate")
    if worker.get("external_effects", False) is not False:
        errors.append("Luna worker may not perform external effects")
    if manifest.get("max_managers") != 1 or manifest.get("max_workers_per_manager") != 1 or manifest.get("max_total_workers") != 1:
        errors.append("first runtime slice must cap managers and workers at one")
    return {"valid": not errors, "errors": errors}


def _manifest_identity(manifest: dict[str, Any], attempt: dict[str, Any]) -> dict[str, Any]:
    report = validate_vertical_slice_manifest(manifest)
    if not report["valid"]:
        raise GatewayError("runtime manifest violates the first vertical-slice contract")
    if sha256_json(manifest) != attempt.get("fabric_manifest_digest"):
        raise GatewayError("runtime admission does not bind the exact validated manifest")
    manager = manifest["managers"][0]
    if attempt.get("role") == "manager":
        identity = manager
        if attempt.get("manifest_identity_id") != manager.get("id") or attempt.get("parent_runtime_id") != "master":
            raise GatewayError("manager admission does not bind the exact manifest identity")
    elif attempt.get("role") == "worker":
        identity = manager["workers"][0]
        if attempt.get("manifest_identity_id") != identity.get("id") or attempt.get("parent_runtime_id") == "master":
            raise GatewayError("worker admission does not bind the exact manifest identity and manager parent")
    else:
        raise GatewayError("runtime role is unsupported")
    if attempt.get("requested_model") != identity.get("model"):
        raise GatewayError("runtime admission model differs from the validated manifest")
    if attempt.get("scope") != identity.get("write_scope"):
        raise GatewayError("runtime admission scope differs from the validated manifest")
    if attempt.get("scope_digest") != sha256_json(attempt.get("scope")):
        raise GatewayError("runtime admission scope digest is invalid")
    if attempt.get("budget") != identity.get("budget"):
        raise GatewayError("runtime admission budget differs from the validated manifest")
    budget = attempt.get("budget")
    expected_budget_fields = {"time_minutes", "token_limit", "cost_usd", "max_concurrency", "max_retries"}
    if not isinstance(budget, dict) or set(budget) != expected_budget_fields:
        raise GatewayError("runtime budget has the wrong shape")
    for field in ("token_limit", "max_concurrency", "max_retries"):
        if not isinstance(budget[field], int) or isinstance(budget[field], bool) or budget[field] < 0:
            raise GatewayError(f"runtime budget {field} must be a non-negative integer")
    for field in ("time_minutes", "cost_usd"):
        if (
            not isinstance(budget[field], (int, float))
            or isinstance(budget[field], bool)
            or not math.isfinite(budget[field])
            or budget[field] < 0
        ):
            raise GatewayError(f"runtime budget {field} must be finite and non-negative")
    if budget["max_concurrency"] != 1 or budget["max_retries"] != 0:
        raise GatewayError("first runtime slice requires concurrency one and no retry")
    return identity


def _lifecycle(attempt: dict[str, Any]) -> dict[str, Any]:
    lifecycle = attempt.get("lifecycle") if isinstance(attempt, dict) else None
    if not isinstance(lifecycle, dict):
        raise GatewayError("runtime attempt lacks lifecycle state")
    return lifecycle


def build_request(
    attempt: dict[str, Any],
    *,
    manifest: dict[str, Any],
    operation: str,
    current_lease_fence: dict[str, Any] | None = None,
    now: datetime | None = None,
) -> dict[str, Any]:
    """Build one immutable command for a protected external gateway."""
    now = (now or datetime.now(timezone.utc)).astimezone(timezone.utc)
    if operation not in OPERATIONS:
        raise GatewayError("gateway operation is unsupported")
    lifecycle = _lifecycle(attempt)
    status = lifecycle.get("status")
    permitted = {
        "launch": {"admitted"},
        "query": {"launch_unknown", "cancel_requested"},
        "observe": {"launched", "running", "cancel_requested", "cancel_acknowledged"},
        "cancel": {"cancel_requested"},
    }
    if status not in permitted[operation]:
        raise GatewayError(f"gateway {operation} is not valid from {status}")
    if operation == "query" and lifecycle.get("provider_task_id") is not None:
        raise GatewayError("query recovery is only for an unbound launch intent")
    if operation in {"observe", "cancel"} and lifecycle.get("provider_task_id") is None:
        raise GatewayError(f"gateway {operation} requires a bound provider task")
    if any(attempt.get(field) in (None, "") for field in IMMUTABLE_ATTEMPT_FIELDS):
        raise GatewayError("runtime admission is missing immutable launch fields")
    _manifest_identity(manifest, attempt)
    if attempt.get("role") == "manager":
        if attempt.get("requested_model") != "gpt-5.6-sol" or attempt.get("parent_runtime_id") != "master":
            raise GatewayError("manager launch requires exact Sol identity and master parent")
    elif attempt.get("role") == "worker":
        if attempt.get("requested_model") != "gpt-5.6-luna" or attempt.get("parent_runtime_id") == "master":
            raise GatewayError("worker launch requires exact Luna identity and manager parent")
    else:
        raise GatewayError("runtime role is unsupported")
    if attempt.get("capabilities") != ["emit_artifact", "read_project"]:
        raise GatewayError("runtime attempt exceeds the read-only artifact capability set")
    fence = attempt.get("lease_fence") if operation == "launch" else current_lease_fence
    if not isinstance(fence, dict):
        raise GatewayError("runtime operation lacks a current controller lease fence")
    expiry = _time(fence.get("expires_at"), "lease_fence.expires_at")
    if expiry <= now:
        raise GatewayError("runtime admission lease fence is expired")
    if any(fence.get(field) in (None, "") for field in ("lease_id", "generation", "owner", "program_version")):
        raise GatewayError("runtime operation lease fence is incomplete")
    if fence.get("program_version") != attempt.get("program_version"):
        raise GatewayError("runtime operation lease belongs to a different program")
    grant = attempt.get("actor_grant")
    if not isinstance(grant, dict) or not grant.get("token") or not grant.get("grant_digest"):
        raise GatewayError("runtime admission lacks its externally signed grant")
    _sha(grant["grant_digest"], "actor_grant.grant_digest")
    request = {
        "schema": REQUEST_SCHEMA,
        "operation": operation,
        "attempt": {field: deepcopy(attempt[field]) for field in IMMUTABLE_ATTEMPT_FIELDS},
        "provider_task_id": lifecycle.get("provider_task_id"),
        "admission_grant_token": _text(grant["token"], "actor_grant.token"),
        "admission_grant_digest": grant["grant_digest"],
        "lease_fence": deepcopy(fence),
        "external_effects_allowed": False,
    }
    _forbidden_material(request)
    return request | {"request_digest": sha256_json(request)}


def load_envelope(path: Path) -> dict[str, Any]:
    value = observation_module().load_json_strict(path)
    if not isinstance(value, dict):
        raise GatewayError("gateway result envelope must be an object")
    return value


def _project_artifact(root: Path, relative: Any) -> tuple[Path, bytes]:
    try:
        path = observation_module().resolve_project_artifact(root, relative)
        value = path.read_bytes()
    except (OSError, ValueError) as exc:
        raise GatewayError(str(exc)) from None
    return path, value


def verify_result(
    envelope: Any,
    *,
    request: dict[str, Any],
    keyring_path: Path,
    artifact_root: Path,
    now: datetime | None = None,
) -> VerifiedGatewayRecord:
    """Verify one gateway result and return a lifecycle-ready trusted record."""
    now = (now or datetime.now(timezone.utc)).astimezone(timezone.utc)
    if not isinstance(envelope, dict) or set(envelope) != {"claims", "signature"}:
        raise GatewayError("gateway result must contain exactly claims and signature")
    claims = envelope.get("claims")
    if not isinstance(claims, dict) or set(claims) != RESULT_FIELDS or claims.get("schema") != RESULT_SCHEMA:
        raise GatewayError("gateway result claims have the wrong shape")
    if request.get("schema") != REQUEST_SCHEMA or request.get("request_digest") != sha256_json({
        key: value for key, value in request.items() if key != "request_digest"
    }):
        raise GatewayError("gateway request is not canonically bound")
    operation = claims.get("operation")
    if operation != request.get("operation") or claims.get("event_type") not in OPERATION_EVENTS.get(operation, set()):
        raise GatewayError("gateway result event is not permitted for the request")
    if claims.get("request_digest") != request.get("request_digest"):
        raise GatewayError("gateway result does not bind the exact request")
    issued_at = _time(claims.get("issued_at"), "issued_at")
    expires_at = _time(claims.get("expires_at"), "expires_at")
    provider_time = _time(claims.get("provider_timestamp"), "provider_timestamp")
    gateway_time = _time(claims.get("gateway_received_at"), "gateway_received_at")
    if issued_at > now + MAX_FUTURE_SKEW or expires_at <= now or expires_at <= issued_at:
        raise GatewayError("gateway result has an invalid validity window")
    if expires_at - issued_at > MAX_RESULT_TTL:
        raise GatewayError("gateway result TTL exceeds five minutes")
    if provider_time > now + MAX_FUTURE_SKEW or gateway_time < provider_time or gateway_time > issued_at + MAX_FUTURE_SKEW:
        raise GatewayError("gateway/provider timestamps are inconsistent")
    attempt = request["attempt"]
    binding_fields = (
        "project_id",
        "provider",
        "surface",
        "account",
        "program_version",
        "work_id",
        "cycle_id",
        "attempt_id",
        "parent_runtime_id",
        "role",
        "requested_model",
        "fabric_manifest_digest",
        "phase2_contract_digest",
    )
    if any(claims.get(field) != attempt.get(field) for field in binding_fields):
        raise GatewayError("gateway result does not bind the admitted runtime identity")
    task_id = claims.get("provider_task_id")
    if claims["event_type"] in {"launch_unknown", "launch_rejected"}:
        if task_id is not None or claims.get("observed_model") is not None:
            raise GatewayError("pre-task launch outcome cannot invent task or model identity")
    else:
        _text(task_id, "provider_task_id")
        if claims.get("observed_model") != attempt.get("requested_model"):
            raise GatewayError("gateway result does not prove the exact admitted model")
    if request.get("provider_task_id") not in {None, task_id}:
        raise GatewayError("gateway result changes the bound provider task")
    if not isinstance(claims.get("provider_sequence"), int) or isinstance(claims["provider_sequence"], bool) or claims["provider_sequence"] < 0:
        raise GatewayError("provider_sequence must be a non-negative integer")
    for field in ("raw_artifact_sha256", "payload_sha256"):
        _sha(claims.get(field), field)
    public_key = observation_module().load_gateway_key(
        keyring_path,
        _text(claims.get("gateway_key_id"), "gateway_key_id"),
        issued_at,
    )
    try:
        observation_module().verify_signature(claims, envelope.get("signature"), public_key)
    except ValueError as exc:
        raise GatewayError(str(exc)) from None
    _, raw_bytes = _project_artifact(artifact_root, claims.get("raw_artifact_path"))
    if hashlib.sha256(raw_bytes).hexdigest() != claims.get("raw_artifact_sha256"):
        raise GatewayError("gateway raw artifact digest does not match")
    raw = observation_module().load_json_bytes_strict(raw_bytes)
    if not isinstance(raw, dict) or set(raw) != RAW_FIELDS:
        raise GatewayError("gateway raw artifact has the wrong shape")
    for field in RAW_FIELDS - {"payload"}:
        if raw.get(field) != claims.get(field):
            raise GatewayError(f"gateway raw artifact {field} does not match signed claims")
    if sha256_json(raw.get("payload")) != claims.get("payload_sha256"):
        raise GatewayError("gateway provider payload digest does not match")
    if claims["event_type"] == "launch_rejected" and raw["payload"] != {
        "provider_status": "rejected",
        "reason": "model_unavailable",
        "usage": None,
    }:
        raise GatewayError("launch_rejected must prove definitive model unavailability")
    digest = sha256_json(claims)
    value = {
        "observation_digest": digest,
        "claims": deepcopy(claims),
        "signature": envelope["signature"],
        "signature_digest": hashlib.sha256(str(envelope["signature"]).encode("utf-8")).hexdigest(),
        "raw": deepcopy(raw),
        "raw_artifact_b64": base64.b64encode(raw_bytes).decode("ascii"),
        "verified_at": now.isoformat(),
    }
    return VerifiedGatewayRecord(value, _seal=_VERIFICATION_SEAL)


def reverify_retained_record(
    record: Any,
    *,
    keyring_path: Path,
    now: datetime | None = None,
    historical: bool = False,
) -> VerifiedGatewayRecord:
    """Cryptographically replay one retained observation after restart."""
    now = (now or datetime.now(timezone.utc)).astimezone(timezone.utc)
    expected_fields = {
        "observation_digest", "claims", "signature", "signature_digest",
        "raw", "raw_artifact_b64", "verified_at",
    }
    if not isinstance(record, dict) or set(record) != expected_fields:
        raise GatewayError("retained gateway record has the wrong shape")
    claims = record.get("claims")
    if not isinstance(claims, dict) or set(claims) != RESULT_FIELDS or claims.get("schema") != RESULT_SCHEMA:
        raise GatewayError("retained gateway claims have the wrong shape")
    if record.get("observation_digest") != sha256_json(claims):
        raise GatewayError("retained observation digest does not bind signed claims")
    if record.get("signature_digest") != hashlib.sha256(str(record.get("signature")).encode("utf-8")).hexdigest():
        raise GatewayError("retained signature digest is invalid")
    issued_at = _time(claims.get("issued_at"), "issued_at")
    expires_at = _time(claims.get("expires_at"), "expires_at")
    if expires_at <= issued_at or expires_at - issued_at > MAX_RESULT_TTL:
        raise GatewayError("retained gateway validity window is invalid")
    if not historical and (issued_at > now + MAX_FUTURE_SKEW or expires_at <= now):
        raise GatewayError("retained gateway result is not currently valid")
    operation = claims.get("operation")
    if operation not in OPERATIONS or claims.get("event_type") not in OPERATION_EVENTS[operation]:
        raise GatewayError("retained gateway operation/event binding is invalid")
    public_key = observation_module().load_gateway_key(
        keyring_path,
        _text(claims.get("gateway_key_id"), "gateway_key_id"),
        issued_at,
        allow_retired=historical,
    )
    try:
        observation_module().verify_signature(claims, record.get("signature"), public_key)
    except ValueError as exc:
        raise GatewayError(str(exc)) from None
    try:
        raw_bytes = base64.b64decode(record.get("raw_artifact_b64"), validate=True)
    except (ValueError, TypeError, binascii.Error):
        raise GatewayError("retained raw artifact encoding is invalid") from None
    if hashlib.sha256(raw_bytes).hexdigest() != claims.get("raw_artifact_sha256"):
        raise GatewayError("retained raw artifact digest does not match")
    raw = observation_module().load_json_bytes_strict(raw_bytes)
    if raw != record.get("raw") or not isinstance(raw, dict) or set(raw) != RAW_FIELDS:
        raise GatewayError("retained raw artifact content changed")
    for field in RAW_FIELDS - {"payload"}:
        if raw.get(field) != claims.get(field):
            raise GatewayError(f"retained raw artifact {field} does not match signed claims")
    if sha256_json(raw.get("payload")) != claims.get("payload_sha256"):
        raise GatewayError("retained provider payload digest does not match")
    event = claims.get("event_type")
    if event in {"launch_unknown", "launch_rejected"}:
        if claims.get("provider_task_id") is not None or claims.get("observed_model") is not None:
            raise GatewayError("retained pre-task launch outcome invents task or model identity")
    elif (
        not isinstance(claims.get("provider_task_id"), str)
        or not claims["provider_task_id"]
        or claims.get("observed_model") != claims.get("requested_model")
    ):
        raise GatewayError("retained gateway result lacks exact provider task/model proof")
    if event == "launch_rejected" and raw.get("payload") != {
        "provider_status": "rejected", "reason": "model_unavailable", "usage": None,
    }:
        raise GatewayError("retained launch rejection semantics changed")
    _time(record.get("verified_at"), "verified_at")
    return VerifiedGatewayRecord(record, _seal=_VERIFICATION_SEAL)


def verify_receipt_attestation(
    envelope: Any,
    *,
    attempt: dict[str, Any],
    keyring_path: Path,
    now: datetime | None = None,
) -> VerifiedReceiptAttestation:
    """Verify the gateway signature that binds a receipt to one provider task.

    Receipt content is retained only after this verifier succeeds.  This keeps
    provider attribution separate from an agent-authored ``author`` string.
    """
    now = (now or datetime.now(timezone.utc)).astimezone(timezone.utc)
    if not isinstance(envelope, dict) or set(envelope) != {"claims", "signature"}:
        raise GatewayError("receipt attestation must contain exactly claims and signature")
    claims = envelope.get("claims")
    if (
        not isinstance(claims, dict)
        or set(claims) != RECEIPT_ATTESTATION_FIELDS
        or claims.get("schema") != RECEIPT_ATTESTATION_SCHEMA
    ):
        raise GatewayError("receipt attestation claims have the wrong shape")
    lifecycle = _lifecycle(attempt)
    provider_task_id = lifecycle.get("provider_task_id")
    if lifecycle.get("status") == "blocked_model_unavailable":
        if provider_task_id is not None:
            raise GatewayError("model-unavailable receipt cannot invent a provider task")
    else:
        provider_task_id = _text(provider_task_id, "provider_task_id")
    expected = {
        "action": "attest-runtime-receipt",
        "project_id": attempt.get("project_id"),
        "attempt_id": attempt.get("attempt_id"),
        "provider_task_id": provider_task_id,
    }
    if any(claims.get(field) != value for field, value in expected.items()):
        raise GatewayError("receipt attestation does not bind the exact runtime task")
    _sha(claims.get("receipt_payload_hash"), "receipt_payload_hash")
    _text(claims.get("nonce"), "nonce")
    issued_at = _time(claims.get("issued_at"), "issued_at")
    expires_at = _time(claims.get("expires_at"), "expires_at")
    if issued_at > now + MAX_FUTURE_SKEW or expires_at <= now or expires_at <= issued_at:
        raise GatewayError("receipt attestation has an invalid validity window")
    if expires_at - issued_at > MAX_RESULT_TTL:
        raise GatewayError("receipt attestation TTL exceeds five minutes")
    public_key = observation_module().load_gateway_key(
        keyring_path,
        _text(claims.get("gateway_key_id"), "gateway_key_id"),
        issued_at,
    )
    try:
        observation_module().verify_signature(claims, envelope.get("signature"), public_key)
    except ValueError as exc:
        raise GatewayError(str(exc)) from None
    value = {
        "attestation_digest": sha256_json(claims),
        "claims": deepcopy(claims),
        "signature": envelope["signature"],
        "signature_digest": hashlib.sha256(str(envelope["signature"]).encode("utf-8")).hexdigest(),
        "verified_at": now.isoformat(),
    }
    return VerifiedReceiptAttestation(value, _seal=_VERIFICATION_SEAL)


def reverify_receipt_attestation(
    record: Any,
    *,
    keyring_path: Path,
    now: datetime | None = None,
    historical: bool = False,
) -> VerifiedReceiptAttestation:
    now = (now or datetime.now(timezone.utc)).astimezone(timezone.utc)
    expected_fields = {"attestation_digest", "claims", "signature", "signature_digest", "verified_at"}
    if not isinstance(record, dict) or set(record) != expected_fields:
        raise GatewayError("retained receipt attestation has the wrong shape")
    claims = record.get("claims")
    if (
        not isinstance(claims, dict)
        or set(claims) != RECEIPT_ATTESTATION_FIELDS
        or claims.get("schema") != RECEIPT_ATTESTATION_SCHEMA
    ):
        raise GatewayError("retained receipt attestation claims have the wrong shape")
    if record.get("attestation_digest") != sha256_json(claims):
        raise GatewayError("retained receipt attestation digest is invalid")
    if record.get("signature_digest") != hashlib.sha256(str(record.get("signature")).encode("utf-8")).hexdigest():
        raise GatewayError("retained receipt signature digest is invalid")
    issued_at = _time(claims.get("issued_at"), "issued_at")
    expires_at = _time(claims.get("expires_at"), "expires_at")
    if expires_at <= issued_at or expires_at - issued_at > MAX_RESULT_TTL:
        raise GatewayError("retained receipt attestation validity window is invalid")
    if not historical and (issued_at > now + MAX_FUTURE_SKEW or expires_at <= now):
        raise GatewayError("retained receipt attestation is not currently valid")
    public_key = observation_module().load_gateway_key(
        keyring_path,
        _text(claims.get("gateway_key_id"), "gateway_key_id"),
        issued_at,
        allow_retired=historical,
    )
    try:
        observation_module().verify_signature(claims, record.get("signature"), public_key)
    except ValueError as exc:
        raise GatewayError(str(exc)) from None
    _time(record.get("verified_at"), "verified_at")
    return VerifiedReceiptAttestation(record, _seal=_VERIFICATION_SEAL)

#!/usr/bin/env python3
"""Pure, fail-closed lifecycle rules for authenticated Company OS runtimes.

The controller owns persistence, leases, decision grants, and artifact IO.  This
module only transforms an already-admitted attempt using gateway-verified
observations or explicit master decisions.  It performs no provider calls and
writes no files.
"""

from __future__ import annotations

import hashlib
import importlib.util
import json
import math
from copy import deepcopy
from datetime import datetime, timezone
from pathlib import Path
from typing import Any


LIFECYCLE_VERSION = "company-os.runtime-lifecycle.v1"
MODEL_MAPPING_VERSION = "exact-provider-model-v1"
ACTIVE_STATES = {
    "admitted",
    "launch_unknown",
    "launched",
    "running",
    "cancel_requested",
    "cancel_acknowledged",
}
TERMINAL_STATES = {
    "succeeded", "failed", "cancelled", "blocked_model_unavailable",
    "cancelled_before_launch",
}
POST_TERMINAL_STATES = {"receipt_recorded", "reconciled"}
ALL_STATES = ACTIVE_STATES | TERMINAL_STATES | POST_TERMINAL_STATES
OBSERVATION_EVENTS = {
    "launch",
    "launch_unknown",
    "launch_rejected",
    "running",
    "heartbeat",
    "cancel_acknowledged",
    "terminal",
}
RECEIPT_STATUSES = {"complete", "blocked", "failed", "cancelled"}
RECONCILIATION_DECISIONS = {"accepted", "rejected", "cancelled", "blocked"}
USAGE_FIELDS = {
    "input_tokens",
    "cached_input_tokens",
    "output_tokens",
    "total_tokens",
    "cost_usd",
    "currency",
    "semantics",
    "provider_revision",
}


class LifecycleError(ValueError):
    """A transition that must not be persisted."""


def receipt_module() -> Any:
    module_path = Path(__file__).resolve().with_name("runtime_receipts.py")
    spec = importlib.util.spec_from_file_location("company_os_runtime_receipts", module_path)
    if spec is None or spec.loader is None:
        raise LifecycleError("runtime receipt module could not be loaded")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def gateway_module() -> Any:
    module_path = Path(__file__).resolve().with_name("runtime_gateway.py")
    spec = importlib.util.spec_from_file_location("company_os_runtime_gateway_for_lifecycle", module_path)
    if spec is None or spec.loader is None:
        raise LifecycleError("runtime gateway verifier could not be loaded")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def canonical_json(value: Any) -> str:
    return json.dumps(
        value,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=True,
        allow_nan=False,
    )


def sha256_json(value: Any) -> str:
    return hashlib.sha256(canonical_json(value).encode("utf-8")).hexdigest()


def _trimmed(value: Any, field: str) -> str:
    if not isinstance(value, str) or not value or value != value.strip():
        raise LifecycleError(f"{field} must be a non-empty trimmed string")
    return value


def _sha(value: Any, field: str) -> str:
    value = _trimmed(value, field)
    if len(value) != 64 or any(character not in "0123456789abcdef" for character in value):
        raise LifecycleError(f"{field} must be a lowercase SHA-256 digest")
    return value


def _time(value: Any, field: str) -> str:
    text = _trimmed(value, field)
    try:
        parsed = datetime.fromisoformat(text.replace("Z", "+00:00"))
    except ValueError:
        raise LifecycleError(f"{field} must be timezone-aware ISO-8601") from None
    if parsed.tzinfo is None:
        raise LifecycleError(f"{field} must be timezone-aware ISO-8601")
    return parsed.astimezone(timezone.utc).isoformat()


def _nonnegative_int(value: Any, field: str) -> int:
    if not isinstance(value, int) or isinstance(value, bool) or value < 0:
        raise LifecycleError(f"{field} must be a non-negative integer")
    return value


def _nonnegative_number(value: Any, field: str) -> float:
    if (
        not isinstance(value, (int, float))
        or isinstance(value, bool)
        or not math.isfinite(value)
        or value < 0
    ):
        raise LifecycleError(f"{field} must be a finite non-negative number")
    return float(value)


def empty_lifecycle() -> dict[str, Any]:
    return {
        "schema": LIFECYCLE_VERSION,
        "status": "admitted",
        "provider_task_id": None,
        "observed_model": None,
        "model_mapping_version": None,
        "model_evidence_digest": None,
        "observation_digests": [],
        "verified_observations": [],
        "last_provider_sequence": None,
        "last_provider_timestamp": None,
        "last_heartbeat_at": None,
        "terminal_observation_digest": None,
        "terminal_decision_digest": None,
        "terminal_provider_event_id": None,
        "terminal_authority": None,
        "terminal_status": None,
        "cancellation": None,
        "telemetry": None,
        "budget_overage": None,
        "receipt": None,
        "reconciliation": None,
    }


def _require_lifecycle(attempt: dict[str, Any]) -> dict[str, Any]:
    if not isinstance(attempt, dict):
        raise LifecycleError("runtime attempt must be an object")
    lifecycle = attempt.get("lifecycle")
    expected = set(empty_lifecycle())
    if not isinstance(lifecycle, dict) or set(lifecycle) != expected:
        raise LifecycleError("runtime attempt lifecycle has the wrong shape")
    if lifecycle.get("schema") != LIFECYCLE_VERSION or lifecycle.get("status") not in ALL_STATES:
        raise LifecycleError("runtime attempt lifecycle schema or status is invalid")
    return lifecycle


def _verified_record(
    record: Any,
    *,
    keyring_path: Path,
    now: datetime | None,
    historical: bool,
) -> tuple[dict[str, Any], dict[str, Any], dict[str, Any]]:
    retained = None
    if not isinstance(record, dict) and callable(getattr(record, "retained_record", None)):
        retained = record.retained_record()
    if not isinstance(retained, dict):
        raise LifecycleError("runtime advancement requires verifier-produced cryptographic evidence")
    try:
        verified = gateway_module().reverify_retained_record(
            retained,
            keyring_path=keyring_path,
            now=now,
            historical=historical,
        )
    except ValueError as exc:
        raise LifecycleError(str(exc)) from None
    retained = verified.retained_record()
    claims = retained.get("claims")
    if not isinstance(claims, dict):
        raise LifecycleError("verified observation lacks claims")
    if claims.get("event_type") not in OBSERVATION_EVENTS:
        raise LifecycleError("verified observation event is unsupported")
    _sha(retained.get("observation_digest"), "observation_digest")
    raw = retained.get("raw")
    if not isinstance(raw, dict) or not isinstance(raw.get("payload"), dict):
        raise LifecycleError("verified observation requires its exact parsed raw artifact")
    return claims, raw["payload"], retained


def _assert_binding(attempt: dict[str, Any], claims: dict[str, Any]) -> None:
    bindings = {
        "attempt_id": "attempt_id",
        "project_id": "project_id",
        "work_id": "work_id",
        "cycle_id": "cycle_id",
        "parent_runtime_id": "parent_runtime_id",
        "role": "role",
        "requested_model": "requested_model",
        "provider": "provider",
        "surface": "surface",
        "account": "account",
        "fabric_manifest_digest": "fabric_manifest_digest",
        "phase2_contract_digest": "phase2_contract_digest",
    }
    for attempt_field, claim_field in bindings.items():
        if attempt.get(attempt_field) != claims.get(claim_field):
            raise LifecycleError(f"verified observation {claim_field} does not bind the attempt")
    if attempt.get("program_version") != claims.get("program_version"):
        raise LifecycleError("verified observation program_version does not bind the attempt")


def _usage(payload: dict[str, Any]) -> dict[str, Any] | None:
    value = payload.get("usage")
    if value is None:
        return None
    if not isinstance(value, dict) or set(value) != USAGE_FIELDS:
        raise LifecycleError("provider usage has the wrong shape")
    result = {
        field: _nonnegative_int(value.get(field), f"usage.{field}")
        for field in ("input_tokens", "cached_input_tokens", "output_tokens", "total_tokens")
    }
    if result["cached_input_tokens"] > result["input_tokens"]:
        raise LifecycleError("cached input tokens cannot exceed input tokens")
    if result["total_tokens"] != result["input_tokens"] + result["output_tokens"]:
        raise LifecycleError("total tokens must equal input plus output tokens")
    result.update(
        {
            "cost_usd": _nonnegative_number(value.get("cost_usd"), "usage.cost_usd"),
            "currency": _trimmed(value.get("currency"), "usage.currency"),
            "semantics": _trimmed(value.get("semantics"), "usage.semantics"),
            "provider_revision": _trimmed(value.get("provider_revision"), "usage.provider_revision"),
        }
    )
    if result["currency"] != "USD" or result["semantics"] not in {"cumulative", "terminal"}:
        raise LifecycleError("provider usage currency or semantics is unsupported")
    return result


def _merge_usage(
    existing: dict[str, Any] | None,
    current: dict[str, Any],
    *,
    observation_digest: str,
) -> dict[str, Any]:
    value = deepcopy(current)
    value["source_observation_digests"] = [observation_digest]
    value["provider_revisions"] = [current["provider_revision"]]
    if existing is None:
        return value
    if not isinstance(existing, dict):
        raise LifecycleError("retained provider telemetry is invalid")
    revisions = existing.get("provider_revisions")
    sources = existing.get("source_observation_digests")
    if not isinstance(revisions, list) or not isinstance(sources, list):
        raise LifecycleError("retained provider telemetry lacks provenance")
    if current["provider_revision"] in revisions:
        raise LifecycleError("provider telemetry revision cannot be reused")
    for field in ("input_tokens", "cached_input_tokens", "output_tokens", "total_tokens", "cost_usd"):
        prior = existing.get(field)
        if not isinstance(prior, (int, float)) or isinstance(prior, bool) or current[field] < prior:
            raise LifecycleError(f"provider telemetry {field} cannot decrease")
    if current["currency"] != existing.get("currency"):
        raise LifecycleError("provider telemetry currency cannot change")
    value["provider_revisions"] = revisions + [current["provider_revision"]]
    value["source_observation_digests"] = sources + [observation_digest]
    return value


def apply_verified_observation(
    attempt: dict[str, Any],
    record: Any,
    *,
    keyring_path: Path,
    now: datetime | None = None,
    historical: bool = False,
) -> dict[str, Any]:
    """Return a candidate attempt after one trusted provider fact."""
    candidate = deepcopy(attempt)
    lifecycle = _require_lifecycle(candidate)
    claims, payload, retained_record = _verified_record(
        record,
        keyring_path=keyring_path,
        now=now,
        historical=historical,
    )
    _assert_binding(candidate, claims)
    digest = retained_record["observation_digest"]
    if digest in lifecycle["observation_digests"]:
        return candidate
    sequence = _nonnegative_int(claims.get("provider_sequence"), "provider_sequence")
    previous_sequence = lifecycle.get("last_provider_sequence")
    if previous_sequence is not None and sequence <= previous_sequence:
        raise LifecycleError("provider sequence cannot regress or repeat")
    provider_time = _time(claims.get("provider_timestamp"), "provider_timestamp")
    previous_provider_time = lifecycle.get("last_provider_timestamp")
    if (
        previous_provider_time is not None
        and datetime.fromisoformat(provider_time)
        < datetime.fromisoformat(_time(previous_provider_time, "last_provider_timestamp"))
    ):
        raise LifecycleError("provider timestamp cannot decrease")
    event = claims["event_type"]
    provider_task_id = claims.get("provider_task_id")
    if event in {"launch_unknown", "launch_rejected"}:
        if provider_task_id is not None:
            _trimmed(provider_task_id, "provider_task_id")
    else:
        provider_task_id = _trimmed(provider_task_id, "provider_task_id")
    bound_task = lifecycle.get("provider_task_id")
    if bound_task is not None and provider_task_id is not None and provider_task_id != bound_task:
        raise LifecycleError("one runtime attempt cannot bind multiple provider tasks")

    status = lifecycle["status"]
    observed_model = claims.get("observed_model")
    if event not in {"launch_unknown", "launch_rejected"}:
        observed_model = _trimmed(observed_model, "observed_model")
        if observed_model != candidate.get("requested_model"):
            raise LifecycleError("provider-observed model does not exactly match the admitted model")
    if status in TERMINAL_STATES | POST_TERMINAL_STATES:
        raise LifecycleError("provider terminal state is immutable")
    current_usage = _usage(payload)
    if current_usage is not None:
        expected_semantics = "terminal" if event == "terminal" else "cumulative"
        if current_usage["semantics"] != expected_semantics:
            raise LifecycleError(f"{event} observation requires {expected_semantics} usage semantics")

    next_status = status
    if event == "launch_unknown":
        if status not in {"admitted", "launch_unknown", "cancel_requested"}:
            raise LifecycleError("launch_unknown is invalid after a provider task is bound")
        next_status = "cancel_requested" if lifecycle.get("cancellation") is not None else "launch_unknown"
    elif event == "launch_rejected":
        if status not in {"admitted", "launch_unknown", "cancel_requested"}:
            raise LifecycleError("launch_rejected is valid only before a provider task is bound")
        if payload != {
            "provider_status": "rejected",
            "reason": "model_unavailable",
            "usage": None,
        }:
            raise LifecycleError("launch rejection does not prove model unavailability")
        terminal = "cancelled_before_launch" if lifecycle.get("cancellation") is not None else "blocked_model_unavailable"
        lifecycle["terminal_status"] = terminal
        lifecycle["terminal_observation_digest"] = digest
        lifecycle["terminal_provider_event_id"] = claims.get("provider_event_id")
        lifecycle["terminal_authority"] = "provider_observation"
        next_status = terminal
    elif event == "launch":
        if status not in {"admitted", "launch_unknown", "cancel_requested"}:
            raise LifecycleError("launch is valid only from admitted or launch_unknown")
        next_status = "cancel_requested" if lifecycle.get("cancellation") is not None else "launched"
    elif event in {"running", "heartbeat"}:
        if status not in {"launched", "running", "cancel_requested", "cancel_acknowledged"}:
            raise LifecycleError("running evidence requires a launched attempt")
        next_status = status if status in {"cancel_requested", "cancel_acknowledged"} else "running"
        lifecycle["last_heartbeat_at"] = provider_time
    elif event == "cancel_acknowledged":
        if status != "cancel_requested":
            raise LifecycleError("cancellation acknowledgement requires an authoritative request")
        next_status = "cancel_acknowledged"
    elif event == "terminal":
        terminal = payload.get("status")
        if terminal not in {"succeeded", "failed", "cancelled"}:
            raise LifecycleError("terminal observation must declare succeeded, failed, or cancelled")
        if lifecycle.get("cancellation") is not None:
            terminal = "cancelled"
        elif status not in {"launched", "running"}:
            raise LifecycleError("terminal evidence requires launched or running state")
        if current_usage is None:
            raise LifecycleError("terminal observation requires provider-derived usage")
        lifecycle["terminal_status"] = terminal
        lifecycle["terminal_observation_digest"] = digest
        lifecycle["terminal_provider_event_id"] = claims.get("provider_event_id")
        lifecycle["terminal_authority"] = "provider_observation"
        next_status = terminal

    if provider_task_id is not None:
        lifecycle["provider_task_id"] = provider_task_id
    if observed_model is not None:
        lifecycle["observed_model"] = observed_model
        lifecycle["model_mapping_version"] = MODEL_MAPPING_VERSION
        if lifecycle.get("model_evidence_digest") is None:
            lifecycle["model_evidence_digest"] = digest
    if current_usage is not None:
        lifecycle["telemetry"] = _merge_usage(
            lifecycle.get("telemetry"),
            current_usage,
            observation_digest=digest,
        )
    budget = candidate.get("budget")
    if not isinstance(budget, dict):
        raise LifecycleError("runtime attempt lacks its admitted budget")
    overages: dict[str, dict[str, float]] = {}
    telemetry = lifecycle.get("telemetry")
    if telemetry is not None:
        if telemetry["total_tokens"] > budget.get("token_limit", -1):
            overages["total_tokens"] = {
                "actual": float(telemetry["total_tokens"]),
                "limit": float(budget.get("token_limit", -1)),
            }
        if telemetry["cost_usd"] > budget.get("cost_usd", -1):
            overages["cost_usd"] = {
                "actual": float(telemetry["cost_usd"]),
                "limit": float(budget.get("cost_usd", -1)),
            }
    retained = lifecycle.get("verified_observations")
    first_time = (
        _time(
            retained[0].get("claims", {}).get("provider_timestamp"),
            "first_provider_timestamp",
        )
        if retained
        else provider_time
    )
    elapsed_minutes = max(
        0.0,
        (
            datetime.fromisoformat(provider_time)
            - datetime.fromisoformat(first_time)
        ).total_seconds()
        / 60.0,
    )
    time_limit = _nonnegative_number(budget.get("time_minutes"), "budget.time_minutes")
    if elapsed_minutes > time_limit:
        overages["time_minutes"] = {
            "actual": elapsed_minutes,
            "limit": time_limit,
        }
    lifecycle["budget_overage"] = overages or None
    lifecycle["status"] = next_status
    lifecycle["observation_digests"].append(digest)
    lifecycle["verified_observations"].append(retained_record)
    lifecycle["last_provider_sequence"] = sequence
    lifecycle["last_provider_timestamp"] = provider_time
    return candidate


def request_cancellation(
    attempt: dict[str, Any],
    *,
    requested_by: str,
    reason: str,
    grant_token: str,
    decision_public_key_path: Path,
    requested_at: str,
    now: datetime | None = None,
    historical: bool = False,
) -> dict[str, Any]:
    candidate = deepcopy(attempt)
    lifecycle = _require_lifecycle(candidate)
    if (
        lifecycle["status"] in TERMINAL_STATES | POST_TERMINAL_STATES
        and lifecycle.get("cancellation") is None
    ):
        raise LifecycleError("terminal runtime cannot be cancelled")
    existing = lifecycle.get("cancellation")
    normalized_time = _time(requested_at, "requested_at")
    request_payload = {
        "attempt_id": candidate.get("attempt_id"),
        "requested_by": _trimmed(requested_by, "requested_by"),
        "reason": _trimmed(reason, "reason"),
        "requested_at": normalized_time,
        "after_observation_count": (
            existing.get("after_observation_count")
            if isinstance(existing, dict)
            else len(lifecycle.get("verified_observations", []))
        ),
    }
    expected_claims = {
        "actor": requested_by,
        "action": "cancel-runtime",
        "resource": f"runtime:{candidate.get('attempt_id')}",
        "project_id": candidate.get("project_id"),
        "program_version": candidate.get("program_version"),
        "work_id": candidate.get("work_id"),
        "cycle_id": candidate.get("cycle_id"),
        "dimension": "runtime-cancellation",
        "decision": "cancelled",
        "payload_hash": sha256_json(request_payload),
    }
    try:
        grant = receipt_module()._verify_decision_grant(
            grant_token,
            public_key_path=decision_public_key_path,
            expected_claims=expected_claims,
            now=(now or datetime.now(timezone.utc)).astimezone(timezone.utc),
            historical=historical or existing is not None,
        )
    except ValueError as exc:
        raise LifecycleError(str(exc)) from None
    request = {
        **request_payload,
        "grant": grant,
    }
    if existing is not None:
        if existing == request:
            return candidate
        raise LifecycleError("runtime cancellation is irreversible and already bound")
    lifecycle["cancellation"] = request
    if lifecycle["status"] == "admitted":
        lifecycle["status"] = "cancelled_before_launch"
        lifecycle["terminal_status"] = "cancelled_before_launch"
        lifecycle["terminal_authority"] = "decision_grant"
        lifecycle["terminal_decision_digest"] = grant["grant_digest"]
    else:
        lifecycle["status"] = "cancel_requested"
    return candidate


def record_receipt(
    attempt: dict[str, Any],
    receipt: dict[str, Any],
    *,
    expected_child_attempts: list[dict[str, Any]],
    verified_attestation: Any,
    keyring_path: Path,
    decision_public_key_path: Path | None = None,
    now: datetime | None = None,
) -> dict[str, Any]:
    try:
        return receipt_module().record_receipt(
            attempt,
            receipt,
            expected_child_attempts=expected_child_attempts,
            verified_attestation=verified_attestation,
            keyring_path=keyring_path,
            decision_public_key_path=decision_public_key_path,
            now=now,
        )
    except ValueError as exc:
        raise LifecycleError(str(exc)) from None


def reconcile(
    attempt: dict[str, Any],
    *,
    decision: str,
    reviewer: str,
    grant_token: str,
    decision_public_key_path: Path,
    reconciled_at: str,
    now: datetime | None = None,
) -> dict[str, Any]:
    try:
        return receipt_module().reconcile(
            attempt,
            decision=decision,
            reviewer=reviewer,
            grant_token=grant_token,
            decision_public_key_path=decision_public_key_path,
            reconciled_at=reconciled_at,
            now=now,
        )
    except ValueError as exc:
        raise LifecycleError(str(exc)) from None


def audit_attempt(
    attempt: dict[str, Any],
    *,
    keyring_path: Path,
    decision_public_key_path: Path | None = None,
    expected_child_attempts: list[dict[str, Any]] | None = None,
) -> list[str]:
    """Replay all signed authority and reject any retained-state divergence."""
    try:
        current = _require_lifecycle(attempt)
        status = current["status"]
        retained = current.get("verified_observations")
        if not isinstance(retained, list) or len(retained) != len(current.get("observation_digests", [])):
            raise LifecycleError("runtime retained observation set is incomplete")

        cancellation = current.get("cancellation")
        cancellation_index = -1
        if cancellation is not None:
            if decision_public_key_path is None:
                raise LifecycleError("cancelled runtime audit requires the pinned decision issuer key")
            expected_fields = {
                "attempt_id", "requested_by", "reason", "requested_at",
                "after_observation_count", "grant",
            }
            if not isinstance(cancellation, dict) or set(cancellation) != expected_fields:
                raise LifecycleError("retained cancellation has the wrong shape")
            cancellation_index = _nonnegative_int(
                cancellation.get("after_observation_count"),
                "cancellation.after_observation_count",
            )
            if cancellation_index > len(retained):
                raise LifecycleError("retained cancellation observation boundary is invalid")
            grant = cancellation.get("grant")
            if not isinstance(grant, dict) or not isinstance(grant.get("token"), str):
                raise LifecycleError("retained cancellation lacks its signed decision grant")

        replay = deepcopy(attempt)
        replay["lifecycle"] = empty_lifecycle()
        verified_digests: list[str] = []
        for index, record in enumerate(retained):
            if cancellation is not None and cancellation_index == index:
                replay = request_cancellation(
                    replay,
                    requested_by=cancellation["requested_by"],
                    reason=cancellation["reason"],
                    grant_token=cancellation["grant"]["token"],
                    decision_public_key_path=decision_public_key_path,
                    requested_at=cancellation["requested_at"],
                    historical=True,
                )
            try:
                verified = gateway_module().reverify_retained_record(
                    record,
                    keyring_path=keyring_path,
                    historical=True,
                )
            except ValueError as exc:
                raise LifecycleError(str(exc)) from None
            _assert_binding(attempt, verified["claims"])
            verified_digests.append(verified["observation_digest"])
            replay = apply_verified_observation(
                replay,
                verified,
                keyring_path=keyring_path,
                historical=True,
            )
        if cancellation is not None and cancellation_index == len(retained):
            replay = request_cancellation(
                replay,
                requested_by=cancellation["requested_by"],
                reason=cancellation["reason"],
                grant_token=cancellation["grant"]["token"],
                decision_public_key_path=decision_public_key_path,
                requested_at=cancellation["requested_at"],
                historical=True,
            )

        if verified_digests != current.get("observation_digests"):
            raise LifecycleError("runtime observation digest order changed")
        derived_fields = set(empty_lifecycle()) - {"schema", "status", "receipt", "reconciliation"}
        replay_lifecycle = replay["lifecycle"]
        for field in sorted(derived_fields):
            if current.get(field) != replay_lifecycle.get(field):
                raise LifecycleError(f"retained runtime {field} differs from deterministic replay")
        expected_status = current.get("terminal_status") if status in POST_TERMINAL_STATES else status
        if replay_lifecycle.get("status") != expected_status:
            raise LifecycleError("retained runtime status differs from deterministic replay")
        if status != "admitted" and not current["observation_digests"] and cancellation is None:
            raise LifecycleError("advanced runtime lifecycle lacks trusted evidence or cancellation authority")

        if status in TERMINAL_STATES | POST_TERMINAL_STATES:
            if current.get("terminal_status") not in TERMINAL_STATES:
                raise LifecycleError("terminal runtime lacks a terminal status")
            if current.get("terminal_authority") == "provider_observation":
                _sha(current.get("terminal_observation_digest"), "terminal_observation_digest")
                if current.get("terminal_observation_digest") not in verified_digests:
                    raise LifecycleError("terminal runtime evidence is not in the signed observation set")
            elif current.get("terminal_authority") == "decision_grant":
                grant = current.get("cancellation", {}).get("grant", {})
                if current.get("terminal_decision_digest") != grant.get("grant_digest"):
                    raise LifecycleError("terminal cancellation does not bind its signed decision grant")
                if current.get("terminal_observation_digest") is not None:
                    raise LifecycleError("decision-terminal runtime cannot invent provider terminal evidence")
            else:
                raise LifecycleError("terminal runtime lacks a recognized authority")
        if current.get("observed_model") is not None:
            if current.get("observed_model") != attempt.get("requested_model"):
                raise LifecycleError("retained observed model differs from admitted model")
            if current.get("model_evidence_digest") not in verified_digests:
                raise LifecycleError("retained model evidence is not signed")
        telemetry = current.get("telemetry")
        if telemetry is not None:
            sources = telemetry.get("source_observation_digests") if isinstance(telemetry, dict) else None
            revisions = telemetry.get("provider_revisions") if isinstance(telemetry, dict) else None
            if (
                not isinstance(sources, list)
                or not set(sources).issubset(set(verified_digests))
                or not isinstance(revisions, list)
                or len(revisions) != len(set(revisions))
            ):
                raise LifecycleError("retained telemetry provenance is invalid")
        if status in POST_TERMINAL_STATES and not isinstance(current.get("receipt"), dict):
            raise LifecycleError("post-terminal runtime lacks a receipt")
        if status in POST_TERMINAL_STATES:
            receipt_errors = receipt_module().audit_retained_receipt(
                attempt,
                keyring_path=keyring_path,
                decision_public_key_path=decision_public_key_path,
                expected_child_attempts=expected_child_attempts or [],
            )
            if receipt_errors:
                raise LifecycleError(receipt_errors[0])
        if status == "reconciled" and not isinstance(current.get("reconciliation"), dict):
            raise LifecycleError("reconciled runtime lacks reconciliation")
        if status == "reconciled":
            if decision_public_key_path is None:
                raise LifecycleError("reconciled runtime audit requires the pinned decision issuer key")
            reconciliation_errors = receipt_module().audit_retained_reconciliation(
                attempt,
                decision_public_key_path=decision_public_key_path,
            )
            if reconciliation_errors:
                raise LifecycleError(reconciliation_errors[0])
    except LifecycleError as exc:
        return [str(exc)]
    return []

#!/usr/bin/env python3
"""Feature-off verifier for canonical Company OS runtime observations.

This module performs no provider calls and writes no files. It verifies one
signed observation and returns a candidate in-memory inbox for the controller
to persist under its lock.
"""

from __future__ import annotations

import base64
import binascii
import hashlib
import json
import subprocess
import tempfile
from copy import deepcopy
from datetime import datetime, timedelta, timezone
from pathlib import Path
from typing import Any


SCHEMA = "company-os.runtime-observation.v1"
KEYRING_SCHEMA = "company-os.runtime-gateway-keyring.v1"
MAX_ARTIFACT_BYTES = 1_048_576
MAX_ENVELOPE_TTL = timedelta(minutes=5)
MAX_FUTURE_SKEW = timedelta(seconds=30)
ALLOWED_EVENT_TYPES = {
    "launch",
    "running",
    "heartbeat",
    "cancel_acknowledged",
    "terminal",
}

CLAIM_FIELDS = {
    "schema",
    "gateway_key_id",
    "provider",
    "surface",
    "account",
    "provider_task_id",
    "provider_event_id",
    "event_type",
    "provider_sequence",
    "provider_timestamp",
    "gateway_received_at",
    "payload_sha256",
    "raw_artifact_path",
    "raw_artifact_sha256",
    "project_id",
    "program_version",
    "work_id",
    "cycle_id",
    "attempt_id",
    "parent_runtime_id",
    "role",
    "requested_model",
    "observed_model",
    "fabric_manifest_digest",
    "phase2_contract_digest",
    "nonce",
    "issued_at",
    "expires_at",
}

RAW_ARTIFACT_FIELDS = {
    "provider",
    "surface",
    "account",
    "provider_task_id",
    "provider_event_id",
    "event_type",
    "provider_sequence",
    "provider_timestamp",
    "observed_model",
    "payload",
}

EXPECTED_BINDINGS = {
    "project_id",
    "program_version",
    "work_id",
    "cycle_id",
    "attempt_id",
    "parent_runtime_id",
    "role",
    "requested_model",
    "provider",
    "surface",
    "account",
    "fabric_manifest_digest",
    "phase2_contract_digest",
}


class ObservationError(ValueError):
    """A rejected envelope.  Callers must not persist candidate state."""


def canonical_json(value: Any) -> str:
    return json.dumps(
        value,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=True,
        allow_nan=False,
    )


def sha256_bytes(value: bytes) -> str:
    return hashlib.sha256(value).hexdigest()


def sha256_json(value: Any) -> str:
    return sha256_bytes(canonical_json(value).encode("utf-8"))


def _reject_constant(value: str) -> None:
    raise ObservationError(f"non-finite JSON number is forbidden: {value}")


def _unique_object(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
    result: dict[str, Any] = {}
    for key, value in pairs:
        if key in result:
            raise ObservationError(f"duplicate JSON key is forbidden: {key}")
        result[key] = value
    return result


def load_json_bytes_strict(value: bytes) -> Any:
    try:
        text = value.decode("utf-8")
        return json.loads(
            text,
            object_pairs_hook=_unique_object,
            parse_constant=_reject_constant,
        )
    except (UnicodeError, json.JSONDecodeError) as exc:
        raise ObservationError(f"invalid JSON artifact: {exc}") from None


def load_json_strict(path: Path) -> Any:
    try:
        value = path.read_bytes()
    except OSError as exc:
        raise ObservationError(f"invalid JSON artifact: {exc}") from None
    return load_json_bytes_strict(value)


def parse_time(value: Any, field: str) -> datetime:
    if not isinstance(value, str) or not value:
        raise ObservationError(f"{field} must be a timezone-aware ISO-8601 string")
    try:
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError:
        raise ObservationError(f"{field} must be a timezone-aware ISO-8601 string") from None
    if parsed.tzinfo is None:
        raise ObservationError(f"{field} must be timezone-aware")
    return parsed.astimezone(timezone.utc)


def require_trimmed_string(value: Any, field: str) -> str:
    if not isinstance(value, str) or not value or value != value.strip():
        raise ObservationError(f"{field} must be a non-empty trimmed string")
    return value


def require_sha256(value: Any, field: str) -> str:
    text = require_trimmed_string(value, field)
    if len(text) != 64 or any(character not in "0123456789abcdef" for character in text):
        raise ObservationError(f"{field} must be a lowercase SHA-256 hex digest")
    return text


def resolve_project_artifact(root: Path, relative: Any) -> Path:
    relative_text = require_trimmed_string(relative, "raw_artifact_path")
    candidate_path = Path(relative_text)
    if candidate_path.is_absolute() or "\\" in relative_text:
        raise ObservationError("raw_artifact_path must be a relative project-local path")
    root = root.resolve()
    resolved = (root / candidate_path).resolve()
    try:
        resolved.relative_to(root)
    except ValueError:
        raise ObservationError("raw_artifact_path escapes the artifact root") from None
    if not resolved.is_file():
        raise ObservationError("raw observation artifact does not exist")
    if resolved.stat().st_size > MAX_ARTIFACT_BYTES:
        raise ObservationError("raw observation artifact exceeds the one-megabyte limit")
    return resolved


def load_gateway_key(
    keyring_path: Path,
    key_id: str,
    valid_at: datetime,
    *,
    allow_retired: bool = False,
) -> Path:
    keyring = load_json_strict(keyring_path.resolve())
    if not isinstance(keyring, dict) or set(keyring) != {"schema", "keys"}:
        raise ObservationError("gateway keyring has the wrong shape")
    if keyring.get("schema") != KEYRING_SCHEMA or not isinstance(keyring.get("keys"), list):
        raise ObservationError("gateway keyring schema is unsupported")
    keys: dict[str, dict[str, Any]] = {}
    for item in keyring["keys"]:
        required = {
            "key_id", "algorithm", "public_key_path", "status", "not_before", "not_after"
        }
        if not isinstance(item, dict) or set(item) != required:
            raise ObservationError("gateway keyring entry has the wrong shape")
        item_id = require_trimmed_string(item.get("key_id"), "gateway key ID")
        if item_id in keys:
            raise ObservationError("gateway keyring contains a duplicate key ID")
        keys[item_id] = item
    if key_id not in keys:
        raise ObservationError("observation gateway key ID is unknown")
    selected = keys[key_id]
    allowed_statuses = {"active", "retired"} if allow_retired else {"active"}
    if selected.get("algorithm") != "rsa-sha256" or selected.get("status") not in allowed_statuses:
        raise ObservationError("observation gateway key status or algorithm is not permitted")
    not_before = parse_time(selected.get("not_before"), "gateway key not_before")
    not_after = parse_time(selected.get("not_after"), "gateway key not_after")
    if not_before > valid_at or not_after <= valid_at or not_after <= not_before:
        raise ObservationError("observation gateway key is outside its validity window")
    public_value = require_trimmed_string(selected.get("public_key_path"), "public_key_path")
    public_path = Path(public_value)
    if not public_path.is_absolute():
        public_path = keyring_path.resolve().parent / public_path
    public_path = public_path.resolve()
    if not public_path.is_file():
        raise ObservationError("observation gateway public key does not exist")
    return public_path


def verify_signature(claims: dict[str, Any], signature_value: Any, public_key: Path) -> None:
    signature_text = require_trimmed_string(signature_value, "signature")
    try:
        signature = base64.b64decode(
            signature_text + "=" * (-len(signature_text) % 4),
            altchars=b"-_",
            validate=True,
        )
    except (binascii.Error, ValueError, TypeError):
        raise ObservationError("observation gateway signature is malformed") from None
    if not signature:
        raise ObservationError("observation gateway signature is empty")
    payload = canonical_json(claims).encode("utf-8")
    try:
        with tempfile.NamedTemporaryFile() as payload_file, tempfile.NamedTemporaryFile() as signature_file:
            payload_file.write(payload)
            payload_file.flush()
            signature_file.write(signature)
            signature_file.flush()
            result = subprocess.run(
                [
                    "openssl",
                    "dgst",
                    "-sha256",
                    "-verify",
                    str(public_key),
                    "-signature",
                    signature_file.name,
                    payload_file.name,
                ],
                capture_output=True,
                check=False,
            )
    except OSError:
        raise ObservationError("OpenSSL verification is unavailable") from None
    if result.returncode != 0:
        raise ObservationError("observation gateway signature is invalid")


def verify_observation(
    envelope: Any,
    *,
    expected_attempt: dict[str, Any],
    keyring_path: Path,
    artifact_root: Path,
    now: datetime | None = None,
    retained_verified_at: datetime | None = None,
) -> dict[str, Any]:
    now = (now or datetime.now(timezone.utc)).astimezone(timezone.utc)
    if not isinstance(envelope, dict) or set(envelope) != {"claims", "signature"}:
        raise ObservationError("observation envelope must contain exactly claims and signature")
    claims = envelope.get("claims")
    if not isinstance(claims, dict) or set(claims) != CLAIM_FIELDS:
        raise ObservationError("observation claims have the wrong shape")
    if claims.get("schema") != SCHEMA:
        raise ObservationError("observation schema is unsupported")

    text_fields = CLAIM_FIELDS - {
        "program_version", "provider_sequence", "observed_model"
    }
    for field in text_fields:
        require_trimmed_string(claims.get(field), field)
    if not isinstance(claims.get("program_version"), int) or isinstance(claims["program_version"], bool) or claims["program_version"] < 1:
        raise ObservationError("program_version must be a positive integer")
    if not isinstance(claims.get("provider_sequence"), int) or isinstance(claims["provider_sequence"], bool) or claims["provider_sequence"] < 0:
        raise ObservationError("provider_sequence must be a non-negative integer")
    observed_model = claims.get("observed_model")
    if observed_model is not None:
        require_trimmed_string(observed_model, "observed_model")
    if claims.get("event_type") not in ALLOWED_EVENT_TYPES:
        raise ObservationError("event_type is not supported")
    for field in ("payload_sha256", "raw_artifact_sha256", "fabric_manifest_digest", "phase2_contract_digest"):
        require_sha256(claims.get(field), field)

    issued_at = parse_time(claims.get("issued_at"), "issued_at")
    expires_at = parse_time(claims.get("expires_at"), "expires_at")
    provider_time = parse_time(claims.get("provider_timestamp"), "provider_timestamp")
    gateway_time = parse_time(claims.get("gateway_received_at"), "gateway_received_at")
    verification_time = retained_verified_at or now
    if issued_at > verification_time + MAX_FUTURE_SKEW:
        raise ObservationError("observation issued_at is in the future")
    if expires_at <= verification_time or expires_at <= issued_at:
        raise ObservationError("observation envelope is expired or has an invalid time window")
    if expires_at - issued_at > MAX_ENVELOPE_TTL:
        raise ObservationError("observation envelope TTL exceeds five minutes")
    if provider_time > verification_time + MAX_FUTURE_SKEW or gateway_time > verification_time + MAX_FUTURE_SKEW:
        raise ObservationError("provider or gateway timestamp is in the future")
    if gateway_time < provider_time:
        raise ObservationError("gateway receipt cannot predate the provider event")
    if gateway_time > issued_at + MAX_FUTURE_SKEW:
        raise ObservationError("gateway receipt cannot postdate envelope issuance")
    if issued_at - gateway_time > MAX_ENVELOPE_TTL:
        raise ObservationError("gateway receipt is too old for this envelope")

    if not isinstance(expected_attempt, dict) or expected_attempt.get("status") != "admitted":
        raise ObservationError("observation requires an admitted runtime attempt")
    admitted_at_value = expected_attempt.get("admitted_at")
    if admitted_at_value is not None:
        admitted_at = parse_time(admitted_at_value, "admitted_at")
        if provider_time + MAX_FUTURE_SKEW < admitted_at:
            raise ObservationError("provider observation predates runtime admission")
    missing_expected = EXPECTED_BINDINGS - set(expected_attempt)
    if missing_expected:
        raise ObservationError(f"expected attempt lacks bindings: {sorted(missing_expected)}")
    for field in EXPECTED_BINDINGS:
        if claims.get(field) != expected_attempt.get(field):
            raise ObservationError(f"observation {field} does not match the admitted attempt")
    bound_task = expected_attempt.get("provider_task_id")
    if bound_task is not None and claims.get("provider_task_id") != bound_task:
        raise ObservationError("observation provider_task_id conflicts with the bound task")

    public_key = load_gateway_key(
        keyring_path,
        require_trimmed_string(claims.get("gateway_key_id"), "gateway_key_id"),
        issued_at,
        allow_retired=retained_verified_at is not None,
    )
    verify_signature(claims, envelope.get("signature"), public_key)

    artifact_path = resolve_project_artifact(artifact_root, claims.get("raw_artifact_path"))
    try:
        artifact_bytes = artifact_path.read_bytes()
    except OSError as exc:
        raise ObservationError(f"raw observation artifact could not be read: {exc}") from None
    if len(artifact_bytes) > MAX_ARTIFACT_BYTES:
        raise ObservationError("raw observation artifact exceeds the one-megabyte limit")
    if sha256_bytes(artifact_bytes) != claims.get("raw_artifact_sha256"):
        raise ObservationError("raw observation artifact digest does not match")
    raw = load_json_bytes_strict(artifact_bytes)
    if not isinstance(raw, dict) or set(raw) != RAW_ARTIFACT_FIELDS:
        raise ObservationError("raw observation artifact has the wrong shape")
    raw_claim_map = {
        "provider": "provider",
        "surface": "surface",
        "account": "account",
        "provider_task_id": "provider_task_id",
        "provider_event_id": "provider_event_id",
        "event_type": "event_type",
        "provider_sequence": "provider_sequence",
        "provider_timestamp": "provider_timestamp",
        "observed_model": "observed_model",
    }
    for raw_field, claim_field in raw_claim_map.items():
        if raw.get(raw_field) != claims.get(claim_field):
            raise ObservationError(f"raw artifact {raw_field} does not match signed claims")
    if sha256_json(raw.get("payload")) != claims.get("payload_sha256"):
        raise ObservationError("canonical provider payload digest does not match")

    event_identity = {
        "provider": claims["provider"],
        "account": claims["account"],
        "provider_task_id": claims["provider_task_id"],
        "provider_event_id": claims["provider_event_id"],
    }
    claims_digest = sha256_json(claims)
    return {
        "event_key": sha256_json(event_identity),
        "observation_digest": claims_digest,
        "claims": deepcopy(claims),
        "signature": str(envelope["signature"]),
        "signature_digest": sha256_bytes(str(envelope["signature"]).encode("utf-8")),
        "verified_at": verification_time.isoformat(),
        "trust": "gateway_verified",
    }


def empty_inbox(*, enabled: bool = False) -> dict[str, Any]:
    return {
        "enabled": enabled,
        "status": "enabled" if enabled else "disabled",
        "attempt_binding_digest": None,
        "bound_provider_task_id": None,
        "trusted_observations": [],
        "consumed_nonces": [],
    }


def attempt_binding_digest(expected_attempt: dict[str, Any]) -> str:
    return sha256_json({
        field: expected_attempt.get(field)
        for field in sorted(EXPECTED_BINDINGS | {"provider_task_id", "status"})
    })


def audit_retained_inbox(
    state: dict[str, Any],
    *,
    expected_attempt: dict[str, Any],
    keyring_path: Path,
    artifact_root: Path,
    now: datetime,
) -> None:
    expected_state_fields = {
        "enabled", "status", "attempt_binding_digest", "bound_provider_task_id",
        "trusted_observations", "consumed_nonces"
    }
    if set(state) != expected_state_fields:
        raise ObservationError("observation inbox state has the wrong shape")
    expected_digest = attempt_binding_digest(expected_attempt)
    binding = state.get("attempt_binding_digest")
    observations = state.get("trusted_observations")
    nonces = state.get("consumed_nonces")
    if binding not in {None, expected_digest}:
        raise ObservationError("observation inbox belongs to a different admitted attempt")
    if binding is None and observations:
        raise ObservationError("retained observations lack an attempt binding")
    bound_task = state.get("bound_provider_task_id")
    if bound_task is not None:
        require_trimmed_string(bound_task, "bound_provider_task_id")
    if observations and bound_task is None:
        raise ObservationError("retained observations lack one bound provider task")
    if not observations and bound_task is not None:
        raise ObservationError("provider task is bound without a trusted observation")
    if not isinstance(observations, list) or not isinstance(nonces, list):
        raise ObservationError("observation inbox state is invalid")
    if any(not isinstance(item, dict) for item in observations) or any(
        not isinstance(item, str) or not item for item in nonces
    ):
        raise ObservationError("retained observation inbox state is invalid")

    event_keys: set[str] = set()
    observed_nonces: list[str] = []
    latest_sequence: dict[tuple[str, str, str], int] = {}
    record_fields = {
        "event_key", "observation_digest", "claims", "signature",
        "signature_digest", "verified_at", "trust",
    }
    for item in observations:
        if set(item) != record_fields or item.get("trust") != "gateway_verified":
            raise ObservationError("retained trusted observation has the wrong shape")
        verified_at = parse_time(item.get("verified_at"), "retained observation verified_at")
        if verified_at > now + MAX_FUTURE_SKEW:
            raise ObservationError("retained observation verified_at is in the future")
        rebuilt = verify_observation(
            {"claims": item.get("claims"), "signature": item.get("signature")},
            expected_attempt=expected_attempt,
            keyring_path=keyring_path,
            artifact_root=artifact_root,
            now=now,
            retained_verified_at=verified_at,
        )
        for field in ("event_key", "observation_digest", "signature_digest", "trust"):
            if rebuilt.get(field) != item.get(field):
                raise ObservationError(f"retained observation {field} failed revalidation")
        event_key = str(item["event_key"])
        if event_key in event_keys:
            raise ObservationError("retained observation event keys are not unique")
        event_keys.add(event_key)
        claims = item["claims"]
        if claims.get("provider_task_id") != bound_task:
            raise ObservationError("retained observation binds a different provider task")
        nonce = claims["nonce"]
        if nonce in observed_nonces:
            raise ObservationError("retained observation nonce is duplicated")
        observed_nonces.append(nonce)
        stream = (claims["provider"], claims["account"], claims["provider_task_id"])
        sequence = claims["provider_sequence"]
        if stream in latest_sequence and sequence <= latest_sequence[stream]:
            raise ObservationError("retained provider sequence is not monotonic")
        latest_sequence[stream] = sequence
    if nonces != observed_nonces:
        raise ObservationError("retained consumed nonces do not match trusted observations")


def verify_and_ingest(
    state: dict[str, Any],
    envelope: Any,
    *,
    expected_attempt: dict[str, Any],
    keyring_path: Path,
    artifact_root: Path,
    now: datetime | None = None,
) -> tuple[dict[str, Any], dict[str, Any]]:
    if not isinstance(state, dict):
        raise ObservationError("observation inbox state must be an object")
    if state.get("enabled") is not True or state.get("status") != "enabled":
        raise ObservationError("observation gateway is feature-off")
    now = (now or datetime.now(timezone.utc)).astimezone(timezone.utc)
    audit_retained_inbox(
        state,
        expected_attempt=expected_attempt,
        keyring_path=keyring_path,
        artifact_root=artifact_root,
        now=now,
    )
    observations = state["trusted_observations"]
    nonces = state["consumed_nonces"]

    record = verify_observation(
        envelope,
        expected_attempt=expected_attempt,
        keyring_path=keyring_path,
        artifact_root=artifact_root,
        now=now,
    )
    for existing in observations:
        if existing.get("event_key") == record["event_key"]:
            if existing.get("observation_digest") == record["observation_digest"]:
                return deepcopy(state), {
                    "status": "verified",
                    "idempotent": True,
                    "event_key": record["event_key"],
                }
            raise ObservationError("provider event key conflicts with a different observation digest")

    claims = record["claims"]
    bound_task = state.get("bound_provider_task_id")
    if bound_task is not None and claims["provider_task_id"] != bound_task:
        raise ObservationError("one runtime admission cannot bind multiple provider tasks")
    nonce = claims["nonce"]
    if nonce in nonces:
        raise ObservationError("observation gateway nonce was already consumed")
    stream = (
        claims["provider"],
        claims["account"],
        claims["provider_task_id"],
    )
    stream_sequences = [
        item.get("claims", {}).get("provider_sequence")
        for item in observations
        if (
            item.get("claims", {}).get("provider"),
            item.get("claims", {}).get("account"),
            item.get("claims", {}).get("provider_task_id"),
        ) == stream
    ]
    if stream_sequences and claims["provider_sequence"] <= max(stream_sequences):
        raise ObservationError("provider sequence is duplicate, stale, or reordered")

    candidate = deepcopy(state)
    candidate["attempt_binding_digest"] = attempt_binding_digest(expected_attempt)
    candidate["bound_provider_task_id"] = claims["provider_task_id"]
    candidate["trusted_observations"].append(record)
    candidate["consumed_nonces"].append(nonce)
    return candidate, {
        "status": "verified",
        "idempotent": False,
        "event_key": record["event_key"],
    }

#!/usr/bin/env python3
"""Immutable receipt roots and issuer-bound runtime reconciliation.

This module consumes lifecycle state that has already been advanced from
gateway-verified provider observations.  It never verifies provider facts,
mints authority, performs IO, or persists state.
"""

from __future__ import annotations

import hashlib
import importlib.util
import json
import base64
import binascii
import subprocess
import tempfile
from copy import deepcopy
from datetime import datetime, timezone
from pathlib import Path
from typing import Any


RECEIPT_SCHEMA = "company-os.runtime-receipt.v1"
RECONCILIATION_SCHEMA = "company-os.runtime-reconciliation.v1"
RECEIPT_STATUSES = {"complete", "blocked", "failed", "cancelled"}
RECONCILIATION_DECISIONS = {"accepted", "rejected", "cancelled", "blocked"}
TERMINAL_STATES = {
    "succeeded", "failed", "cancelled", "blocked_model_unavailable",
    "cancelled_before_launch",
}


class ReceiptError(ValueError):
    """A receipt or reconciliation that must not be retained."""


def canonical_json(value: Any) -> str:
    return json.dumps(
        value,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=True,
        allow_nan=False,
    )


def sha256_json(value: Any) -> str:
    return hashlib.sha256(canonical_json(value).encode("utf-8")).hexdigest()


def gateway_module() -> Any:
    module_path = Path(__file__).resolve().with_name("runtime_gateway.py")
    spec = importlib.util.spec_from_file_location("company_os_runtime_gateway_for_receipts", module_path)
    if spec is None or spec.loader is None:
        raise ReceiptError("runtime gateway verifier could not be loaded")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def lifecycle_module() -> Any:
    module_path = Path(__file__).resolve().with_name("runtime_lifecycle.py")
    spec = importlib.util.spec_from_file_location("company_os_runtime_lifecycle_for_receipts", module_path)
    if spec is None or spec.loader is None:
        raise ReceiptError("runtime lifecycle auditor could not be loaded")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def _text(value: Any, field: str) -> str:
    if not isinstance(value, str) or not value or value != value.strip():
        raise ReceiptError(f"{field} must be a non-empty trimmed string")
    return value


def _sha(value: Any, field: str) -> str:
    value = _text(value, field)
    if len(value) != 64 or any(character not in "0123456789abcdef" for character in value):
        raise ReceiptError(f"{field} must be a lowercase SHA-256 digest")
    return value


def _time(value: Any, field: str) -> str:
    value = _text(value, field)
    try:
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
    except ValueError:
        raise ReceiptError(f"{field} must be timezone-aware ISO-8601") from None
    if parsed.tzinfo is None:
        raise ReceiptError(f"{field} must be timezone-aware ISO-8601")
    return parsed.astimezone(timezone.utc).isoformat()


def runtime_identity(attempt: dict[str, Any]) -> dict[str, Any]:
    fields = (
        "attempt_id",
        "project_id",
        "manifest_identity_id",
        "program_version",
        "work_id",
        "cycle_id",
        "parent_runtime_id",
        "role",
        "requested_model",
        "provider",
        "surface",
        "account",
        "scope",
        "scope_digest",
        "budget",
        "capabilities",
        "fabric_manifest_digest",
        "phase2_contract_digest",
        "idempotency_key",
    )
    if not isinstance(attempt, dict) or any(attempt.get(field) in (None, "") for field in fields):
        raise ReceiptError("runtime identity is incomplete")
    return {field: attempt[field] for field in fields}


def runtime_identity_digest(attempt: dict[str, Any]) -> str:
    return sha256_json(runtime_identity(attempt))


def telemetry_digest(lifecycle: dict[str, Any]) -> str:
    telemetry = lifecycle.get("telemetry")
    if (
        lifecycle.get("status") == "cancelled_before_launch"
        or lifecycle.get("terminal_status") == "cancelled_before_launch"
    ) and telemetry is None:
        return sha256_json({
            "cancelled_before_launch": True,
            "terminal_decision_digest": lifecycle.get("terminal_decision_digest"),
        })
    if (
        lifecycle.get("status") == "blocked_model_unavailable"
        or lifecycle.get("terminal_status") == "blocked_model_unavailable"
    ) and telemetry is None:
        return sha256_json({
            "unavailable_reason": "model_unavailable",
            "source_observation_digest": lifecycle.get("terminal_observation_digest"),
        })
    if not isinstance(telemetry, dict):
        raise ReceiptError("receipt requires provider-derived telemetry")
    return sha256_json(telemetry)


def _audit_child_provider_proof(
    child: dict[str, Any],
    *,
    parent_attempt_id: str,
    keyring_path: Path,
) -> str:
    """Return one child receipt digest only after full provider-proof replay."""
    lifecycle = child.get("lifecycle") if isinstance(child, dict) else None
    if (
        not isinstance(lifecycle, dict)
        or child.get("role") != "worker"
        or child.get("requested_model") != "gpt-5.6-luna"
        or child.get("parent_runtime_id") != parent_attempt_id
        or lifecycle.get("status") not in {"receipt_recorded", "reconciled"}
        or lifecycle.get("terminal_status") != "succeeded"
        or lifecycle.get("observed_model") != "gpt-5.6-luna"
    ):
        raise ReceiptError("manager child is not a successful exact receipted Luna runtime")
    retained = lifecycle.get("verified_observations")
    digests = lifecycle.get("observation_digests")
    if not isinstance(retained, list) or not retained or not isinstance(digests, list):
        raise ReceiptError("manager child lacks its signed provider observation set")
    verified_digests: list[str] = []
    for record in retained:
        verified = gateway_module().reverify_retained_record(
            record,
            keyring_path=keyring_path,
            historical=True,
        )
        claims = verified["claims"]
        bindings = {
            "attempt_id": child.get("attempt_id"),
            "project_id": child.get("project_id"),
            "program_version": child.get("program_version"),
            "work_id": child.get("work_id"),
            "cycle_id": child.get("cycle_id"),
            "parent_runtime_id": parent_attempt_id,
            "role": "worker",
            "requested_model": "gpt-5.6-luna",
            "provider": child.get("provider"),
            "surface": child.get("surface"),
            "account": child.get("account"),
            "fabric_manifest_digest": child.get("fabric_manifest_digest"),
            "phase2_contract_digest": child.get("phase2_contract_digest"),
        }
        if any(claims.get(field) != value for field, value in bindings.items()):
            raise ReceiptError("manager child provider proof does not bind its exact runtime identity")
        verified_digests.append(verified["observation_digest"])
    if verified_digests != digests:
        raise ReceiptError("manager child provider observation order changed")
    if (
        lifecycle.get("model_evidence_digest") not in verified_digests
        or lifecycle.get("terminal_observation_digest") not in verified_digests
        or not isinstance(lifecycle.get("provider_task_id"), str)
        or not lifecycle["provider_task_id"]
    ):
        raise ReceiptError("manager child lacks signed model, task, or terminal provider proof")
    terminal_child = deepcopy(child)
    terminal_child["lifecycle"]["status"] = lifecycle["terminal_status"]
    terminal_child["lifecycle"]["receipt"] = None
    terminal_child["lifecycle"]["reconciliation"] = None
    lifecycle_errors = lifecycle_module().audit_attempt(
        terminal_child,
        keyring_path=keyring_path,
    )
    if lifecycle_errors:
        raise ReceiptError(f"manager child lifecycle failed replay: {lifecycle_errors[0]}")
    child_errors = audit_retained_receipt(
        child,
        keyring_path=keyring_path,
        expected_child_attempts=[],
    )
    if child_errors:
        raise ReceiptError(f"manager child receipt failed replay: {child_errors[0]}")
    child_receipt = lifecycle.get("receipt")
    if not isinstance(child_receipt, dict) or child_receipt.get("status") != "complete":
        raise ReceiptError("manager child lacks a complete immutable receipt")
    return _sha(child_receipt.get("receipt_digest"), "child receipt digest")


def _receipt_root_payload(retained: dict[str, Any]) -> dict[str, Any]:
    return {
        "runtime_identity_digest": retained["runtime_identity_digest"],
        "terminal_observation_digest": retained["terminal_observation_digest"],
        "model_evidence_digest": retained["model_evidence_digest"],
        "telemetry_digest": retained["telemetry_digest"],
        "artifact_digests": retained["artifact_digests"],
        "checks": retained["checks"],
        "child_receipt_digests": sorted(retained["child_receipt_digests"]),
        "receipt_digest": retained["receipt_digest"],
    }


def _validate_receipt_payload(
    attempt: dict[str, Any],
    receipt: dict[str, Any],
    *,
    expected_child_attempts: list[dict[str, Any]],
    verified_attestation: Any,
    keyring_path: Path,
    decision_public_key_path: Path | None,
    now: datetime | None,
) -> tuple[dict[str, Any], dict[str, Any]]:
    lifecycle = attempt.get("lifecycle") if isinstance(attempt, dict) else None
    if not isinstance(lifecycle, dict) or lifecycle.get("status") not in TERMINAL_STATES:
        raise ReceiptError("receipt requires trusted terminal state")
    if lifecycle.get("status") in {"blocked_model_unavailable", "cancelled_before_launch"}:
        if lifecycle.get("observed_model") is not None or lifecycle.get("model_evidence_digest") is not None:
            raise ReceiptError("pre-task terminal receipt cannot invent model evidence")
    elif lifecycle.get("observed_model") != attempt.get("requested_model"):
        raise ReceiptError("receipt requires verified exact model identity")
    expected_fields = {
        "schema",
        "attempt_id",
        "role",
        "status",
        "runtime_identity_digest",
        "terminal_observation_digest",
        "observed_model",
        "model_evidence_digest",
        "telemetry_digest",
        "artifact_digests",
        "checks",
        "author",
        "attestation_digest",
        "child_receipt_digests",
    }
    if not isinstance(receipt, dict) or set(receipt) != expected_fields:
        raise ReceiptError("runtime receipt has the wrong shape")
    if receipt.get("schema") != RECEIPT_SCHEMA:
        raise ReceiptError("runtime receipt schema is unsupported")
    if receipt.get("attempt_id") != attempt.get("attempt_id") or receipt.get("role") != attempt.get("role"):
        raise ReceiptError("runtime receipt identity does not bind the attempt")
    if receipt.get("status") not in RECEIPT_STATUSES:
        raise ReceiptError("runtime receipt status is invalid")
    expected_statuses = {
        "succeeded": {"complete"},
        "failed": {"failed", "blocked"},
        "cancelled": {"cancelled"},
        "blocked_model_unavailable": {"blocked"},
        "cancelled_before_launch": {"cancelled"},
    }
    if receipt.get("status") not in expected_statuses[lifecycle["status"]]:
        raise ReceiptError("runtime receipt status contradicts provider terminal state")
    if receipt.get("runtime_identity_digest") != runtime_identity_digest(attempt):
        raise ReceiptError("runtime receipt identity digest is stale")
    if receipt.get("terminal_observation_digest") != lifecycle.get("terminal_observation_digest"):
        raise ReceiptError("runtime receipt does not bind terminal provider evidence")
    if receipt.get("observed_model") != lifecycle.get("observed_model"):
        raise ReceiptError("runtime receipt observed model is stale")
    if receipt.get("model_evidence_digest") != lifecycle.get("model_evidence_digest"):
        raise ReceiptError("runtime receipt does not bind model evidence")
    if receipt.get("telemetry_digest") != telemetry_digest(lifecycle):
        raise ReceiptError("runtime receipt does not bind provider telemetry")
    author = _text(receipt.get("author"), "author")
    cancellation = lifecycle.get("cancellation")
    expected_author = (
        cancellation.get("requested_by")
        if lifecycle.get("status") == "cancelled_before_launch" and isinstance(cancellation, dict)
        else lifecycle.get("provider_task_id") or lifecycle.get("terminal_provider_event_id")
    )
    if author != expected_author:
        raise ReceiptError("runtime receipt author is not the attested provider task")
    attestation_digest = _sha(receipt.get("attestation_digest"), "attestation_digest")
    for field in ("artifact_digests", "checks", "child_receipt_digests"):
        if not isinstance(receipt.get(field), list):
            raise ReceiptError(f"receipt.{field} must be an array")
    if any(
        not isinstance(item, dict) or set(item) != {"path", "sha256"}
        for item in receipt["artifact_digests"]
    ):
        raise ReceiptError("runtime receipt artifact entries must be content-addressed")
    if receipt.get("status") == "complete" and not receipt["artifact_digests"]:
        raise ReceiptError("complete runtime receipt requires a content-addressed artifact")
    for artifact in receipt["artifact_digests"]:
        _text(artifact.get("path"), "artifact.path")
        _sha(artifact.get("sha256"), "artifact.sha256")
    if any(
        not isinstance(item, dict)
        or set(item) != {"name", "status", "evidence"}
        or item.get("status") not in {"passed", "failed"}
        for item in receipt["checks"]
    ):
        raise ReceiptError("runtime receipt check outcomes are invalid")
    if receipt.get("status") == "complete" and not receipt["checks"]:
        raise ReceiptError("complete runtime receipt requires exact check outcomes")
    for check in receipt["checks"]:
        _text(check.get("name"), "check.name")
        _text(check.get("evidence"), "check.evidence")
    if receipt.get("status") == "complete" and any(
        check.get("status") != "passed" for check in receipt["checks"]
    ):
        raise ReceiptError("complete runtime receipt cannot contain failed checks")
    if lifecycle.get("status") == "cancelled_before_launch" and (
        receipt["artifact_digests"]
        or receipt["checks"]
        or receipt["child_receipt_digests"]
    ):
        raise ReceiptError("pre-launch cancellation receipt must use the canonical empty evidence set")
    if receipt.get("status") == "complete" and lifecycle.get("budget_overage") is not None:
        raise ReceiptError("budget-overage runtime cannot produce a complete receipt")
    if not isinstance(expected_child_attempts, list):
        raise ReceiptError("expected child attempts must be an array")
    if attempt.get("role") == "manager":
        if receipt.get("status") == "complete" and len(expected_child_attempts) != 1:
            raise ReceiptError("successful runtime manager receipt requires exactly one Luna child")
        if receipt.get("status") != "complete" and len(expected_child_attempts) > 1:
            raise ReceiptError("non-successful runtime manager receipt has too many children")
        expected_children = sorted(
            _audit_child_provider_proof(
                child,
                parent_attempt_id=attempt.get("attempt_id"),
                keyring_path=keyring_path,
            )
            for child in expected_child_attempts
        )
    else:
        if expected_child_attempts:
            raise ReceiptError("worker receipt cannot receive expected child attempts")
        expected_children = []
    actual_children = sorted(_sha(value, "child_receipt_digest") for value in receipt["child_receipt_digests"])
    if len(actual_children) != len(set(actual_children)) or actual_children != expected_children:
        raise ReceiptError("runtime receipt child set is incomplete, extra, duplicated, or substituted")
    if attempt.get("role") == "worker" and actual_children:
        raise ReceiptError("workers cannot report child receipts")
    if lifecycle.get("status") == "cancelled_before_launch":
        if verified_attestation is not None:
            raise ReceiptError("pre-launch cancellation receipt cannot claim provider attestation")
        if decision_public_key_path is None or not isinstance(cancellation, dict):
            raise ReceiptError("pre-launch cancellation receipt requires the pinned decision issuer key")
        grant = _verify_cancellation_grant(
            attempt,
            cancellation,
            public_key_path=decision_public_key_path,
        )
        if attestation_digest != grant.get("grant_digest"):
            raise ReceiptError("pre-launch cancellation receipt does not bind its decision grant")
        retained_attestation = {
            "authority": "decision_grant",
            "grant_digest": grant["grant_digest"],
            "grant": grant,
        }
    else:
        retained_attestation = None
        if not isinstance(verified_attestation, dict) and callable(getattr(verified_attestation, "retained_record", None)):
            retained_attestation = verified_attestation.retained_record()
        if not isinstance(retained_attestation, dict):
            raise ReceiptError("runtime receipt requires verifier-produced cryptographic attestation")
        try:
            verified = gateway_module().reverify_receipt_attestation(
                retained_attestation,
                keyring_path=keyring_path,
                now=now,
                historical=False,
            )
        except ValueError as exc:
            raise ReceiptError(str(exc)) from None
        retained_attestation = verified.retained_record()
        claims = retained_attestation.get("claims")
        if not isinstance(claims, dict):
            raise ReceiptError("runtime receipt attestation lacks verified claims")
        attested_payload = {key: value for key, value in receipt.items() if key != "attestation_digest"}
        expected_attestation = {
            "action": "attest-runtime-receipt",
            "attempt_id": attempt.get("attempt_id"),
            "provider_task_id": lifecycle.get("provider_task_id"),
            "receipt_payload_hash": sha256_json(attested_payload),
        }
        if any(claims.get(key) != value for key, value in expected_attestation.items()):
            raise ReceiptError("runtime receipt attestation does not bind the exact provider task and content")
        if retained_attestation.get("attestation_digest") != attestation_digest:
            raise ReceiptError("runtime receipt attestation digest does not match verified evidence")
    return deepcopy(receipt), retained_attestation


def record_receipt(
    attempt: dict[str, Any],
    receipt: dict[str, Any],
    *,
    expected_child_attempts: list[dict[str, Any]],
    verified_attestation: Any,
    keyring_path: Path,
    decision_public_key_path: Path | None = None,
    now: datetime | None = None,
) -> dict[str, Any]:
    candidate = deepcopy(attempt)
    lifecycle = candidate.get("lifecycle")
    if not isinstance(lifecycle, dict):
        raise ReceiptError("runtime lifecycle is missing")
    existing = lifecycle.get("receipt")
    if isinstance(existing, dict):
        accepted_payload = {
            key: value
            for key, value in existing.items()
            if key not in {"receipt_digest", "receipt_root", "attestation_record"}
        }
        if accepted_payload == receipt:
            audit_errors = audit_retained_receipt(
                candidate,
                keyring_path=keyring_path,
                decision_public_key_path=decision_public_key_path,
                expected_child_attempts=expected_child_attempts,
            )
            if audit_errors:
                raise ReceiptError(audit_errors[0])
            return candidate
        raise ReceiptError("runtime receipt is immutable")
    retained, retained_attestation = _validate_receipt_payload(
        candidate,
        receipt,
        expected_child_attempts=expected_child_attempts,
        verified_attestation=verified_attestation,
        keyring_path=keyring_path,
        decision_public_key_path=decision_public_key_path,
        now=now,
    )
    retained["receipt_digest"] = sha256_json(receipt)
    retained["receipt_root"] = sha256_json(_receipt_root_payload(retained))
    retained["attestation_record"] = retained_attestation
    lifecycle["receipt"] = retained
    lifecycle["status"] = "receipt_recorded"
    return candidate


def reconciliation_payload(
    attempt: dict[str, Any],
    *,
    decision: str,
    reviewer: str,
    reconciled_at: str,
) -> dict[str, Any]:
    lifecycle = attempt.get("lifecycle") if isinstance(attempt, dict) else None
    receipt = lifecycle.get("receipt") if isinstance(lifecycle, dict) else None
    if not isinstance(receipt, dict):
        raise ReceiptError("reconciliation requires a complete runtime receipt")
    if decision not in RECONCILIATION_DECISIONS:
        raise ReceiptError("runtime reconciliation decision is invalid")
    terminal_authority = lifecycle.get("terminal_authority")
    terminal_observation_digest = lifecycle.get("terminal_observation_digest")
    terminal_decision_digest = lifecycle.get("terminal_decision_digest")
    if terminal_authority == "provider_observation":
        _sha(terminal_observation_digest, "terminal_observation_digest")
    elif terminal_authority == "decision_grant":
        _sha(terminal_decision_digest, "terminal_decision_digest")
    else:
        raise ReceiptError("reconciliation requires a recognized terminal authority")
    return {
        "schema": RECONCILIATION_SCHEMA,
        "attempt_id": attempt.get("attempt_id"),
        "decision": decision,
        "reviewer": _text(reviewer, "reviewer"),
        "receipt_root": _sha(receipt.get("receipt_root"), "receipt_root"),
        "terminal_authority": terminal_authority,
        "terminal_observation_digest": terminal_observation_digest,
        "terminal_decision_digest": terminal_decision_digest,
        "telemetry_digest": _sha(receipt.get("telemetry_digest"), "telemetry_digest"),
        "reconciled_at": _time(reconciled_at, "reconciled_at"),
    }


def _verify_decision_grant(
    token: Any,
    *,
    public_key_path: Path,
    expected_claims: dict[str, Any],
    now: datetime,
    historical: bool = False,
) -> dict[str, Any]:
    if not isinstance(token, str) or not token:
        raise ReceiptError("reconciliation decision grant is required")
    try:
        encoded, encoded_signature = token.split(".", 1)
        payload_bytes = base64.urlsafe_b64decode(encoded + "=" * (-len(encoded) % 4))
        claims = json.loads(payload_bytes.decode("utf-8"))
        signature = base64.urlsafe_b64decode(encoded_signature + "=" * (-len(encoded_signature) % 4))
    except (ValueError, TypeError, UnicodeError, json.JSONDecodeError, binascii.Error):
        raise ReceiptError("reconciliation decision grant is malformed") from None
    if not isinstance(claims, dict) or any(claims.get(key) != value for key, value in expected_claims.items()):
        raise ReceiptError("reconciliation decision grant does not bind the exact decision")
    _text(claims.get("nonce"), "decision grant nonce")
    expiry = datetime.fromisoformat(_time(claims.get("expiry"), "decision grant expiry"))
    if not historical and expiry <= now.astimezone(timezone.utc):
        raise ReceiptError("reconciliation decision grant is expired")
    try:
        public_key_bytes = public_key_path.resolve().read_bytes()
        with tempfile.NamedTemporaryFile() as payload_file, tempfile.NamedTemporaryFile() as signature_file, tempfile.NamedTemporaryFile() as public_file:
            payload_file.write(encoded.encode("ascii")); payload_file.flush()
            signature_file.write(signature); signature_file.flush()
            public_file.write(public_key_bytes); public_file.flush()
            result = subprocess.run(
                ["openssl", "dgst", "-sha256", "-verify", public_file.name, "-signature", signature_file.name, payload_file.name],
                capture_output=True,
                check=False,
            )
    except (OSError, UnicodeError):
        raise ReceiptError("reconciliation decision grant could not be verified") from None
    if result.returncode != 0:
        raise ReceiptError("reconciliation decision grant signature is invalid")
    public_key_pem = public_key_bytes.decode("utf-8")
    return {
        "token": token,
        "grant_digest": hashlib.sha256(token.encode()).hexdigest(),
        "claims": claims,
        "verification_key_pem": public_key_pem,
        "verification_key_sha256": hashlib.sha256(public_key_bytes).hexdigest(),
    }


def _verify_cancellation_grant(
    attempt: dict[str, Any],
    cancellation: dict[str, Any],
    *,
    public_key_path: Path,
) -> dict[str, Any]:
    request_payload = {
        key: cancellation.get(key)
        for key in (
            "attempt_id", "requested_by", "reason", "requested_at",
            "after_observation_count",
        )
    }
    expected_claims = {
        "actor": cancellation.get("requested_by"),
        "action": "cancel-runtime",
        "resource": f"runtime:{attempt.get('attempt_id')}",
        "project_id": attempt.get("project_id"),
        "program_version": attempt.get("program_version"),
        "work_id": attempt.get("work_id"),
        "cycle_id": attempt.get("cycle_id"),
        "dimension": "runtime-cancellation",
        "decision": "cancelled",
        "payload_hash": sha256_json(request_payload),
    }
    retained_grant = cancellation.get("grant")
    if not isinstance(retained_grant, dict):
        raise ReceiptError("retained cancellation decision grant is missing")
    verified = _verify_decision_grant(
        retained_grant.get("token"),
        public_key_path=public_key_path,
        expected_claims=expected_claims,
        now=datetime.now(timezone.utc),
        historical=True,
    )
    if verified != retained_grant:
        raise ReceiptError("retained cancellation decision grant changed")
    return verified


def reconcile(
    attempt: dict[str, Any],
    *,
    decision: str,
    reviewer: str,
    grant_token: str,
    decision_public_key_path: Path,
    reconciled_at: str,
    now: datetime | None = None,
) -> dict[str, Any]:
    candidate = deepcopy(attempt)
    lifecycle = candidate.get("lifecycle")
    if not isinstance(lifecycle, dict):
        raise ReceiptError("runtime lifecycle is missing")
    normalized_time = _time(reconciled_at, "reconciled_at")
    payload = reconciliation_payload(
        candidate, decision=decision, reviewer=reviewer, reconciled_at=normalized_time
    )
    payload_hash = sha256_json(payload)
    receipt = lifecycle.get("receipt")
    if not isinstance(receipt, dict):
        raise ReceiptError("reconciliation requires a complete runtime receipt")
    if decision == "accepted" and (
        lifecycle.get("terminal_status") != "succeeded"
        or receipt.get("status") != "complete"
        or any(check.get("status") != "passed" for check in receipt.get("checks", []))
    ):
        raise ReceiptError("accepted reconciliation requires successful provider state and passed checks")
    if decision == "cancelled" and (
        lifecycle.get("terminal_status") not in {"cancelled", "cancelled_before_launch"}
        or receipt.get("status") != "cancelled"
    ):
        raise ReceiptError("cancelled reconciliation requires cancelled provider and receipt state")
    if decision == "blocked" and receipt.get("status") != "blocked":
        raise ReceiptError("blocked reconciliation requires a blocked receipt")
    existing = lifecycle.get("reconciliation")
    if existing is not None:
        expected_existing = payload | {"grant": existing.get("grant")}
        expected_existing["reconciliation_digest"] = sha256_json(expected_existing)
        if (
            existing == expected_existing
            and isinstance(existing.get("grant"), dict)
            and existing["grant"].get("token") == grant_token
            and not audit_retained_reconciliation(
                candidate,
                decision_public_key_path=decision_public_key_path,
            )
        ):
            return candidate
        raise ReceiptError("runtime reconciliation is immutable")
    expected_claims = {
        "actor": reviewer,
        "action": "reconcile-runtime",
        "resource": f"runtime:{candidate.get('attempt_id')}",
        "project_id": candidate.get("project_id"),
        "program_version": candidate.get("program_version"),
        "work_id": candidate.get("work_id"),
        "cycle_id": candidate.get("cycle_id"),
        "dimension": "runtime-reconciliation",
        "decision": decision,
        "payload_hash": payload_hash,
    }
    grant = _verify_decision_grant(
        grant_token,
        public_key_path=decision_public_key_path,
        expected_claims=expected_claims,
        now=(now or datetime.now(timezone.utc)).astimezone(timezone.utc),
    )
    value = payload | {
        "grant": grant,
    }
    value["reconciliation_digest"] = sha256_json(value)
    if lifecycle.get("status") != "receipt_recorded":
        raise ReceiptError("reconciliation requires receipt_recorded state")
    lifecycle["reconciliation"] = value
    lifecycle["status"] = "reconciled"
    return candidate


def audit_retained_receipt(
    attempt: dict[str, Any],
    *,
    keyring_path: Path,
    decision_public_key_path: Path | None = None,
    expected_child_attempts: list[dict[str, Any]],
) -> list[str]:
    """Recompute receipt roots and replay receipt attribution after restart."""
    try:
        lifecycle = attempt.get("lifecycle") if isinstance(attempt, dict) else None
        receipt = lifecycle.get("receipt") if isinstance(lifecycle, dict) else None
        if not isinstance(receipt, dict):
            raise ReceiptError("retained runtime receipt is missing")
        base = {
            key: value for key, value in receipt.items()
            if key not in {"receipt_digest", "receipt_root", "attestation_record"}
        }
        if receipt.get("receipt_digest") != sha256_json(base):
            raise ReceiptError("retained runtime receipt digest is invalid")
        if receipt.get("receipt_root") != sha256_json(_receipt_root_payload(receipt)):
            raise ReceiptError("retained runtime receipt root is invalid")
        if receipt.get("runtime_identity_digest") != runtime_identity_digest(attempt):
            raise ReceiptError("retained runtime receipt identity changed")
        if receipt.get("terminal_observation_digest") != lifecycle.get("terminal_observation_digest"):
            raise ReceiptError("retained runtime receipt terminal evidence changed")
        if receipt.get("telemetry_digest") != telemetry_digest(lifecycle):
            raise ReceiptError("retained runtime receipt telemetry changed")
        attestation_record = receipt.get("attestation_record")
        if lifecycle.get("terminal_status") == "cancelled_before_launch":
            if decision_public_key_path is None:
                raise ReceiptError("pre-launch cancellation receipt audit requires the pinned decision issuer key")
            cancellation = lifecycle.get("cancellation")
            if not isinstance(cancellation, dict):
                raise ReceiptError("pre-launch cancellation receipt lost its decision")
            verified_grant = _verify_cancellation_grant(
                attempt,
                cancellation,
                public_key_path=decision_public_key_path,
            )
            expected_attestation = {
                "authority": "decision_grant",
                "grant_digest": verified_grant["grant_digest"],
                "grant": verified_grant,
            }
            expected_base = {
                "schema": RECEIPT_SCHEMA,
                "attempt_id": attempt.get("attempt_id"),
                "role": attempt.get("role"),
                "status": "cancelled",
                "runtime_identity_digest": runtime_identity_digest(attempt),
                "terminal_observation_digest": lifecycle.get("terminal_observation_digest"),
                "observed_model": lifecycle.get("observed_model"),
                "model_evidence_digest": lifecycle.get("model_evidence_digest"),
                "telemetry_digest": telemetry_digest(lifecycle),
                "artifact_digests": [],
                "checks": [],
                "author": cancellation.get("requested_by"),
                "attestation_digest": verified_grant["grant_digest"],
                "child_receipt_digests": [],
            }
            if (
                attestation_record != expected_attestation
                or base.get("attestation_digest") != verified_grant["grant_digest"]
                or base != expected_base
            ):
                raise ReceiptError("retained pre-launch cancellation receipt changed from canonical decision evidence")
        else:
            verified = gateway_module().reverify_receipt_attestation(
                attestation_record,
                keyring_path=keyring_path,
                historical=True,
            )
            claims = verified["claims"]
            if (
                claims.get("attempt_id") != attempt.get("attempt_id")
                or claims.get("provider_task_id") != lifecycle.get("provider_task_id")
                or claims.get("receipt_payload_hash") != sha256_json(
                    {key: value for key, value in base.items() if key != "attestation_digest"}
                )
                or verified["attestation_digest"] != base.get("attestation_digest")
            ):
                raise ReceiptError("retained receipt attestation binding changed")
        if attempt.get("role") == "manager":
            if base.get("status") == "complete" and len(expected_child_attempts) != 1:
                raise ReceiptError("retained successful manager receipt lacks its exact Luna child")
            if base.get("status") != "complete" and len(expected_child_attempts) > 1:
                raise ReceiptError("retained non-successful manager receipt has too many children")
            expected_children = sorted(
                _audit_child_provider_proof(
                    child,
                    parent_attempt_id=attempt.get("attempt_id"),
                    keyring_path=keyring_path,
                )
                for child in expected_child_attempts
            )
            if base.get("child_receipt_digests") != expected_children:
                raise ReceiptError("retained manager child receipt binding changed")
        elif expected_child_attempts or base.get("child_receipt_digests"):
            raise ReceiptError("retained worker receipt cannot have children")
    except (ReceiptError, ValueError) as exc:
        return [str(exc)]
    return []


def audit_retained_reconciliation(
    attempt: dict[str, Any],
    *,
    decision_public_key_path: Path,
) -> list[str]:
    """Recompute the signed master decision and immutable digest after restart."""
    try:
        lifecycle = attempt.get("lifecycle") if isinstance(attempt, dict) else None
        value = lifecycle.get("reconciliation") if isinstance(lifecycle, dict) else None
        if not isinstance(value, dict):
            raise ReceiptError("retained runtime reconciliation is missing")
        digest = value.get("reconciliation_digest")
        if digest != sha256_json({key: item for key, item in value.items() if key != "reconciliation_digest"}):
            raise ReceiptError("retained runtime reconciliation digest is invalid")
        grant = value.get("grant")
        if not isinstance(grant, dict):
            raise ReceiptError("retained runtime reconciliation grant is missing")
        payload = {key: item for key, item in value.items() if key not in {"grant", "reconciliation_digest"}}
        expected_payload = reconciliation_payload(
            attempt,
            decision=payload.get("decision"),
            reviewer=payload.get("reviewer"),
            reconciled_at=payload.get("reconciled_at"),
        )
        if payload != expected_payload:
            raise ReceiptError("retained reconciliation payload changed from runtime state")
        expected_claims = {
            "actor": payload.get("reviewer"),
            "action": "reconcile-runtime",
            "resource": f"runtime:{attempt.get('attempt_id')}",
            "project_id": attempt.get("project_id"),
            "program_version": attempt.get("program_version"),
            "work_id": attempt.get("work_id"),
            "cycle_id": attempt.get("cycle_id"),
            "dimension": "runtime-reconciliation",
            "decision": payload.get("decision"),
            "payload_hash": sha256_json(payload),
        }
        pem = grant.get("verification_key_pem")
        trusted_public = decision_public_key_path.resolve().read_bytes()
        if (
            not isinstance(pem, str)
            or grant.get("verification_key_sha256") != hashlib.sha256(pem.encode()).hexdigest()
            or hashlib.sha256(trusted_public).hexdigest() != grant.get("verification_key_sha256")
        ):
            raise ReceiptError("retained decision verification key changed")
        verified = _verify_decision_grant(
            grant.get("token"),
            public_key_path=decision_public_key_path,
            expected_claims=expected_claims,
            now=datetime.now(timezone.utc),
            historical=True,
        )
        if verified.get("grant_digest") != grant.get("grant_digest"):
            raise ReceiptError("retained decision grant digest changed")
    except (ReceiptError, ValueError, OSError) as exc:
        return [str(exc)]
    return []

#!/usr/bin/env python3
from __future__ import annotations

import argparse
import hashlib
import json
from pathlib import Path
from typing import Any, Mapping

SCHEMA = "company-os.engineering-execution-contract.v1"
LEVELS = {"master": 0, "mid": 1, "lower": 2, "worker": 3}
BOOLEAN_GATES = (
    "loom_delivery_loop",
    "durable_state",
    "exclusive_write_ownership",
    "skill_resolution_required",
    "runtime_observation_required",
    "independent_review_required",
    "original_objective_acceptance_required",
)
SECURITY = {"not_applicable": 0, "static": 1, "authorized_pentest": 2}

class ContractError(ValueError):
    pass

def canonical(value: Any) -> bytes:
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False).encode()

def digest(value: Any) -> str:
    return hashlib.sha256(canonical(value)).hexdigest()

def text(value: Any, label: str) -> str:
    if not isinstance(value, str) or not value.strip():
        raise ContractError(f"{label} must be nonempty")
    return value

def seal(value: Mapping[str, Any]) -> dict[str, Any]:
    out = dict(value)
    out["contract_sha256"] = None
    out["contract_sha256"] = digest(out)
    return out

def verify(raw: Mapping[str, Any]) -> dict[str, Any]:
    value = dict(raw)
    if value.get("$schema") != SCHEMA:
        raise ContractError("engineering contract schema is invalid")
    level = value.get("manager_level")
    if level not in LEVELS:
        raise ContractError("manager_level is invalid")
    text(value.get("contract_id"), "contract_id")
    text(value.get("objective_id"), "objective_id")
    rigor = value.get("engineering_rigor")
    if not isinstance(rigor, int) or isinstance(rigor, bool) or not 1 <= rigor <= 10:
        raise ContractError("engineering_rigor must be 1..10")
    for gate in BOOLEAN_GATES:
        if value.get(gate) is not True:
            raise ContractError(f"mandatory gate {gate} must be true")
    if value.get("security_verification") not in SECURITY:
        raise ContractError("security_verification is invalid")
    skills = value.get("required_skills")
    if not isinstance(skills, list) or not all(isinstance(x, str) and x.strip() for x in skills):
        raise ContractError("required_skills must be strings")
    scopes = value.get("write_scopes")
    if not isinstance(scopes, list) or not all(isinstance(x, str) and x.strip() for x in scopes):
        raise ContractError("write_scopes must be strings")
    observed = value.get("contract_sha256")
    if not isinstance(observed, str) or len(observed) != 64:
        raise ContractError("contract_sha256 is invalid")
    if digest({**value, "contract_sha256": None}) != observed:
        raise ContractError("engineering contract digest changed")
    return value

def derive(parent_raw: Mapping[str, Any], child: Mapping[str, Any]) -> dict[str, Any]:
    parent = verify(parent_raw)
    level = child.get("manager_level")
    if level not in LEVELS or LEVELS[level] <= LEVELS[parent["manager_level"]]:
        raise ContractError("child level must be below parent level")
    if child.get("objective_id") != parent["objective_id"]:
        raise ContractError("child objective cannot drift")
    rigor = child.get("engineering_rigor", parent["engineering_rigor"])
    if rigor < parent["engineering_rigor"]:
        raise ContractError("child cannot weaken engineering rigor")
    security = child.get("security_verification", parent["security_verification"])
    if SECURITY.get(security, -1) < SECURITY[parent["security_verification"]]:
        raise ContractError("child cannot weaken security verification")
    required_skills = sorted(set(parent["required_skills"]) | set(child.get("required_skills", [])))
    out = {
        "$schema": SCHEMA,
        "contract_id": text(child.get("contract_id"), "contract_id"),
        "objective_id": parent["objective_id"],
        "manager_level": level,
        "parent_contract_sha256": parent["contract_sha256"],
        "engineering_rigor": rigor,
        "security_verification": security,
        "required_skills": required_skills,
        "write_scopes": list(child.get("write_scopes", [])),
    }
    for gate in BOOLEAN_GATES:
        requested = child.get(gate, parent[gate])
        if parent[gate] is True and requested is not True:
            raise ContractError(f"child cannot weaken {gate}")
        out[gate] = requested
    return seal(out)

def root(request: Mapping[str, Any]) -> dict[str, Any]:
    value = {
        "$schema": SCHEMA,
        "contract_id": text(request.get("contract_id"), "contract_id"),
        "objective_id": text(request.get("objective_id"), "objective_id"),
        "manager_level": "master",
        "parent_contract_sha256": None,
        "engineering_rigor": int(request.get("engineering_rigor", 8)),
        "security_verification": request.get("security_verification", "static"),
        "required_skills": sorted(set(request.get("required_skills", []))),
        "write_scopes": list(request.get("write_scopes", [])),
    }
    for gate in BOOLEAN_GATES:
        value[gate] = True
    return seal(value)

def assert_nonoverlap(contracts: list[Mapping[str, Any]]) -> None:
    owners: dict[str, str] = {}
    for raw in contracts:
        contract = verify(raw)
        for scope in contract["write_scopes"]:
            if scope in owners:
                raise ContractError(f"write scope {scope} has multiple writers: {owners[scope]} and {contract['contract_id']}")
            owners[scope] = contract["contract_id"]

def main() -> int:
    parser = argparse.ArgumentParser()
    sub = parser.add_subparsers(dest="cmd", required=True)
    make = sub.add_parser("root"); make.add_argument("--request", type=Path, required=True); make.add_argument("--output", type=Path, required=True)
    child = sub.add_parser("derive"); child.add_argument("--parent", type=Path, required=True); child.add_argument("--request", type=Path, required=True); child.add_argument("--output", type=Path, required=True)
    check = sub.add_parser("verify"); check.add_argument("--contract", type=Path, required=True)
    args = parser.parse_args()
    try:
        read = lambda p: json.loads(p.read_text())
        if args.cmd == "root": result = root(read(args.request)); args.output.write_text(json.dumps(result, indent=2, sort_keys=True) + "\n")
        elif args.cmd == "derive": result = derive(read(args.parent), read(args.request)); args.output.write_text(json.dumps(result, indent=2, sort_keys=True) + "\n")
        else: result = verify(read(args.contract))
        print(json.dumps({"ok": True, "contract_sha256": result["contract_sha256"]}, sort_keys=True)); return 0
    except (ContractError, OSError, json.JSONDecodeError, ValueError) as exc:
        print(json.dumps({"ok": False, "error": str(exc)}, sort_keys=True)); return 2

if __name__ == "__main__":
    raise SystemExit(main())

{
  "$schema": "company-os.evaluator-execution-request.v1",
  "run_id": "gameplay-evaluation-001",
  "objective_id": "viral-game",
  "evaluator_id": "gameplay",
  "evaluator_contract_path": "outcome/evaluator-contract.json",
  "adapter_registry_path": "outcome/adapter-registry.json",
  "benchmark_contract_path": "outcome/benchmark-contract.json",
  "executor_actor_id": "independent-gameplay-reviewer",
  "production_actor_ids": [
    "game-builder",
    "game-manager"
  ],
  "artifacts": [
    {
      "artifact_id": "candidate-build",
      "artifact_class_id": "playable-build",
      "path": "builds/candidate/index.html",
      "sha256": "REPLACE_WITH_ARTIFACT_SHA256"
    }
  ],
  "arguments": {}
}

#!/usr/bin/env python3
"""Execute a content addressed outcome evaluator through a local adapter."""

from __future__ import annotations

import argparse
import hashlib
import json
import math
import os
import subprocess
import sys
from pathlib import Path, PurePosixPath
from typing import Any, Mapping, Sequence

REQUEST_SCHEMA = "company-os.evaluator-execution-request.v1"
CONTRACT_SCHEMA = "company-os.evaluator-runtime-contract.v1"
REGISTRY_SCHEMA = "company-os.evaluator-adapter-registry.v1"
BENCHMARK_SCHEMA = "company-os.benchmark-contract.v1"
ADAPTER_INPUT_SCHEMA = "company-os.evaluator-adapter-input.v1"
ADAPTER_OUTPUT_SCHEMA = "company-os.evaluator-adapter-output.v1"
RECEIPT_SCHEMA = "company-os.evaluator-execution-receipt.v1"

MAX_TIMEOUT_SECONDS = 3600
MAX_OUTPUT_BYTES = 10 * 1024 * 1024
DEFAULT_OUTPUT_BYTES = 1024 * 1024
SAFE_ENVIRONMENT_KEYS = (
    "SYSTEMROOT",
    "WINDIR",
    "COMSPEC",
    "TMP",
    "TEMP",
    "TMPDIR",
    "HOME",
)
FINDING_SEVERITIES = {"info", "warning", "error", "critical"}


class EvaluatorExecutionError(ValueError):
    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(f"{code}: {message}")


def canonical_bytes(value: Any) -> bytes:
    try:
        return json.dumps(
            value,
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=False,
            allow_nan=False,
        ).encode("utf-8")
    except (TypeError, ValueError) as exc:
        raise EvaluatorExecutionError(
            "E_CANONICAL", f"value is not canonical JSON: {exc}"
        ) from exc


def digest(value: Any) -> str:
    return hashlib.sha256(canonical_bytes(value)).hexdigest()


def bytes_digest(value: bytes) -> str:
    return hashlib.sha256(value).hexdigest()


def file_digest(path: Path) -> str:
    value = hashlib.sha256()
    with path.open("rb") as handle:
        for chunk in iter(lambda: handle.read(1024 * 1024), b""):
            value.update(chunk)
    return value.hexdigest()


def _reject_constant(value: str) -> None:
    raise EvaluatorExecutionError(
        "E_JSON", f"non finite JSON value is forbidden: {value}"
    )


def _object(pairs: list[tuple[str, Any]]) -> dict[str, Any]:
    result: dict[str, Any] = {}
    for key, value in pairs:
        if key in result:
            raise EvaluatorExecutionError(
                "E_JSON", f"duplicate JSON key is forbidden: {key}"
            )
        result[key] = value
    return result


def parse_json_bytes(value: bytes, label: str) -> Any:
    try:
        return json.loads(
            value.decode("utf-8"),
            object_pairs_hook=_object,
            parse_constant=_reject_constant,
        )
    except EvaluatorExecutionError:
        raise
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise EvaluatorExecutionError("E_JSON", f"invalid JSON in {label}") from exc


def read_json(path: Path, label: str) -> Any:
    try:
        return parse_json_bytes(path.read_bytes(), label)
    except OSError as exc:
        raise EvaluatorExecutionError(
            "E_READ", f"cannot read {label}: {path}"
        ) from exc


def require_object(value: Any, label: str) -> Mapping[str, Any]:
    if not isinstance(value, Mapping):
        raise EvaluatorExecutionError("E_SCHEMA", f"{label} must be an object")
    return value


def require_text(value: Any, label: str) -> str:
    if not isinstance(value, str) or not value.strip():
        raise EvaluatorExecutionError(
            "E_SCHEMA", f"{label} must be a nonempty string"
        )
    if "\x00" in value:
        raise EvaluatorExecutionError("E_SCHEMA", f"{label} contains a null byte")
    return value


def require_sha256(value: Any, label: str) -> str:
    text = require_text(value, label)
    if len(text) != 64 or any(character not in "0123456789abcdef" for character in text):
        raise EvaluatorExecutionError(
            "E_SCHEMA", f"{label} must be a lowercase sha256"
        )
    return text


def require_strings(value: Any, label: str, *, nonempty: bool = False) -> list[str]:
    if not isinstance(value, list):
        raise EvaluatorExecutionError("E_SCHEMA", f"{label} must be an array")
    result = [require_text(item, f"{label}[]") for item in value]
    if nonempty and not result:
        raise EvaluatorExecutionError("E_SCHEMA", f"{label} must not be empty")
    if len(result) != len(set(result)):
        raise EvaluatorExecutionError("E_DUPLICATE", f"{label} contains duplicates")
    return sorted(result)


def require_string_list(value: Any, label: str) -> list[str]:
    if not isinstance(value, list):
        raise EvaluatorExecutionError("E_SCHEMA", f"{label} must be an array")
    return [require_text(item, f"{label}[]") for item in value]


def require_exact_keys(value: Mapping[str, Any], expected: set[str], label: str) -> None:
    observed = set(value)
    if observed != expected:
        missing = sorted(expected - observed)
        extra = sorted(observed - expected)
        raise EvaluatorExecutionError(
            "E_SCHEMA",
            f"{label} keys are invalid; missing={missing} extra={extra}",
        )


def verify_self_digest(value: Mapping[str, Any], field: str, label: str) -> str:
    observed = require_sha256(value.get(field), f"{label}.{field}")
    candidate = dict(value)
    candidate[field] = None
    if digest(candidate) != observed:
        raise EvaluatorExecutionError(
            "E_DIGEST", f"{label}.{field} does not match exact content"
        )
    return observed


def safe_file(project_root: Path, value: Any, label: str) -> tuple[Path, str]:
    raw = require_text(value, label)
    if "\\" in raw:
        raise EvaluatorExecutionError(
            "E_PATH", f"{label} must use slash separated project paths"
        )
    pure = PurePosixPath(raw)
    if pure.is_absolute() or not pure.parts or any(part in {"", ".", ".."} for part in pure.parts):
        raise EvaluatorExecutionError(
            "E_PATH", f"{label} must be a safe project relative path"
        )
    root = project_root.resolve()
    current = root
    for part in pure.parts:
        current = current / part
        if current.is_symlink():
            raise EvaluatorExecutionError(
                "E_PATH", f"{label} may not traverse a symlink"
            )
    try:
        resolved = (root / Path(*pure.parts)).resolve(strict=True)
    except OSError as exc:
        raise EvaluatorExecutionError(
            "E_PATH", f"{label} does not resolve to an existing file"
        ) from exc
    if resolved != root and root not in resolved.parents:
        raise EvaluatorExecutionError("E_PATH", f"{label} escapes the project root")
    if not resolved.is_file() or resolved.is_symlink():
        raise EvaluatorExecutionError(
            "E_PATH", f"{label} must reference a regular file"
        )
    return resolved, pure.as_posix()


def load_bound_json(
    project_root: Path,
    path_value: Any,
    label: str,
    schema: str,
    digest_field: str,
) -> tuple[dict[str, Any], dict[str, Any]]:
    path, relative = safe_file(project_root, path_value, f"{label}_path")
    value = dict(require_object(read_json(path, label), label))
    if value.get("$schema") != schema:
        raise EvaluatorExecutionError(
            "E_SCHEMA", f"{label} must use schema {schema}"
        )
    content_digest = verify_self_digest(value, digest_field, label)
    return value, {
        "path": relative,
        "file_sha256": file_digest(path),
        digest_field: content_digest,
    }


def find_evaluator(contract: Mapping[str, Any], evaluator_id: str) -> dict[str, Any]:
    records = contract.get("evaluators")
    if not isinstance(records, list):
        raise EvaluatorExecutionError(
            "E_SCHEMA", "evaluator contract evaluators must be an array"
        )
    matches = [item for item in records if isinstance(item, Mapping) and item.get("evaluator_id") == evaluator_id]
    if len(matches) != 1:
        raise EvaluatorExecutionError(
            "E_EVALUATOR", f"evaluator contract must contain exactly one {evaluator_id}"
        )
    evaluator = dict(matches[0])
    if evaluator.get("research_only") is not False:
        raise EvaluatorExecutionError(
            "E_EVALUATOR", f"evaluator {evaluator_id} is research only"
        )
    if evaluator.get("independent_role") is not True:
        raise EvaluatorExecutionError(
            "E_AUTHORITY", f"evaluator {evaluator_id} is not independent"
        )
    require_text(evaluator.get("adapter_locator"), "evaluator.adapter_locator")
    require_strings(
        evaluator.get("artifact_classes"),
        "evaluator.artifact_classes",
        nonempty=True,
    )
    require_strings(
        evaluator.get("produces_evidence"),
        "evaluator.produces_evidence",
        nonempty=True,
    )
    require_strings(
        evaluator.get("score_dimensions", []),
        "evaluator.score_dimensions",
    )
    return evaluator


def validate_registry(registry: Mapping[str, Any]) -> str:
    if registry.get("$schema") != REGISTRY_SCHEMA:
        raise EvaluatorExecutionError(
            "E_SCHEMA", f"adapter registry must use schema {REGISTRY_SCHEMA}"
        )
    registry_digest = verify_self_digest(registry, "registry_sha256", "adapter registry")
    records = registry.get("adapters")
    if not isinstance(records, list) or not records:
        raise EvaluatorExecutionError(
            "E_SCHEMA", "adapter registry adapters must be a nonempty array"
        )
    locators: list[str] = []
    for index, item in enumerate(records):
        record = require_object(item, f"adapter registry adapters[{index}]")
        locators.append(
            require_text(record.get("adapter_locator"), f"adapter[{index}].adapter_locator")
        )
    if len(locators) != len(set(locators)):
        raise EvaluatorExecutionError(
            "E_DUPLICATE", "adapter registry contains duplicate locators"
        )
    return registry_digest


def resolve_adapter(
    project_root: Path,
    registry: Mapping[str, Any],
    evaluator: Mapping[str, Any],
) -> tuple[dict[str, Any], Path, dict[str, Any]]:
    locator = evaluator["adapter_locator"]
    records = registry["adapters"]
    matches = [item for item in records if isinstance(item, Mapping) and item.get("adapter_locator") == locator]
    if len(matches) != 1:
        raise EvaluatorExecutionError(
            "E_ADAPTER", f"adapter registry must contain exactly one {locator}"
        )
    adapter = dict(matches[0])
    required_keys = {
        "adapter_locator",
        "runtime",
        "entrypoint",
        "entrypoint_sha256",
        "timeout_seconds",
        "max_output_bytes",
        "arguments",
        "artifact_classes",
        "produces_evidence",
        "score_dimensions",
    }
    require_exact_keys(adapter, required_keys, f"adapter {locator}")
    runtime = adapter.get("runtime")
    if runtime not in {"python", "executable"}:
        raise EvaluatorExecutionError(
            "E_ADAPTER", f"adapter {locator} runtime is unsupported"
        )
    entrypoint, relative = safe_file(
        project_root, adapter.get("entrypoint"), f"adapter {locator}.entrypoint"
    )
    expected_entrypoint_digest = require_sha256(
        adapter.get("entrypoint_sha256"),
        f"adapter {locator}.entrypoint_sha256",
    )
    if file_digest(entrypoint) != expected_entrypoint_digest:
        raise EvaluatorExecutionError(
            "E_DIGEST", f"adapter {locator} entrypoint digest does not match"
        )
    timeout = adapter.get("timeout_seconds")
    if (
        not isinstance(timeout, int)
        or isinstance(timeout, bool)
        or timeout < 1
        or timeout > MAX_TIMEOUT_SECONDS
    ):
        raise EvaluatorExecutionError(
            "E_ADAPTER", f"adapter {locator} timeout_seconds is invalid"
        )
    max_output = adapter.get("max_output_bytes")
    if (
        not isinstance(max_output, int)
        or isinstance(max_output, bool)
        or max_output < 1024
        or max_output > MAX_OUTPUT_BYTES
    ):
        raise EvaluatorExecutionError(
            "E_ADAPTER", f"adapter {locator} max_output_bytes is invalid"
        )
    arguments = require_string_list(adapter.get("arguments"), f"adapter {locator}.arguments")
    for field in ("artifact_classes", "produces_evidence", "score_dimensions"):
        adapter_values = require_strings(adapter.get(field), f"adapter {locator}.{field}")
        evaluator_values = require_strings(evaluator.get(field), f"evaluator.{field}")
        if adapter_values != evaluator_values:
            raise EvaluatorExecutionError(
                "E_BINDING", f"adapter {locator}.{field} does not match evaluator contract"
            )
    if runtime == "executable" and not os.access(entrypoint, os.X_OK):
        raise EvaluatorExecutionError(
            "E_ADAPTER", f"adapter {locator} entrypoint is not executable"
        )
    descriptor = {
        "adapter_locator": locator,
        "runtime": runtime,
        "entrypoint": relative,
        "entrypoint_sha256": expected_entrypoint_digest,
        "arguments": arguments,
        "timeout_seconds": timeout,
        "max_output_bytes": max_output,
    }
    return adapter, entrypoint, descriptor


def validate_artifacts(
    project_root: Path,
    artifacts: Any,
    evaluator: Mapping[str, Any],
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    if not isinstance(artifacts, list) or not artifacts:
        raise EvaluatorExecutionError(
            "E_ARTIFACT", "execution request artifacts must be a nonempty array"
        )
    allowed_classes = set(
        require_strings(
            evaluator.get("artifact_classes"),
            "evaluator.artifact_classes",
            nonempty=True,
        )
    )
    seen: set[str] = set()
    covered: set[str] = set()
    portable: list[dict[str, Any]] = []
    runtime_values: list[dict[str, Any]] = []
    expected_keys = {"artifact_id", "artifact_class_id", "path", "sha256"}
    for index, raw in enumerate(artifacts):
        item = require_object(raw, f"artifacts[{index}]")
        require_exact_keys(item, expected_keys, f"artifacts[{index}]")
        artifact_id = require_text(item.get("artifact_id"), f"artifacts[{index}].artifact_id")
        if artifact_id in seen:
            raise EvaluatorExecutionError("E_DUPLICATE", f"duplicate artifact_id {artifact_id}")
        seen.add(artifact_id)
        artifact_class = require_text(
            item.get("artifact_class_id"),
            f"artifacts[{index}].artifact_class_id",
        )
        if artifact_class not in allowed_classes:
            raise EvaluatorExecutionError(
                "E_ARTIFACT", f"artifact {artifact_id} has an unhandled class"
            )
        path, relative = safe_file(
            project_root, item.get("path"), f"artifacts[{index}].path"
        )
        expected_digest = require_sha256(
            item.get("sha256"), f"artifacts[{index}].sha256"
        )
        observed_digest = file_digest(path)
        if observed_digest != expected_digest:
            raise EvaluatorExecutionError(
                "E_DIGEST", f"artifact {artifact_id} digest does not match"
            )
        record = {
            "artifact_id": artifact_id,
            "artifact_class_id": artifact_class,
            "path": relative,
            "sha256": observed_digest,
            "size": path.stat().st_size,
        }
        portable.append(record)
        runtime_values.append({**record, "resolved_path": str(path)})
        covered.add(artifact_class)
    missing = sorted(allowed_classes - covered)
    if missing:
        raise EvaluatorExecutionError(
            "E_ARTIFACT", f"required artifact classes are missing: {missing}"
        )
    portable.sort(key=lambda item: item["artifact_id"])
    runtime_values.sort(key=lambda item: item["artifact_id"])
    return portable, runtime_values


def safe_environment() -> dict[str, str]:
    environment = {
        "PYTHONHASHSEED": "0",
        "PYTHONNOUSERSITE": "1",
        "LANG": "C.UTF-8",
        "LC_ALL": "C.UTF-8",
    }
    for key in SAFE_ENVIRONMENT_KEYS:
        value = os.environ.get(key)
        if value:
            environment[key] = value
    return environment


def validate_scores(value: Any, dimensions: Sequence[str]) -> dict[str, float]:
    scores = require_object(value, "adapter output scores")
    expected = set(dimensions)
    if set(scores) != expected:
        raise EvaluatorExecutionError(
            "E_OUTPUT",
            f"adapter output score dimensions are invalid; expected={sorted(expected)} observed={sorted(scores)}",
        )
    result: dict[str, float] = {}
    for dimension in sorted(expected):
        score = scores.get(dimension)
        if (
            not isinstance(score, (int, float))
            or isinstance(score, bool)
            or not math.isfinite(float(score))
            or float(score) < 0.0
            or float(score) > 10.0
        ):
            raise EvaluatorExecutionError(
                "E_OUTPUT", f"adapter output score is invalid: {dimension}"
            )
        result[dimension] = float(score)
    return result


def validate_findings(value: Any) -> list[dict[str, str]]:
    if not isinstance(value, list):
        raise EvaluatorExecutionError("E_OUTPUT", "adapter output findings must be an array")
    result: list[dict[str, str]] = []
    seen: set[str] = set()
    expected = {"code", "severity", "statement"}
    for index, raw in enumerate(value):
        item = require_object(raw, f"findings[{index}]")
        require_exact_keys(item, expected, f"findings[{index}]")
        code = require_text(item.get("code"), f"findings[{index}].code")
        if code in seen:
            raise EvaluatorExecutionError("E_DUPLICATE", f"duplicate finding code {code}")
        seen.add(code)
        severity = item.get("severity")
        if severity not in FINDING_SEVERITIES:
            raise EvaluatorExecutionError(
                "E_OUTPUT", f"finding {code} has invalid severity"
            )
        statement = require_text(
            item.get("statement"), f"findings[{index}].statement"
        )
        result.append({"code": code, "severity": severity, "statement": statement})
    return sorted(result, key=lambda item: item["code"])


def validate_evidence(
    project_root: Path,
    value: Any,
    required_types: Sequence[str],
) -> list[dict[str, Any]]:
    if not isinstance(value, list):
        raise EvaluatorExecutionError("E_OUTPUT", "adapter output evidence must be an array")
    required = set(required_types)
    seen_ids: set[str] = set()
    observed_types: set[str] = set()
    result: list[dict[str, Any]] = []
    expected = {"evidence_id", "evidence_type", "path"}
    for index, raw in enumerate(value):
        item = require_object(raw, f"evidence[{index}]")
        require_exact_keys(item, expected, f"evidence[{index}]")
        evidence_id = require_text(item.get("evidence_id"), f"evidence[{index}].evidence_id")
        if evidence_id in seen_ids:
            raise EvaluatorExecutionError(
                "E_DUPLICATE", f"duplicate evidence_id {evidence_id}"
            )
        seen_ids.add(evidence_id)
        evidence_type = require_text(
            item.get("evidence_type"), f"evidence[{index}].evidence_type"
        )
        if evidence_type not in required:
            raise EvaluatorExecutionError(
                "E_OUTPUT", f"evidence {evidence_id} has an undeclared type"
            )
        path, relative = safe_file(
            project_root, item.get("path"), f"evidence[{index}].path"
        )
        result.append(
            {
                "evidence_id": evidence_id,
                "evidence_type": evidence_type,
                "path": relative,
                "sha256": file_digest(path),
                "size": path.stat().st_size,
            }
        )
        observed_types.add(evidence_type)
    missing = sorted(required - observed_types)
    if missing:
        raise EvaluatorExecutionError(
            "E_OUTPUT", f"required evidence types are missing: {missing}"
        )
    return sorted(result, key=lambda item: item["evidence_id"])


def execute(project_root: Path, request: Mapping[str, Any]) -> dict[str, Any]:
    project_root = project_root.resolve()
    if not project_root.is_dir() or project_root.is_symlink():
        raise EvaluatorExecutionError("E_PATH", "project_root must be a real directory")
    expected_request_keys = {
        "$schema",
        "run_id",
        "objective_id",
        "evaluator_id",
        "evaluator_contract_path",
        "adapter_registry_path",
        "benchmark_contract_path",
        "executor_actor_id",
        "production_actor_ids",
        "artifacts",
        "arguments",
    }
    require_exact_keys(request, expected_request_keys, "execution request")
    if request.get("$schema") != REQUEST_SCHEMA:
        raise EvaluatorExecutionError(
            "E_SCHEMA", f"execution request must use {REQUEST_SCHEMA}"
        )
    run_id = require_text(request.get("run_id"), "run_id")
    objective_id = require_text(request.get("objective_id"), "objective_id")
    evaluator_id = require_text(request.get("evaluator_id"), "evaluator_id")
    executor_actor_id = require_text(
        request.get("executor_actor_id"), "executor_actor_id"
    )
    production_actor_ids = require_strings(
        request.get("production_actor_ids"), "production_actor_ids"
    )
    if executor_actor_id in set(production_actor_ids):
        raise EvaluatorExecutionError(
            "E_AUTHORITY", "evaluator executor is a production actor"
        )
    arguments = dict(require_object(request.get("arguments"), "arguments"))
    canonical_bytes(arguments)

    evaluator_contract, evaluator_binding = load_bound_json(
        project_root,
        request.get("evaluator_contract_path"),
        "evaluator contract",
        CONTRACT_SCHEMA,
        "contract_sha256",
    )
    if evaluator_contract.get("objective_id") != objective_id:
        raise EvaluatorExecutionError(
            "E_BINDING", "evaluator contract objective_id does not match request"
        )
    if evaluator_contract.get("ready") is not True:
        raise EvaluatorExecutionError("E_EVALUATOR", "evaluator contract is not ready")
    evaluator = find_evaluator(evaluator_contract, evaluator_id)

    benchmark_contract, benchmark_binding = load_bound_json(
        project_root,
        request.get("benchmark_contract_path"),
        "benchmark contract",
        BENCHMARK_SCHEMA,
        "contract_sha256",
    )
    if benchmark_contract.get("objective_id") != objective_id:
        raise EvaluatorExecutionError(
            "E_BINDING", "benchmark contract objective_id does not match request"
        )
    if benchmark_contract.get("ready") is not True:
        raise EvaluatorExecutionError("E_BENCHMARK", "benchmark contract is not ready")

    registry, registry_binding = load_bound_json(
        project_root,
        request.get("adapter_registry_path"),
        "adapter registry",
        REGISTRY_SCHEMA,
        "registry_sha256",
    )
    validate_registry(registry)
    adapter, entrypoint, adapter_descriptor = resolve_adapter(
        project_root, registry, evaluator
    )

    artifact_bindings, runtime_artifacts = validate_artifacts(
        project_root, request.get("artifacts"), evaluator
    )
    portable_input = {
        "$schema": ADAPTER_INPUT_SCHEMA,
        "schema_version": 1,
        "run_id": run_id,
        "objective_id": objective_id,
        "evaluator_id": evaluator_id,
        "evaluator": evaluator,
        "artifacts": artifact_bindings,
        "benchmarks": benchmark_contract,
        "arguments": arguments,
    }
    runtime_input = {**portable_input, "artifacts": runtime_artifacts}
    input_payload = canonical_bytes(runtime_input)

    runtime = adapter_descriptor["runtime"]
    arguments_list = adapter_descriptor["arguments"]
    if runtime == "python":
        command = [sys.executable, str(entrypoint), *arguments_list]
    else:
        command = [str(entrypoint), *arguments_list]
    command_descriptor = {
        "runtime": runtime,
        "entrypoint": adapter_descriptor["entrypoint"],
        "arguments": arguments_list,
    }
    timeout = adapter_descriptor["timeout_seconds"]
    try:
        process = subprocess.run(
            command,
            cwd=project_root,
            env=safe_environment(),
            input=input_payload,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            check=False,
            timeout=timeout,
        )
    except subprocess.TimeoutExpired as exc:
        raise EvaluatorExecutionError(
            "E_TIMEOUT", f"evaluator adapter exceeded {timeout} seconds"
        ) from exc
    max_output = adapter_descriptor["max_output_bytes"]
    if len(process.stdout) > max_output or len(process.stderr) > max_output:
        raise EvaluatorExecutionError(
            "E_OUTPUT", "evaluator adapter output exceeded its byte limit"
        )
    stdout_sha256 = bytes_digest(process.stdout)
    stderr_sha256 = bytes_digest(process.stderr)
    if process.returncode != 0:
        raise EvaluatorExecutionError(
            "E_ADAPTER",
            f"evaluator adapter exited nonzero; code={process.returncode} stderr_sha256={stderr_sha256}",
        )

    output = dict(
        require_object(parse_json_bytes(process.stdout, "adapter stdout"), "adapter output")
    )
    expected_output_keys = {
        "$schema",
        "run_id",
        "objective_id",
        "evaluator_id",
        "accepted",
        "scores",
        "findings",
        "evidence",
    }
    require_exact_keys(output, expected_output_keys, "adapter output")
    if output.get("$schema") != ADAPTER_OUTPUT_SCHEMA:
        raise EvaluatorExecutionError(
            "E_OUTPUT", f"adapter output must use {ADAPTER_OUTPUT_SCHEMA}"
        )
    for field, expected in (
        ("run_id", run_id),
        ("objective_id", objective_id),
        ("evaluator_id", evaluator_id),
    ):
        if output.get(field) != expected:
            raise EvaluatorExecutionError(
                "E_BINDING", f"adapter output {field} does not match execution request"
            )
    accepted = output.get("accepted")
    if not isinstance(accepted, bool):
        raise EvaluatorExecutionError(
            "E_OUTPUT", "adapter output accepted must be boolean"
        )
    score_dimensions = require_strings(
        evaluator.get("score_dimensions", []), "evaluator.score_dimensions"
    )
    scores = validate_scores(output.get("scores"), score_dimensions)
    findings = validate_findings(output.get("findings"))
    required_evidence = require_strings(
        evaluator.get("produces_evidence"),
        "evaluator.produces_evidence",
        nonempty=True,
    )
    evidence_bindings = validate_evidence(
        project_root, output.get("evidence"), required_evidence
    )

    receipt: dict[str, Any] = {
        "$schema": RECEIPT_SCHEMA,
        "schema_version": 1,
        "run_id": run_id,
        "objective_id": objective_id,
        "evaluator_id": evaluator_id,
        "executor_actor_id": executor_actor_id,
        "production_actor_ids": production_actor_ids,
        "independent_role": True,
        "accepted": accepted,
        "scores": scores,
        "findings": findings,
        "artifact_bindings": artifact_bindings,
        "evidence_bindings": evidence_bindings,
        "source_bindings": {
            "evaluator_contract": evaluator_binding,
            "benchmark_contract": benchmark_binding,
            "adapter_registry": registry_binding,
            "adapter_entrypoint": {
                "path": adapter_descriptor["entrypoint"],
                "file_sha256": adapter_descriptor["entrypoint_sha256"],
            },
        },
        "execution": {
            "adapter_locator": evaluator["adapter_locator"],
            "runtime": runtime,
            "command_sha256": digest(command_descriptor),
            "timeout_seconds": timeout,
            "exit_code": process.returncode,
            "stdout_sha256": stdout_sha256,
            "stderr_sha256": stderr_sha256,
            "adapter_input_sha256": digest(portable_input),
            "adapter_output_sha256": digest(output),
        },
    }
    receipt["receipt_sha256"] = digest({**receipt, "receipt_sha256": None})
    return receipt


def verify_file_binding(project_root: Path, binding: Mapping[str, Any], label: str) -> None:
    path, _ = safe_file(project_root, binding.get("path"), f"{label}.path")
    expected = require_sha256(binding.get("file_sha256"), f"{label}.file_sha256")
    if file_digest(path) != expected:
        raise EvaluatorExecutionError(
            "E_DIGEST", f"{label} file digest does not match"
        )


def verify_receipt(project_root: Path, receipt: Mapping[str, Any]) -> dict[str, Any]:
    if receipt.get("$schema") != RECEIPT_SCHEMA:
        raise EvaluatorExecutionError(
            "E_SCHEMA", f"execution receipt must use {RECEIPT_SCHEMA}"
        )
    receipt_sha256 = verify_self_digest(
        receipt, "receipt_sha256", "execution receipt"
    )
    executor = require_text(receipt.get("executor_actor_id"), "executor_actor_id")
    production = require_strings(
        receipt.get("production_actor_ids"), "production_actor_ids"
    )
    if receipt.get("independent_role") is not True or executor in set(production):
        raise EvaluatorExecutionError(
            "E_AUTHORITY", "execution receipt is not independent from production"
        )
    sources = require_object(receipt.get("source_bindings"), "source_bindings")
    for label in (
        "evaluator_contract",
        "benchmark_contract",
        "adapter_registry",
        "adapter_entrypoint",
    ):
        verify_file_binding(
            project_root,
            require_object(sources.get(label), f"source_bindings.{label}"),
            f"source_bindings.{label}",
        )
    for collection_name in ("artifact_bindings", "evidence_bindings"):
        values = receipt.get(collection_name)
        if not isinstance(values, list) or not values:
            raise EvaluatorExecutionError(
                "E_SCHEMA", f"{collection_name} must be a nonempty array"
            )
        for index, raw in enumerate(values):
            binding = require_object(raw, f"{collection_name}[{index}]")
            path, _ = safe_file(
                project_root, binding.get("path"), f"{collection_name}[{index}].path"
            )
            expected = require_sha256(
                binding.get("sha256"), f"{collection_name}[{index}].sha256"
            )
            if file_digest(path) != expected:
                raise EvaluatorExecutionError(
                    "E_DIGEST", f"{collection_name}[{index}] file digest does not match"
                )
    return {
        "receipt_sha256": receipt_sha256,
        "objective_id": require_text(receipt.get("objective_id"), "objective_id"),
        "evaluator_id": require_text(receipt.get("evaluator_id"), "evaluator_id"),
        "accepted": receipt.get("accepted") is True,
        "independent_role": True,
    }


def main() -> None:
    parser = argparse.ArgumentParser()
    subparsers = parser.add_subparsers(dest="command", required=True)

    execute_parser = subparsers.add_parser("execute")
    execute_parser.add_argument("--project-root", required=True, type=Path)
    execute_parser.add_argument("--request", required=True, type=Path)
    execute_parser.add_argument("--output", required=True, type=Path)

    verify_parser = subparsers.add_parser("verify")
    verify_parser.add_argument("--project-root", required=True, type=Path)
    verify_parser.add_argument("--receipt", required=True, type=Path)

    args = parser.parse_args()
    if args.command == "execute":
        request = require_object(read_json(args.request, "execution request"), "execution request")
        receipt = execute(args.project_root, request)
        args.output.parent.mkdir(parents=True, exist_ok=True)
        args.output.write_text(
            json.dumps(receipt, indent=2, sort_keys=True) + "\n",
            encoding="utf-8",
        )
        print(
            f"evaluator executed id={receipt['evaluator_id']} accepted={receipt['accepted']}"
        )
        return
    receipt = require_object(read_json(args.receipt, "execution receipt"), "execution receipt")
    result = verify_receipt(args.project_root, receipt)
    print(json.dumps(result, sort_keys=True))


if __name__ == "__main__":
    main()

