          "disposition": {"enum": ["accepted", "rejected"]},
          "attempt_chains": {"type": "integer", "minimum": 1},
          "rework_cycles": {"type": "integer", "minimum": 0},
          "evidence": {
            "type": "object",
            "additionalProperties": false,
            "required": ["terminal_receipts"],
            "properties": {
              "terminal_receipts": {
                "type": "array",
                "minItems": 1,
                "items": {"$ref": "#/$defs/file"}
              }
            }
          }
        }
      }
    }
  },
  "$defs": {
    "id": {"type": "string", "pattern": "^[a-z0-9][a-z0-9._:-]*$"},
    "sha256": {"type": "string", "pattern": "^[0-9a-f]{64}$"},
    "file": {
      "type": "object",
      "additionalProperties": false,
      "required": ["path", "sha256"],
      "properties": {
        "path": {"type": "string", "pattern": "^[A-Za-z0-9][A-Za-z0-9._/-]*$"},
        "sha256": {"$ref": "#/$defs/sha256"}
      }
    }
  }
}

#!/usr/bin/env python3
"""Validate and evaluate the Company OS force-first execution state machine."""

from __future__ import annotations

import argparse
import hashlib
import json
import re
import stat
import sys
from pathlib import Path
from typing import Any


CONTRACT_SCHEMA = "company-os.force-contract.v1"
EVENT_SCHEMA = "company-os.force-event.v1"
HEX64 = re.compile(r"^[0-9a-f]{64}$")
IDENTIFIER = re.compile(r"^[a-z0-9][a-z0-9._-]*$")
SAFE_PATH = re.compile(r"^[a-z0-9][a-z0-9._/-]*$")
SOFT_SLO_KEYS = {
    "first_artifact_seconds",
    "runnable_candidate_seconds",
    "verification_seconds",
    "acceptance_to_receipt_seconds",
    "receipt_to_decision_seconds",
}
BASELINE_HARD_STOPS = {
    "authority_loss",
    "budget_exhausted",
    "collision",
    "explicit_cancel",
    "prohibited_side_effect",
    "scope_violation",
}
EVENTS = {
    "task_started",
    "inflight_observed",
    "intervention_sent",
    "artifact_materialized",
    "late_output_reviewed",
    "candidate_runnable",
    "verification_passed",
    "manager_inspection_passed",
    "manager_inspection_failed",
    "rework_started",
    "receipt_materialized",
    "manager_accept",
    "manager_rework",
    "manager_reject",
    "hard_stop",
}
TERMINAL_EVENTS = {"manager_accept", "manager_reject", "hard_stop"}


class ForceContractError(ValueError):
    """Raised when a force contract or event log is invalid."""


def canonical_bytes(value: Any) -> bytes:
    return json.dumps(value, sort_keys=True, separators=(",", ":")).encode("utf-8")


def canonical_sha256(value: Any) -> str:
    return hashlib.sha256(canonical_bytes(value)).hexdigest()


def _exact_keys(value: dict[str, Any], expected: set[str], label: str) -> None:
    actual = set(value)
    if actual != expected:
        raise ForceContractError(
            f"{label} keys differ; extra={sorted(actual - expected)!r}, "
            f"missing={sorted(expected - actual)!r}"
        )


def _positive_int(value: Any, label: str) -> int:
    if isinstance(value, bool) or not isinstance(value, int) or value <= 0:
        raise ForceContractError(f"{label} must be a positive integer")
    return value


def _safe_path(value: Any, label: str) -> str:
    if not isinstance(value, str) or not SAFE_PATH.fullmatch(value):
        raise ForceContractError(f"{label} must be a safe project-relative path")
    if value.startswith("/") or "//" in value or any(part in {"", ".", ".."} for part in value.split("/")):
        raise ForceContractError(f"{label} must not escape or contain ambiguous segments")
    return value


def _artifact_root(path: Path) -> Path:
    if path.is_symlink():
        raise ForceContractError("artifact root must not be a symlink")
    try:
        resolved = path.resolve(strict=True)
    except OSError as error:
        raise ForceContractError(f"artifact root could not be resolved: {error}") from error
    if not resolved.is_dir():
        raise ForceContractError("artifact root must be a directory")
    return resolved


def _verified_file(root: Path, relative: str, expected_sha256: str | None = None) -> str:
    safe = _safe_path(relative, "artifact path")
    current = root
    parts = safe.split("/")
    for index, part in enumerate(parts):
        current = current / part
        try:
            status = current.lstat()
        except OSError as error:
            raise ForceContractError(f"artifact path is missing or unreadable: {safe}") from error
        if stat.S_ISLNK(status.st_mode):
            raise ForceContractError(f"artifact path contains a symlink: {safe}")
        if index < len(parts) - 1 and not stat.S_ISDIR(status.st_mode):
            raise ForceContractError(f"artifact path parent is not a directory: {safe}")
        if index == len(parts) - 1 and not stat.S_ISREG(status.st_mode):
            raise ForceContractError(f"artifact path is not a regular file: {safe}")
    try:
        current.resolve(strict=True).relative_to(root)
    except (OSError, ValueError) as error:
        raise ForceContractError(f"artifact path escapes its root: {safe}") from error
    try:
        digest = hashlib.sha256(current.read_bytes()).hexdigest()
    except OSError as error:
        raise ForceContractError(f"artifact bytes could not be read: {safe}") from error
    if expected_sha256 is not None and digest != expected_sha256:
        raise ForceContractError(f"artifact digest does not match exact bytes: {safe}")
    return digest


def validate_contract(value: Any) -> dict[str, Any]:
    if not isinstance(value, dict):
        raise ForceContractError("contract must be an object")
    _exact_keys(
        value,
        {"schema", "task_id", "outcome", "started_at_epoch", "soft_slos", "control", "hard_stop_codes"},
        "contract",
    )
    if value["schema"] != CONTRACT_SCHEMA:
        raise ForceContractError("unsupported contract schema")
    if not isinstance(value["task_id"], str) or not IDENTIFIER.fullmatch(value["task_id"]):
        raise ForceContractError("task_id is invalid")
    if not isinstance(value["outcome"], str) or not value["outcome"].strip():
        raise ForceContractError("outcome must be non-empty")
    if isinstance(value["started_at_epoch"], bool) or not isinstance(value["started_at_epoch"], int) or value["started_at_epoch"] < 0:
        raise ForceContractError("started_at_epoch must be a non-negative integer")

    soft_slos = value["soft_slos"]
    if not isinstance(soft_slos, dict):
        raise ForceContractError("soft_slos must be an object")
    _exact_keys(soft_slos, SOFT_SLO_KEYS, "soft_slos")
    for key in sorted(SOFT_SLO_KEYS):
        _positive_int(soft_slos[key], f"soft_slos.{key}")
    if soft_slos["first_artifact_seconds"] > soft_slos["runnable_candidate_seconds"]:
        raise ForceContractError("first artifact SLO must not exceed runnable candidate SLO")
    if soft_slos["runnable_candidate_seconds"] > soft_slos["verification_seconds"]:
        raise ForceContractError("runnable candidate SLO must not exceed verification SLO")

    control = value["control"]
    if not isinstance(control, dict):
        raise ForceContractError("control must be an object")
    _exact_keys(
        control,
        {"inflight_observation_fresh_seconds", "max_rework_cycles", "event_log_owner"},
        "control",
    )
    _positive_int(control["inflight_observation_fresh_seconds"], "control.inflight_observation_fresh_seconds")
    if (
        isinstance(control["max_rework_cycles"], bool)
        or not isinstance(control["max_rework_cycles"], int)
        or not 0 <= control["max_rework_cycles"] <= 3
    ):
        raise ForceContractError("control.max_rework_cycles must be between zero and three")
    if control["event_log_owner"] != "manager":
        raise ForceContractError("control.event_log_owner must be manager")

    codes = value["hard_stop_codes"]
    if not isinstance(codes, list) or not codes or any(not isinstance(code, str) or not IDENTIFIER.fullmatch(code) for code in codes):
        raise ForceContractError("hard_stop_codes must be a non-empty unique identifier list")
    if len(codes) != len(set(codes)):
        raise ForceContractError("hard_stop_codes must be unique")
    missing = sorted(BASELINE_HARD_STOPS - set(codes))
    if missing:
        raise ForceContractError(f"hard_stop_codes omit baseline stops: {missing!r}")
    return value


def _nonempty_strings(value: Any, label: str, *, paths: bool = False) -> list[str]:
    if not isinstance(value, list) or not value:
        raise ForceContractError(f"{label} must be a non-empty list")
    result: list[str] = []
    for index, item in enumerate(value):
        if paths:
            result.append(_safe_path(item, f"{label}[{index}]"))
        elif not isinstance(item, str) or not item.strip():
            raise ForceContractError(f"{label}[{index}] must be non-empty")
        else:
            result.append(item)
    return result


def _validate_evidence(event: str, evidence: Any, hard_stop_codes: set[str]) -> dict[str, Any]:
    if not isinstance(evidence, dict):
        raise ForceContractError(f"{event} evidence must be an object")
    if event in {"task_started", "manager_accept"}:
        _exact_keys(evidence, set(), f"{event} evidence")
    elif event == "inflight_observed":
        _exact_keys(evidence, {"operation"}, f"{event} evidence")
        if not isinstance(evidence["operation"], str) or not evidence["operation"].strip():
            raise ForceContractError("inflight_observed operation must be non-empty")
    elif event == "intervention_sent":
        _exact_keys(evidence, {"missing"}, f"{event} evidence")
        if not isinstance(evidence["missing"], str) or not evidence["missing"].strip():
            raise ForceContractError("intervention_sent missing must be non-empty")
    elif event in {"artifact_materialized", "receipt_materialized"}:
        _exact_keys(evidence, {"path", "sha256"}, f"{event} evidence")
        _safe_path(evidence["path"], f"{event} evidence.path")
        if not isinstance(evidence["sha256"], str) or not HEX64.fullmatch(evidence["sha256"]):
            raise ForceContractError(f"{event} evidence.sha256 must be lowercase SHA-256")
    elif event in {"candidate_runnable", "manager_inspection_passed"}:
        _exact_keys(evidence, {"artifact_paths"}, f"{event} evidence")
        _nonempty_strings(evidence["artifact_paths"], f"{event} evidence.artifact_paths", paths=True)
    elif event == "late_output_reviewed":
        _exact_keys(evidence, {"artifact_paths", "decision"}, f"{event} evidence")
        _nonempty_strings(evidence["artifact_paths"], f"{event} evidence.artifact_paths", paths=True)
        if evidence["decision"] not in {"accept", "rework", "reject"}:
            raise ForceContractError("late_output_reviewed decision must be accept, rework, or reject")
    elif event == "verification_passed":
        _exact_keys(evidence, {"check"}, f"{event} evidence")
        if not isinstance(evidence["check"], str) or not evidence["check"].strip():
            raise ForceContractError("verification_passed check must be non-empty")
    elif event in {"manager_inspection_failed", "rework_started", "manager_rework"}:
        _exact_keys(evidence, {"defects"}, f"{event} evidence")
        _nonempty_strings(evidence["defects"], f"{event} evidence.defects")
    elif event == "manager_reject":
        _exact_keys(evidence, {"reason"}, f"{event} evidence")
        if not isinstance(evidence["reason"], str) or not evidence["reason"].strip():
            raise ForceContractError("manager_reject reason must be non-empty")
    elif event == "hard_stop":
        _exact_keys(evidence, {"code", "detail"}, f"{event} evidence")
        if evidence["code"] not in hard_stop_codes:
            raise ForceContractError("hard_stop code is not declared by the contract")
        if not isinstance(evidence["detail"], str) or not evidence["detail"].strip():
            raise ForceContractError("hard_stop detail must be non-empty")
    return evidence


def validate_events(
    contract: dict[str, Any], values: Any, artifact_root: Path
) -> list[dict[str, Any]]:
    if not isinstance(values, list) or not values:
        raise ForceContractError("event log must contain at least task_started")
    resolved_root = _artifact_root(artifact_root)
    events: list[dict[str, Any]] = []
    last_at = contract["started_at_epoch"]
    terminal_seen = False
    task_started_count = 0
    last_rework_sequence = 0
    cycle_started_at = contract["started_at_epoch"]
    cycle_artifact_sequence = 0
    cycle_artifact_paths: dict[str, str] = {}
    candidate_sequence = 0
    candidate_paths: set[str] = set()
    inspection_pass_sequence = 0
    verification_pass_sequence = 0
    receipt_sequence = 0
    rework_requested_sequence = 0
    rework_count = 0
    unresolved_late_paths: set[str] = set()
    late_reviewed_paths: set[str] = set()
    blocked_late_paths: set[str] = set()
    all_materialized_paths: set[str] = set()
    for index, value in enumerate(values, start=1):
        if not isinstance(value, dict):
            raise ForceContractError(f"event {index} must be an object")
        _exact_keys(value, {"schema", "sequence", "task_id", "event", "at_epoch", "evidence"}, f"event {index}")
        if value["schema"] != EVENT_SCHEMA:
            raise ForceContractError(f"event {index} schema is unsupported")
        if value["sequence"] != index:
            raise ForceContractError("event sequences must be contiguous starting at one")
        if value["task_id"] != contract["task_id"]:
            raise ForceContractError(f"event {index} task_id does not match contract")
        event = value["event"]
        if event not in EVENTS:
            raise ForceContractError(f"event {index} type is unsupported")
        at_epoch = value["at_epoch"]
        if isinstance(at_epoch, bool) or not isinstance(at_epoch, int) or at_epoch < last_at:
            raise ForceContractError("event timestamps must be non-decreasing and not predate launch")
        if terminal_seen:
            raise ForceContractError("events after a terminal decision are not allowed")
        _validate_evidence(event, value["evidence"], set(contract["hard_stop_codes"]))

        if event == "task_started":
            task_started_count += 1
            if index != 1 or task_started_count != 1:
                raise ForceContractError("task_started must appear exactly once as the first event")
        elif index == 1:
            raise ForceContractError("task_started must be the first event")

        if receipt_sequence > last_rework_sequence and event not in {
            "manager_accept",
            "manager_rework",
            "manager_reject",
            "hard_stop",
        }:
            raise ForceContractError(
                "receipt is sealed; only a manager decision or hard stop may follow"
            )

        if event == "rework_started":
            if rework_requested_sequence <= last_rework_sequence:
                raise ForceContractError("rework_started requires a preceding bounded rework request")
            if rework_count >= contract["control"]["max_rework_cycles"]:
                raise ForceContractError("rework count exceeds contract maximum")
            rework_count += 1
            last_rework_sequence = index
            cycle_started_at = at_epoch
            cycle_artifact_sequence = 0
            cycle_artifact_paths = {}
            candidate_sequence = 0
            candidate_paths = set()
            inspection_pass_sequence = 0
            verification_pass_sequence = 0
            receipt_sequence = 0
            rework_requested_sequence = 0
            unresolved_late_paths = set()
            blocked_late_paths = set()
        elif event == "artifact_materialized":
            path = value["evidence"]["path"]
            if path in all_materialized_paths:
                raise ForceContractError("materialized artifact paths must be immutable and unique")
            digest = _verified_file(resolved_root, path, value["evidence"]["sha256"])
            all_materialized_paths.add(path)
            cycle_artifact_paths[path] = digest
            candidate_sequence = 0
            candidate_paths = set()
            verification_pass_sequence = 0
            inspection_pass_sequence = 0
            receipt_sequence = 0
            if cycle_artifact_sequence == 0:
                cycle_artifact_sequence = index
                if at_epoch - cycle_started_at > contract["soft_slos"]["first_artifact_seconds"]:
                    unresolved_late_paths = {path}
        elif event == "late_output_reviewed":
            reviewed = set(value["evidence"]["artifact_paths"])
            if not unresolved_late_paths:
                raise ForceContractError("late_output_reviewed requires an unresolved late artifact")
            if reviewed != unresolved_late_paths:
                raise ForceContractError("late output review must bind the exact unresolved artifact paths")
            if reviewed & late_reviewed_paths:
                raise ForceContractError("late output review decisions are immutable")
            late_reviewed_paths.update(reviewed)
            unresolved_late_paths = set()
            late_decision = value["evidence"]["decision"]
            if late_decision in {"rework", "reject"}:
                blocked_late_paths.update(reviewed)
            if late_decision == "rework":
                rework_requested_sequence = index
        elif event == "candidate_runnable":
            proposed = set(value["evidence"]["artifact_paths"])
            if cycle_artifact_sequence <= last_rework_sequence:
                raise ForceContractError("candidate requires fresh materialization in the current cycle")
            if unresolved_late_paths:
                raise ForceContractError("late artifact must be reviewed before candidate use")
            if not proposed.issubset(cycle_artifact_paths):
                raise ForceContractError("candidate paths must be materialized in the current cycle")
            if proposed & blocked_late_paths:
                raise ForceContractError("reworked or rejected late output cannot enter a candidate")
            for path in proposed:
                _verified_file(resolved_root, path, cycle_artifact_paths[path])
            candidate_paths = proposed
            candidate_sequence = index
            verification_pass_sequence = 0
            inspection_pass_sequence = 0
            receipt_sequence = 0
        elif event == "verification_passed":
            if candidate_sequence <= last_rework_sequence:
                raise ForceContractError("verification requires a fresh runnable candidate")
            verification_pass_sequence = index
            inspection_pass_sequence = 0
            receipt_sequence = 0
        elif event == "manager_inspection_passed":
            if rework_requested_sequence > last_rework_sequence:
                raise ForceContractError("manager inspection pass requires the requested rework to start")
            if verification_pass_sequence <= candidate_sequence:
                raise ForceContractError(
                    "manager inspection pass requires fresh verification of the current candidate"
                )
            inspected = set(value["evidence"]["artifact_paths"])
            if inspected != candidate_paths:
                raise ForceContractError("manager inspection must bind every current candidate path")
            for path in inspected:
                _verified_file(resolved_root, path, cycle_artifact_paths[path])
            inspection_pass_sequence = index
            receipt_sequence = 0
        elif event == "manager_inspection_failed":
            inspection_pass_sequence = 0
            receipt_sequence = 0
            rework_requested_sequence = index
        elif event == "manager_rework":
            receipt_sequence = 0
            rework_requested_sequence = index
        elif event == "receipt_materialized":
            if inspection_pass_sequence <= verification_pass_sequence:
                raise ForceContractError(
                    "receipt requires fresh manager inspection of the current verified candidate"
                )
            _verified_file(
                resolved_root,
                value["evidence"]["path"],
                value["evidence"]["sha256"],
            )
            receipt_sequence = index
        elif event == "manager_accept":
            if rework_requested_sequence > last_rework_sequence:
                raise ForceContractError("manager acceptance cannot bypass requested rework")
            if receipt_sequence <= last_rework_sequence:
                raise ForceContractError("manager acceptance requires a fresh receipt after rework")

        if event in TERMINAL_EVENTS:
            terminal_seen = True
        last_at = at_epoch
        events.append(value)
    return events


def read_contract(path: Path) -> dict[str, Any]:
    try:
        value = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as error:
        raise ForceContractError(f"contract could not be read: {error}") from error
    return validate_contract(value)


def read_events(
    path: Path, contract: dict[str, Any], artifact_root: Path
) -> list[dict[str, Any]]:
    values: list[Any] = []
    try:
        for line_number, raw in enumerate(path.read_text(encoding="utf-8").splitlines(), start=1):
            if not raw.strip():
                raise ForceContractError(f"event log line {line_number} is blank")
            try:
                values.append(json.loads(raw))
            except json.JSONDecodeError as error:
                raise ForceContractError(f"event log line {line_number} is not JSON") from error
    except (OSError, UnicodeError) as error:
        raise ForceContractError(f"event log could not be read: {error}") from error
    return validate_events(contract, values, artifact_root)


def _latest(events: list[dict[str, Any]], event_type: str, *, after_sequence: int = 0) -> dict[str, Any] | None:
    return next(
        (item for item in reversed(events) if item["event"] == event_type and item["sequence"] > after_sequence),
        None,
    )


def evaluate(contract: dict[str, Any], events: list[dict[str, Any]], now_epoch: int) -> dict[str, Any]:
    if isinstance(now_epoch, bool) or not isinstance(now_epoch, int) or now_epoch < events[-1]["at_epoch"]:
        raise ForceContractError("now_epoch must be an integer at or after the latest event")
    started = contract["started_at_epoch"]
    elapsed = now_epoch - started
    latest_rework = _latest(events, "rework_started")
    rework_sequence = latest_rework["sequence"] if latest_rework else 0
    cycle_started = latest_rework["at_epoch"] if latest_rework else started
    cycle_elapsed = now_epoch - cycle_started
    artifacts = [item for item in events if item["event"] == "artifact_materialized"]
    cycle_artifacts = [item for item in artifacts if item["sequence"] > rework_sequence]
    cycle_first_artifact = cycle_artifacts[0] if cycle_artifacts else None
    latest_cycle_artifact_sequence = (
        cycle_artifacts[-1]["sequence"] if cycle_artifacts else rework_sequence
    )
    candidate = _latest(
        events,
        "candidate_runnable",
        after_sequence=latest_cycle_artifact_sequence,
    )
    verification = (
        _latest(events, "verification_passed", after_sequence=candidate["sequence"])
        if candidate
        else None
    )
    inspection_pass = (
        _latest(events, "manager_inspection_passed", after_sequence=verification["sequence"])
        if verification
        else None
    )
    inspection_fail = _latest(events, "manager_inspection_failed", after_sequence=rework_sequence)
    inspection_failure_is_latest = bool(
        inspection_fail
        and (not inspection_pass or inspection_fail["sequence"] > inspection_pass["sequence"])
    )
    receipt = (
        _latest(events, "receipt_materialized", after_sequence=inspection_pass["sequence"])
        if inspection_pass
        else None
    )
    accepted = _latest(events, "manager_accept")
    rejected = _latest(events, "manager_reject")
    hard_stop = _latest(events, "hard_stop")
    manager_rework = _latest(events, "manager_rework", after_sequence=rework_sequence)
    latest_late_artifact = (
        cycle_first_artifact
        if cycle_first_artifact
        and cycle_first_artifact["at_epoch"] - cycle_started
        > contract["soft_slos"]["first_artifact_seconds"]
        else None
    )
    late_review = _latest(
        events,
        "late_output_reviewed",
        after_sequence=latest_late_artifact["sequence"] if latest_late_artifact else 0,
    )
    fresh_inflight = _latest(
        events,
        "inflight_observed",
        after_sequence=max(
            rework_sequence,
            cycle_artifacts[-1]["sequence"] if cycle_artifacts else 0,
        ),
    )
    fresh_window = contract["control"]["inflight_observation_fresh_seconds"]
    inflight_is_fresh = bool(fresh_inflight and now_epoch - fresh_inflight["at_epoch"] <= fresh_window)

    first_artifact = cycle_first_artifact
    slos = contract["soft_slos"]
    soft_miss_set: set[str] = set()
    cycle_boundaries = [
        {"sequence": 0, "at_epoch": started},
        *[item for item in events if item["event"] == "rework_started"],
    ]
    for cycle_index, boundary in enumerate(cycle_boundaries):
        next_boundary = (
            cycle_boundaries[cycle_index + 1]
            if cycle_index + 1 < len(cycle_boundaries)
            else None
        )
        end_sequence = next_boundary["sequence"] if next_boundary else len(events) + 1
        end_epoch = next_boundary["at_epoch"] if next_boundary else now_epoch
        cycle_events = [
            item
            for item in events
            if boundary["sequence"] < item["sequence"] < end_sequence
        ]
        milestones = {
            "first_artifact": next(
                (item for item in cycle_events if item["event"] == "artifact_materialized"),
                None,
            ),
            "runnable_candidate": next(
                (item for item in cycle_events if item["event"] == "candidate_runnable"),
                None,
            ),
            "verification": next(
                (item for item in cycle_events if item["event"] == "verification_passed"),
                None,
            ),
        }
        milestone_slos = {
            "first_artifact": slos["first_artifact_seconds"],
            "runnable_candidate": slos["runnable_candidate_seconds"],
            "verification": slos["verification_seconds"],
        }
        for name, milestone in milestones.items():
            observed_elapsed = (
                milestone["at_epoch"] - boundary["at_epoch"]
                if milestone
                else end_epoch - boundary["at_epoch"]
            )
            if observed_elapsed > milestone_slos[name]:
                soft_miss_set.add(name)
        cycle_receipt = next(
            (item for item in cycle_events if item["event"] == "receipt_materialized"),
            None,
        )
        cycle_inspection = next(
            (
                item
                for item in reversed(cycle_events)
                if item["event"] == "manager_inspection_passed"
                and (not cycle_receipt or item["sequence"] < cycle_receipt["sequence"])
            ),
            None,
        )
        if cycle_inspection and cycle_receipt:
            if (
                cycle_receipt["at_epoch"] - cycle_inspection["at_epoch"]
                > slos["acceptance_to_receipt_seconds"]
            ):
                soft_miss_set.add("acceptance_to_receipt")
        elif cycle_inspection and not any(
            item["sequence"] > cycle_inspection["sequence"]
            and item["event"] in {"manager_inspection_failed", "manager_rework"}
            for item in cycle_events
        ):
            if end_epoch - cycle_inspection["at_epoch"] > slos["acceptance_to_receipt_seconds"]:
                soft_miss_set.add("acceptance_to_receipt")

        if cycle_receipt:
            cycle_decision = next(
                (
                    item
                    for item in cycle_events
                    if item["sequence"] > cycle_receipt["sequence"]
                    and item["event"] in {"manager_accept", "manager_rework", "manager_reject"}
                ),
                None,
            )
            decision_epoch = cycle_decision["at_epoch"] if cycle_decision else end_epoch
            if decision_epoch - cycle_receipt["at_epoch"] > slos["receipt_to_decision_seconds"]:
                soft_miss_set.add("receipt_to_decision")
    manager_decisions = [
        item
        for item in events
        if item["event"] in {"manager_accept", "manager_rework", "manager_reject"}
    ]
    terminal_manager = manager_decisions[-1] if manager_decisions else None

    first_pass_acceptance: bool | None
    if any(item["event"] in {"manager_inspection_failed", "manager_rework", "manager_reject"} for item in events):
        first_pass_acceptance = False
    elif inspection_pass:
        first_pass_acceptance = True
    else:
        first_pass_acceptance = None

    if hard_stop:
        state, action, reason = "stopped", "stop_and_report", hard_stop["evidence"]["code"]
    elif accepted:
        state, action, reason = "completed", "publish_manager_receipt", "manager accepted the verified receipt"
    elif rejected:
        state, action, reason = "rejected", "report_rejection", rejected["evidence"]["reason"]
    elif latest_late_artifact and not late_review:
        state, action, reason = "late_output_quarantined", "quarantine_and_inspect_late_output", "late output requires an independent quality decision"
    elif late_review and late_review["evidence"]["decision"] == "reject":
        state, action, reason = "late_output_rejected", "manager_decide_rejected_late_output", "manager rejected the late output on quality"
    elif late_review and late_review["evidence"]["decision"] == "rework":
        if sum(item["event"] == "rework_started" for item in events) >= contract["control"]["max_rework_cycles"]:
            state, action, reason = "rework_exhausted", "escalate_rework_exhausted", "late-output defects remain after the rework budget"
        else:
            state, action, reason = "rework_required", "exact_rework", "manager found bounded defects in late output"
    elif manager_rework or inspection_failure_is_latest:
        if sum(item["event"] == "rework_started" for item in events) >= contract["control"]["max_rework_cycles"]:
            state, action, reason = "rework_exhausted", "escalate_rework_exhausted", "named defects remain after the rework budget"
        else:
            state, action, reason = "rework_required", "exact_rework", "manager inspection named bounded defects"
    elif receipt:
        state, action, reason = "decision_ready", "manager_decide_now", "receipt exists and verifies"
    elif verification and inspection_pass:
        state, action, reason = "acceptance_ready", "materialize_receipt_now", "all acceptance inputs are complete"
    elif verification:
        state, action, reason = "inspection_ready", "manager_inspect_now", "verification passed; direct inspection is next"
    elif candidate:
        if cycle_elapsed > slos["verification_seconds"] and not inflight_is_fresh:
            state, action, reason = "verification_late", "send_precise_intervention", "verification SLO missed without fresh in-flight evidence"
        elif cycle_elapsed > slos["verification_seconds"]:
            state, action, reason = "verification_inflight", "continue_bounded_grace", "verification is observably in flight"
        else:
            state, action, reason = "candidate_ready", "verify_candidate", "runnable candidate exists"
    elif first_artifact:
        if cycle_elapsed > slos["runnable_candidate_seconds"] and not inflight_is_fresh:
            state, action, reason = "candidate_late", "send_precise_intervention", "candidate SLO missed without fresh in-flight evidence"
        elif cycle_elapsed > slos["runnable_candidate_seconds"]:
            state, action, reason = "candidate_inflight", "continue_bounded_grace", "candidate work is observably in flight"
        else:
            state, action, reason = "materialized", "produce_runnable_candidate", "at least one real artifact exists"
    elif cycle_elapsed > slos["first_artifact_seconds"] and inflight_is_fresh:
        state, action, reason = "materialization_inflight", "continue_bounded_grace", "first artifact is late but work is observably in flight"
    elif cycle_elapsed > slos["first_artifact_seconds"]:
        state, action, reason = "materialization_late", "send_precise_intervention", "first artifact SLO missed without fresh in-flight evidence"
    else:
        state, action, reason = "materializing", "materialize_first_artifact", "no real artifact exists yet"

    return {
        "schema": "company-os.force-evaluation.v1",
        "ok": True,
        "task_id": contract["task_id"],
        "state": state,
        "next_action": action,
        "reason": reason,
        "metrics": {
            "elapsed_seconds": elapsed,
            "first_artifact_seconds": None if not first_artifact else first_artifact["at_epoch"] - cycle_started,
            "runnable_candidate_seconds": None if not candidate else candidate["at_epoch"] - cycle_started,
            "verification_seconds": None if not verification else verification["at_epoch"] - cycle_started,
            "acceptance_to_receipt_seconds": None if not (inspection_pass and receipt) else receipt["at_epoch"] - inspection_pass["at_epoch"],
            "receipt_to_decision_seconds": None if not (receipt and terminal_manager) else terminal_manager["at_epoch"] - receipt["at_epoch"],
            "first_pass_acceptance": first_pass_acceptance,
            "rework_count": sum(item["event"] == "rework_started" for item in events),
            "manager_intervention_count": sum(item["event"] == "intervention_sent" for item in events),
            "soft_slo_misses": sorted(soft_miss_set),
            "hard_stop_count": sum(item["event"] == "hard_stop" for item in events),
        },
        "bindings": {
            "contract_sha256": canonical_sha256(contract),
            "event_log_sha256": canonical_sha256(events),
            "artifact_set_sha256": canonical_sha256(
                [
                    {
                        "event": item["event"],
                        "path": item["evidence"]["path"],
                        "sha256": item["evidence"]["sha256"],
                    }
                    for item in events
                    if item["event"] in {"artifact_materialized", "receipt_materialized"}
                ]
            ),
            "last_sequence": events[-1]["sequence"],
        },
    }


def parser() -> argparse.ArgumentParser:
    root = argparse.ArgumentParser()
    commands = root.add_subparsers(dest="command", required=True)
    for name in ("validate", "evaluate"):
        command = commands.add_parser(name)
        command.add_argument("--contract", type=Path, required=True)
        command.add_argument("--events", type=Path, required=True)
        command.add_argument("--artifact-root", type=Path, required=True)
        if name == "evaluate":
            command.add_argument("--now-epoch", type=int, required=True)
    return root


def main(argv: list[str] | None = None) -> int:
    args = parser().parse_args(argv)
    try:
        contract = read_contract(args.contract)
        events = read_events(args.events, contract, args.artifact_root)
        if args.command == "validate":
            result = {
                "schema": "company-os.force-validation.v1",
                "ok": True,
                "task_id": contract["task_id"],
                "contract_sha256": canonical_sha256(contract),
                "event_log_sha256": canonical_sha256(events),
                "artifact_set_sha256": canonical_sha256(
                    [
                        {
                            "event": item["event"],
                            "path": item["evidence"]["path"],
                            "sha256": item["evidence"]["sha256"],
                        }
                        for item in events
                        if item["event"] in {"artifact_materialized", "receipt_materialized"}
                    ]
                ),
                "event_count": len(events),
            }
        else:
            result = evaluate(contract, events, args.now_epoch)
    except ForceContractError as error:
        print(json.dumps({"ok": False, "error": str(error)}, sort_keys=True, separators=(",", ":")))
        return 1
    print(json.dumps(result, sort_keys=True, separators=(",", ":")))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Evaluate authenticated, predeclared release scope without weakening gates."""

from __future__ import annotations

import argparse
import hashlib
import json
import math
import re
import stat
from pathlib import Path
from typing import Any

import force_loop_controller as force
import rsa_trust
import seal_force_snapshot as force_snapshot


CONTRACT_SCHEMA = "company-os.release-scope.v1"
STATUS_SCHEMA = "company-os.release-status.v1"
DESIGN_DECISION_SCHEMA = "company-os.release-scope-design-decision.v1"
DELIVERABLE_RECEIPT_SCHEMA = "company-os.release-deliverable-receipt.v1"
SNAPSHOT_RECEIPT_SCHEMA = "company-os.force-log-snapshot.v1"
ADMISSION_SCHEMA = "company-os.release-scope-admission.v1"
ADMISSION_VERIFICATION_SCHEMA = "company-os.release-scope-admission-verification.v1"
ADMISSION_REGISTRY_SCHEMA = "company-os.release-scope-admission-registry.v1"
AUTH_SCHEME = rsa_trust.SCHEME
IDENTIFIER = re.compile(r"^[a-z0-9][a-z0-9._:-]*$")
HEX64 = re.compile(r"^[0-9a-f]{64}$")
SAFE_PATH = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._/-]*$")
REGISTRY_FILE = re.compile(r"^definition-([0-9]{8})\.json$")


class ReleaseScopeError(ValueError):
    """Raised when release-scope evidence is invalid."""


def canonical_bytes(value: Any) -> bytes:
    try:
        return json.dumps(
            value,
            sort_keys=True,
            separators=(",", ":"),
            ensure_ascii=False,
            allow_nan=False,
        ).encode("utf-8")
    except (TypeError, ValueError, UnicodeError, OverflowError) as error:
        raise ReleaseScopeError(f"value is not canonical JSON: {error}") from error


def canonical_sha256(value: Any) -> str:
    return hashlib.sha256(canonical_bytes(value)).hexdigest()


def _exact_keys(value: dict[str, Any], expected: set[str], label: str) -> None:
    actual = set(value)
    if actual != expected:
        raise ReleaseScopeError(
            f"{label} keys differ; extra={sorted(actual - expected)!r}, "
            f"missing={sorted(expected - actual)!r}"
        )


def _identifier(value: Any, label: str) -> str:
    if not isinstance(value, str) or not IDENTIFIER.fullmatch(value):
        raise ReleaseScopeError(f"{label} is invalid")
    return value


def _digest(value: Any, label: str) -> str:
    if not isinstance(value, str) or not HEX64.fullmatch(value):
        raise ReleaseScopeError(f"{label} must be lowercase SHA-256")
    return value


def _safe_path(value: Any, label: str) -> str:
    if not isinstance(value, str) or not SAFE_PATH.fullmatch(value):
        raise ReleaseScopeError(f"{label} must be a safe project-relative path")
    if value.startswith("/") or "//" in value or any(
        part in {"", ".", ".."} for part in value.split("/")
    ):
        raise ReleaseScopeError(f"{label} must not escape or contain ambiguous segments")
    return value


def _root(path: Path) -> Path:
    if path.is_symlink():
        raise ReleaseScopeError("artifact root must not be a symlink")
    try:
        resolved = path.resolve(strict=True)
    except OSError as error:
        raise ReleaseScopeError(f"artifact root could not be resolved: {error}") from error
    if not resolved.is_dir():
        raise ReleaseScopeError("artifact root must be a directory")
    return resolved


def _trusted_master_public_key(root: Path, path: Path) -> Path:
    """Resolve the host trust anchor and keep it outside manager-owned evidence."""
    if path.is_symlink():
        raise ReleaseScopeError("trusted master public key must not be a symlink")
    try:
        resolved = path.resolve(strict=True)
    except OSError as error:
        raise ReleaseScopeError(
            f"trusted master public key could not be resolved: {error}"
        ) from error
    if resolved == root or root in resolved.parents:
        raise ReleaseScopeError(
            "trusted master public key must be supplied outside the artifact root"
        )
    try:
        rsa_trust.read_public_key(resolved, "trusted master public key")
    except rsa_trust.TrustError as error:
        raise ReleaseScopeError(str(error)) from error
    return resolved


def _trusted_admission_registry(root: Path, path: Path) -> Path:
    if path.is_symlink():
        raise ReleaseScopeError("trusted admission registry must not be a symlink")
    try:
        resolved = path.resolve(strict=True)
        status = resolved.lstat()
    except OSError as error:
        raise ReleaseScopeError(
            f"trusted admission registry could not be resolved: {error}"
        ) from error
    if not stat.S_ISDIR(status.st_mode):
        raise ReleaseScopeError("trusted admission registry must be a directory")
    if resolved == root or root in resolved.parents:
        raise ReleaseScopeError(
            "trusted admission registry must be supplied outside the artifact root"
        )
    return resolved


def _registry_program_directory(
    registry_root: Path,
    contract: dict[str, Any],
    *,
    create: bool,
) -> Path:
    current = registry_root
    for key in ("project_id", "program_id", "cycle_id"):
        part = _identifier(contract[key], f"registry.{key}")
        current = current / part
        if create:
            try:
                current.mkdir(mode=0o700)
                force_snapshot._fsync_directory(current.parent)
            except FileExistsError:
                pass
            except OSError as error:
                raise ReleaseScopeError(
                    f"trusted admission registry could not create its program path: {error}"
                ) from error
        try:
            status = current.lstat()
        except FileNotFoundError as error:
            raise ReleaseScopeError("release scope has no registered admission") from error
        except OSError as error:
            raise ReleaseScopeError(
                f"trusted admission registry program path is unreadable: {error}"
            ) from error
        if stat.S_ISLNK(status.st_mode) or not stat.S_ISDIR(status.st_mode):
            raise ReleaseScopeError(
                "trusted admission registry program path must be a real directory"
            )
    return current


def _admission_registry_record(
    contract: dict[str, Any],
    trusted_master_public_key: Path,
) -> dict[str, Any]:
    try:
        raw_key, _, _ = rsa_trust.read_public_key(
            trusted_master_public_key, "trusted master public key"
        )
    except rsa_trust.TrustError as error:
        raise ReleaseScopeError(str(error)) from error
    return {
        "schema": ADMISSION_REGISTRY_SCHEMA,
        "project_id": contract["project_id"],
        "program_id": contract["program_id"],
        "program_version": contract["program_version"],
        "definition_version": contract["definition_version"],
        "cycle_id": contract["cycle_id"],
        "scope_admission_sha256": contract["scope_admission"]["sha256"],
        "scope_definition_sha256": scope_definition_sha256(contract),
        "predecessor_admission_sha256": contract["predecessor_admission_sha256"],
        "trusted_master_public_key_sha256": hashlib.sha256(raw_key).hexdigest(),
    }


def _read_registry_records(directory: Path) -> list[dict[str, Any]]:
    records: list[dict[str, Any]] = []
    try:
        entries = sorted(directory.iterdir(), key=lambda item: item.name)
    except OSError as error:
        raise ReleaseScopeError(f"trusted admission registry is unreadable: {error}") from error
    for entry in entries:
        match = REGISTRY_FILE.fullmatch(entry.name)
        if match is None:
            raise ReleaseScopeError(
                f"trusted admission registry contains an unexpected entry: {entry.name}"
            )
        if entry.is_symlink():
            raise ReleaseScopeError("trusted admission registry contains a symlink")
        try:
            status = entry.lstat()
            raw = entry.read_bytes()
            value = json.loads(raw)
        except (OSError, UnicodeError, json.JSONDecodeError) as error:
            raise ReleaseScopeError(
                f"trusted admission registry record is unreadable: {entry.name}"
            ) from error
        if not stat.S_ISREG(status.st_mode) or not isinstance(value, dict):
            raise ReleaseScopeError("trusted admission registry record is not canonical JSON")
        if raw != canonical_bytes(value) + b"\n":
            raise ReleaseScopeError("trusted admission registry record bytes are noncanonical")
        _exact_keys(
            value,
            {
                "schema",
                "project_id",
                "program_id",
                "program_version",
                "definition_version",
                "cycle_id",
                "scope_admission_sha256",
                "scope_definition_sha256",
                "predecessor_admission_sha256",
                "trusted_master_public_key_sha256",
            },
            "trusted admission registry record",
        )
        version = int(match.group(1))
        if (
            value["schema"] != ADMISSION_REGISTRY_SCHEMA
            or isinstance(value["definition_version"], bool)
            or not isinstance(value["definition_version"], int)
            or value["definition_version"] != version
            or isinstance(value["program_version"], bool)
            or not isinstance(value["program_version"], int)
            or value["program_version"] < 1
        ):
            raise ReleaseScopeError("trusted admission registry version binding is invalid")
        for key in ("project_id", "program_id", "cycle_id"):
            _identifier(value[key], f"trusted admission registry record.{key}")
        for key in (
            "scope_admission_sha256",
            "scope_definition_sha256",
            "predecessor_admission_sha256",
            "trusted_master_public_key_sha256",
        ):
            _digest(value[key], f"trusted admission registry record.{key}")
        records.append(value)
    for index, record in enumerate(records, start=1):
        if record["definition_version"] != index:
            raise ReleaseScopeError("trusted admission registry versions are not contiguous")
        expected_predecessor = (
            "0" * 64 if index == 1 else records[index - 2]["scope_admission_sha256"]
        )
        if record["predecessor_admission_sha256"] != expected_predecessor:
            raise ReleaseScopeError("trusted admission registry lineage is broken")
    return records


def _register_admission(
    contract: dict[str, Any],
    artifact_root: Path,
    trusted_master_public_key: Path,
    trusted_admission_registry: Path,
) -> dict[str, Any]:
    root = _root(artifact_root)
    key = _trusted_master_public_key(root, trusted_master_public_key)
    registry = _trusted_admission_registry(root, trusted_admission_registry)
    directory = _registry_program_directory(registry, contract, create=True)
    records = _read_registry_records(directory)
    expected = _admission_registry_record(contract, key)
    identity_keys = {
        "project_id",
        "program_id",
        "program_version",
        "cycle_id",
        "trusted_master_public_key_sha256",
    }
    if any(
        any(record[item] != expected[item] for item in identity_keys)
        for record in records
    ):
        raise ReleaseScopeError("trusted admission registry identity lineage is broken")
    version = contract["definition_version"]
    if version <= len(records):
        if version == len(records) and records[version - 1] == expected:
            return expected
        raise ReleaseScopeError(
            "release scope definition version is already registered with different bytes"
        )
    if version != len(records) + 1:
        raise ReleaseScopeError(
            "release scope definition version must advance exactly one registered predecessor"
        )
    expected_predecessor = (
        "0" * 64 if not records else records[-1]["scope_admission_sha256"]
    )
    if contract["predecessor_admission_sha256"] != expected_predecessor:
        raise ReleaseScopeError(
            "release scope predecessor does not match the trusted admission registry head"
        )
    target = directory / f"definition-{version:08d}.json"
    try:
        force_snapshot._exclusive_write(target, canonical_bytes(expected) + b"\n")
    except force.ForceContractError as error:
        raise ReleaseScopeError(f"release scope admission could not be registered: {error}") from error
    return expected


def _verify_registered_admission(
    contract: dict[str, Any],
    artifact_root: Path,
    trusted_master_public_key: Path,
    trusted_admission_registry: Path,
) -> dict[str, Any]:
    root = _root(artifact_root)
    key = _trusted_master_public_key(root, trusted_master_public_key)
    registry = _trusted_admission_registry(root, trusted_admission_registry)
    directory = _registry_program_directory(registry, contract, create=False)
    records = _read_registry_records(directory)
    version = contract["definition_version"]
    expected = _admission_registry_record(contract, key)
    identity_keys = {
        "project_id",
        "program_id",
        "program_version",
        "cycle_id",
        "trusted_master_public_key_sha256",
    }
    if any(
        any(record[item] != expected[item] for item in identity_keys)
        for record in records
    ):
        raise ReleaseScopeError("trusted admission registry identity lineage is broken")
    if not records or version != len(records) or records[-1] != expected:
        raise ReleaseScopeError(
            "release scope is not the current exact trusted admission"
        )
    return expected


def _verified_file(
    root: Path, item: dict[str, Any], label: str
) -> tuple[Path, bytes]:
    _exact_keys(item, {"path", "sha256"}, label)
    relative = _safe_path(item["path"], f"{label}.path")
    digest = _digest(item["sha256"], f"{label}.sha256")
    current = root
    parts = relative.split("/")
    for index, part in enumerate(parts):
        current = current / part
        try:
            status = current.lstat()
        except OSError as error:
            raise ReleaseScopeError(f"{label} path is missing: {relative}") from error
        if stat.S_ISLNK(status.st_mode):
            raise ReleaseScopeError(f"{label} path contains a symlink: {relative}")
        if index < len(parts) - 1 and not stat.S_ISDIR(status.st_mode):
            raise ReleaseScopeError(f"{label} parent is not a directory: {relative}")
        if index == len(parts) - 1 and not stat.S_ISREG(status.st_mode):
            raise ReleaseScopeError(f"{label} is not a regular file: {relative}")
    try:
        raw = current.read_bytes()
    except OSError as error:
        raise ReleaseScopeError(f"{label} could not be read: {relative}") from error
    if hashlib.sha256(raw).hexdigest() != digest:
        raise ReleaseScopeError(f"{label} digest does not match exact bytes: {relative}")
    return current, raw


def _canonical_json_evidence(
    root: Path, item: dict[str, Any], label: str
) -> dict[str, Any]:
    _, raw = _verified_file(root, item, label)
    try:
        value = json.loads(raw)
    except (UnicodeError, json.JSONDecodeError) as error:
        raise ReleaseScopeError(f"{label} must be canonical JSON") from error
    if not isinstance(value, dict) or raw != canonical_bytes(value) + b"\n":
        raise ReleaseScopeError(f"{label} must be a canonical JSON object")
    return value


def scope_definition(contract: dict[str, Any]) -> dict[str, Any]:
    return {
        key: contract[key]
        for key in (
            "schema",
            "project_id",
            "program_id",
            "program_version",
            "definition_version",
            "cycle_id",
            "master_task_id",
            "outcome_digest",
            "predecessor_admission_sha256",
            "admission_verification_path",
            "deliverables",
            "policy",
        )
    }


def scope_definition_sha256(contract: dict[str, Any]) -> str:
    return canonical_sha256(scope_definition(contract))


def signature_payload(record: dict[str, Any]) -> bytes:
    try:
        return canonical_bytes(rsa_trust.unsigned_record(record))
    except rsa_trust.TrustError as error:
        raise ReleaseScopeError(str(error)) from error


def _verify_signed_record(
    record: dict[str, Any], public_key_path: Path, label: str
) -> str:
    try:
        return rsa_trust.verify_record(
            record,
            signature_payload(record),
            public_key_path,
            label,
        )
    except rsa_trust.TrustError as error:
        raise ReleaseScopeError(str(error)) from error


def _validate_design_decision(
    contract: dict[str, Any], root: Path, trusted_master_public_key: Path
) -> dict[str, Any]:
    reference = contract["accepted_design_decision"]
    if not isinstance(reference, dict):
        raise ReleaseScopeError("accepted_design_decision must be an evidence reference")
    decision = _canonical_json_evidence(root, reference, "accepted design decision")
    _exact_keys(
        decision,
        {
            "schema",
            "record_version",
            "decision",
            "authority_role",
            "decider_task_id",
            "bindings",
            "authentication",
        },
        "accepted design decision",
    )
    if decision["schema"] != DESIGN_DECISION_SCHEMA or decision["record_version"] != 1:
        raise ReleaseScopeError("accepted design decision schema/version is invalid")
    if decision["decision"] != "accepted" or decision["authority_role"] != "master":
        raise ReleaseScopeError("release scope lacks an accepted master design decision")
    if decision["decider_task_id"] != contract["master_task_id"]:
        raise ReleaseScopeError("release scope design decider does not match master task")
    bindings = decision["bindings"]
    if not isinstance(bindings, dict):
        raise ReleaseScopeError("accepted design decision bindings are invalid")
    _exact_keys(
        bindings,
        {
            "project_id",
            "program_id",
            "program_version",
            "definition_version",
            "cycle_id",
            "outcome_digest",
            "predecessor_admission_sha256",
            "scope_definition_sha256",
        },
        "accepted design decision bindings",
    )
    expected = {
        "project_id": contract["project_id"],
        "program_id": contract["program_id"],
        "program_version": contract["program_version"],
        "definition_version": contract["definition_version"],
        "cycle_id": contract["cycle_id"],
        "outcome_digest": contract["outcome_digest"],
        "predecessor_admission_sha256": contract["predecessor_admission_sha256"],
        "scope_definition_sha256": scope_definition_sha256(contract),
    }
    if bindings != expected:
        raise ReleaseScopeError("accepted design decision does not bind exact pre-dispatch scope")
    _verify_signed_record(decision, trusted_master_public_key, "accepted design decision")
    return decision


def _validate_admission_shape(
    admission: dict[str, Any],
    trusted_master_public_key: Path,
    label: str,
) -> dict[str, Any]:
    _exact_keys(
        admission,
        {
            "schema",
            "record_version",
            "admission_id",
            "decision",
            "bindings",
            "accepted_design_decision",
            "authentication",
        },
        label,
    )
    if admission["schema"] != ADMISSION_SCHEMA or admission["record_version"] != 1:
        raise ReleaseScopeError(f"{label} schema/version is invalid")
    _identifier(admission["admission_id"], f"{label}.admission_id")
    if admission["decision"] != "admitted_pre_dispatch":
        raise ReleaseScopeError(f"{label} is not a pre-dispatch admission")
    bindings = admission["bindings"]
    if not isinstance(bindings, dict):
        raise ReleaseScopeError(f"{label} bindings are invalid")
    _exact_keys(
        bindings,
        {
            "project_id",
            "program_id",
            "program_version",
            "definition_version",
            "cycle_id",
            "master_task_id",
            "outcome_digest",
            "scope_definition_sha256",
            "predecessor_admission_sha256",
            "accepted_design_decision_sha256",
        },
        f"{label} bindings",
    )
    if not isinstance(admission["accepted_design_decision"], dict):
        raise ReleaseScopeError(f"{label} design-decision reference is invalid")
    _exact_keys(
        admission["accepted_design_decision"],
        {"path", "sha256"},
        f"{label}.accepted_design_decision",
    )
    for key in (
        "outcome_digest",
        "scope_definition_sha256",
        "predecessor_admission_sha256",
        "accepted_design_decision_sha256",
    ):
        _digest(bindings[key], f"{label}.bindings.{key}")
    if (
        bindings["accepted_design_decision_sha256"]
        != admission["accepted_design_decision"]["sha256"]
    ):
        raise ReleaseScopeError(
            f"{label} design-decision digest does not match its evidence reference"
        )
    _verify_signed_record(admission, trusted_master_public_key, label)
    return admission


def _validate_predecessor_admission(
    contract: dict[str, Any],
    root: Path,
    trusted_master_public_key: Path,
) -> None:
    reference = contract["predecessor_scope_admission"]
    digest = contract["predecessor_admission_sha256"]
    if contract["definition_version"] == 1:
        if reference is not None or digest != "0" * 64:
            raise ReleaseScopeError(
                "definition version one must not claim a predecessor admission"
            )
        return
    if not isinstance(reference, dict) or reference.get("sha256") != digest:
        raise ReleaseScopeError(
            "scope change requires the exact predecessor admission reference"
        )
    predecessor = _canonical_json_evidence(root, reference, "predecessor scope admission")
    _validate_admission_shape(
        predecessor,
        trusted_master_public_key,
        "predecessor scope admission",
    )
    bindings = predecessor["bindings"]
    expected = {
        "project_id": contract["project_id"],
        "program_id": contract["program_id"],
        "program_version": contract["program_version"],
        "definition_version": contract["definition_version"] - 1,
    }
    if any(bindings.get(key) != value for key, value in expected.items()):
        raise ReleaseScopeError(
            "predecessor admission does not form an exact definition lineage"
        )


def _validate_scope_admission(
    contract: dict[str, Any],
    root: Path,
    trusted_master_public_key: Path,
) -> dict[str, Any]:
    reference = contract["scope_admission"]
    if not isinstance(reference, dict):
        raise ReleaseScopeError("scope_admission must be an evidence reference")
    admission = _canonical_json_evidence(root, reference, "scope admission")
    _validate_admission_shape(admission, trusted_master_public_key, "scope admission")
    expected_bindings = {
        "project_id": contract["project_id"],
        "program_id": contract["program_id"],
        "program_version": contract["program_version"],
        "definition_version": contract["definition_version"],
        "cycle_id": contract["cycle_id"],
        "master_task_id": contract["master_task_id"],
        "outcome_digest": contract["outcome_digest"],
        "scope_definition_sha256": scope_definition_sha256(contract),
        "predecessor_admission_sha256": contract["predecessor_admission_sha256"],
        "accepted_design_decision_sha256": contract["accepted_design_decision"]["sha256"],
    }
    if admission["bindings"] != expected_bindings:
        raise ReleaseScopeError("scope admission does not bind exact pre-dispatch scope")
    if admission["accepted_design_decision"] != contract["accepted_design_decision"]:
        raise ReleaseScopeError("scope admission does not bind the accepted design decision bytes")
    return admission


def _validate_contract_structure(
    value: Any,
    artifact_root: Path,
    trusted_master_public_key: Path,
) -> dict[str, Any]:
    if not isinstance(value, dict):
        raise ReleaseScopeError("release scope contract must be an object")
    _exact_keys(
        value,
        {
            "schema",
            "project_id",
            "program_id",
            "program_version",
            "definition_version",
            "cycle_id",
            "master_task_id",
            "outcome_digest",
            "predecessor_admission_sha256",
            "predecessor_scope_admission",
            "admission_verification_path",
            "deliverables",
            "policy",
            "accepted_design_decision",
            "scope_admission",
        },
        "release scope contract",
    )
    if value["schema"] != CONTRACT_SCHEMA:
        raise ReleaseScopeError("release scope contract schema is unsupported")
    for key in ("project_id", "program_id", "cycle_id", "master_task_id"):
        _identifier(value[key], key)
    for key in ("program_version", "definition_version"):
        if isinstance(value[key], bool) or not isinstance(value[key], int) or value[key] < 1:
            raise ReleaseScopeError(f"{key} must be a positive integer")
    _digest(value["outcome_digest"], "outcome_digest")
    _digest(value["predecessor_admission_sha256"], "predecessor_admission_sha256")
    root = _root(artifact_root)
    trusted_master_public_key = _trusted_master_public_key(
        root, trusted_master_public_key
    )
    _safe_path(value["admission_verification_path"], "admission_verification_path")
    policy = value["policy"]
    if not isinstance(policy, dict):
        raise ReleaseScopeError("policy must be an object")
    _exact_keys(
        policy,
        {"required_failure", "optional_failure", "max_optional_recovery_chains"},
        "policy",
    )
    if policy["required_failure"] != "block_release":
        raise ReleaseScopeError("required_failure must be block_release")
    if policy["optional_failure"] != "omit_without_quality_relaxation":
        raise ReleaseScopeError("optional_failure must be omit_without_quality_relaxation")
    if (
        isinstance(policy["max_optional_recovery_chains"], bool)
        or not isinstance(policy["max_optional_recovery_chains"], int)
        or not 0 <= policy["max_optional_recovery_chains"] <= 2
    ):
        raise ReleaseScopeError("max_optional_recovery_chains must be between zero and two")
    deliverables = value["deliverables"]
    if not isinstance(deliverables, list) or not deliverables:
        raise ReleaseScopeError("deliverables must be a non-empty list")
    ids: list[str] = []
    required_count = 0
    for index, item in enumerate(deliverables):
        if not isinstance(item, dict):
            raise ReleaseScopeError(f"deliverables[{index}] must be an object")
        _exact_keys(
            item,
            {
                "deliverable_id",
                "manager_task_id",
                "manager_public_key",
                "manager_charter",
                "criticality",
                "outcome_contribution",
            },
            f"deliverables[{index}]",
        )
        ids.append(_identifier(item["deliverable_id"], f"deliverables[{index}].deliverable_id"))
        _identifier(item["manager_task_id"], f"deliverables[{index}].manager_task_id")
        manager_key = item["manager_public_key"]
        if not isinstance(manager_key, dict):
            raise ReleaseScopeError(f"deliverables[{index}].manager_public_key is invalid")
        manager_key_path, _ = _verified_file(
            root,
            manager_key,
            f"deliverables[{index}].manager_public_key",
        )
        try:
            rsa_trust.read_public_key(
                manager_key_path,
                f"deliverables[{index}].manager_public_key",
            )
        except rsa_trust.TrustError as error:
            raise ReleaseScopeError(str(error)) from error
        manager_charter = item["manager_charter"]
        if not isinstance(manager_charter, dict):
            raise ReleaseScopeError(f"deliverables[{index}].manager_charter is invalid")
        _validate_manager_charter(
            value,
            root,
            manager_charter,
            item["manager_task_id"],
            f"deliverables[{index}].manager_charter",
        )
        if item["criticality"] not in {"required", "optional"}:
            raise ReleaseScopeError(f"deliverables[{index}].criticality is invalid")
        required_count += item["criticality"] == "required"
        if not isinstance(item["outcome_contribution"], str) or not item[
            "outcome_contribution"
        ].strip():
            raise ReleaseScopeError(f"deliverables[{index}].outcome_contribution is empty")
    if len(ids) != len(set(ids)):
        raise ReleaseScopeError("deliverable identifiers must be unique")
    if required_count == 0:
        raise ReleaseScopeError("at least one deliverable must be required")
    _validate_design_decision(value, root, trusted_master_public_key)
    _validate_predecessor_admission(value, root, trusted_master_public_key)
    _validate_scope_admission(value, root, trusted_master_public_key)
    return value


def validate_contract(
    value: Any,
    artifact_root: Path,
    trusted_master_public_key: Path,
    trusted_admission_registry: Path,
) -> dict[str, Any]:
    contract = _validate_contract_structure(
        value,
        artifact_root,
        trusted_master_public_key,
    )
    _verify_registered_admission(
        contract,
        artifact_root,
        trusted_master_public_key,
        trusted_admission_registry,
    )
    return contract


def build_admission_verification(
    contract: dict[str, Any],
    artifact_root: Path,
    trusted_master_public_key: Path,
    trusted_admission_registry: Path,
) -> dict[str, Any]:
    contract = validate_contract(
        contract,
        artifact_root,
        trusted_master_public_key,
        trusted_admission_registry,
    )
    registry_record = _verify_registered_admission(
        contract,
        artifact_root,
        trusted_master_public_key,
        trusted_admission_registry,
    )
    decision = _canonical_json_evidence(
        _root(artifact_root),
        contract["accepted_design_decision"],
        "accepted design decision",
    )
    return {
        "schema": ADMISSION_VERIFICATION_SCHEMA,
        "ok": True,
        "project_id": contract["project_id"],
        "program_id": contract["program_id"],
        "program_version": contract["program_version"],
        "definition_version": contract["definition_version"],
        "cycle_id": contract["cycle_id"],
        "admission_verification_path": contract["admission_verification_path"],
        "scope_definition_sha256": scope_definition_sha256(contract),
        "scope_contract_sha256": canonical_sha256(contract),
        "registry_record_sha256": canonical_sha256(registry_record),
        "scope_admission": contract["scope_admission"],
        "accepted_design_decision": contract["accepted_design_decision"],
        "master_public_key_sha256": decision["authentication"]["public_key_sha256"],
    }


def write_admission_verification(
    contract: dict[str, Any],
    artifact_root: Path,
    trusted_master_public_key: Path,
    trusted_admission_registry: Path,
) -> dict[str, Any]:
    """Materialize the deterministic pre-dispatch gate at its signed path."""
    root = _root(artifact_root)
    contract = _validate_contract_structure(
        contract,
        root,
        trusted_master_public_key,
    )
    _register_admission(
        contract,
        root,
        trusted_master_public_key,
        trusted_admission_registry,
    )
    value = build_admission_verification(
        contract,
        root,
        trusted_master_public_key,
        trusted_admission_registry,
    )
    relative = contract["admission_verification_path"]
    target, existing = force_snapshot._safe_target(root, relative)
    content = canonical_bytes(value) + b"\n"
    if existing is not None and existing != content:
        raise ReleaseScopeError(
            "existing admission verification conflicts with the admitted scope"
        )
    if existing is None:
        try:
            force_snapshot._exclusive_write(target, content)
        except force.ForceContractError as error:
            raise ReleaseScopeError(
                f"admission verification could not be materialized: {error}"
            ) from error
    return {
        **value,
        "evidence": {
            "path": relative,
            "sha256": hashlib.sha256(content).hexdigest(),
        },
    }


def _validate_snapshot_receipt(
    root: Path,
    reference: dict[str, Any],
    force_contract_reference: dict[str, Any],
    expected_terminal: str,
    expected_task_id: str,
    label: str,
) -> dict[str, Any]:
    force_contract_path, _ = _verified_file(
        root,
        force_contract_reference,
        f"{label}.force_contract",
    )
    try:
        force_contract = force.read_contract(force_contract_path)
    except force.ForceContractError as error:
        raise ReleaseScopeError(f"{label} force contract is invalid: {error}") from error
    if force_contract["task_id"] != expected_task_id:
        raise ReleaseScopeError(f"{label} force contract task does not match terminal receipt")
    snapshot = _canonical_json_evidence(root, reference, label)
    _exact_keys(
        snapshot,
        {
            "schema",
            "task_id",
            "contract_sha256",
            "snapshot_path",
            "snapshot_sha256",
            "event_count",
            "terminal",
            "artifact_set_sha256",
        },
        label,
    )
    if snapshot["schema"] != SNAPSHOT_RECEIPT_SCHEMA:
        raise ReleaseScopeError(f"{label} schema is invalid")
    if snapshot["task_id"] != expected_task_id:
        raise ReleaseScopeError(f"{label} task does not match terminal receipt")
    terminal = snapshot["terminal"]
    if not isinstance(terminal, dict):
        raise ReleaseScopeError(f"{label} terminal evidence is invalid")
    _exact_keys(terminal, {"event", "sequence", "at_epoch"}, f"{label} terminal")
    if terminal["event"] != expected_terminal:
        raise ReleaseScopeError(f"{label} terminal decision does not match disposition")
    for key in ("contract_sha256", "snapshot_sha256", "artifact_set_sha256"):
        _digest(snapshot[key], f"{label}.{key}")
    snapshot_path = _safe_path(snapshot["snapshot_path"], f"{label}.snapshot_path")
    _verified_file(
        root,
        {"path": snapshot_path, "sha256": snapshot["snapshot_sha256"]},
        f"{label}.snapshot",
    )
    if (
        isinstance(snapshot["event_count"], bool)
        or not isinstance(snapshot["event_count"], int)
        or snapshot["event_count"] < 1
    ):
        raise ReleaseScopeError(f"{label} event_count is invalid")
    try:
        verification = force_snapshot.verify(
            force_contract_path,
            root,
            snapshot_path,
            reference["path"],
        )
    except force.ForceContractError as error:
        raise ReleaseScopeError(f"{label} sealed force evidence is invalid: {error}") from error
    if verification["terminal_event"] != expected_terminal:
        raise ReleaseScopeError(f"{label} verified terminal decision does not match disposition")
    if expected_terminal == "manager_reject" and not verification[
        "terminal_rejection_inspected"
    ]:
        raise ReleaseScopeError(
            f"{label} rejection lacks verified failed inspection of the terminal candidate"
        )
    return {
        "artifacts": verification["terminal_artifacts"],
        "rework_cycles": verification["rework_cycles"],
    }


def _validate_admission_verification(
    contract: dict[str, Any],
    root: Path,
    reference: dict[str, Any],
    expected: dict[str, Any],
    label: str,
) -> None:
    if reference.get("path") != contract["admission_verification_path"]:
        raise ReleaseScopeError(f"{label} path differs from the pre-dispatch gate")
    value = _canonical_json_evidence(root, reference, label)
    if value != expected:
        raise ReleaseScopeError(f"{label} does not match the pre-dispatch admission gate")


def _validate_manager_charter(
    contract: dict[str, Any],
    root: Path,
    reference: dict[str, Any],
    manager_task_id: str,
    label: str,
) -> None:
    charter = _canonical_json_evidence(root, reference, label)
    if not isinstance(charter, dict) or charter.get("schema") != "company-os.mission-charter.v2":
        raise ReleaseScopeError(f"{label} schema is invalid")
    for key in ("program_version", "definition_version", "outcome_digest"):
        if charter.get(key) != contract[key]:
            raise ReleaseScopeError(f"{label} {key} does not match release scope")
    ids = charter.get("ids")
    expected_ids = {
        "project_id": contract["project_id"],
        "program_id": contract["program_id"],
        "cycle_id": contract["cycle_id"],
        "task_id": manager_task_id,
        "parent_task_id": contract["master_task_id"],
    }
    if not isinstance(ids, dict) or any(ids.get(key) != value for key, value in expected_ids.items()):
        raise ReleaseScopeError(f"{label} identity does not match release manager ownership")
    context = charter.get("task_local_context")
    paths = context.get("artifact_paths") if isinstance(context, dict) else None
    required_paths = {
        contract["scope_admission"]["path"],
        contract["admission_verification_path"],
    }
    if (
        not isinstance(paths, list)
        or any(not isinstance(path, str) for path in paths)
        or not required_paths.issubset(set(paths))
    ):
        raise ReleaseScopeError(
            f"{label} was not dispatched with the pre-dispatch admission evidence"
        )


def _validate_terminal_receipt(
    contract: dict[str, Any],
    root: Path,
    reference: dict[str, Any],
    deliverable_id: str,
    admission_verification: dict[str, Any],
    trusted_master_public_key: Path,
    label: str,
) -> dict[str, Any]:
    receipt = _canonical_json_evidence(root, reference, label)
    _exact_keys(
        receipt,
        {
            "schema",
            "project_id",
            "program_id",
            "program_version",
            "definition_version",
            "cycle_id",
            "deliverable_id",
            "manager_task_id",
            "attempt_chain",
            "force_task_id",
            "rework_cycles",
            "disposition",
            "manager_charter",
            "scope_admission_verification",
            "force_contract",
            "terminal_force_snapshot_receipt",
            "quality_score",
            "quality_gate_lowered",
            "defects",
            "artifact_evidence",
            "authentication",
        },
        label,
    )
    if receipt["schema"] != DELIVERABLE_RECEIPT_SCHEMA:
        raise ReleaseScopeError(f"{label} schema is invalid")
    expected_bindings = {
        "project_id": contract["project_id"],
        "program_id": contract["program_id"],
        "program_version": contract["program_version"],
        "definition_version": contract["definition_version"],
        "cycle_id": contract["cycle_id"],
        "deliverable_id": deliverable_id,
        "manager_task_id": next(
            item["manager_task_id"]
            for item in contract["deliverables"]
            if item["deliverable_id"] == deliverable_id
        ),
    }
    if any(receipt[key] != expected for key, expected in expected_bindings.items()):
        raise ReleaseScopeError(f"{label} does not bind exact release scope")
    definition = next(
        item for item in contract["deliverables"] if item["deliverable_id"] == deliverable_id
    )
    manager_key_path, _ = _verified_file(
        root,
        definition["manager_public_key"],
        f"{label}.manager_public_key",
    )
    _verify_signed_record(receipt, manager_key_path, label)
    admission_reference = receipt["scope_admission_verification"]
    manager_charter_reference = receipt["manager_charter"]
    if not isinstance(admission_reference, dict):
        raise ReleaseScopeError(f"{label} admission verification reference is invalid")
    if not isinstance(manager_charter_reference, dict):
        raise ReleaseScopeError(f"{label} manager charter reference is invalid")
    _validate_admission_verification(
        contract,
        root,
        admission_reference,
        admission_verification,
        f"{label}.scope_admission_verification",
    )
    if manager_charter_reference != definition["manager_charter"]:
        raise ReleaseScopeError(f"{label} manager charter differs from admitted scope")
    _validate_manager_charter(
        contract,
        root,
        manager_charter_reference,
        receipt["manager_task_id"],
        f"{label}.manager_charter",
    )
    _identifier(receipt["force_task_id"], f"{label}.force_task_id")
    for key in ("attempt_chain", "rework_cycles"):
        if isinstance(receipt[key], bool) or not isinstance(receipt[key], int) or receipt[key] < 0:
            raise ReleaseScopeError(f"{label}.{key} is invalid")
    if receipt["attempt_chain"] < 1 or receipt["rework_cycles"] > 3:
        raise ReleaseScopeError(f"{label} attempt/rework bounds are invalid")
    if receipt["disposition"] not in {"accepted", "rejected"}:
        raise ReleaseScopeError(f"{label} disposition is invalid")
    score = receipt["quality_score"]
    if isinstance(score, bool) or not isinstance(score, (int, float)) or not math.isfinite(score):
        raise ReleaseScopeError(f"{label} quality_score is invalid")
    if not 0 <= score <= 10:
        raise ReleaseScopeError(f"{label} quality_score must be between zero and ten")
    if receipt["quality_gate_lowered"] is not False:
        raise ReleaseScopeError(f"{label} lowered a quality gate")
    defects = receipt["defects"]
    if not isinstance(defects, list) or any(
        not isinstance(defect, str) or not defect.strip() for defect in defects
    ):
        raise ReleaseScopeError(f"{label} defects are invalid")
    if receipt["disposition"] == "accepted":
        if score < 9 or defects:
            raise ReleaseScopeError(f"{label} accepted below the quality threshold")
        terminal_event = "manager_accept"
    else:
        if score >= 9 or not defects:
            raise ReleaseScopeError(f"{label} rejected receipt must retain failed score and defects")
        terminal_event = "manager_reject"
    force_contract_reference = receipt["force_contract"]
    snapshot_reference = receipt["terminal_force_snapshot_receipt"]
    if not isinstance(force_contract_reference, dict):
        raise ReleaseScopeError(f"{label} force contract reference is invalid")
    if not isinstance(snapshot_reference, dict):
        raise ReleaseScopeError(f"{label} snapshot reference is invalid")
    terminal_force = _validate_snapshot_receipt(
        root,
        snapshot_reference,
        force_contract_reference,
        terminal_event,
        receipt["force_task_id"],
        f"{label}.terminal_force_snapshot_receipt",
    )
    if receipt["rework_cycles"] != terminal_force["rework_cycles"]:
        raise ReleaseScopeError(f"{label} rework count does not match sealed force evidence")
    artifact_evidence = receipt["artifact_evidence"]
    if not isinstance(artifact_evidence, list) or not artifact_evidence:
        raise ReleaseScopeError(f"{label} requires exact artifact evidence")
    seen_paths: set[str] = set()
    for index, artifact in enumerate(artifact_evidence):
        if not isinstance(artifact, dict):
            raise ReleaseScopeError(f"{label}.artifact_evidence[{index}] is invalid")
        _verified_file(root, artifact, f"{label}.artifact_evidence[{index}]")
        path = artifact["path"]
        if path in seen_paths:
            raise ReleaseScopeError(f"{label} repeats artifact evidence path")
        seen_paths.add(path)
    normalized_artifacts = sorted(
        ({"path": item["path"], "sha256": item["sha256"]} for item in artifact_evidence),
        key=lambda item: item["path"],
    )
    if normalized_artifacts != terminal_force["artifacts"]:
        raise ReleaseScopeError(
            f"{label} artifact evidence does not match the terminal force candidate"
        )
    return receipt


def validate_status(
    contract: dict[str, Any],
    value: Any,
    artifact_root: Path,
    trusted_master_public_key: Path,
    trusted_admission_registry: Path,
) -> dict[str, Any]:
    if not isinstance(value, dict):
        raise ReleaseScopeError("release status must be an object")
    _exact_keys(
        value,
        {
            "schema",
            "project_id",
            "program_id",
            "program_version",
            "definition_version",
            "cycle_id",
            "scope_contract_sha256",
            "deliverables",
        },
        "release status",
    )
    if value["schema"] != STATUS_SCHEMA:
        raise ReleaseScopeError("release status schema is unsupported")
    for key in (
        "project_id",
        "program_id",
        "program_version",
        "definition_version",
        "cycle_id",
    ):
        if value[key] != contract[key]:
            raise ReleaseScopeError(f"release status {key} does not match scope contract")
    if value["scope_contract_sha256"] != canonical_sha256(contract):
        raise ReleaseScopeError("release status scope digest does not match")
    expected = {item["deliverable_id"]: item for item in contract["deliverables"]}
    statuses = value["deliverables"]
    if not isinstance(statuses, list):
        raise ReleaseScopeError("release status deliverables must be a list")
    actual_ids: list[str] = []
    root = _root(artifact_root)
    admission_verification = build_admission_verification(
        contract,
        root,
        trusted_master_public_key,
        trusted_admission_registry,
    )
    for index, item in enumerate(statuses):
        if not isinstance(item, dict):
            raise ReleaseScopeError(f"status deliverables[{index}] must be an object")
        _exact_keys(
            item,
            {"deliverable_id", "disposition", "attempt_chains", "rework_cycles", "evidence"},
            f"status deliverables[{index}]",
        )
        deliverable_id = _identifier(
            item["deliverable_id"], f"status deliverables[{index}].deliverable_id"
        )
        actual_ids.append(deliverable_id)
        if deliverable_id not in expected:
            raise ReleaseScopeError(f"status contains unknown deliverable: {deliverable_id}")
        if item["disposition"] not in {"accepted", "rejected"}:
            raise ReleaseScopeError("deliverable disposition must be accepted or rejected")
        for key in ("attempt_chains", "rework_cycles"):
            if isinstance(item[key], bool) or not isinstance(item[key], int) or item[key] < 0:
                raise ReleaseScopeError(f"{key} must be a non-negative integer")
        if item["attempt_chains"] < 1:
            raise ReleaseScopeError("attempt_chains must be at least one")
        evidence = item["evidence"]
        if not isinstance(evidence, dict):
            raise ReleaseScopeError("deliverable evidence must be an object")
        _exact_keys(evidence, {"terminal_receipts"}, "deliverable evidence")
        references = evidence["terminal_receipts"]
        if not isinstance(references, list) or len(references) != item["attempt_chains"]:
            raise ReleaseScopeError("terminal receipts must cover every attempt chain")
        receipts: list[dict[str, Any]] = []
        reference_paths: set[str] = set()
        for receipt_index, reference in enumerate(references):
            if not isinstance(reference, dict):
                raise ReleaseScopeError("terminal receipt reference must be an object")
            _exact_keys(reference, {"path", "sha256"}, "terminal receipt reference")
            if reference["path"] in reference_paths:
                raise ReleaseScopeError("terminal receipt references must be unique")
            reference_paths.add(reference["path"])
            receipts.append(
                _validate_terminal_receipt(
                    contract,
                    root,
                    reference,
                    deliverable_id,
                    admission_verification,
                    trusted_master_public_key,
                    f"{deliverable_id}.terminal_receipts[{receipt_index}]",
                )
            )
        chains = [receipt["attempt_chain"] for receipt in receipts]
        if chains != list(range(1, item["attempt_chains"] + 1)):
            raise ReleaseScopeError("terminal receipts must be ordered contiguous attempt chains")
        if sum(receipt["rework_cycles"] for receipt in receipts) != item["rework_cycles"]:
            raise ReleaseScopeError("release status rework count does not match terminal receipts")
        dispositions = [receipt["disposition"] for receipt in receipts]
        if item["disposition"] == "accepted":
            if dispositions[-1] != "accepted" or any(
                disposition != "rejected" for disposition in dispositions[:-1]
            ):
                raise ReleaseScopeError("accepted deliverable attempt history is inconsistent")
        elif any(disposition != "rejected" for disposition in dispositions):
            raise ReleaseScopeError("rejected deliverable attempt history is inconsistent")
        if expected[deliverable_id]["criticality"] == "optional":
            maximum = 1 + contract["policy"]["max_optional_recovery_chains"]
            if item["attempt_chains"] > maximum:
                raise ReleaseScopeError(
                    f"optional deliverable {deliverable_id} exceeded its recovery-chain cap"
                )
            if item["disposition"] == "rejected" and item["attempt_chains"] != maximum:
                raise ReleaseScopeError(
                    f"optional deliverable {deliverable_id} cannot be omitted before recovery cap exhaustion"
                )
    if len(actual_ids) != len(set(actual_ids)):
        raise ReleaseScopeError("release status deliverable identifiers must be unique")
    if set(actual_ids) != set(expected):
        raise ReleaseScopeError(
            f"release status scope differs; extra={sorted(set(actual_ids) - set(expected))!r}, "
            f"missing={sorted(set(expected) - set(actual_ids))!r}"
        )
    return value


def evaluate(contract: dict[str, Any], status: dict[str, Any]) -> dict[str, Any]:
    definitions = {item["deliverable_id"]: item for item in contract["deliverables"]}
    required_rejected: list[str] = []
    optional_rejected: list[str] = []
    accepted: list[str] = []
    for item in status["deliverables"]:
        deliverable_id = item["deliverable_id"]
        if item["disposition"] == "accepted":
            accepted.append(deliverable_id)
        elif definitions[deliverable_id]["criticality"] == "required":
            required_rejected.append(deliverable_id)
        else:
            optional_rejected.append(deliverable_id)
    if required_rejected:
        decision = "release_blocked"
        next_action = "repair_or_reject_required_scope"
    elif optional_rejected:
        decision = "eligible_for_core_acceptance_with_graceful_degradation"
        next_action = "request_authenticated_master_scope_decision"
    else:
        decision = "eligible_for_full_acceptance"
        next_action = "request_authenticated_master_scope_decision"
    return {
        "schema": "company-os.release-scope-evaluation.v1",
        "ok": True,
        "project_id": contract["project_id"],
        "program_id": contract["program_id"],
        "program_version": contract["program_version"],
        "definition_version": contract["definition_version"],
        "cycle_id": contract["cycle_id"],
        "decision": decision,
        "next_action": next_action,
        "accepted_deliverables": sorted(accepted),
        "rejected_required_deliverables": sorted(required_rejected),
        "omitted_optional_deliverables": sorted(optional_rejected),
        "quality_gate_lowered": False,
        "master_acceptance_inferred": False,
        "scope_definition_sha256": scope_definition_sha256(contract),
        "scope_contract_sha256": canonical_sha256(contract),
        "release_status_sha256": canonical_sha256(status),
    }


def _read_json(path: Path, label: str) -> Any:
    if path.is_symlink():
        raise ReleaseScopeError(f"{label} must not be a symlink")
    try:
        status = path.lstat()
        value = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, json.JSONDecodeError) as error:
        raise ReleaseScopeError(f"{label} could not be read: {error}") from error
    if not stat.S_ISREG(status.st_mode):
        raise ReleaseScopeError(f"{label} must be a regular file")
    return value


def parser() -> argparse.ArgumentParser:
    root = argparse.ArgumentParser()
    commands = root.add_subparsers(dest="command", required=True)
    admit = commands.add_parser("admit")
    evaluate_parser = commands.add_parser("evaluate")
    for command in (admit, evaluate_parser):
        command.add_argument("--contract", type=Path, required=True)
        command.add_argument("--artifact-root", type=Path, required=True)
        command.add_argument("--trusted-master-public-key", type=Path, required=True)
        command.add_argument("--trusted-admission-registry", type=Path, required=True)
    evaluate_parser.add_argument("--status", type=Path, required=True)
    return root


def main(argv: list[str] | None = None) -> int:
    args = parser().parse_args(argv)
    try:
        raw_contract = _read_json(args.contract, "release scope contract")
        if args.command == "admit":
            result = write_admission_verification(
                raw_contract,
                args.artifact_root,
                args.trusted_master_public_key,
                args.trusted_admission_registry,
            )
        else:
            contract = validate_contract(
                raw_contract,
                args.artifact_root,
                args.trusted_master_public_key,
                args.trusted_admission_registry,
            )
            status = validate_status(
                contract,
                _read_json(args.status, "release status"),
                args.artifact_root,
                args.trusted_master_public_key,
                args.trusted_admission_registry,
            )
            result = evaluate(contract, status)
    except ReleaseScopeError as error:
        print(json.dumps({"ok": False, "error": str(error)}, sort_keys=True, separators=(",", ":")))
        return 1
    print(json.dumps(result, sort_keys=True, separators=(",", ":")))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Minimal RSA-3072 PKCS#1 v1.5 trust verification for Company OS records."""

from __future__ import annotations

import base64
import hashlib
import hmac
import re
import stat
from pathlib import Path
from typing import Any


SCHEME = "company-os.rsa-3072-sha256-pkcs1-v1_5.v1"
SIGNATURE = re.compile(r"^[A-Za-z0-9_-]{512}$")
KEY_ID = re.compile(r"^[a-z0-9][a-z0-9._:-]*$")
PEM_HEADER = b"-----BEGIN PUBLIC KEY-----"
PEM_FOOTER = b"-----END PUBLIC KEY-----"
RSA_ALGORITHM = bytes.fromhex("300d06092a864886f70d0101010500")
SHA256_DIGEST_INFO = bytes.fromhex("3031300d060960864801650304020105000420")


class TrustError(ValueError):
    """Raised when a trust anchor or detached signature is invalid."""


def _length(data: bytes, offset: int) -> tuple[int, int]:
    if offset >= len(data):
        raise TrustError("RSA public key DER length is truncated")
    first = data[offset]
    if first < 0x80:
        return first, offset + 1
    count = first & 0x7F
    if count == 0 or count > 4 or offset + 1 + count > len(data):
        raise TrustError("RSA public key DER length is invalid")
    raw = data[offset + 1 : offset + 1 + count]
    if raw[0] == 0:
        raise TrustError("RSA public key DER length is noncanonical")
    value = int.from_bytes(raw, "big")
    if value < 0x80:
        raise TrustError("RSA public key DER length is noncanonical")
    return value, offset + 1 + count


def _tlv(data: bytes, offset: int, tag: int, label: str) -> tuple[bytes, int]:
    if offset >= len(data) or data[offset] != tag:
        raise TrustError(f"RSA public key {label} tag is invalid")
    size, start = _length(data, offset + 1)
    end = start + size
    if end > len(data):
        raise TrustError(f"RSA public key {label} is truncated")
    return data[start:end], end


def _integer(data: bytes, offset: int, label: str) -> tuple[int, int]:
    raw, end = _tlv(data, offset, 0x02, label)
    if not raw or raw[0] & 0x80:
        raise TrustError(f"RSA public key {label} is not a positive integer")
    if len(raw) > 1 and raw[0] == 0 and not raw[1] & 0x80:
        raise TrustError(f"RSA public key {label} is noncanonical")
    return int.from_bytes(raw, "big"), end


def _pem_der(raw: bytes) -> bytes:
    lines = raw.strip().splitlines()
    if len(lines) < 3 or lines[0] != PEM_HEADER or lines[-1] != PEM_FOOTER:
        raise TrustError("master public key must be a PEM SubjectPublicKeyInfo key")
    body = b"".join(lines[1:-1])
    if not body or any(not line or line.strip() != line for line in lines[1:-1]):
        raise TrustError("master public key PEM encoding is invalid")
    try:
        return base64.b64decode(body, validate=True)
    except (ValueError, base64.binascii.Error) as error:
        raise TrustError("master public key PEM body is invalid") from error


def parse_public_key(raw: bytes) -> tuple[int, int]:
    der = _pem_der(raw)
    outer, end = _tlv(der, 0, 0x30, "SubjectPublicKeyInfo")
    if end != len(der):
        raise TrustError("RSA public key has trailing DER bytes")
    algorithm, offset = _tlv(outer, 0, 0x30, "algorithm")
    if algorithm != RSA_ALGORITHM[2:]:
        raise TrustError("public key algorithm is not canonical rsaEncryption")
    bit_string, offset = _tlv(outer, offset, 0x03, "bit string")
    if offset != len(outer) or not bit_string or bit_string[0] != 0:
        raise TrustError("RSA public key bit string is invalid")
    rsa, rsa_end = _tlv(bit_string[1:], 0, 0x30, "key sequence")
    if rsa_end != len(bit_string) - 1:
        raise TrustError("RSA public key sequence has trailing bytes")
    modulus, rsa_offset = _integer(rsa, 0, "modulus")
    exponent, rsa_offset = _integer(rsa, rsa_offset, "exponent")
    if rsa_offset != len(rsa):
        raise TrustError("RSA public key integers have trailing bytes")
    if modulus.bit_length() != 3072 or exponent != 65537:
        raise TrustError("public key must be RSA-3072 with exponent 65537")
    return modulus, exponent


def read_public_key(path: Path, label: str) -> tuple[bytes, int, int]:
    if path.is_symlink():
        raise TrustError(f"{label} must not be a symlink")
    try:
        status = path.lstat()
        raw = path.read_bytes()
    except OSError as error:
        raise TrustError(f"{label} could not be read: {error}") from error
    if not stat.S_ISREG(status.st_mode):
        raise TrustError(f"{label} must be a regular file")
    modulus, exponent = parse_public_key(raw)
    return raw, modulus, exponent


def unsigned_record(record: dict[str, Any]) -> dict[str, Any]:
    authentication = record.get("authentication")
    if not isinstance(authentication, dict):
        raise TrustError("record authentication is invalid")
    if set(authentication) != {"scheme", "key_id", "public_key_sha256", "signature"}:
        raise TrustError("record authentication keys differ")
    if authentication.get("scheme") != SCHEME:
        raise TrustError("record authentication scheme is unsupported")
    key_id = authentication.get("key_id")
    if not isinstance(key_id, str) or not KEY_ID.fullmatch(key_id):
        raise TrustError("record authentication key_id is invalid")
    public_digest = authentication.get("public_key_sha256")
    if (
        not isinstance(public_digest, str)
        or not re.fullmatch(r"[0-9a-f]{64}", public_digest)
    ):
        raise TrustError("record public-key digest is invalid")
    unsigned = dict(record)
    unsigned["authentication"] = {
        "scheme": SCHEME,
        "key_id": key_id,
        "public_key_sha256": public_digest,
    }
    return unsigned


def verify_record(
    record: dict[str, Any],
    canonical_payload: bytes,
    public_key_path: Path,
    label: str,
) -> str:
    unsigned_record(record)
    authentication = record["authentication"]
    raw_key, modulus, exponent = read_public_key(public_key_path, f"{label} public key")
    key_digest = hashlib.sha256(raw_key).hexdigest()
    if not hmac.compare_digest(authentication["public_key_sha256"], key_digest):
        raise TrustError(f"{label} public key does not match the signed trust anchor")
    signature_text = authentication.get("signature")
    if not isinstance(signature_text, str) or not SIGNATURE.fullmatch(signature_text):
        raise TrustError(f"{label} signature encoding is invalid")
    try:
        signature = base64.urlsafe_b64decode(signature_text + "==")
    except (ValueError, base64.binascii.Error) as error:
        raise TrustError(f"{label} signature encoding is invalid") from error
    if len(signature) != 384:
        raise TrustError(f"{label} signature length is invalid")
    signature_value = int.from_bytes(signature, "big")
    if signature_value >= modulus:
        raise TrustError(f"{label} signature representative is out of range")
    encoded = pow(signature_value, exponent, modulus).to_bytes(384, "big")
    digest_info = SHA256_DIGEST_INFO + hashlib.sha256(canonical_payload).digest()
    expected = b"\x00\x01" + (b"\xff" * (384 - len(digest_info) - 3)) + b"\x00" + digest_info
    if not hmac.compare_digest(encoded, expected):
        raise TrustError(f"{label} signature does not verify")
    return key_digest

#!/usr/bin/env python3
"""Seal and verify an immutable terminal snapshot of a force event log."""

from __future__ import annotations

import argparse
import hashlib
import json
import os
import re
import stat
from pathlib import Path
from typing import Any

import force_loop_controller as force


SNAPSHOT_SCHEMA = "company-os.force-log-snapshot.v1"
SOURCE_PATH = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._/-]*$")


def _artifact_rows(events: list[dict[str, Any]]) -> list[dict[str, str]]:
    return [
        {
            "event": item["event"],
            "path": item["evidence"]["path"],
            "sha256": item["evidence"]["sha256"],
        }
        for item in events
        if item["event"] in {"artifact_materialized", "receipt_materialized"}
    ]


def _terminal_artifact_rows(events: list[dict[str, Any]]) -> list[dict[str, str]]:
    terminal_event = events[-1]["event"]
    if terminal_event == "manager_accept":
        boundary = next(
            (
                item
                for item in reversed(events)
                if item["event"] == "manager_inspection_passed"
            ),
            None,
        )
    elif terminal_event == "manager_reject":
        candidate, _, inspection = _terminal_rejection_chain(events)
        boundary = candidate if inspection is not None else None
    else:
        boundary = None
    if boundary is None:
        return []
    paths = boundary["evidence"]["artifact_paths"]
    materialized = {
        item["evidence"]["path"]: item["evidence"]["sha256"]
        for item in events
        if item["event"] == "artifact_materialized"
        and item["sequence"] < boundary["sequence"]
    }
    return [
        {"path": path, "sha256": materialized[path]}
        for path in sorted(paths)
    ]


def _terminal_rejection_chain(
    events: list[dict[str, Any]],
) -> tuple[dict[str, Any] | None, dict[str, Any] | None, dict[str, Any] | None]:
    if events[-1]["event"] != "manager_reject":
        return None, None, None
    candidate = next(
        (item for item in reversed(events[:-1]) if item["event"] == "candidate_runnable"),
        None,
    )
    if candidate is None:
        return None, None, None
    verification = next(
        (
            item
            for item in events[candidate["sequence"] : -1]
            if item["event"] == "verification_passed"
        ),
        None,
    )
    if verification is None:
        return candidate, None, None
    inspection = next(
        (
            item
            for item in events[verification["sequence"] : -1]
            if item["event"] == "manager_inspection_failed"
        ),
        None,
    )
    if inspection is None:
        return candidate, verification, None
    invalid_after_inspection = {
        "artifact_materialized",
        "candidate_runnable",
        "verification_passed",
        "manager_inspection_passed",
        "manager_rework",
        "rework_started",
    }
    if any(
        item["event"] in invalid_after_inspection
        for item in events[inspection["sequence"] : -1]
    ):
        return candidate, verification, None
    return candidate, verification, inspection


def _snapshot_bytes(events: list[dict[str, Any]]) -> bytes:
    return b"".join(force.canonical_bytes(item) + b"\n" for item in events)


def _safe_target(root: Path, relative: str) -> tuple[Path, bytes | None]:
    safe = force._safe_path(relative, "snapshot target")
    resolved_root = force._artifact_root(root)
    current = resolved_root
    parts = safe.split("/")
    for part in parts[:-1]:
        current = current / part
        try:
            status = current.lstat()
        except OSError as error:
            raise force.ForceContractError(
                f"snapshot target parent is missing or unreadable: {safe}"
            ) from error
        if stat.S_ISLNK(status.st_mode) or not stat.S_ISDIR(status.st_mode):
            raise force.ForceContractError(
                f"snapshot target parent must be a real directory: {safe}"
            )
    target = current / parts[-1]
    try:
        status = target.lstat()
    except FileNotFoundError:
        return target, None
    except OSError as error:
        raise force.ForceContractError(
            f"snapshot target could not be inspected: {safe}"
        ) from error
    if stat.S_ISLNK(status.st_mode) or not stat.S_ISREG(status.st_mode):
        raise force.ForceContractError(
            f"snapshot target must be a regular non-symlink file: {safe}"
        )
    try:
        return target, target.read_bytes()
    except OSError as error:
        raise force.ForceContractError(
            f"snapshot target could not be read: {safe}"
        ) from error


def _safe_existing_source(root: Path, supplied: Path, label: str) -> Path:
    if ".." in supplied.parts:
        raise force.ForceContractError(f"{label} must not contain parent traversal")
    resolved_root = force._artifact_root(root)
    lexical_root = Path(os.path.abspath(root))
    candidate = supplied if supplied.is_absolute() else lexical_root / supplied
    lexical = Path(os.path.abspath(candidate))
    try:
        relative = lexical.relative_to(lexical_root)
    except ValueError as error:
        raise force.ForceContractError(f"{label} must stay under artifact root") from error
    relative_text = relative.as_posix()
    if not SOURCE_PATH.fullmatch(relative_text) or any(
        part in {"", ".", ".."} for part in relative.parts
    ):
        raise force.ForceContractError(f"{label} must be a safe project-relative path")
    current = resolved_root
    for index, part in enumerate(relative.parts):
        current = current / part
        try:
            status = current.lstat()
        except OSError as error:
            raise force.ForceContractError(f"{label} is missing or unreadable") from error
        if stat.S_ISLNK(status.st_mode):
            raise force.ForceContractError(f"{label} path contains a symlink")
        if index < len(relative.parts) - 1 and not stat.S_ISDIR(status.st_mode):
            raise force.ForceContractError(f"{label} parent is not a directory")
        if index == len(relative.parts) - 1 and not stat.S_ISREG(status.st_mode):
            raise force.ForceContractError(f"{label} must be a regular file")
    return current


def _exclusive_write(path: Path, content: bytes) -> None:
    try:
        with path.open("xb") as stream:
            stream.write(content)
            stream.flush()
            os.fsync(stream.fileno())
        _fsync_directory(path.parent)
    except FileExistsError as error:
        raise force.ForceContractError(
            f"snapshot target already exists: {path.name}"
        ) from error
    except OSError as error:
        raise force.ForceContractError(
            f"snapshot target could not be written: {path.name}: {error}"
        ) from error


def _fsync_directory(path: Path) -> None:
    descriptor = os.open(path, os.O_RDONLY | getattr(os, "O_DIRECTORY", 0))
    try:
        os.fsync(descriptor)
    finally:
        os.close(descriptor)


def build_receipt(
    contract: dict[str, Any],
    events: list[dict[str, Any]],
    snapshot_path: str,
    snapshot_sha256: str,
) -> dict[str, Any]:
    terminal = events[-1]
    if terminal["event"] not in force.TERMINAL_EVENTS:
        raise force.ForceContractError(
            "force log may be sealed only after a terminal manager decision or hard stop"
        )
    return {
        "schema": SNAPSHOT_SCHEMA,
        "task_id": contract["task_id"],
        "contract_sha256": force.canonical_sha256(contract),
        "snapshot_path": snapshot_path,
        "snapshot_sha256": snapshot_sha256,
        "event_count": len(events),
        "terminal": {
            "event": terminal["event"],
            "sequence": terminal["sequence"],
            "at_epoch": terminal["at_epoch"],
        },
        "artifact_set_sha256": force.canonical_sha256(_artifact_rows(events)),
    }


def seal(
    contract_path: Path,
    events_path: Path,
    artifact_root: Path,
    snapshot_relative: str,
    receipt_relative: str,
) -> dict[str, Any]:
    safe_contract_path = _safe_existing_source(artifact_root, contract_path, "force contract")
    safe_events_path = _safe_existing_source(artifact_root, events_path, "force event log")
    contract = force.read_contract(safe_contract_path)
    events = force.read_events(safe_events_path, contract, artifact_root)
    snapshot_target, existing_snapshot = _safe_target(artifact_root, snapshot_relative)
    receipt_target, existing_receipt = _safe_target(artifact_root, receipt_relative)
    if snapshot_target == receipt_target:
        raise force.ForceContractError("snapshot and receipt targets must differ")

    snapshot_content = _snapshot_bytes(events)
    snapshot_sha256 = hashlib.sha256(snapshot_content).hexdigest()
    receipt = build_receipt(
        contract,
        events,
        force._safe_path(snapshot_relative, "snapshot path"),
        snapshot_sha256,
    )
    receipt_content = force.canonical_bytes(receipt) + b"\n"

    if existing_snapshot is not None and existing_snapshot != snapshot_content:
        raise force.ForceContractError("existing snapshot bytes do not match terminal evidence")
    if existing_receipt is not None and existing_receipt != receipt_content:
        raise force.ForceContractError("existing snapshot receipt does not match terminal evidence")
    snapshot_created = existing_snapshot is None
    if snapshot_created:
        _exclusive_write(snapshot_target, snapshot_content)
    try:
        if existing_receipt is None:
            _exclusive_write(receipt_target, receipt_content)
        _fsync_directory(snapshot_target.parent)
        if receipt_target.parent != snapshot_target.parent:
            _fsync_directory(receipt_target.parent)
    except force.ForceContractError:
        raise
    except OSError as error:
        raise force.ForceContractError(
            f"snapshot pair durability could not be confirmed: {error}"
        ) from error

    return {
        "schema": "company-os.force-log-seal-result.v1",
        "ok": True,
        "task_id": contract["task_id"],
        "snapshot_path": snapshot_relative,
        "snapshot_sha256": snapshot_sha256,
        "receipt_path": receipt_relative,
        "receipt_sha256": hashlib.sha256(receipt_content).hexdigest(),
        "event_count": len(events),
        "terminal_event": events[-1]["event"],
    }


def _read_canonical_json(path: Path, label: str) -> tuple[dict[str, Any], bytes]:
    if path.is_symlink():
        raise force.ForceContractError(f"{label} must not be a symlink")
    try:
        status = path.lstat()
        raw = path.read_bytes()
        value = json.loads(raw)
    except (OSError, UnicodeError, json.JSONDecodeError) as error:
        raise force.ForceContractError(f"{label} could not be read: {error}") from error
    if not stat.S_ISREG(status.st_mode) or not isinstance(value, dict):
        raise force.ForceContractError(f"{label} must be a regular canonical JSON object")
    if raw != force.canonical_bytes(value) + b"\n":
        raise force.ForceContractError(f"{label} bytes are not canonical JSON")
    return value, raw


def _read_snapshot(path: Path) -> tuple[list[dict[str, Any]], bytes]:
    if path.is_symlink():
        raise force.ForceContractError("snapshot must not be a symlink")
    try:
        status = path.lstat()
        raw = path.read_bytes()
    except OSError as error:
        raise force.ForceContractError(f"snapshot could not be read: {error}") from error
    if not stat.S_ISREG(status.st_mode) or not raw.endswith(b"\n"):
        raise force.ForceContractError("snapshot must be a newline-terminated regular file")
    values: list[dict[str, Any]] = []
    for line_number, raw_line in enumerate(raw.splitlines(), start=1):
        try:
            value = json.loads(raw_line)
        except json.JSONDecodeError as error:
            raise force.ForceContractError(
                f"snapshot line {line_number} is not JSON"
            ) from error
        if not isinstance(value, dict) or raw_line != force.canonical_bytes(value):
            raise force.ForceContractError(
                f"snapshot line {line_number} is not canonical JSON"
            )
        values.append(value)
    return values, raw


def verify(
    contract_path: Path,
    artifact_root: Path,
    snapshot_relative: str,
    receipt_relative: str,
) -> dict[str, Any]:
    safe_contract_path = _safe_existing_source(artifact_root, contract_path, "force contract")
    contract = force.read_contract(safe_contract_path)
    resolved_root = force._artifact_root(artifact_root)
    force._verified_file(resolved_root, snapshot_relative)
    force._verified_file(resolved_root, receipt_relative)
    snapshot_path = resolved_root / force._safe_path(snapshot_relative, "snapshot path")
    receipt_path = resolved_root / force._safe_path(receipt_relative, "receipt path")
    receipt, receipt_bytes = _read_canonical_json(receipt_path, "snapshot receipt")
    expected_keys = {
        "schema",
        "task_id",
        "contract_sha256",
        "snapshot_path",
        "snapshot_sha256",
        "event_count",
        "terminal",
        "artifact_set_sha256",
    }
    force._exact_keys(receipt, expected_keys, "snapshot receipt")
    if receipt["schema"] != SNAPSHOT_SCHEMA:
        raise force.ForceContractError("snapshot receipt schema is unsupported")
    if receipt["task_id"] != contract["task_id"]:
        raise force.ForceContractError("snapshot receipt task does not match contract")
    if receipt["contract_sha256"] != force.canonical_sha256(contract):
        raise force.ForceContractError("snapshot receipt contract digest does not match")
    if receipt["snapshot_path"] != snapshot_relative:
        raise force.ForceContractError("snapshot receipt path does not match requested snapshot")

    events, snapshot_bytes = _read_snapshot(snapshot_path)
    accepted_events = force.validate_events(contract, events, resolved_root)
    expected_receipt = build_receipt(
        contract,
        accepted_events,
        snapshot_relative,
        hashlib.sha256(snapshot_bytes).hexdigest(),
    )
    if receipt != expected_receipt:
        raise force.ForceContractError("snapshot receipt does not match exact snapshot evidence")
    return {
        "schema": "company-os.force-log-snapshot-verification.v1",
        "ok": True,
        "task_id": contract["task_id"],
        "snapshot_sha256": receipt["snapshot_sha256"],
        "receipt_sha256": hashlib.sha256(receipt_bytes).hexdigest(),
        "event_count": len(accepted_events),
        "terminal_event": accepted_events[-1]["event"],
        "terminal_artifacts": _terminal_artifact_rows(accepted_events),
        "rework_cycles": sum(
            item["event"] == "rework_started" for item in accepted_events
        ),
        "terminal_rejection_inspected": (
            _terminal_rejection_chain(accepted_events)[2] is not None
            if accepted_events[-1]["event"] == "manager_reject"
            else None
        ),
    }


def parser() -> argparse.ArgumentParser:
    root = argparse.ArgumentParser()
    commands = root.add_subparsers(dest="command", required=True)
    seal_parser = commands.add_parser("seal")
    verify_parser = commands.add_parser("verify")
    for command in (seal_parser, verify_parser):
        command.add_argument("--contract", type=Path, required=True)
        command.add_argument("--artifact-root", type=Path, required=True)
        command.add_argument("--snapshot-path", required=True)
        command.add_argument("--receipt-path", required=True)
    seal_parser.add_argument("--events", type=Path, required=True)
    return root


def main(argv: list[str] | None = None) -> int:
    args = parser().parse_args(argv)
    try:
        if args.command == "seal":
            result = seal(
                args.contract,
                args.events,
                args.artifact_root,
                args.snapshot_path,
                args.receipt_path,
            )
        else:
            result = verify(
                args.contract,
                args.artifact_root,
                args.snapshot_path,
                args.receipt_path,
            )
    except force.ForceContractError as error:
        print(json.dumps({"ok": False, "error": str(error)}, sort_keys=True, separators=(",", ":")))
        return 1
    print(json.dumps(result, sort_keys=True, separators=(",", ":")))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

