#!/usr/bin/env python3
"""Mission-level executive governor for reality-first Company OS execution."""
from __future__ import annotations

import argparse
import hashlib
import json
import math
from pathlib import Path
from typing import Any, Mapping

INPUT_SCHEMA = "company-os.outcome-executive-input.v1"
DECISION_SCHEMA = "company-os.outcome-executive-decision.v1"
CAPABILITY_STATES = {"missing": 0, "partial": 1, "runnable": 2, "connected": 3, "verified": 4}
WORK_CLASSES = (
    "research",
    "architecture",
    "governance",
    "implementation",
    "integration",
    "runtime",
    "repair",
    "evaluation",
    "documentation",
    "packaging",
    "checkpoint",
)
EXECUTION_CLASSES = {"implementation", "integration", "runtime", "repair"}


class GovernorError(ValueError):
    pass


def canonical(value: Any) -> bytes:
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False).encode("utf-8")


def digest(value: Any) -> str:
    return hashlib.sha256(canonical(value)).hexdigest()


def _text(value: Any, label: str) -> str:
    if not isinstance(value, str) or not value.strip() or "\x00" in value:
        raise GovernorError(f"{label} must be a nonempty string")
    return value.strip()


def _fraction(value: Any, label: str) -> float:
    if not isinstance(value, (int, float)) or isinstance(value, bool) or not math.isfinite(float(value)):
        raise GovernorError(f"{label} must be finite")
    current = float(value)
    if current < 0.0 or current > 1.0:
        raise GovernorError(f"{label} must be between 0 and 1")
    return current


def _bool(value: Any, label: str) -> bool:
    if not isinstance(value, bool):
        raise GovernorError(f"{label} must be boolean")
    return value


def _reality_level(signals: Mapping[str, Any]) -> int:
    names = (
        "internal_primitives",
        "runnable_capability",
        "connected_vertical_slice",
        "user_usable",
        "independent_acceptance",
    )
    observed = [_bool(signals.get(name, False), f"reality.{name}") for name in names]
    # Higher reality is not allowed to float above a missing lower layer.
    for index in range(1, len(observed)):
        if observed[index] and not observed[index - 1]:
            raise GovernorError(f"reality.{names[index]} requires reality.{names[index - 1]}")
    level = 0
    for index, present in enumerate(observed, 1):
        if present:
            level = index
    return level


def _capabilities(raw: Any) -> list[dict[str, Any]]:
    if not isinstance(raw, list) or not raw:
        raise GovernorError("required_capabilities must be a nonempty list")
    result: list[dict[str, Any]] = []
    seen: set[str] = set()
    for index, item in enumerate(raw):
        if not isinstance(item, Mapping):
            raise GovernorError(f"required_capabilities[{index}] must be an object")
        capability_id = _text(item.get("capability_id"), f"required_capabilities[{index}].capability_id")
        if capability_id in seen:
            raise GovernorError(f"duplicate capability_id {capability_id}")
        seen.add(capability_id)
        state = item.get("state")
        if state not in CAPABILITY_STATES:
            raise GovernorError(f"{capability_id}.state is invalid")
        critical = item.get("critical", True)
        if not isinstance(critical, bool):
            raise GovernorError(f"{capability_id}.critical must be boolean")
        priority = item.get("priority", 50)
        if not isinstance(priority, int) or isinstance(priority, bool) or priority < 0 or priority > 100:
            raise GovernorError(f"{capability_id}.priority must be 0..100")
        existing = item.get("existing_implementation")
        if existing is not None:
            existing = _text(existing, f"{capability_id}.existing_implementation")
        result.append(
            {
                "capability_id": capability_id,
                "state": state,
                "critical": critical,
                "priority": priority,
                "existing_implementation": existing,
            }
        )
    return result


def _allocation(raw: Any) -> dict[str, float]:
    if raw is None:
        raw = {}
    if not isinstance(raw, Mapping):
        raise GovernorError("allocation must be an object")
    unknown = set(raw) - set(WORK_CLASSES)
    if unknown:
        raise GovernorError(f"allocation has unknown work classes: {sorted(unknown)}")
    result = {name: _fraction(raw.get(name, 0.0), f"allocation.{name}") for name in WORK_CLASSES}
    total = sum(result.values())
    if total <= 0:
        return result
    return {name: value / total for name, value in result.items()}


def _dominant_bottleneck(capabilities: list[dict[str, Any]]) -> dict[str, Any] | None:
    unresolved = [item for item in capabilities if item["state"] != "verified"]
    if not unresolved:
        return None
    # Critical first, then closest-to-nothing first, then explicit priority.
    unresolved.sort(
        key=lambda item: (
            0 if item["critical"] else 1,
            CAPABILITY_STATES[item["state"]],
            -item["priority"],
            item["capability_id"],
        )
    )
    return unresolved[0]


def evaluate(payload: Mapping[str, Any]) -> dict[str, Any]:
    if payload.get("$schema") != INPUT_SCHEMA:
        raise GovernorError("input schema is invalid")
    objective_id = _text(payload.get("objective_id"), "objective_id")
    objective = _text(payload.get("objective"), "objective")
    budget_fraction = _fraction(payload.get("budget_fraction_consumed", 0.0), "budget_fraction_consumed")
    reality_raw = payload.get("reality", {})
    if not isinstance(reality_raw, Mapping):
        raise GovernorError("reality must be an object")
    reality_level = _reality_level(reality_raw)
    capabilities = _capabilities(payload.get("required_capabilities"))
    allocation = _allocation(payload.get("allocation"))
    bottleneck = _dominant_bottleneck(capabilities)

    first_reality_incident = budget_fraction >= 0.25 and reality_level < 3
    if reality_level >= 5:
        mode = "accepted"
    elif budget_fraction >= 0.88:
        mode = "reality_closure"
    elif budget_fraction >= 0.70 and reality_level < 4:
        mode = "critical_path"
    elif first_reality_incident or (budget_fraction >= 0.40 and reality_level < 3):
        mode = "compression"
    else:
        mode = "normal"

    total = sum(allocation.values())
    if total:
        execution_ratio = sum(allocation[name] for name in EXECUTION_CLASSES)
        governance_tax = allocation["governance"]
        research_tax = allocation["research"]
        documentation_tax = allocation["documentation"]
    else:
        execution_ratio = governance_tax = research_tax = documentation_tax = 0.0

    allocation_incident = reality_level < 3 and budget_fraction >= 0.10 and total > 0 and execution_ratio < 0.50
    existing_capability_preference = bool(
        bottleneck and bottleneck.get("existing_implementation") and bottleneck["state"] in {"missing", "partial"}
    )

    if mode == "accepted":
        allowed = ["checkpoint", "documentation", "packaging"]
        paused: list[str] = []
    elif mode == "reality_closure":
        allowed = ["integration", "runtime", "repair", "evaluation", "packaging", "checkpoint"]
        paused = [name for name in WORK_CLASSES if name not in allowed]
    elif mode == "critical_path":
        allowed = ["implementation", "integration", "runtime", "repair", "evaluation", "packaging", "checkpoint"]
        paused = ["research", "architecture", "governance", "documentation"]
    elif mode == "compression" or first_reality_incident:
        allowed = ["implementation", "integration", "runtime", "repair", "evaluation", "checkpoint", "packaging"]
        paused = ["documentation"]
        if reality_level < 2:
            paused.extend(["governance"])
        paused = sorted(set(paused))
    else:
        allowed = list(WORK_CLASSES)
        paused = []

    orders: list[str] = []
    if mode != "accepted":
        if bottleneck:
            orders.append(f"Make {bottleneck['capability_id']} the global execution bottleneck until observable progress changes its state.")
        if reality_level < 3:
            orders.append("Materialize and run the smallest connected end-to-end artifact before expanding architecture, research, or governance.")
        if first_reality_incident:
            orders.append("Execution incident: pause broad research/speculation and redirect managers to implementation, integration, runtime, and repair.")
        if allocation_incident:
            orders.append("Raise direct product execution above half of active mission allocation until R3 exists.")
        if existing_capability_preference and bottleneck:
            orders.append(
                f"Integrate and exercise supplied capability {bottleneck['existing_implementation']} before authorizing a replacement implementation."
            )
        if mode == "reality_closure":
            orders.append("Do not start new features or broad research. Integrate, run, fix, verify, package, and checkpoint the strongest real outcome now.")
        elif mode == "critical_path":
            orders.append("Pause noncritical lanes. Spend remaining resources only on blockers between current reality and a fresh user-usable outcome.")
        orders.append("Checkpoint tested product bytes promptly; governance receipts are not a substitute for durable product state.")

    decision = {
        "$schema": DECISION_SCHEMA,
        "objective_id": objective_id,
        "objective": objective,
        "budget_fraction_consumed": budget_fraction,
        "reality_level": f"R{reality_level}",
        "reality_level_index": reality_level,
        "mode": mode,
        "first_reality_incident": first_reality_incident,
        "allocation_incident": allocation_incident,
        "dominant_bottleneck": bottleneck,
        "existing_capability_preference": existing_capability_preference,
        "product_execution_ratio": round(execution_ratio, 6),
        "governance_tax": round(governance_tax, 6),
        "research_tax": round(research_tax, 6),
        "documentation_tax": round(documentation_tax, 6),
        "allowed_work_classes": allowed,
        "paused_work_classes": paused,
        "manager_orders": orders,
        "required_capabilities": capabilities,
        "decision_sha256": None,
    }
    decision["decision_sha256"] = digest(decision)
    return decision


def verify(decision: Mapping[str, Any]) -> dict[str, Any]:
    value = dict(decision)
    if value.get("$schema") != DECISION_SCHEMA:
        raise GovernorError("decision schema is invalid")
    observed = value.get("decision_sha256")
    if not isinstance(observed, str) or len(observed) != 64:
        raise GovernorError("decision digest is invalid")
    candidate = dict(value)
    candidate["decision_sha256"] = None
    if digest(candidate) != observed:
        raise GovernorError("decision digest changed")
    return value


def main() -> int:
    parser = argparse.ArgumentParser()
    sub = parser.add_subparsers(dest="command", required=True)
    run = sub.add_parser("evaluate")
    run.add_argument("--input", type=Path, required=True)
    run.add_argument("--output", type=Path, required=True)
    check = sub.add_parser("verify")
    check.add_argument("--input", type=Path, required=True)
    args = parser.parse_args()
    try:
        payload = json.loads(args.input.read_text(encoding="utf-8"))
        if args.command == "evaluate":
            result = evaluate(payload)
            args.output.parent.mkdir(parents=True, exist_ok=True)
            args.output.write_text(json.dumps(result, indent=2, sort_keys=True) + "\n", encoding="utf-8")
        else:
            result = verify(payload)
        print(json.dumps({"ok": True, "decision_sha256": result["decision_sha256"], "mode": result["mode"], "reality_level": result["reality_level"]}, sort_keys=True))
        return 0
    except (GovernorError, OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        print(json.dumps({"ok": False, "error": str(exc)}, sort_keys=True))
        return 2


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Validate real Company OS execution-efficiency receipts.

The validator deliberately separates deliverable acceptance from hierarchy,
Luna, efficiency, and scale evidence. Missing host telemetry is valid only when
it is declared unavailable; it can never make an efficiency gate pass.
"""

from __future__ import annotations

import argparse
import json
import math
import re
import sys
from collections import defaultdict
from datetime import datetime
from pathlib import Path
from typing import Any


SCHEMA = "company-os.execution-efficiency-receipt.v1"
ID_PATTERN = re.compile(r"^[a-z0-9][a-z0-9._:-]{0,127}$")
TIMING_FIELDS = (
    "program_start",
    "first_manager_dispatch",
    "first_worker_dispatch",
    "first_usable_result",
    "first_artifact_materialization",
    "final_acceptance",
)
USAGE_FIELDS = (
    "total_tokens",
    "luna_tokens",
    "sol_tokens",
    "cost_usd",
    "single_thread_baseline_sol_tokens",
    "single_thread_baseline_lead_time_seconds",
)
TOP_LEVEL_KEYS = {
    "schema",
    "program_id",
    "comparison_class",
    "status",
    "timing",
    "topology",
    "usage",
    "quality",
    "requirements",
    "requirement_results",
    "artifact_plan",
    "artifacts",
    "decision",
}
AUTHORITY_RANK = {"manager": 1, "master": 2, "user": 3}


class ReceiptError(ValueError):
    """Raised for a malformed receipt source."""


def _canonical_json(value: Any) -> str:
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False)


def _is_int(value: Any) -> bool:
    return isinstance(value, int) and not isinstance(value, bool)


def _is_number(value: Any) -> bool:
    return (
        isinstance(value, (int, float))
        and not isinstance(value, bool)
        and math.isfinite(value)
    )


def _check_exact_keys(
    value: Any,
    expected: set[str],
    path: str,
    errors: list[str],
) -> dict[str, Any]:
    if not isinstance(value, dict):
        errors.append(f"{path} must be an object")
        return {}
    actual = set(value)
    if actual != expected:
        missing = sorted(expected - actual)
        extra = sorted(actual - expected)
        if missing:
            errors.append(f"{path} missing keys: {', '.join(missing)}")
        if extra:
            errors.append(f"{path} has unknown keys: {', '.join(extra)}")
    return value


def _check_nonempty_string(value: Any, path: str, errors: list[str]) -> str | None:
    if not isinstance(value, str) or not value.strip():
        errors.append(f"{path} must be a non-empty string")
        return None
    return value


def _check_id(value: Any, path: str, errors: list[str]) -> str | None:
    result = _check_nonempty_string(value, path, errors)
    if result is not None and not ID_PATTERN.fullmatch(result):
        errors.append(f"{path} must be canonical lowercase ASCII ID")
    return result


def _check_string_list(
    value: Any,
    path: str,
    errors: list[str],
    *,
    allow_empty: bool = True,
) -> list[str]:
    if not isinstance(value, list):
        errors.append(f"{path} must be an array")
        return []
    if not allow_empty and not value:
        errors.append(f"{path} must not be empty")
    result: list[str] = []
    for index, item in enumerate(value):
        checked = _check_nonempty_string(item, f"{path}[{index}]", errors)
        if checked is not None:
            result.append(checked)
    if len(result) != len(set(result)):
        errors.append(f"{path} must not contain duplicates")
    return result


def _check_id_list(
    value: Any,
    path: str,
    errors: list[str],
    *,
    allow_empty: bool = True,
) -> list[str]:
    if not isinstance(value, list):
        errors.append(f"{path} must be an array")
        return []
    if not allow_empty and not value:
        errors.append(f"{path} must not be empty")
    result: list[str] = []
    for index, item in enumerate(value):
        checked = _check_id(item, f"{path}[{index}]", errors)
        if checked is not None:
            result.append(checked)
    if len(result) != len(set(result)):
        errors.append(f"{path} must not contain duplicates")
    return result


def _parse_timestamp(value: Any, path: str, errors: list[str]) -> datetime | None:
    if value is None:
        return None
    if not isinstance(value, str):
        errors.append(f"{path} must be an RFC3339 timestamp or null")
        return None
    normalized = value[:-1] + "+00:00" if value.endswith("Z") else value
    try:
        parsed = datetime.fromisoformat(normalized)
    except ValueError:
        errors.append(f"{path} must be an RFC3339 timestamp or null")
        return None
    if parsed.tzinfo is None:
        errors.append(f"{path} timestamp must include a timezone")
        return None
    return parsed


def _load_receipt(path: Path) -> dict[str, Any]:
    try:
        raw = path.read_bytes()
    except OSError as error:
        raise ReceiptError(f"cannot read {path}: {error}") from error
    try:
        value = json.loads(raw)
    except json.JSONDecodeError as error:
        raise ReceiptError(f"{path} is not valid JSON: {error}") from error
    if not isinstance(value, dict):
        raise ReceiptError(f"{path} must contain one JSON object")
    return value


def validate_receipt(receipt: dict[str, Any], source: str = "<memory>") -> dict[str, Any]:
    errors: list[str] = []
    warnings: list[str] = []

    root = _check_exact_keys(receipt, TOP_LEVEL_KEYS, "receipt", errors)
    if root.get("schema") != SCHEMA:
        errors.append(f"receipt.schema must equal {SCHEMA!r}")
    program_id = _check_id(root.get("program_id"), "receipt.program_id", errors)
    comparison_class = _check_id(
        root.get("comparison_class"), "receipt.comparison_class", errors
    )
    status = root.get("status")
    if status not in {"accepted", "rework", "blocked", "failed"}:
        errors.append("receipt.status must be accepted, rework, blocked, or failed")

    timing = _check_exact_keys(
        root.get("timing"),
        set(TIMING_FIELDS) | {"unavailable", "not_applicable"},
        "receipt.timing",
        errors,
    )
    timing_unavailable = set(
        _check_string_list(timing.get("unavailable"), "receipt.timing.unavailable", errors)
    )
    timing_not_applicable = set(
        _check_string_list(
            timing.get("not_applicable"), "receipt.timing.not_applicable", errors
        )
    )
    unknown_timing_markers = (timing_unavailable | timing_not_applicable) - set(
        TIMING_FIELDS
    )
    if unknown_timing_markers:
        errors.append(
            "receipt.timing markers reference unknown fields: "
            + ", ".join(sorted(unknown_timing_markers))
        )
    if timing_unavailable & timing_not_applicable:
        errors.append("receipt.timing unavailable and not_applicable must be disjoint")
    parsed_times: dict[str, datetime | None] = {}
    for field in TIMING_FIELDS:
        value = timing.get(field)
        parsed_times[field] = _parse_timestamp(value, f"receipt.timing.{field}", errors)
        if value is None and field not in timing_unavailable | timing_not_applicable:
            errors.append(
                f"receipt.timing.{field} is null but is not declared unavailable or not_applicable"
            )
        if value is not None and field in timing_unavailable | timing_not_applicable:
            errors.append(f"receipt.timing.{field} has a value but is marked unavailable")
    observed_sequence = [
        (field, parsed_times[field])
        for field in TIMING_FIELDS
        if parsed_times[field] is not None
    ]
    for (prior_name, prior), (later_name, later) in zip(
        observed_sequence, observed_sequence[1:]
    ):
        assert prior is not None and later is not None
        if later < prior:
            errors.append(
                f"receipt.timing.{later_name} precedes {prior_name}"
            )

    topology = _check_exact_keys(
        root.get("topology"),
        {
            "requested_lanes",
            "manager_assignments",
            "workers",
            "max_observed_concurrency",
            "concurrency_limit",
            "variances",
        },
        "receipt.topology",
        errors,
    )
    lanes_value = topology.get("requested_lanes")
    if not isinstance(lanes_value, list) or not lanes_value:
        errors.append("receipt.topology.requested_lanes must be a non-empty array")
        lanes_value = []
    lanes: dict[str, dict[str, Any]] = {}
    for index, raw_lane in enumerate(lanes_value):
        lane = _check_exact_keys(
            raw_lane,
            {"lane_id", "outcome"},
            f"receipt.topology.requested_lanes[{index}]",
            errors,
        )
        lane_id = _check_id(
            lane.get("lane_id"),
            f"receipt.topology.requested_lanes[{index}].lane_id",
            errors,
        )
        _check_nonempty_string(
            lane.get("outcome"),
            f"receipt.topology.requested_lanes[{index}].outcome",
            errors,
        )
        if lane_id:
            if lane_id in lanes:
                errors.append(f"duplicate requested lane {lane_id!r}")
            lanes[lane_id] = lane

    managers_value = topology.get("manager_assignments")
    if not isinstance(managers_value, list) or not managers_value:
        errors.append("receipt.topology.manager_assignments must be a non-empty array")
        managers_value = []
    managers: dict[str, dict[str, Any]] = {}
    lane_owners: dict[str, list[str]] = defaultdict(list)
    for index, raw_manager in enumerate(managers_value):
        manager = _check_exact_keys(
            raw_manager,
            {
                "manager_task_id",
                "lane_ids",
                "requested_model",
                "requested_effort",
                "observed_model",
                "observed_effort",
            },
            f"receipt.topology.manager_assignments[{index}]",
            errors,
        )
        manager_id = _check_id(
            manager.get("manager_task_id"),
            f"receipt.topology.manager_assignments[{index}].manager_task_id",
            errors,
        )
        lane_ids = _check_string_list(
            manager.get("lane_ids"),
            f"receipt.topology.manager_assignments[{index}].lane_ids",
            errors,
            allow_empty=False,
        )
        for lane_id in lane_ids:
            if lane_id not in lanes:
                errors.append(f"manager {manager_id!r} references unknown lane {lane_id!r}")
            elif manager_id:
                lane_owners[lane_id].append(manager_id)
        _check_nonempty_string(
            manager.get("requested_model"),
            f"receipt.topology.manager_assignments[{index}].requested_model",
            errors,
        )
        _check_nonempty_string(
            manager.get("requested_effort"),
            f"receipt.topology.manager_assignments[{index}].requested_effort",
            errors,
        )
        observed_model = manager.get("observed_model")
        observed_effort = manager.get("observed_effort")
        if (observed_model is None) != (observed_effort is None):
            errors.append(f"manager {manager_id!r} observed model and effort must be paired")
        for field, value in (
            ("observed_model", observed_model),
            ("observed_effort", observed_effort),
        ):
            if value is not None:
                _check_nonempty_string(
                    value,
                    f"receipt.topology.manager_assignments[{index}].{field}",
                    errors,
                )
        if manager_id:
            if manager_id in managers:
                errors.append(f"duplicate manager task {manager_id!r}")
            managers[manager_id] = manager

    for lane_id in lanes:
        owners = lane_owners.get(lane_id, [])
        if len(owners) != 1:
            errors.append(
                f"requested lane {lane_id!r} must have exactly one manager owner; found {len(owners)}"
            )

    workers_value = topology.get("workers")
    if not isinstance(workers_value, list):
        errors.append("receipt.topology.workers must be an array")
        workers_value = []
    workers: dict[str, dict[str, Any]] = {}
    for index, raw_worker in enumerate(workers_value):
        worker = _check_exact_keys(
            raw_worker,
            {
                "worker_task_id",
                "manager_task_id",
                "requested_model",
                "requested_effort",
                "observed_model",
                "observed_effort",
            },
            f"receipt.topology.workers[{index}]",
            errors,
        )
        worker_id = _check_id(
            worker.get("worker_task_id"),
            f"receipt.topology.workers[{index}].worker_task_id",
            errors,
        )
        manager_id = _check_id(
            worker.get("manager_task_id"),
            f"receipt.topology.workers[{index}].manager_task_id",
            errors,
        )
        if manager_id and manager_id not in managers:
            errors.append(f"worker {worker_id!r} references unknown manager {manager_id!r}")
        _check_nonempty_string(
            worker.get("requested_model"),
            f"receipt.topology.workers[{index}].requested_model",
            errors,
        )
        _check_nonempty_string(
            worker.get("requested_effort"),
            f"receipt.topology.workers[{index}].requested_effort",
            errors,
        )
        observed_model = worker.get("observed_model")
        observed_effort = worker.get("observed_effort")
        if (observed_model is None) != (observed_effort is None):
            errors.append(f"worker {worker_id!r} observed model and effort must be paired")
        for field, value in (
            ("observed_model", observed_model),
            ("observed_effort", observed_effort),
        ):
            if value is not None:
                _check_nonempty_string(
                    value,
                    f"receipt.topology.workers[{index}].{field}",
                    errors,
                )
        if worker_id:
            if worker_id in workers:
                errors.append(f"duplicate worker task {worker_id!r}")
            workers[worker_id] = worker

    concurrency_limit = topology.get("concurrency_limit")
    if not _is_int(concurrency_limit) or concurrency_limit < 1:
        errors.append("receipt.topology.concurrency_limit must be a positive integer")
        concurrency_limit = None
    max_concurrency = topology.get("max_observed_concurrency")
    if max_concurrency is not None and (
        not _is_int(max_concurrency) or max_concurrency < 1
    ):
        errors.append(
            "receipt.topology.max_observed_concurrency must be a positive integer or null"
        )
        max_concurrency = None
    if (
        max_concurrency is not None
        and concurrency_limit is not None
        and max_concurrency > concurrency_limit
    ):
        errors.append("observed concurrency exceeds the declared concurrency limit")

    variances_value = topology.get("variances")
    if not isinstance(variances_value, list):
        errors.append("receipt.topology.variances must be an array")
        variances_value = []
    variance_keys: set[tuple[str, tuple[str, ...]]] = set()
    for index, raw_variance in enumerate(variances_value):
        variance = _check_exact_keys(
            raw_variance,
            {"type", "actor_task_id", "actor_role", "lane_ids", "reason"},
            f"receipt.topology.variances[{index}]",
            errors,
        )
        variance_type = variance.get("type")
        if variance_type not in {
            "host_cap_consolidation",
            "manager_direct_labor",
            "master_direct_labor",
            "other",
        }:
            errors.append(f"receipt.topology.variances[{index}].type is invalid")
        actor_id = _check_id(
            variance.get("actor_task_id"),
            f"receipt.topology.variances[{index}].actor_task_id",
            errors,
        )
        actor_role = variance.get("actor_role")
        if actor_role not in {"master", "manager"}:
            errors.append(f"receipt.topology.variances[{index}].actor_role is invalid")
        if actor_role == "manager" and actor_id and actor_id not in managers:
            errors.append(f"variance references unknown manager {actor_id!r}")
        if variance_type == "master_direct_labor" and actor_role != "master":
            errors.append("master_direct_labor must use actor_role master")
        if variance_type in {"host_cap_consolidation", "manager_direct_labor"} and actor_role != "manager":
            errors.append(f"{variance_type} must use actor_role manager")
        lane_ids = sorted(
            _check_string_list(
                variance.get("lane_ids"),
                f"receipt.topology.variances[{index}].lane_ids",
                errors,
                allow_empty=False,
            )
        )
        for lane_id in lane_ids:
            if lane_id not in lanes:
                errors.append(f"variance references unknown lane {lane_id!r}")
        _check_nonempty_string(
            variance.get("reason"),
            f"receipt.topology.variances[{index}].reason",
            errors,
        )
        if variance_type == "host_cap_consolidation" and len(lane_ids) < 2:
            errors.append("host_cap_consolidation must name at least two lanes")
        if variance_type == "host_cap_consolidation" and actor_id:
            variance_keys.add((actor_id, tuple(lane_ids)))

    for manager_id, manager in managers.items():
        owned = tuple(sorted(manager.get("lane_ids", [])))
        if len(owned) > 1 and (manager_id, owned) not in variance_keys:
            errors.append(
                f"manager {manager_id!r} owns multiple lanes without an exact disclosed variance"
            )

    if not workers and "first_worker_dispatch" not in timing_not_applicable:
        errors.append(
            "first_worker_dispatch must be not_applicable when no workers were dispatched"
        )
    if workers and "first_worker_dispatch" in timing_not_applicable:
        errors.append("first_worker_dispatch cannot be not_applicable when workers exist")

    usage = _check_exact_keys(
        root.get("usage"), set(USAGE_FIELDS) | {"unavailable"}, "receipt.usage", errors
    )
    usage_unavailable = set(
        _check_string_list(usage.get("unavailable"), "receipt.usage.unavailable", errors)
    )
    unknown_usage = usage_unavailable - set(USAGE_FIELDS)
    if unknown_usage:
        errors.append(
            "receipt.usage.unavailable references unknown fields: "
            + ", ".join(sorted(unknown_usage))
        )
    usage_values: dict[str, float | None] = {}
    for field in USAGE_FIELDS:
        value = usage.get(field)
        if value is None:
            usage_values[field] = None
            if field not in usage_unavailable:
                errors.append(
                    f"receipt.usage.{field} is null but is not declared unavailable"
                )
        elif not _is_number(value) or value < 0:
            errors.append(f"receipt.usage.{field} must be a non-negative number or null")
            usage_values[field] = None
        else:
            usage_values[field] = float(value)
            if field in usage_unavailable:
                errors.append(f"receipt.usage.{field} has a value but is marked unavailable")
    total_tokens = usage_values["total_tokens"]
    luna_tokens = usage_values["luna_tokens"]
    sol_tokens = usage_values["sol_tokens"]
    if total_tokens is not None and luna_tokens is not None and luna_tokens > total_tokens:
        errors.append("luna_tokens cannot exceed total_tokens")
    if total_tokens is not None and sol_tokens is not None and sol_tokens > total_tokens:
        errors.append("sol_tokens cannot exceed total_tokens")

    quality = _check_exact_keys(
        root.get("quality"),
        {
            "required_artifacts",
            "accepted_artifacts",
            "first_pass_accepted",
            "rework_cycles",
            "write_collisions",
            "duplicate_artifacts",
            "independent_reviewed",
        },
        "receipt.quality",
        errors,
    )
    for field in (
        "required_artifacts",
        "accepted_artifacts",
        "rework_cycles",
        "write_collisions",
        "duplicate_artifacts",
    ):
        value = quality.get(field)
        if not _is_int(value) or value < 0:
            errors.append(f"receipt.quality.{field} must be a non-negative integer")
    for field in ("first_pass_accepted", "independent_reviewed"):
        if not isinstance(quality.get(field), bool):
            errors.append(f"receipt.quality.{field} must be boolean")

    requirements_value = root.get("requirements")
    if not isinstance(requirements_value, list) or not requirements_value:
        errors.append("receipt.requirements must be a non-empty array")
        requirements_value = []
    requirements: dict[str, dict[str, Any]] = {}
    for index, raw_requirement in enumerate(requirements_value):
        requirement = _check_exact_keys(
            raw_requirement,
            {"requirement_id", "statement", "source", "mandatory"},
            f"receipt.requirements[{index}]",
            errors,
        )
        requirement_id = _check_id(
            requirement.get("requirement_id"),
            f"receipt.requirements[{index}].requirement_id",
            errors,
        )
        _check_nonempty_string(
            requirement.get("statement"),
            f"receipt.requirements[{index}].statement",
            errors,
        )
        _check_nonempty_string(
            requirement.get("source"),
            f"receipt.requirements[{index}].source",
            errors,
        )
        if not isinstance(requirement.get("mandatory"), bool):
            errors.append(f"receipt.requirements[{index}].mandatory must be boolean")
        if requirement_id:
            if requirement_id in requirements:
                errors.append(f"duplicate requirement {requirement_id!r}")
            requirements[requirement_id] = requirement

    results_value = root.get("requirement_results")
    if not isinstance(results_value, list):
        errors.append("receipt.requirement_results must be an array")
        results_value = []
    requirement_results: dict[str, dict[str, Any]] = {}
    for index, raw_result in enumerate(results_value):
        result = _check_exact_keys(
            raw_result,
            {"requirement_id", "status", "evidence"},
            f"receipt.requirement_results[{index}]",
            errors,
        )
        requirement_id = _check_id(
            result.get("requirement_id"),
            f"receipt.requirement_results[{index}].requirement_id",
            errors,
        )
        if requirement_id and requirement_id not in requirements:
            errors.append(f"requirement result references unknown requirement {requirement_id!r}")
        if result.get("status") not in {"satisfied", "unsatisfied", "unknown"}:
            errors.append(f"receipt.requirement_results[{index}].status is invalid")
        _check_string_list(
            result.get("evidence"),
            f"receipt.requirement_results[{index}].evidence",
            errors,
            allow_empty=False,
        )
        if requirement_id:
            if requirement_id in requirement_results:
                errors.append(f"duplicate requirement result {requirement_id!r}")
            requirement_results[requirement_id] = result
    missing_requirement_results = sorted(set(requirements) - set(requirement_results))
    if missing_requirement_results:
        errors.append(
            "requirements missing independent results: "
            + ", ".join(missing_requirement_results)
        )

    plan_value = root.get("artifact_plan")
    if not isinstance(plan_value, list):
        errors.append("receipt.artifact_plan must be an array")
        plan_value = []
    artifact_plan: dict[str, dict[str, Any]] = {}
    mandatory_requirement_ids = {
        requirement_id
        for requirement_id, requirement in requirements.items()
        if requirement.get("mandatory") is True
    }
    planned_requirement_ids: set[str] = set()
    planned_capability_bindings: set[tuple[str, str]] = set()
    for index, raw_plan in enumerate(plan_value):
        plan = _check_exact_keys(
            raw_plan,
            {
                "artifact_id",
                "kind",
                "expected_title",
                "owner_lane_id",
                "requirement_ids",
                "required_capability_ids",
            },
            f"receipt.artifact_plan[{index}]",
            errors,
        )
        artifact_id = _check_id(
            plan.get("artifact_id"), f"receipt.artifact_plan[{index}].artifact_id", errors
        )
        _check_nonempty_string(
            plan.get("kind"), f"receipt.artifact_plan[{index}].kind", errors
        )
        _check_nonempty_string(
            plan.get("expected_title"),
            f"receipt.artifact_plan[{index}].expected_title",
            errors,
        )
        owner_lane = _check_id(
            plan.get("owner_lane_id"),
            f"receipt.artifact_plan[{index}].owner_lane_id",
            errors,
        )
        if owner_lane and owner_lane not in lanes:
            errors.append(f"artifact plan references unknown lane {owner_lane!r}")
        requirement_ids = _check_id_list(
            plan.get("requirement_ids"),
            f"receipt.artifact_plan[{index}].requirement_ids",
            errors,
            allow_empty=False,
        )
        for requirement_id in requirement_ids:
            if requirement_id not in requirements:
                errors.append(
                    f"artifact plan {artifact_id!r} references unknown requirement {requirement_id!r}"
                )
            else:
                planned_requirement_ids.add(requirement_id)
        capability_ids = _check_id_list(
            plan.get("required_capability_ids"),
            f"receipt.artifact_plan[{index}].required_capability_ids",
            errors,
            allow_empty=False,
        )
        if artifact_id:
            planned_capability_bindings.update(
                (artifact_id, capability_id) for capability_id in capability_ids
            )
        if artifact_id:
            if artifact_id in artifact_plan:
                errors.append(f"duplicate planned artifact {artifact_id!r}")
            artifact_plan[artifact_id] = plan
    unmapped_mandatory_requirements = sorted(
        mandatory_requirement_ids - planned_requirement_ids
    )
    if unmapped_mandatory_requirements:
        errors.append(
            "mandatory requirements not mapped to an artifact: "
            + ", ".join(unmapped_mandatory_requirements)
        )

    artifacts_value = root.get("artifacts")
    if not isinstance(artifacts_value, list):
        errors.append("receipt.artifacts must be an array")
        artifacts_value = []
    artifacts: dict[str, dict[str, Any]] = {}
    external_ids: set[str] = set()
    artifact_requirement_gaps: dict[str, list[str]] = {}
    artifact_capability_gaps: dict[str, list[str]] = {}
    for index, raw_artifact in enumerate(artifacts_value):
        artifact = _check_exact_keys(
            raw_artifact,
            {
                "artifact_id",
                "kind",
                "title",
                "external_id",
                "owner_lane_id",
                "satisfied_requirement_ids",
                "applied_capability_ids",
                "refetched",
                "accepted",
            },
            f"receipt.artifacts[{index}]",
            errors,
        )
        artifact_id = _check_id(
            artifact.get("artifact_id"), f"receipt.artifacts[{index}].artifact_id", errors
        )
        kind = _check_nonempty_string(
            artifact.get("kind"), f"receipt.artifacts[{index}].kind", errors
        )
        title = _check_nonempty_string(
            artifact.get("title"), f"receipt.artifacts[{index}].title", errors
        )
        external_id = _check_nonempty_string(
            artifact.get("external_id"),
            f"receipt.artifacts[{index}].external_id",
            errors,
        )
        owner_lane = _check_id(
            artifact.get("owner_lane_id"),
            f"receipt.artifacts[{index}].owner_lane_id",
            errors,
        )
        if owner_lane and owner_lane not in lanes:
            errors.append(f"artifact {artifact_id!r} references unknown lane {owner_lane!r}")
        satisfied_requirement_ids = set(
            _check_id_list(
                artifact.get("satisfied_requirement_ids"),
                f"receipt.artifacts[{index}].satisfied_requirement_ids",
                errors,
            )
        )
        for requirement_id in satisfied_requirement_ids:
            if requirement_id not in requirements:
                errors.append(
                    f"artifact {artifact_id!r} claims unknown requirement {requirement_id!r}"
                )
        applied_capability_ids = set(
            _check_id_list(
                artifact.get("applied_capability_ids"),
                f"receipt.artifacts[{index}].applied_capability_ids",
                errors,
            )
        )
        for field in ("refetched", "accepted"):
            if not isinstance(artifact.get(field), bool):
                errors.append(f"receipt.artifacts[{index}].{field} must be boolean")
        if external_id:
            if external_id in external_ids:
                errors.append(f"duplicate artifact external_id {external_id!r}")
            external_ids.add(external_id)
        if artifact_id:
            if artifact_id in artifacts:
                errors.append(f"duplicate artifact {artifact_id!r}")
            artifacts[artifact_id] = artifact
            planned = artifact_plan.get(artifact_id)
            if planned is None:
                errors.append(f"artifact {artifact_id!r} is not in artifact_plan")
            else:
                comparisons = (
                    ("kind", kind, planned.get("kind")),
                    ("title", title, planned.get("expected_title")),
                    ("owner_lane_id", owner_lane, planned.get("owner_lane_id")),
                )
                for field, actual, expected in comparisons:
                    if actual != expected:
                        errors.append(
                            f"artifact {artifact_id!r} {field} does not match its plan"
                        )
                required_requirement_ids = set(planned.get("requirement_ids", []))
                required_capability_ids = set(
                    planned.get("required_capability_ids", [])
                )
                missing_requirement_ids = sorted(
                    required_requirement_ids - satisfied_requirement_ids
                )
                missing_capability_ids = sorted(
                    required_capability_ids - applied_capability_ids
                )
                artifact_requirement_gaps[artifact_id] = missing_requirement_ids
                artifact_capability_gaps[artifact_id] = missing_capability_ids
                if artifact.get("accepted") is True and missing_requirement_ids:
                    errors.append(
                        f"artifact {artifact_id!r} is accepted but misses requirements: "
                        + ", ".join(missing_requirement_ids)
                    )
                if artifact.get("accepted") is True and missing_capability_ids:
                    errors.append(
                        f"artifact {artifact_id!r} is accepted but misses required capabilities: "
                        + ", ".join(missing_capability_ids)
                    )
    missing_artifacts = sorted(set(artifact_plan) - set(artifacts))
    if missing_artifacts:
        errors.append("planned artifacts missing from readback: " + ", ".join(missing_artifacts))

    decision = _check_exact_keys(
        root.get("decision"),
        {
            "status",
            "reviewer",
            "authority",
            "required_authority",
            "evidence",
        },
        "receipt.decision",
        errors,
    )
    decision_status = decision.get("status")
    if decision_status not in {"accepted", "rework", "blocked", "failed"}:
        errors.append("receipt.decision.status is invalid")
    if status != decision_status:
        errors.append("receipt.status must equal receipt.decision.status")
    _check_nonempty_string(decision.get("reviewer"), "receipt.decision.reviewer", errors)
    decision_authority = decision.get("authority")
    required_authority = decision.get("required_authority")
    if decision_authority not in AUTHORITY_RANK:
        errors.append("receipt.decision.authority must be manager, master, or user")
    if required_authority not in AUTHORITY_RANK:
        errors.append(
            "receipt.decision.required_authority must be manager, master, or user"
        )
    authority_sufficient = bool(
        decision_authority in AUTHORITY_RANK
        and required_authority in AUTHORITY_RANK
        and AUTHORITY_RANK[decision_authority]
        >= AUTHORITY_RANK[required_authority]
    )
    _check_string_list(
        decision.get("evidence"), "receipt.decision.evidence", errors, allow_empty=False
    )

    required_artifacts = quality.get("required_artifacts")
    accepted_artifacts = quality.get("accepted_artifacts")
    if _is_int(required_artifacts) and required_artifacts != len(artifact_plan):
        errors.append("quality.required_artifacts must equal artifact_plan length")
    counted_accepted = sum(
        1
        for artifact in artifacts.values()
        if artifact.get("accepted") is True and artifact.get("refetched") is True
    )
    if _is_int(accepted_artifacts) and accepted_artifacts != counted_accepted:
        errors.append("quality.accepted_artifacts does not match accepted readback artifacts")

    satisfied_mandatory_requirements = {
        requirement_id
        for requirement_id in mandatory_requirement_ids
        if requirement_results.get(requirement_id, {}).get("status") == "satisfied"
    }
    mandatory_requirements_satisfied = bool(
        mandatory_requirement_ids
        and satisfied_mandatory_requirements == mandatory_requirement_ids
    )
    applied_capability_bindings = {
        (artifact_id, capability_id)
        for artifact_id, artifact in artifacts.items()
        for capability_id in artifact.get("applied_capability_ids", [])
    }
    applied_required_capability_bindings = (
        planned_capability_bindings & applied_capability_bindings
    )
    required_capabilities_applied = bool(
        planned_capability_bindings
        and planned_capability_bindings <= applied_capability_bindings
    )
    artifact_contracts_satisfied = bool(
        artifact_plan
        and set(artifact_plan) == set(artifacts)
        and all(
            not artifact_requirement_gaps.get(artifact_id)
            and not artifact_capability_gaps.get(artifact_id)
            and artifact.get("refetched") is True
            for artifact_id, artifact in artifacts.items()
        )
    )
    if status == "accepted" and not mandatory_requirements_satisfied:
        errors.append("accepted receipt has unsatisfied or unknown mandatory requirements")
    if status == "accepted" and not required_capabilities_applied:
        errors.append("accepted receipt is missing required capability application")
    if status == "accepted" and not authority_sufficient:
        errors.append("accepted receipt decision is below the required authority")

    delivery_accepted = bool(
        not errors
        and status == "accepted"
        and decision_status == "accepted"
        and quality.get("independent_reviewed") is True
        and mandatory_requirements_satisfied
        and required_capabilities_applied
        and artifact_contracts_satisfied
        and authority_sufficient
        and _is_int(required_artifacts)
        and required_artifacts > 0
        and accepted_artifacts == required_artifacts
        and quality.get("write_collisions") == 0
        and quality.get("duplicate_artifacts") == 0
    )
    hierarchy_materialized = bool(
        not errors and lanes and managers and all(len(lane_owners.get(lane_id, [])) == 1 for lane_id in lanes)
    )
    observed_luna_workers = [
        worker
        for worker in workers.values()
        if worker.get("observed_model") == "gpt-5.6-luna"
        and worker.get("observed_effort") == "max"
    ]
    all_worker_models_observed = bool(
        workers
        and all(
            worker.get("observed_model") is not None
            and worker.get("observed_effort") is not None
            for worker in workers.values()
        )
    )
    luna_execution_proven = bool(
        delivery_accepted
        and hierarchy_materialized
        and observed_luna_workers
        and all_worker_models_observed
    )

    required_timing = {
        "program_start",
        "first_manager_dispatch",
        "first_usable_result",
        "first_artifact_materialization",
        "final_acceptance",
    }
    if workers:
        required_timing.add("first_worker_dispatch")
    timing_complete = all(parsed_times.get(field) is not None for field in required_timing)
    usage_complete = all(usage_values[field] is not None for field in USAGE_FIELDS)
    lead_time_seconds: float | None = None
    if parsed_times.get("program_start") and parsed_times.get("final_acceptance"):
        lead_time_seconds = (
            parsed_times["final_acceptance"] - parsed_times["program_start"]
        ).total_seconds()
    luna_token_share: float | None = None
    if total_tokens and luna_tokens is not None:
        luna_token_share = luna_tokens / total_tokens
    sol_token_reduction: float | None = None
    baseline_sol = usage_values["single_thread_baseline_sol_tokens"]
    if baseline_sol and sol_tokens is not None:
        sol_token_reduction = 1.0 - (sol_tokens / baseline_sol)
    lead_time_improvement: float | None = None
    baseline_lead = usage_values["single_thread_baseline_lead_time_seconds"]
    if baseline_lead and lead_time_seconds is not None:
        lead_time_improvement = 1.0 - (lead_time_seconds / baseline_lead)

    scaling_evidence_eligible = bool(
        delivery_accepted
        and hierarchy_materialized
        and luna_execution_proven
        and timing_complete
        and usage_complete
        and max_concurrency is not None
        and lead_time_seconds is not None
    )
    efficiency_proven = bool(
        scaling_evidence_eligible
        and sol_token_reduction is not None
        and sol_token_reduction >= 0.40
        and lead_time_improvement is not None
        and lead_time_improvement >= 0.0
    )

    if not workers:
        warnings.append("no worker tasks were dispatched; Luna execution is unproven")
    if timing_unavailable:
        warnings.append(
            "timing unavailable: " + ", ".join(sorted(timing_unavailable))
        )
    if usage_unavailable:
        warnings.append("usage unavailable: " + ", ".join(sorted(usage_unavailable)))
    if any(manager.get("observed_model") is None for manager in managers.values()):
        warnings.append("one or more manager models were not observed")
    if workers and not all_worker_models_observed:
        warnings.append("one or more worker models were not observed")
    if quality.get("first_pass_accepted") is False:
        warnings.append("final acceptance required rework")
    unsatisfied_mandatory_requirements = sorted(
        mandatory_requirement_ids - satisfied_mandatory_requirements
    )
    if unsatisfied_mandatory_requirements:
        warnings.append(
            "mandatory requirements not satisfied: "
            + ", ".join(unsatisfied_mandatory_requirements)
        )
    missing_required_capabilities = sorted(
        planned_capability_bindings - applied_capability_bindings
    )
    if missing_required_capabilities:
        warnings.append(
            "required capabilities not applied: "
            + ", ".join(
                f"{artifact_id}:{capability_id}"
                for artifact_id, capability_id in missing_required_capabilities
            )
        )
    if not authority_sufficient:
        warnings.append("acceptance decision is below the required authority")

    return {
        "source": source,
        "program_id": program_id,
        "comparison_class": comparison_class,
        "ok": not errors,
        "errors": errors,
        "warnings": warnings,
        "metrics": {
            "requested_lanes": len(lanes),
            "unique_managers": len(managers),
            "workers": len(workers),
            "observed_luna_max_workers": len(observed_luna_workers),
            "maximum_observed_concurrency": max_concurrency,
            "mandatory_requirements_satisfied": len(
                satisfied_mandatory_requirements
            ),
            "mandatory_requirements_total": len(mandatory_requirement_ids),
            "required_capabilities_applied": len(
                applied_required_capability_bindings
            ),
            "required_capabilities_total": len(planned_capability_bindings),
            "accepted_artifact_rate": (
                accepted_artifacts / required_artifacts
                if _is_int(required_artifacts)
                and required_artifacts > 0
                and _is_int(accepted_artifacts)
                else None
            ),
            "first_pass_accepted": quality.get("first_pass_accepted"),
            "rework_cycles": quality.get("rework_cycles"),
            "write_collisions": quality.get("write_collisions"),
            "duplicate_artifacts": quality.get("duplicate_artifacts"),
            "lead_time_seconds": lead_time_seconds,
            "luna_token_share": luna_token_share,
            "sol_token_reduction": sol_token_reduction,
            "lead_time_improvement": lead_time_improvement,
        },
        "gates": {
            "delivery_accepted": delivery_accepted,
            "mandatory_requirements_satisfied": mandatory_requirements_satisfied,
            "required_capabilities_applied": required_capabilities_applied,
            "acceptance_authority_satisfied": authority_sufficient,
            "hierarchy_materialized": hierarchy_materialized,
            "luna_execution_proven": luna_execution_proven,
            "efficiency_proven": efficiency_proven,
            "scaling_evidence_eligible": scaling_evidence_eligible,
        },
        "_aggregate": {
            "status": status,
            "quality": quality,
            "usage": usage_values,
            "lead_time_seconds": lead_time_seconds,
        },
    }


def aggregate_results(results: list[dict[str, Any]]) -> dict[str, Any]:
    groups: dict[str, list[dict[str, Any]]] = defaultdict(list)
    for result in results:
        comparison_class = result.get("comparison_class")
        if result.get("ok") and isinstance(comparison_class, str):
            groups[comparison_class].append(result)

    output: dict[str, Any] = {}
    for comparison_class, group in sorted(groups.items()):
        cycles = len(group)
        accepted = sum(1 for item in group if item["gates"]["delivery_accepted"])
        first_pass = sum(
            1 for item in group if item["metrics"]["first_pass_accepted"] is True
        )
        rework_cycles = sum(
            item["metrics"]["rework_cycles"]
            for item in group
            if _is_int(item["metrics"]["rework_cycles"])
        )
        collisions = sum(
            item["metrics"]["write_collisions"]
            for item in group
            if _is_int(item["metrics"]["write_collisions"])
        )
        duplicates = sum(
            item["metrics"]["duplicate_artifacts"]
            for item in group
            if _is_int(item["metrics"]["duplicate_artifacts"])
        )
        total_tokens_values = [item["_aggregate"]["usage"]["total_tokens"] for item in group]
        luna_tokens_values = [item["_aggregate"]["usage"]["luna_tokens"] for item in group]
        sol_tokens_values = [item["_aggregate"]["usage"]["sol_tokens"] for item in group]
        baseline_sol_values = [
            item["_aggregate"]["usage"]["single_thread_baseline_sol_tokens"]
            for item in group
        ]
        luna_share = None
        if all(value is not None for value in total_tokens_values + luna_tokens_values):
            total = sum(total_tokens_values)
            luna_share = sum(luna_tokens_values) / total if total else None
        sol_reduction = None
        if all(value is not None for value in sol_tokens_values + baseline_sol_values):
            baseline = sum(baseline_sol_values)
            sol_reduction = 1.0 - (sum(sol_tokens_values) / baseline) if baseline else None
        lead_nonregression = all(
            item["metrics"]["lead_time_improvement"] is not None
            and item["metrics"]["lead_time_improvement"] >= 0
            for item in group
        )
        first_pass_rate = first_pass / cycles if cycles else 0.0
        rework_rate = rework_cycles / (cycles + rework_cycles) if cycles + rework_cycles else 0.0
        all_eligible = all(item["gates"]["scaling_evidence_eligible"] for item in group)
        scale_gate = bool(
            cycles >= 3
            and accepted == cycles
            and all_eligible
            and first_pass_rate >= 0.85
            and rework_rate < 0.20
            and collisions == 0
            and duplicates == 0
            and luna_share is not None
            and luna_share >= 0.70
            and sol_reduction is not None
            and sol_reduction >= 0.40
            and lead_nonregression
        )
        output[comparison_class] = {
            "cycles": cycles,
            "accepted_cycles": accepted,
            "first_pass_rate": first_pass_rate,
            "rework_rate": rework_rate,
            "write_collisions": collisions,
            "duplicate_artifacts": duplicates,
            "luna_token_share": luna_share,
            "sol_token_reduction": sol_reduction,
            "lead_time_nonregression": lead_nonregression,
            "all_receipts_scaling_eligible": all_eligible,
            "scale_gate_passed": scale_gate,
        }
    return output


def parser() -> argparse.ArgumentParser:
    result = argparse.ArgumentParser()
    result.add_argument("receipts", nargs="+", type=Path)
    return result


def main() -> int:
    args = parser().parse_args()
    results: list[dict[str, Any]] = []
    load_errors: list[str] = []
    for path in args.receipts:
        try:
            receipt = _load_receipt(path)
        except ReceiptError as error:
            load_errors.append(str(error))
            continue
        results.append(validate_receipt(receipt, str(path)))
    payload = {
        "schema": "company-os.execution-efficiency-validation.v1",
        "ok": not load_errors and all(result["ok"] for result in results),
        "load_errors": load_errors,
        "receipts": [
            {key: value for key, value in result.items() if key != "_aggregate"}
            for result in results
        ],
        "comparison_groups": aggregate_results(results),
    }
    sys.stdout.write(_canonical_json(payload) + "\n")
    return 0 if payload["ok"] else 1


if __name__ == "__main__":
    raise SystemExit(main())

# Hit Areas

Target sizes, expanding hit areas without changing visual size, and collision rules.

## Target sizes

Separate the conformance baseline from larger usability targets:

| Standard | Minimum |
| --- | --- |
| WCAG 2.5.8 (AA) | 24×24px, the hard floor |
| WCAG 2.5.5 (AAA) | 44×44px |
| Apple HIG | 44×44pt |
| Material Design | 48×48dp |

WCAG 2.5.8 Level AA requires a 24×24 CSS-pixel target or one of its defined exceptions. Treat 44px as a recommended touch target for primary controls and 40px as a useful desktop target when the product's density permits. Smaller controls are not automatically failures: check the spacing, equivalent-control, inline, user-agent, and essential exceptions before reporting one.

Under the spacing exception, an undersized target passes if a 24px circle centered on its bounding box does not intersect another target or another undersized target's circle; in the simple case, 20px targets need at least a 4px gap.

The visible element can stay small; the hit area is what must be big. If it looks clickable, it must be clickable across its whole visual extent: no dead zones (a checkbox and its label share one hit target).

## Expanding the hit area

If the visible element is smaller (e.g., a 20×20 checkbox), extend the hit area with a pseudo-element. Put the pseudo-element on the wrapping `<label>` or `<button>`, not on the `<input>` itself; replaced elements don't render `::before`/`::after` reliably.

### CSS Example

```css
/* Small checkbox with expanded 44px hit area, on the wrapping label */
.checkbox-label {
  position: relative;
  width: 20px;
  height: 20px;
}

.checkbox-label::after {
  content: "";
  position: absolute;
  top: 50%;
  left: 50%; /* physical centering: direction-independent */
  transform: translate(-50%, -50%);
  width: 44px;
  height: 44px;
}
```

### Tailwind Example

```tsx
<button className="relative size-5 after:absolute after:top-1/2 after:left-1/2 after:size-11 after:-translate-1/2">
  <CheckIcon />
</button>
```

### Layout alternative

When the element can afford real box size, skip the pseudo-element and let the box itself be the target; this also gives the browser the real geometry for scrolling and gestures:

```css
.icon-button {
  min-width: 44px;
  min-height: 44px;
  display: inline-grid;
  place-items: center;
}
```

## Collision Rule

If the extended hit area overlaps another interactive element, shrink the pseudo-element, but make it as large as possible without colliding. Two interactive elements should never have overlapping hit areas.

## Decorative layers

A decorative layer painted over interactive content absorbs every pointer event its box covers: a gradient scrim, a glow, a blurred sheen, a full-bleed `::after`. The control underneath looks live and does nothing, and no amount of hit-area sizing fixes it.

Give each one `pointer-events: none` (Tailwind: `pointer-events-none`) so events reach the control below, plus `aria-hidden="true"` to keep it out of the accessibility tree:

```css
.card-glow {
  position: absolute;
  inset: 0;
  pointer-events: none;
}
```

Keep pointer events on any layer the user is meant to hit: a modal scrim that dismisses on click is a control, not decoration.

## Touch behavior

- Add `touch-action: manipulation` to interactive elements to remove the double-tap-to-zoom delay on mobile.
- Set `touch-action: none` on a surface implementing its own pan, zoom, or drag gestures, so the browser stops claiming those gestures for scrolling and pinch-zoom. Scope it to that surface; at page level it takes away scrolling.
- Set `-webkit-tap-highlight-color` to match the design instead of the default gray flash.
- Put hover-only styling behind `@media (hover: hover)`. On touch, `:hover` latches after a tap and holds until the user taps elsewhere, so the hover treatment reads as a stuck selected state. Tailwind 4's `hover:` variant already compiles under this query.
- Prefer generous targets and clear affordances over finicky interactions (tiny drag handles, precise hover zones).

# Motion and Zoom

`prefers-reduced-motion`, zoom and reflow, and unit choices that respect user settings.

## prefers-reduced-motion

Make motion opt-in: wrap animations in `@media (prefers-reduced-motion: no-preference)` so users who asked for reduced motion get the static version by default, instead of you chasing every animation with an override.

```css
/* Good: motion is opt-in */
.card {
  /* static styles */
}
@media (prefers-reduced-motion: no-preference) {
  .card {
    transition: transform 200ms ease-out;
  }
}
```

```tsx
// Tailwind: motion-safe / motion-reduce variants
<div className="motion-safe:transition-transform motion-safe:hover:-translate-y-1" />
```

For an existing codebase where opt-in isn't feasible, the global kill switch is the fallback:

```css
@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}
```

`0.01ms` rather than `none` so `animationend`/`transitionend` events still fire and JS that waits on them doesn't hang.

### What to disable vs reduce

Reduced motion means reduced, not eliminated: it targets vestibular triggers, not feedback.

| Disable entirely | Replace | Keep |
| --- | --- | --- |
| Parallax scrolling | Slide/scale/zoom transitions → opacity crossfade | Loading spinners and progress |
| Autoplaying video, GIFs, looping decoration | Smooth scrolling → instant jump | Instant state changes (hover color, focus ring) |
| Spinning, large-scale movement across the screen | Auto-rotating carousels → start paused | Brief functional feedback (button press) |

Animations must be interruptible and driven by user input; nothing should autoplay or refuse to stop. Under reduced motion, carousels start paused.

## Autoplay and timed UI

Motion the user didn't ask for, and UI that acts on its own schedule:

- **No autoplaying media without visible controls** (WCAG 2.2.2): anything that moves, blinks or updates automatically for more than 5 seconds needs a visible pause/stop control. Muted looping hero videos included.
- **Prefer explicit dismissal over timers.** Auto-dismissing toasts are acceptable only for low-stakes confirmations; anything containing an action, an error, or information the user may need to act on stays until dismissed. If a toast must time out, 5 seconds is the floor, and hovering or focusing it pauses the timer.
- **Never put critical information only in a timed element.** A vanished toast with the only link to an undo action is data loss on a schedule.

## Zoom and reflow

- **200% zoom** (WCAG 1.4.4): all content and functionality must survive text scaled to 200%, and the viewport must leave the reader able to zoom.
- **Reflow at 320px** (WCAG 1.4.10): at 400% zoom on a 1280px viewport (equivalent to a 320px viewport) the page must work with vertical scrolling only: no two-dimensional scrolling except for genuinely 2D content (tables, maps, code blocks), which scroll inside their own container.

Fixed heights are what break under zoom: use `min-height` on anything containing text and let containers grow.

### rem vs px

Respect how the codebase is set up: if the project sizes in `px` (or an established Tailwind scale), stay consistent with it; don't introduce mixed units into someone else's system. Where you do have the choice (new code, or a codebase already on `rem`), `rem` respects the user's base font size and `px` ignores it:

| Use `rem` | Use `px` |
| --- | --- |
| `font-size` | Borders and hairlines |
| `max-width` of text containers | Focus outline width and offset |
| Media-query breakpoints (`@media (min-width: 48rem)`) | `box-shadow` details |
| Spacing that should scale with text | Fixed-size decorations |

Breakpoints are where the choice matters most: at a larger base font size, an `em`/`rem` query switches to the mobile layout when the text needs it; a `px` query doesn't.

# Color Formats

Which notation to write colors in, how to convert between them, and what happens at the edges of a display's gamut. This is the only file in this skill concerned with notation; every other rule here is expressed in perceptual terms and holds regardless of what you write the values in.

## Choosing a notation

| Notation | Good for | Weakness |
| --- | --- | --- |
| Hex | Universal support, compact, what design tools hand you | Opaque — no channel is readable or editable by hand |
| `rgb()` | Same reach as hex, readable alpha | Channels do not correspond to anything a designer thinks about |
| `hsl()` | Channels look like design controls | Its lightness is not perceptual and its hue drifts; a ramp built by varying lightness bunches at one end and shifts hue |
| `oklch()` | Perceptually uniform lightness, stable hue, predictable ramps | Baseline 2023, so very old browser matrices need a fallback |

**Match whatever the project already uses.** A consistent hex system is better than a hex system with a few `oklch()` values scattered through it, and introducing a second representation to fix one color makes the palette harder to reason about, not easier. Notation is not a defect: a project on hex is not doing it wrong.

**For a genuinely new color system, `oklch()` is the best default.** It is the one notation where the numbers behave the way the ramp rules in [palette-generation.md](palette-generation.md) describe — even lightness steps stay even, and a fixed hue stays fixed. Everywhere else, a color library gets you the same ramp and emits whatever the project writes.

```css
oklch(L C H)          /* lightness 0–1, chroma 0–~0.4, hue 0–360 */
oklch(L C H / alpha)  /* alpha uses a slash, never a comma */
```

## Converting

Convert when the user asks, when an agreed migration is in scope, or when the project is already standardizing on a notation and this value is the straggler. Do not convert an isolated value in a project that deliberately uses something else, and do not convert because this skill happened to load.

When conversion is in scope, change the values and nothing else:

- Leave CSS keywords alone: `currentColor`, `inherit`, `transparent`, `initial`, `unset`.
- Leave gradient functions alone. Convert the color stops inside them; do not touch the interpolation method.
- Leave colors in third-party configs that expect a specific format.
- Preserve comments and formatting.

```css
/* Before */
color: #3b82f6;
border: 1px solid rgba(0, 0, 0, 0.1);

/* After */
color: oklch(0.623 0.188 259.815);
border: 1px solid oklch(0 0 0 / 0.1);
```

Bulk conversion is a migration, not cleanup. It changes every rendered color by a rounding margin and touches files nobody asked about, so it needs to be the task rather than a side effect of one.

## Gamut

Every sRGB color exists in Display P3; the reverse is not true. P3 covers roughly 50% more colors, which matters only for the most saturated values — a color at 60% of maximum vividness looks the same on both.

A color more vivid than its display can render gets clipped, and clipping is not graceful: it flattens neighbouring steps into the same rendered color, so the top of a ramp can lose its distinctions entirely on an sRGB screen. Maximum achievable vividness varies by both hue and lightness — cyans top out far lower than reds and purples — so a ramp that clips does so at some steps and not others.

The fix is to reduce vividness while holding hue and lightness. Generate ramps against sRGB unless the product is display-restricted, then add P3 as an enhancement:

```css
.accent {
  background: #3b82f6;
}

@media (color-gamut: p3) {
  .accent {
    background: oklch(0.62 0.24 259);
  }
}
```

Order matters: the sRGB value comes first so every display gets something, and the P3 rule only overrides where it will actually render. A P3 color with no fallback is a `HIGH` finding — it does not degrade, it fails.

For browser matrices predating `oklch()` support, the same layering works with `@supports`:

```css
.accent {
  background: #3b82f6;
}

@supports (color: oklch(0 0 0)) {
  .accent {
    background: oklch(0.62 0.19 259);
  }
}
```

Check the project's actual browser matrix before adding this. On a modern baseline it is dead weight.

## Modern CSS worth knowing

- **`color-mix()`** derives one color from another — `color-mix(in oklab, var(--color-accent-solid) 15%, white)` for a tinted background. Useful for states; keep generated values out of the token layer, since a mixed color cannot be inspected in a design tool.
- **Relative color syntax** — `oklch(from var(--color-accent-solid) calc(l - 0.1) c h)` — adjusts one channel of an existing color. Powerful and easy to overuse: a token defined by three chained derivations is unreadable.
- **`light-dark()`** puts both appearances in one declaration. See [palette-generation.md](palette-generation.md).

All three compute at render time, so their output cannot be contrast-checked statically. Measure the rendered result.

# Color Usage

How to deploy color once the system exists: meaning, emphasis, gradients, and appearance variants. For picking the values, see [palette-generation.md](palette-generation.md); for naming them, see [token-naming.md](token-naming.md); for checking pairs, see [contrast.md](contrast.md).

## One color, one meaning

Use a color for one purpose — interactive, destructive, featured — across the whole interface. If the accent signals that text is interactive, that hue on non-interactive text tells users to click something that is not clickable. Treat anything within about 15° of hue as the same color for this purpose; users do not perceive a near-miss as a different color, only as a slightly different shade of the same one.

```css
/* Bad: the accent means both "link" and "decorative heading" */
a { color: #3b82f6; }
.section-title { color: #4f8ef7; }

/* Good: interactive elements own the accent; headings stay neutral */
a { color: var(--color-accent-text); }
.section-title { color: var(--color-text-primary); }
```

The rule runs in both directions. A color that means one thing must also not be *absent* where that thing occurs: if the accent means interactive, an interactive element rendered in neutral is just as misleading.

Color is never the only carrier of meaning — pair it with an icon, a label, or a shape. `better-accessibility` owns that requirement.

## Use tokens in their role

Apply a semantic token only for the role it names. `--color-text-secondary` is muted foreground text; using it as a background breaks every future theme change that assumes the role, because the value that happened to work as both will stop working as both.

```css
/* Bad: separator token repurposed as a text color because it looked right */
.caption { color: var(--color-border); }

/* Bad: text token repurposed as a background */
.tag { background: var(--color-text-secondary); }
```

If a role has no token yet, add the token. Never borrow one by value — the role inventory in [token-naming.md](token-naming.md) is the list of roles a system needs.

## One colored action per view

When the product uses a filled color to encode primary emphasis, give that treatment to one primary action in the current decision context and leave peer actions neutral. Multiple colored backgrounds are fine when they encode distinct states or categories rather than competing as peer actions. Preserve an established component hierarchy that communicates emphasis another way; do not recolor controls merely to impose this recipe.

```html
<!-- Good: one filled primary action, neutral secondaries -->
<button class="bg-accent-solid text-white">Save</button>
<button class="text-neutral-700">Cancel</button>

<!-- Bad: every action colored, so nothing is primary -->
<button class="bg-accent-solid text-white">Save</button>
<button class="bg-accent-solid text-white">Duplicate</button>
<button class="bg-accent-solid text-white">Export</button>
```

Put the color on the background, not the label: a filled button reads as primary from across the room, while accent-colored label text on a neutral button reads as a link. Selected states — an active tab, a checked segment — may use the accent on the glyph and label; that is state, not emphasis.

## Gradients

**The interpolation space is a look, not a correctness setting.** Three are worth knowing, and the difference between them is most visible in the middle of the gradient:

```css
/* sRGB — the default and the classic. Midpoint darkens and mutes. */
background: linear-gradient(#3b82f6, #ec4899);

/* oklab — even brightness across the transition. The best default. */
background: linear-gradient(in oklab, #3b82f6, #ec4899);

/* oklch — travels around the hue wheel, staying vivid throughout. */
background: linear-gradient(in oklch, #3b82f6, #ec4899);
```

`oklab` and sRGB are **rectangular**: they interpolate in a straight line through the color space. `oklch` is **polar**: it interpolates the hue angle, so it arcs around the wheel and passes through every hue between the two stops. That is why it stays saturated, and also why it can produce hues nobody asked for — a blue-to-pink gradient routes through purple, which may be exactly the look or may be a surprise.

**The gray dead zone is a rectangular-space problem.** Two hues on opposite sides of the wheel sit on either side of the neutral axis, so a straight line between them passes near gray and the middle goes lifeless. Two fixes: switch to a polar space, which routes around the axis instead of through it, or add a third stop at a hue between the two and keep the space you have.

With a polar space you also control which way it goes around:

```css
/* The short way round — usually what you want */
background: linear-gradient(in oklch shorter hue, #3b82f6, #ec4899);

/* The long way — sweeps most of the spectrum */
background: linear-gradient(in oklch longer hue, #3b82f6, #ec4899);
```

**Banding shows up on large areas.** A gradient spanning a hero section with little contrast between its stops will step visibly on 8-bit displays. Widen the contrast between stops, shrink the area, or overlay a subtle noise texture.

**Keep text off gradients where you can.** Contrast varies continuously across a gradient, so a single measurement does not describe it. If text must sit on one, measure against the worst region rather than the average, or put a scrim behind it.

## Color across cultures

Color meaning is not universal. If a color is load-bearing — finance, status, alerts — verify the meaning holds in every locale you ship to.

| Color | Common Western reading | Elsewhere |
| --- | --- | --- |
| Red | Danger, loss, errors | Luck, prosperity; **gains** in Chinese financial UIs |
| Green | Success, gains, go | Losses in Chinese financial UIs |
| White | Purity, cleanliness | Mourning in parts of East Asia |
| Gold | Premium, luxury | Religious significance in some regions |

The classic case: stock tickers show gains in green for English locales and in red for Chinese ones. If the product localizes into such markets, make gain and loss per-locale tokens rather than hardcoded values.

## Light, dark, and increased contrast

Every custom color needs a light and a dark variant; deriving the dark appearance is covered in [palette-generation.md](palette-generation.md). Beyond that, users who enable increased contrast expect visibly stronger differentiation:

```css
:root {
  --color-accent-solid: #3b82f6;
}

@media (prefers-color-scheme: dark) {
  :root { --color-accent-solid: #60a5fa; }
}

@media (prefers-contrast: more) {
  :root { --color-accent-solid: #1d4ed8; }
}
```

The increased-contrast variant widens the foreground/background gap by at least 15 points of perceived lightness over the default, then gets re-verified against APCA's preferred thresholds (Lc 90 body, Lc 75 non-body). Widening the gap without remeasuring is not the same as fixing it.

# Palette Generation

Producing the values once the structure is decided. For which ramps to build and what each step is for, see [palette-structure.md](palette-structure.md).

## Start from the brand color

A brand color arrives as a single value, usually a hex. Two decisions come before any ramp exists:

**Which step does it occupy?** A brand color meant for buttons and links belongs on the solid-fill step — `500` in a Tailwind ramp, `9` in a Radix one. Placing it there means `bg-brand-500` renders the actual brand color rather than an approximation of it.

**Is it pinned or snapped?** If the brand color is contractually fixed, pin it: it stays exact and the ramp is built outward from it, accepting slightly uneven spacing at that step. Otherwise snap it — nudge it onto the ramp so every step is evenly spaced, which is almost always the better-looking result and is invisible to everyone who has not held a swatch against the screen.

If the brand color fails contrast as a fill behind white text, it is still the brand color; it is just not the solid-fill step. Put it where it lands and use a darker step for interactive fills. Do not quietly darken the brand.

## What a correct ramp looks like

These are properties of the finished ramp, checkable against any output, in any notation:

- **Steps are evenly spaced in perceived lightness.** Not in the number your format happens to call "lightness" — HSL's lightness is not perceptual, and evenly spaced HSL values produce a ramp that bunches at one end.
- **Hue is constant end to end.** Every step is recognisably the same color. A ramp whose hue wanders reads as two colors blended, and it will not sit correctly against a neutral built on a different hue.
- **Vividness peaks in the middle and falls off at both ends.** The lightest and darkest steps are nearly neutral; the middle steps carry the color. A ramp that holds full vividness into the extremes produces a `50` that glows and a `950` that looks like ink spilled on the brand.
- **Steps are denser at the light end.** Light backgrounds need finer distinctions than dark ones — `50` to `200` should be close together, `800` to `950` further apart. Evenly spaced lightness across the whole range makes the pale end unusable, because `50` and `100` will not be distinguishable as two different surfaces.
- **No two adjacent steps are indistinguishable.** If `200` and `300` look identical on a calibrated screen, the ramp has more steps than it has decisions. Drop one.
- **Both ends stop short of pure black and white.** Pure black and pure white cannot carry any hue, so a ramp that reaches them loses its identity exactly where the page background lives.

## Use a color library

Do not compute these by hand or by eye. `culori`, `colorjs.io`, and `chroma.js` all convert between every notation, measure perceived lightness, and interpolate perceptually. Read the brand color in whatever format it arrives, do the math in a perceptual space, and emit the notation the project already uses:

```js
import { formatHex, interpolate, samples } from 'culori'

// Perceptual interpolation, hex in and hex out.
const ramp = interpolate(['#eff6ff', '#3b82f6', '#172554'], 'lab')
const steps = samples(11).map((t) => formatHex(ramp(t)))
```

The output format is the project's choice; for a ramp the interpolation space is not, because the steps have to land evenly in perceived lightness and sRGB interpolation is what produces muddy mid-steps. Decorative gradients are the opposite case, where the space is a deliberate look ([color-usage.md](color-usage.md)).

```css
:root {
  --brand-50: #eff6ff;
  --brand-100: #dbeafe;
  --brand-200: #bfdbfe;
  --brand-300: #93c5fd;
  --brand-400: #60a5fa;
  --brand-500: #3b82f6;
  --brand-600: #2563eb;
  --brand-700: #1d4ed8;
  --brand-800: #1e40af;
  --brand-900: #1e3a8a;
  --brand-950: #172554;
}
```

## Several hues at once

When a system has an accent plus status ramps, the ramps must agree step for step: `danger-500` and `brand-500` should read as equally bright and equally vivid, or a red button will look heavier than a blue one at the same step.

- **Match perceived lightness exactly.** Same step, same brightness, across every hue.
- **Match vividness relatively, not absolutely.** Hues do not have the same maximum vividness — a saturated yellow and a saturated blue are not equally far from gray, and no format makes them so. Set each ramp to the same *proportion* of what its own hue can reach. Copying one ramp's saturation number onto another hue makes one of them look washed out.

Yellows and cyans are the usual casualties: both peak much lower than reds and blues, so a status ramp built by copying numbers will have a warning color that looks weak next to the danger color.

## Dark mode

A dark palette is not the light palette reversed. Reversal is the starting point, not the output.

Swap the semantic roles first, then tune the values:

```css
:root {
  --color-bg: var(--brand-50);
  --color-text: var(--brand-950);
}

.dark {
  --color-bg: var(--brand-950);
  --color-text: var(--brand-50);
}
```

Three things almost always need hand-tuning after the swap:

- **Vividness comes down.** A saturated color that reads as confident on white reads as neon on near-black. Dark appearances generally need the accent a step or two less vivid.
- **The dark end needs more separation.** Steps that were distinguishable as pale backgrounds collapse into each other as dark surfaces.
- **Contrast does not survive the mirror.** A pair passing in light mode can fail reversed, because contrast is not symmetric. Recheck every foreground against its actual background in both appearances — see [contrast.md](contrast.md).

### Choosing the switching mechanism

Pick one and use it throughout:

- **`prefers-color-scheme` alone** — correct when the product has no theme toggle. Nothing to persist, nothing to hydrate.
- **A `.dark` class** — required as soon as users can override the system setting. The media query then only sets the initial value.
- **`light-dark()`** — collapses both values into one declaration and is the least code when the project also sets `color-scheme`. It reads the `color-scheme` property, not a class, so a class-based toggle must set `color-scheme` too.

```css
:root {
  color-scheme: light dark;
  --color-bg: light-dark(#ffffff, #172554);
}
```

Mixing mechanisms is the common failure: a media query setting some tokens and a class setting others gives a half-themed interface the moment a user overrides their system preference.

# Spacing & Adaptivity

Space between controls, margins against the viewport, hinting at off-screen content, and layouts that survive resizing and translation.

## Breathing Room Between Targets

Controls placed too close together get mis-tapped and read as one unit. When the project has no established density scale, use these starting points:

| Between | Starting point |
| --- | --- |
| Adjacent bordered/filled controls (buttons, inputs) | `12px` |
| Around borderless controls (text buttons, icon buttons) | `24px` |
| Unrelated control groups | `24px`+ (2× the intra-group gap) |

Borderless controls usually need more clearance because nothing marks where one target ends and the next begins; the space itself is the boundary. Compact professional tools may use less when the hit areas remain distinct and do not overlap. Preserve an established, usable density instead of expanding controls solely to match these values.

```html
<!-- Good: bordered buttons at 12px, icon buttons given room -->
<div class="flex gap-3">
  <button class="rounded-lg border px-4 py-2">Cancel</button>
  <button class="rounded-lg bg-blue-600 px-4 py-2 text-white">Save</button>
</div>

<!-- Bad: three borderless icon buttons packed at 4px -->
<div class="flex gap-1">
  <button><TrashIcon /></button>
  <button><ArchiveIcon /></button>
  <button><ShareIcon /></button>
</div>
```

WCAG target-size requirements, larger usability targets, and pseudo-element expansion are covered by the `better-accessibility` skill; these clearances are in addition, so expanded hit areas never overlap.

## Inset Buttons from the Edges

In content layouts, buttons pressed accidentally against the viewport can look like system chrome and clip against curved corners or gesture zones. Keep them inside the layout margins. Edge-to-edge actions remain valid when they intentionally are application/platform chrome and account for safe areas:

```css
/* Good: inset action bar */
.action-bar {
  padding-inline: 16px;
  padding-bottom: calc(16px + env(safe-area-inset-bottom));
}
.action-bar button { width: 100%; border-radius: 12px; }

/* Bad: button glued to all three edges */
.action-bar button {
  width: 100vw;
  border-radius: 0;
  position: fixed;
  bottom: 0;
}
```

Start near `16px` inline margin on mobile when the project has no layout token; the button can still span the full content width inside those margins.

## Progressive Disclosure Needs an Affordance

Hiding complexity is good; hiding it without a cue is a trap. Every piece of off-screen or collapsed content needs a visible hint that it exists. Preserve the product's established scroll indicator or disclosure pattern; use the recipes below when no clear cue exists:

- **Peeking items.** In a horizontal scroller or carousel, size items so the next one peeks `16–32px` past the container edge. A row of cards that ends exactly at the edge looks complete, and nobody scrolls it.
- **Disclosure controls.** Collapsed sections get a chevron or "Show more" control; the label states what's hidden ("Show 12 more results"), not just "More".
- **Truncation cues.** Clamped text shows an ellipsis and a way to expand; see `better-typography` for truncation mechanics.

The peeking-scroller recipe: the container's padding creates the peek, and snap points stay on the content edge.

```css
.scroller {
  display: flex;
  gap: 12px;
  overflow-x: auto;
  padding-inline: 24px;
  scroll-padding-inline: 24px;
  scroll-snap-type: x mandatory;
}
.scroller > * {
  flex: 0 0 calc(100% - 48px - 24px); /* container minus margins minus peek */
  scroll-snap-align: start;
}
```

```html
<!-- Tailwind: the 80% width keeps the next card's leading 16-32px visible -->
<div class="flex gap-3 overflow-x-auto px-6 [scroll-padding-inline:1.5rem] snap-x snap-mandatory">
  <div class="w-[80%] shrink-0 snap-start">…</div>
  <div class="w-[80%] shrink-0 snap-start">…</div>
</div>
```

## Content Bleeds, Controls Float

The two layers behave differently at the edges:

- **Content layer**: backgrounds, hero media, and scrollable lists extend to the viewport edges.
- **Control layer**: text and controls stay inside the layout margins and safe areas, floating above the content.

```css
/* Good: full-bleed media inside a constrained article */
.article {
  display: grid;
  grid-template-columns: 1fr min(65ch, calc(100% - 48px)) 1fr;
}
.article > * { grid-column: 2; }
.article > .full-bleed { grid-column: 1 / -1; }
```

Sticky headers and floating action buttons account for safe areas:

```css
.fab {
  position: fixed;
  inset-inline-end: calc(16px + env(safe-area-inset-right));
  bottom: calc(16px + env(safe-area-inset-bottom));
}
```

## Hold Structure Until It Breaks

Breakpoints belong to the content, not the device catalog:

- Break where the layout actually stops fitting (when the sidebar squeezes the content below its minimum measure, when the card grid drops below a usable column width), not at `768px` because a preset says so.
- Collapse late. A layout that keeps its expanded structure as long as it genuinely fits stays stable and familiar; premature collapsing throws away space users paid for.
- Prefer **container queries** for components: a card should adapt to the column it's in, not to the viewport.

```css
/* Good: component adapts to its container */
.card-list { container-type: inline-size; }
@container (max-width: 400px) {
  .card { grid-template-columns: 1fr; }
}

/* Bad: viewport media query breaks the card inside a narrow sidebar */
@media (max-width: 768px) {
  .card { grid-template-columns: 1fr; }
}
```

Test order: the smallest supported size and the largest first (those break first), then the sizes in between.

## Plan for Growth and Clipping

Layouts fail in two directions: content grows, and viewports shrink.

**String expansion varies substantially by language and source-string length.** Do not rely on one universal percentage. Rules:

- No fixed widths sized to English labels; use `max-width` plus wrapping.
- No fixed heights on text containers; use `min-height` if a floor is needed.
- Buttons size themselves from their label (`padding-inline`), never a hardcoded width.
- Test with pseudo-localization or a long-string locale before shipping.

```css
/* Good: label defines the size */
.button { padding-inline: 16px; white-space: nowrap; }

/* Bad: German will overflow or truncate */
.button { width: 96px; overflow: hidden; }
```

**Clipping:** never park critical actions where they can be cut off: the bottom edge of a resizable pane, below the fold of a fixed-height modal, behind an expanding keyboard. Keep primary actions in stable chrome: a sticky footer with safe-area padding, or the top of the view. If a modal's content scrolls, its action row doesn't.

# Spacing and sizing

A sensible scale and comfortable spacing do more for typography than any effect.

## Units

| Unit | Behavior |
| --- | --- |
| `px` | Fixed |
| `em` | Scales with the current font size |
| `rem` | Scales with the root font size |
| `%` on `font-size` | Relative to the parent's font size, behaves like `em` |

## Type scale

A small set of predefined sizes used across a product, deviated from as little as possible. Hard-coding sizes without a system breaks down at scale.

```css
:root {
  --text-sm: 0.875rem;
  --text-base: 1rem;
  --text-lg: 1.125rem;
  --text-xl: 1.5rem;
  --text-2xl: 2rem;
}
```

There are many existing scales to pick from, or define a custom one. The Tailwind type scale (`text-xs` through `text-9xl`, each class pairing a size with a matching line height) is a solid ready-made choice.

For solo projects the default names work fine as long as there are clear rules for where each size is used. On a team, give sizes semantic names: `text-sm` tells you the size but not the use; `text-body-sm` keeps sizes consistent with clear usage rules.

A role-based scale pairs each size with its line-height and weight, so a role is one decision instead of three. A solid starting point for a product interface:

| Role | Size | Line-height | Weight |
| --- | --- | --- | --- |
| Display | `2.25rem` (36px) | `1.1` | `600` |
| Title | `1.5rem` (24px) | `1.2` | `600` |
| Heading | `1.125rem` (18px) | `1.3` | `600` |
| Body | `1rem` (16px) | `1.5` | `400` |
| Caption | `0.8125rem` (13px) | `1.4` | `400` |

Emphasis within a role is one weight step up (`400` → `500`), not a size change.

## Heading hierarchy

Assign each heading level to a descending step of the scale, so hierarchy comes from the scale instead of one-off sizes:

```css
h1 { font-size: var(--text-2xl); }
h2 { font-size: var(--text-xl); }
h3 { font-size: var(--text-lg); }
```

In Tailwind the same mapping is utility classes per level (`text-2xl`, `text-xl`, `text-lg`), typically centralized in a component or `@layer base` rather than repeated inline.

When reviewing a page, compare the computed size of headings within each semantic section: a child that accidentally renders more prominently than its parent breaks the visual hierarchy. Deep levels may share a size when the scale runs out of comfortable steps, as long as weight or letter-spacing keeps them distinct. A heading should not be smaller than body text unless it is deliberately a label-style overline.

Heading semantics and outline quality belong to `better-accessibility`. Pick the element from the document structure, then use this skill to make that structure visually legible; never pick a heading element for its browser-default size.

## Kerning and letter-spacing

- **Kerning** adjusts specific pairs like `AV` or `Ye`. It is built into the font and browsers apply it automatically. Only switch it off deliberately with `font-kerning: none`.
- **`letter-spacing`** adds the same space between every character:
  - Large headings often look better slightly negative.
  - Small uppercase labels need a little positive spacing so letters do not feel crowded.
  - Body copy needs neither.

```css
/* Good */
.display-heading {
  letter-spacing: -0.02em;
}

.uppercase-label {
  text-transform: uppercase;
  letter-spacing: 0.05em;
}
```

## Line-height

| Text | Value |
| --- | --- |
| Headings | ~`1.1` |
| Body copy | `1.5`–`1.6` |

Prefer unitless values: they scale with the font size, fixed values like `line-height: 24px` do not. Tailwind's `leading-snug`, `leading-normal` and `leading-relaxed` are sensible defaults that rarely need overriding.

Tight line-height is for short text. Anything that wraps to three or more lines needs at least `1.4`, even in height-constrained places like list rows and cards: a tightly-leaded paragraph is harder to read than a taller row is to fit.

```css
/* Bad: card description at heading leading */
.card-description { line-height: 1.1; }

/* Good: it wraps to 3 lines, so it reads as body text */
.card-description { line-height: 1.4; }
```

## Text trimming with text-box

Fonts reserve space above and below the letters, which is why text sits slightly too low in buttons and badges. `text-box` trims it. Two parts: which edges to trim (`trim-both`, `trim-start`, `trim-end`) and where:

| Keyword | Trims at |
| --- | --- |
| `cap` | The cap height (top) |
| `alphabetic` | The baseline (bottom) |
| `text` | The font's own text edge, keeping room for descenders |

```css
/* trim top and bottom */
.badge {
  text-box: trim-both cap alphabetic;
}

/* trim only the top */
.heading {
  text-box: trim-start cap;
}

/* trim only the bottom */
.label {
  text-box: trim-end alphabetic;
}
```

Supported in Chromium (133+) and Safari (18.2+), not yet Firefox; treat it as progressive enhancement, where unsupported browsers keep the default leading.

# Variable fonts and OpenType

What a font file can do beyond drawing letters, and how to reach those abilities from CSS.

## Static vs variable

- **Static font:** one weight and one style per file. Regular + medium + bold = three files.
- **Variable font:** an entire range in one file. Any value in the range works, e.g. `font-weight: 589`.

A variable font is not automatically better. One or two weights: static files can be smaller. Several weights, optical sizes or custom axes: a variable font usually makes more sense.

## Load intended weights and styles

When you use a weight or style the active family does not provide, the browser may synthesize it. Prefer loading the faces the design actually uses. Disable synthesis only after verifying the complete fallback stack and every semantic emphasis state; `none` disables weight, style, small-cap, superscript, and subscript synthesis together and can erase distinctions when the real face is unavailable.

```css
.brand-wordmark {
  /* Safe only after this isolated treatment is verified */
  font-synthesis: none;
}
```

For body and interface text, keep synthesis enabled unless a verified font setup supplies every requested form. If only one mode is unwanted, use the specific longhand (`font-synthesis-weight`, `font-synthesis-style`, and related properties) instead of the blanket shorthand.

## Axes

Variable-font controls, each with a four-letter tag. A font only supports the axes its designer included.

| Axis | Tag | Controls |
| --- | --- | --- |
| Weight | `wght` | Stroke thickness (like `font-weight`) |
| Optical size | `opsz` | Details and spacing tuned for the display size |
| Width | `wdth` | Glyph width |
| Slant | `slnt` | Slant angle |
| Custom | e.g. `GRAD` (Roboto Flex) | Whatever the designer built |

Inter's variable file exposes only `wght` and `opsz`.

Optical sizes predate variable fonts and many fonts still ship them as separate files: Heldane Text is sturdier and more spaced for reading sizes, Heldane Display has finer details for large sizes.

## Properties over axis tags

When a property exists, use it. `font-weight` keeps working when a non-variable fallback renders; `font-variation-settings` silently does nothing. Save the raw tags for custom axes with no property of their own:

```css
/* Good: common axes use the properties */
.heading {
  font-weight: 650;
  font-optical-sizing: auto;
}

/* Good: custom axis with no property of its own */
.heading-grade {
  font-variation-settings: "GRAD" 80;
}

/* Bad: weight via raw tag breaks on fallback fonts */
.heading {
  font-variation-settings: "wght" 650;
}
```

## OpenType features

OpenType is the standard behind almost every modern font. Features are extra built-in options and, unlike axes, they work the same on static and variable fonts. A font only ships the features its designer included.

| Tag | Feature |
| --- | --- |
| `tnum` | Tabular numbers: every digit the same width |
| `zero` | Slashed zero: `0` distinct from `O` |
| `liga` | Ligatures: joins pairs like "fi" into one shape |
| `ss01`–`ss20` | Stylistic sets (numbered slots) |
| `cv01`–`cv99` | Character variants (numbered slots) |

Same rule as axes: prefer the `font-variant-*` properties, reserve `font-feature-settings` for tags with no property:

```css
/* Good: common features use the properties */
.price {
  font-variant-numeric: tabular-nums;
}

/* Good: slashed zero via the property too */
.id {
  font-variant-numeric: slashed-zero;
}

/* Good: niche feature with no property of its own */
.logo {
  font-feature-settings: "ss01" 1;
}
```

Tabular numbers matter for changing values: without them each digit has a different width and the layout shifts as values update.

## Small caps, superscripts, subscripts

- **Small capitals:** uppercase letters drawn at a smaller size. Enable real ones with `font-variant-caps`.
- **Superscripts** sit above the normal line (the 2 in x²), **subscripts** below it (H₂O). Enable proper glyphs with `font-variant-position`.

Both require the font to include the glyphs.

## Stylistic sets and character variants

`ss01` = stylistic set, slot 01. `cv11` = character variant, slot 11. What each slot does differs font to font, which is why they are numbered, not named. Check the font's docs. In Inter, `ss01` switches to open digits and `cv11` swaps in a single-story `a`.

# Animations

Interruptible transitions, press feedback, and the restraint that decides whether to animate at all. Staged entrances and exits live in [enter-exit.md](enter-exit.md); icon swaps in [icon-transitions.md](icon-transitions.md).

## Interruptible Animations

Users change intent mid-interaction. If animations aren't interruptible, the interface feels broken.

### CSS Transitions vs. Keyframes

| | CSS Transitions | CSS Keyframe Animations |
| --- | --- | --- |
| **Behavior** | Interpolate toward latest state | Run on a fixed timeline |
| **Interruptible** | Yes, retargets mid-animation | No, restarts from beginning |
| **Use for** | Interactive state changes (hover, toggle, open/close) | Staged sequences that run once (enter animations, loading) |
| **Duration** | Fixed; retargets the value mid-flight, not the timeline | Fixed timeline, restarts from the beginning |

```css
/* Good: interruptible transition for a toggle */
.drawer {
  transform: translateX(-100%);
  transition: transform 200ms ease-out;
}
.drawer.open {
  transform: translateX(0);
}

/* Clicking again mid-animation smoothly reverses, no jank */
```

```css
/* Bad: keyframe animation for interactive element */
.drawer.open {
  animation: slideIn 200ms ease-out forwards;
}

/* Closing mid-animation snaps or restarts, feels broken */
```

**Rule:** Always prefer CSS transitions for interactive elements. Reserve keyframes for one-shot sequences.

## Scale on Press

A subtle scale-down on click gives buttons tactile feedback. Always use `scale(0.96)`. Never use a value smaller than `0.95`: anything below feels exaggerated. Use CSS transitions for interruptibility, so that if the user releases mid-press, it smoothly returns.

Not every button needs this. Add a `static` prop to your button component that disables the scale effect when the motion would be distracting.

### CSS Example

```css
.button {
  transition-property: scale;
  transition-duration: 150ms;
  transition-timing-function: ease-out;
}

.button:active {
  scale: 0.96;
}
```

### Tailwind Example

```tsx
<button className="transition-transform duration-150 ease-out active:scale-[0.96]">
  Click me
</button>
```

### Motion Example

```tsx
<motion.button whileTap={{ scale: 0.96 }}>
  Click me
</motion.button>
```

### Static Prop Pattern

Extract the scale class into a variable and conditionally apply it based on a `static` prop:

```tsx
const tapScale = "active:not-disabled:scale-[0.96]";

function Button({ static: isStatic, className, children, ...props }) {
  return (
    <button
      className={cn(
        "transition-transform duration-150 ease-out",
        !isStatic && tapScale,
        className,
      )}
      {...props}
    >
      {children}
    </button>
  );
}

// Usage
<Button>Click me</Button>           {/* scales on press */}
<Button static>Submit</Button>       {/* no scale */}
```

## Skip Animation on Page Load

Use `initial={false}` on `AnimatePresence` to prevent enter animations from firing on first render. Elements that are already in their default state shouldn't animate in on page load, only on subsequent state changes.

### When It Works

```tsx
// Good: icon doesn't animate in on mount, only on state change
<AnimatePresence initial={false} mode="popLayout">
  <motion.span
    key={isActive ? "active" : "inactive"}
    initial={{ opacity: 0, scale: 0.25, filter: "blur(4px)" }}
    animate={{ opacity: 1, scale: 1, filter: "blur(0px)" }}
    exit={{ opacity: 0, scale: 0.25, filter: "blur(4px)" }}
  >
    <Icon />
  </motion.span>
</AnimatePresence>
```

Works well for: icon swaps, toggles, tabs, segmented controls: anything that has a default state on page load.

### When It Breaks

Don't use `initial={false}` when the component relies on its `initial` prop to set up a first-time enter animation, like a staggered page hero or a loading state. In those cases, removing the initial animation skips the entire entrance.

```tsx
// Bad: initial={false} would skip the staggered page enter entirely
<AnimatePresence initial={false}>
  <motion.div initial="hidden" animate="visible" variants={...}>
    ...
  </motion.div>
</AnimatePresence>
```

Verify the component still looks right on a full page refresh before applying this.

## Suppress Transitions on Theme Switch

Flipping the theme changes `color`, `background-color`, `border-color`, and `box-shadow` on nearly every element at once. Everything carrying a transition on those properties animates simultaneously, so the switch reads as a slow smear across the page instead of an instant change. Disable transitions for the duration of the swap and restore them right after.

Inject a stylesheet that turns off every transition, force a reflow so the new colors commit while it still applies, then drop it on the next frame:

```tsx
"use client";

import { useEffect } from "react";

export function DisableThemeTransitions() {
  useEffect(() => {
    const mql = window.matchMedia("(prefers-color-scheme: dark)");

    const handleChange = () => {
      const style = document.createElement("style");
      style.append(
        document.createTextNode(
          "*,*::before,*::after{transition:none !important}"
        )
      );
      document.head.append(style);

      const _flushReflow = document.body.offsetHeight;

      requestAnimationFrame(() => {
        requestAnimationFrame(() => style.remove());
      });
    };

    mql.addEventListener("change", handleChange);
    return () => mql.removeEventListener("change", handleChange);
  }, []);

  return null;
}
```

`document.body.offsetHeight` is read for its side effect: it forces a synchronous style flush, so the new theme resolves while the override is still in the document and no transition ever starts. The nested `requestAnimationFrame` removes the override only after that paint, putting transitions back before the next interaction.

This component covers the OS-level change. An in-app theme toggle needs the same treatment around its own flip: apply the override, change the theme, flush, remove. `next-themes` ships this as its `disableTransitionOnChange` prop.

## Motion Restraint

Motion is a budget, not a garnish. Three rules decide whether an animation belongs at all:

- **No custom animation on high-frequency interactions.** An animation on something users trigger constantly (every keystroke, every list-row hover, every tab switch in a work tool) charges its attention cost on every single trigger. Reserve expressive motion for infrequent moments (first load of a view, success states, empty states); high-frequency interactions get instant feedback or the subtlest possible transition (`opacity`/`background-color` at ≤150ms).
- **Motion is never the only feedback channel.** Every state change an animation communicates must also be visible when the animation doesn't run: a color change, an icon swap, a label. Users with reduced motion enabled, and anyone who blinked, still need to see what happened.
- **Brief and precise beats prominent.** If a shorter, smaller animation communicates the same thing, use it. When in doubt, cut the duration, not the clarity.

```css
/* Good: high-frequency hover gets a minimal transition */
.row:hover {
  background-color: var(--surface-hover);
  transition: background-color 100ms ease-out;
}

/* Bad: every hover replays a full entrance */
.row:hover .row-icon {
  animation: bounceIn 500ms;
}
```

Honoring `prefers-reduced-motion` is covered by the `better-accessibility` skill; apply it to every animation in this file.

# Enter and exit animations

Staged entrances and the exits that follow them. For interactive state feedback see [animations.md](animations.md); for icon swaps see [icon-transitions.md](icon-transitions.md).

## Enter Animations: Split and Stagger

Use this pattern for infrequent staged entrances where sequence helps communicate hierarchy, such as the first load of a page hero, success state, or empty state. Break a large container into semantic chunks and animate each individually. Do not stagger routine interactions such as row hovers, keystrokes, or repeated tab changes.

### Step by Step

1. **Split** into logical groups (title, description, buttons)
2. **Stagger** with ~100ms delay between groups
3. **For titles**, consider splitting into individual words with ~80ms stagger
4. **Combine** `opacity`, `blur`, and `translateY` for the enter effect

### Code Example

```tsx
// Motion (Framer Motion): staggered enter
function PageHeader() {
  return (
    <motion.div
      initial="hidden"
      animate="visible"
      variants={{
        visible: { transition: { staggerChildren: 0.1 } },
      }}
    >
      <motion.h1
        variants={{
          hidden: { opacity: 0, y: 12, filter: "blur(4px)" },
          visible: { opacity: 1, y: 0, filter: "blur(0px)" },
        }}
      >
        Welcome
      </motion.h1>

      <motion.p
        variants={{
          hidden: { opacity: 0, y: 12, filter: "blur(4px)" },
          visible: { opacity: 1, y: 0, filter: "blur(0px)" },
        }}
      >
        A description of the page.
      </motion.p>

      <motion.div
        variants={{
          hidden: { opacity: 0, y: 12, filter: "blur(4px)" },
          visible: { opacity: 1, y: 0, filter: "blur(0px)" },
        }}
      >
        <Button>Get started</Button>
      </motion.div>
    </motion.div>
  );
}
```

### CSS-Only Stagger

```css
.stagger-item {
  opacity: 0;
  transform: translateY(12px);
  filter: blur(4px);
  animation: fadeInUp 400ms ease-out forwards;
}

.stagger-item:nth-child(1) { animation-delay: 0ms; }
.stagger-item:nth-child(2) { animation-delay: 100ms; }
.stagger-item:nth-child(3) { animation-delay: 200ms; }

@keyframes fadeInUp {
  to {
    opacity: 1;
    transform: translateY(0);
    filter: blur(0);
  }
}
```

## Exit Animations

Exit animations should be softer and less attention-grabbing than enter animations. The user's focus is moving to the next thing; don't fight for attention.

### Subtle Exit (Recommended)

```tsx
// Small fixed translateY: indicates direction without drama
<motion.div
  exit={{
    opacity: 0,
    y: -12,
    filter: "blur(4px)",
    transition: { duration: 0.15, ease: "easeOut" },
  }}
>
  {content}
</motion.div>
```

### Full Exit (When Context Matters)

```tsx
// Slide fully out: use when spatial context is important
// (e.g., a card returning to a list, a drawer closing)
<motion.div
  exit={{
    opacity: 0,
    x: "-100%",
    transition: { duration: 0.2, ease: "easeOut" },
  }}
>
  {content}
</motion.div>
```

### Good vs. Bad

```css
/* Good: subtle exit */
.item-exit {
  opacity: 0;
  transform: translateY(-12px);
  transition: opacity 150ms ease-out, transform 150ms ease-out;
}

/* Bad: dramatic exit that steals focus */
.item-exit {
  opacity: 0;
  transform: translateY(-100%) scale(0.5);
  transition: all 400ms ease-out;
}

/* Sometimes correct: remove immediately when motion adds no context */
.item-exit {
  display: none;
}
```

**Key points:**
- Use a small fixed `translateY` (e.g., `-12px`) instead of the full container height
- Keep some directional movement to indicate where the element went
- Exit duration should be shorter than enter duration (150ms vs 300ms)
- Use a subtle exit when it preserves spatial context. Remove immediately when motion adds no information, the interaction repeats frequently, or reduced motion is requested.

Honoring `prefers-reduced-motion` is covered by the `better-accessibility` skill; apply it to every animation in this file.

# Performance

Transition specificity and GPU compositing hints.

## Transition Only What Changes

Never use `transition: all` or Tailwind's `transition-all`. Always specify the exact properties that change. (Tailwind's bare `transition` maps to a curated default list of colors, opacity, shadow and transforms, not to `all`; still prefer naming exactly what changes.)

### Why

- `transition: all` forces the browser to watch every property for changes
- Causes unexpected transitions on properties you didn't intend to animate (colors, padding, shadows)
- Prevents browser optimizations

### CSS Example

```css
/* Good: only transition what changes */
.button {
  transition-property: scale, background-color;
  transition-duration: 150ms;
  transition-timing-function: ease-out;
}

/* Bad: transition everything */
.button {
  transition: all 150ms ease-out;
}
```

### Tailwind

```tsx
// Good: explicit properties
<button className="transition-[scale,background-color] duration-150 ease-out">

// Bad: transition all
<button className="transition-all duration-150 ease-out">
```

### Tailwind `transition-transform` Note

`transition-transform` in Tailwind maps to `transition-property: transform, translate, scale, rotate`, so it covers all transform-related properties, not just `transform`. Use this when you're only animating transforms. For multiple non-transform properties, use the bracket syntax: `transition-[scale,opacity,filter]`.

## Use `will-change` Sparingly

`will-change` hints the browser to pre-promote an element to its own GPU compositing layer. Without it, the browser promotes the element only when the animation starts; that one-time layer promotion can cause a micro-stutter on the first frame.

This particularly helps when an element is changing `scale`, `rotation`, or moving around with `transform`. For other properties, it doesn't help much: the browser can't composite them on the GPU anyway.

### Rules

```css
/* Good: specific property that benefits from GPU compositing */
.animated-card {
  will-change: transform;
}

/* Good: multiple compositor-friendly properties */
.animated-card {
  will-change: transform, opacity;
}

/* Bad: never use will-change: all */
.animated-card {
  will-change: all;
}

/* Bad: properties that can't be GPU-composited anyway */
.animated-card {
  will-change: background-color, padding;
}
```

### Useful Properties

| Property | GPU-compositable | Worth using `will-change` |
| --- | --- | --- |
| `transform` | Yes | Yes |
| `opacity` | Yes | Yes |
| `filter` (blur, brightness) | Yes | Yes |
| `clip-path` | Newer Chromium only | Rarely; not reliable cross-browser |
| `top`, `left`, `width`, `height` | No | No |
| `background`, `border`, `color` | No | No |

### When to Skip

Modern browsers are already good at optimizing on their own. Only add `will-change` when you notice first-frame stutter; Safari in particular benefits from it. Don't add it preemptively to every animated element; each extra compositing layer costs memory.

# Surfaces

Border radius, optical alignment, shadows, and image outlines.

## Concentric Border Radius

When nesting rounded elements, the outer radius must equal the inner radius plus the padding between them:

```
outerRadius = innerRadius + padding
```

This rule is most useful when nested surfaces are close together. If padding is larger than `24px`, treat the layers as separate surfaces and choose each radius independently instead of forcing strict concentric math.

### Example

```css
/* Good: concentric radii */
.card {
  border-radius: 20px; /* 12 + 8 */
  padding: 8px;
}
.card-inner {
  border-radius: 12px;
}

/* Bad: same radius on both */
.card {
  border-radius: 12px;
  padding: 8px;
}
.card-inner {
  border-radius: 12px;
}
```

### Tailwind Example

```tsx
// Good: outer radius accounts for padding
<div className="rounded-2xl p-2">       {/* 16px radius, 8px padding */}
  <div className="rounded-lg">          {/* 8px radius = 16 - 8 ✓ */}
    ...
  </div>
</div>

// Bad: same radius on both
<div className="rounded-xl p-2">
  <div className="rounded-xl">          {/* same radius, looks off */}
    ...
  </div>
</div>
```

Mismatched border radii on closely nested surfaces is a common source of visual tension. Calculate concentrically when the layers share a visible, even inset; preserve an established component token when the layers are independent or the padding is intentionally asymmetric.

## Optical Alignment

When geometric centering looks off, align optically instead.

### Buttons with Text + Icon

When an icon makes otherwise symmetric padding look unbalanced, use slightly less padding on the icon side. A useful starting point is:
`icon-side padding = text-side padding - 2px`.

```css
/* Good: less padding on icon side */
.button-with-icon {
  padding-inline-start: 16px;
  padding-inline-end: 14px; /* trailing icon side = text side - 2px */
}

/* Bad: equal padding looks like icon is pushed too far right */
.button-with-icon {
  padding-inline: 16px;
}
```

```tsx
// Tailwind
<button className="ps-4 pe-3.5 flex items-center gap-2">
  <span>Continue</span>
  <ArrowRightIcon />
</button>
```

### Play Button Triangles

Play icons are triangular and their geometric center is not their visual center. Shift slightly right:

```css
/* Good: optically centered */
.play-button svg {
  transform: translateX(2px); /* physical correction to the glyph itself */
}

/* Bad: geometrically centered but looks off */
.play-button svg {
  /* no adjustment */
}
```

### Asymmetric Icons (Stars, Arrows, Carets)

Some icons have uneven visual weight. The best fix is adjusting the SVG directly so no extra margin/padding is needed in the component code.

```tsx
// Best: fix in the SVG itself
// Adjust the viewBox or path to visually center the icon

// Fallback: adjust with margin
<span className="translate-x-px">
  <StarIcon />
</span>
```

## Shadows Instead of Borders

For **buttons, cards, and containers** that use a border for depth or elevation, prefer replacing it with a subtle `box-shadow`. Shadows adapt to any background since they use transparency; solid borders don't. This also helps when using images or multiple colors as backgrounds: solid border colors don't work well on backgrounds other than the ones they were designed for.

**Do not apply this to dividers** (`border-b`, `border-t`, side borders) or any border whose purpose is layout separation rather than element depth. Those should stay as borders.

### Shadow as Border (Light Mode)

The shadow is comprised of three layers. The first acts as a 1px border ring, the second adds subtle lift, and the third provides ambient depth:

```css
:root {
  --shadow-border:
    0px 0px 0px 1px oklch(0 0 0 / 0.06),
    0px 1px 2px -1px oklch(0 0 0 / 0.06),
    0px 2px 4px 0px oklch(0 0 0 / 0.04);
  --shadow-border-hover:
    0px 0px 0px 1px oklch(0 0 0 / 0.08),
    0px 1px 2px -1px oklch(0 0 0 / 0.08),
    0px 2px 4px 0px oklch(0 0 0 / 0.06);
}
```

### Shadow as Border (Dark Mode)

In dark mode, simplify to a single white ring, since layered depth shadows aren't visible on dark backgrounds:

```css
/* Dark mode: adapt to whatever setup the project uses
   (prefers-color-scheme, class, data attribute, etc.) */
--shadow-border: 0 0 0 1px oklch(1 0 0 / 0.08);
--shadow-border-hover: 0 0 0 1px oklch(1 0 0 / 0.13);
```

### Usage with Hover Transition

Apply the variable and add `transition-[box-shadow]` for a smooth hover:

```css
.card {
  box-shadow: var(--shadow-border);
  transition-property: box-shadow;
  transition-duration: 150ms;
  transition-timing-function: ease-out;
}

.card:hover {
  box-shadow: var(--shadow-border-hover);
}
```

### When to Use Shadows vs. Borders

| Use shadows | Use borders |
| --- | --- |
| Cards, containers with depth | Dividers between list items |
| Buttons with bordered styles | Table cell boundaries |
| Elevated elements (dropdowns, modals) | Form input outlines (for accessibility) |
| Elements on varied backgrounds | Hairline separators in dense UI |
| Hover/focus states for lift effect | |

## Image Outlines

Add a subtle `1px` outline with low opacity to images. This creates consistent depth, especially in design systems where other elements use borders or shadows.

### Color rules (non-negotiable)

- **Light mode**: pure black, `oklch(0 0 0 / 0.1)`.
- **Dark mode**: pure white, `oklch(1 0 0 / 0.1)`.
- Never use a near-black or near-white from the project palette (e.g. slate-900, zinc-900, `#0a0a0a`, `#111827`, `#f5f5f7`). Tinted outlines pick up the surrounding surface color and read as dirt on the image edge.
- Never match the outline to the project's accent or ink color. The outline is a neutral separator, not a themed element.

### Light Mode

```css
img {
  outline: 1px solid oklch(0 0 0 / 0.1);
  outline-offset: -1px; /* draw the ring just inside the image edge */
}
```

### Dark Mode

```css
img {
  outline: 1px solid oklch(1 0 0 / 0.1);
  outline-offset: -1px;
}
```

### Tailwind with Dark Mode

```tsx
<img
  className="outline outline-1 -outline-offset-1 outline-black/10 dark:outline-white/10"
  src={src}
  alt={alt}
/>
```

Use `outline-black/10` and `outline-white/10` specifically, not `outline-slate-*`, `outline-zinc-*`, `outline-neutral-*`, or any tinted scale.

**Why outline instead of border?** `outline` never affects layout (no added width or height at any offset), and `outline-offset: -1px` draws the ring just inside the image edge so it hugs the corner radius instead of sitting outside it.

