#!/usr/bin/env python3
"""Register required outcome evaluators against real project local adapter bytes."""
from __future__ import annotations

import argparse
import hashlib
import importlib.util
import json
from pathlib import Path, PurePosixPath
from typing import Any, Mapping

CONTRACT_SCHEMA = "company-os.evaluator-runtime-contract.v1"
REGISTRY_SCHEMA = "company-os.evaluator-adapter-registry.v1"
WORKSPACE_PREFIX = "workspace://"


class RegistryError(ValueError):
    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(f"{code}: {message}")


def canonical(value: Any) -> bytes:
    return json.dumps(
        value,
        sort_keys=True,
        separators=(",", ":"),
        ensure_ascii=False,
        allow_nan=False,
    ).encode("utf-8")


def digest(value: Any) -> str:
    return hashlib.sha256(canonical(value)).hexdigest()


def file_digest(path: Path) -> str:
    return hashlib.sha256(path.read_bytes()).hexdigest()


def text(value: Any, label: str) -> str:
    if not isinstance(value, str) or not value.strip() or "\x00" in value:
        raise RegistryError("E_SCHEMA", f"{label} must be nonempty")
    return value.strip()


def obj(value: Any, label: str) -> Mapping[str, Any]:
    if not isinstance(value, Mapping):
        raise RegistryError("E_SCHEMA", f"{label} must be an object")
    return value


def sha256(value: Any, label: str) -> str:
    value = text(value, label)
    if len(value) != 64 or any(character not in "0123456789abcdef" for character in value):
        raise RegistryError("E_SCHEMA", f"{label} must be lowercase sha256")
    return value


def execute_module():
    path = (
        Path(__file__).resolve().parents[2]
        / "execute-outcome-evaluator/scripts/execute_evaluator.py"
    )
    spec = importlib.util.spec_from_file_location("company_os_register_evaluator_runtime", path)
    if spec is None or spec.loader is None:
        raise RegistryError("E_RUNTIME", "execute outcome evaluator runtime cannot be loaded")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def read_json(path: Path, label: str) -> Any:
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise RegistryError("E_JSON", f"cannot read {label}: {path}") from exc


def verify_contract(raw: Mapping[str, Any]) -> dict[str, Any]:
    contract = dict(raw)
    if contract.get("$schema") != CONTRACT_SCHEMA:
        raise RegistryError("E_SCHEMA", f"evaluator contract must use {CONTRACT_SCHEMA}")
    observed = sha256(contract.get("contract_sha256"), "contract_sha256")
    if digest({**contract, "contract_sha256": None}) != observed:
        raise RegistryError("E_DIGEST", "evaluator contract content digest does not match")
    if contract.get("ready") is not True:
        raise RegistryError("E_NOT_READY", "evaluator contract is not ready")
    return contract


def workspace_path(project_root: Path, locator: str, label: str) -> tuple[Path, str]:
    locator = text(locator, label)
    if not locator.startswith(WORKSPACE_PREFIX):
        raise RegistryError(
            "E_LOCATOR",
            f"{label} must use workspace:// for locally constructed evaluator adapters",
        )
    raw = locator[len(WORKSPACE_PREFIX) :]
    if not raw or "\\" in raw:
        raise RegistryError("E_LOCATOR", f"{label} workspace path is invalid")
    pure = PurePosixPath(raw)
    if pure.is_absolute() or not pure.parts or any(part in {"", ".", ".."} for part in pure.parts):
        raise RegistryError("E_LOCATOR", f"{label} workspace path is unsafe")
    root = project_root.resolve()
    if not root.is_dir() or root.is_symlink():
        raise RegistryError("E_PATH", "project_root must be a real directory")
    current = root
    for part in pure.parts:
        current /= part
        if current.is_symlink():
            raise RegistryError("E_PATH", f"{label} may not traverse a symlink")
    candidate = root / Path(*pure.parts)
    if not candidate.exists():
        raise RegistryError(
            "E_ADAPTER_MISSING",
            f"required evaluator adapter does not exist: {pure.as_posix()}",
        )
    try:
        resolved = candidate.resolve(strict=True)
    except OSError as exc:
        raise RegistryError("E_ADAPTER_MISSING", f"cannot resolve adapter {raw}") from exc
    if (resolved != root and root not in resolved.parents) or not resolved.is_file() or resolved.is_symlink():
        raise RegistryError("E_PATH", f"required adapter is not a regular project file: {raw}")
    return resolved, pure.as_posix()


def adapter_record(
    project_root: Path,
    evaluator: Mapping[str, Any],
    *,
    timeout_seconds: int,
    max_output_bytes: int,
) -> dict[str, Any]:
    evaluator_id = text(evaluator.get("evaluator_id"), "evaluator_id")
    locator = text(evaluator.get("adapter_locator"), f"{evaluator_id}.adapter_locator")
    entrypoint, relative = workspace_path(project_root, locator, f"{evaluator_id}.adapter_locator")
    artifact_classes = evaluator.get("artifact_classes")
    evidence = evaluator.get("produces_evidence")
    dimensions = evaluator.get("score_dimensions", [])
    for value, label in (
        (artifact_classes, f"{evaluator_id}.artifact_classes"),
        (evidence, f"{evaluator_id}.produces_evidence"),
        (dimensions, f"{evaluator_id}.score_dimensions"),
    ):
        if not isinstance(value, list) or not all(isinstance(item, str) and item for item in value):
            raise RegistryError("E_SCHEMA", f"{label} is invalid")
    return {
        "adapter_locator": locator,
        "runtime": "python",
        "entrypoint": relative,
        "entrypoint_sha256": file_digest(entrypoint),
        "timeout_seconds": timeout_seconds,
        "max_output_bytes": max_output_bytes,
        "arguments": [],
        "artifact_classes": sorted(artifact_classes),
        "produces_evidence": sorted(evidence),
        "score_dimensions": sorted(dimensions),
    }


def build_registry(
    project_root: Path,
    contract_raw: Mapping[str, Any],
    *,
    timeout_seconds: int = 300,
    max_output_bytes: int = 1024 * 1024,
) -> dict[str, Any]:
    if not isinstance(timeout_seconds, int) or isinstance(timeout_seconds, bool) or not 1 <= timeout_seconds <= 3600:
        raise RegistryError("E_SCHEMA", "timeout_seconds must be between 1 and 3600")
    if not isinstance(max_output_bytes, int) or isinstance(max_output_bytes, bool) or not 1024 <= max_output_bytes <= 10 * 1024 * 1024:
        raise RegistryError("E_SCHEMA", "max_output_bytes is outside the evaluator runtime bounds")
    contract = verify_contract(contract_raw)
    records = contract.get("evaluators")
    if not isinstance(records, list) or not records:
        raise RegistryError("E_SCHEMA", "evaluator contract contains no evaluators")
    required = [
        dict(record)
        for record in records
        if isinstance(record, Mapping) and record.get("required") is True
    ]
    if not required:
        raise RegistryError("E_SCHEMA", "evaluator contract contains no required evaluators")
    adapters = [
        adapter_record(
            project_root,
            evaluator,
            timeout_seconds=timeout_seconds,
            max_output_bytes=max_output_bytes,
        )
        for evaluator in sorted(required, key=lambda item: str(item.get("evaluator_id", "")))
    ]
    locators = [adapter["adapter_locator"] for adapter in adapters]
    if len(locators) != len(set(locators)):
        raise RegistryError("E_DUPLICATE", "multiple required evaluators resolve to the same adapter locator")
    registry = {
        "$schema": REGISTRY_SCHEMA,
        "schema_version": 1,
        "adapters": adapters,
        "registry_sha256": None,
    }
    registry["registry_sha256"] = digest(registry)
    runtime = execute_module()
    try:
        runtime.validate_registry(registry)
        for evaluator in required:
            runtime.resolve_adapter(project_root, registry, evaluator)
    except Exception as exc:
        raise RegistryError(
            getattr(exc, "code", "E_ADAPTER"),
            f"adapter registry does not satisfy evaluator runtime: {exc}",
        ) from exc
    return registry


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--project-root", type=Path, required=True)
    parser.add_argument("--evaluator-contract", type=Path, required=True)
    parser.add_argument("--output", type=Path, required=True)
    parser.add_argument("--timeout-seconds", type=int, default=300)
    parser.add_argument("--max-output-bytes", type=int, default=1024 * 1024)
    args = parser.parse_args()
    try:
        contract = obj(read_json(args.evaluator_contract, "evaluator contract"), "evaluator contract")
        registry = build_registry(
            args.project_root,
            contract,
            timeout_seconds=args.timeout_seconds,
            max_output_bytes=args.max_output_bytes,
        )
        args.output.parent.mkdir(parents=True, exist_ok=True)
        args.output.write_text(json.dumps(registry, indent=2, sort_keys=True) + "\n", encoding="utf-8")
        print(
            json.dumps(
                {
                    "ok": True,
                    "registry_sha256": registry["registry_sha256"],
                    "adapter_count": len(registry["adapters"]),
                },
                sort_keys=True,
            )
        )
        return 0
    except RegistryError as exc:
        print(json.dumps({"ok": False, "code": exc.code, "error": exc.message}, sort_keys=True))
        return 2


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Deterministically select a bounded Company OS execution loop."""

from __future__ import annotations

import argparse
import hashlib
import json
import sys
from pathlib import Path
from typing import Any


HERE = Path(__file__).resolve().parent
CATALOG_PATH = HERE.parent / "assets" / "loop-strategies.json"
REQUEST_KEYS = {"schema", "outcome_id", "task_family", "evidence", "shape", "limits", "requirements"}
EVIDENCE_KEYS = {"acceptance_oracle", "objective_metric", "production_traces", "durable_event_source"}
SHAPE_KEYS = {"parallel_lanes", "uncertainty", "recurrence", "failure_cost", "novelty_need", "code_mutation"}
LIMIT_KEYS = {"max_passes", "no_progress_limit", "max_concurrency", "max_depth", "max_cost_usd"}
REQUIREMENT_KEYS = {"independent_review", "worktree_isolation", "post_run_learning", "approval_boundaries"}
TASK_FAMILIES = {"general", "software_delivery", "product_delivery", "research", "optimization", "creative_exploration", "operations"}


class SelectionError(ValueError):
    pass


def canonical_bytes(value: Any) -> bytes:
    return (json.dumps(value, sort_keys=True, separators=(",", ":")) + "\n").encode()


def sha256(value: Any) -> str:
    return hashlib.sha256(canonical_bytes(value)).hexdigest()


def _exact_keys(value: Any, expected: set[str], label: str) -> dict[str, Any]:
    if not isinstance(value, dict):
        raise SelectionError(f"{label} must be an object")
    unknown = sorted(set(value) - expected)
    missing = sorted(expected - set(value))
    if unknown:
        raise SelectionError(f"{label} has unknown keys: {', '.join(unknown)}")
    if missing:
        raise SelectionError(f"{label} is missing keys: {', '.join(missing)}")
    return value


def validate_request(raw: Any) -> dict[str, Any]:
    request = _exact_keys(raw, REQUEST_KEYS, "request")
    if request["schema"] != "company-os.loop-selection-request.v1":
        raise SelectionError("unsupported request schema")
    outcome_id = request["outcome_id"]
    if not isinstance(outcome_id, str) or not outcome_id or any(c not in "abcdefghijklmnopqrstuvwxyz0123456789-" for c in outcome_id):
        raise SelectionError("outcome_id must be a lower-case slug")
    if request["task_family"] not in TASK_FAMILIES:
        raise SelectionError("task_family is invalid")

    evidence = _exact_keys(request["evidence"], EVIDENCE_KEYS, "evidence")
    shape = _exact_keys(request["shape"], SHAPE_KEYS, "shape")
    limits = _exact_keys(request["limits"], LIMIT_KEYS, "limits")
    requirements = _exact_keys(request["requirements"], REQUIREMENT_KEYS, "requirements")

    for key, value in evidence.items():
        if not isinstance(value, bool):
            raise SelectionError(f"evidence.{key} must be boolean")
    if not evidence["acceptance_oracle"]:
        raise SelectionError("an observable acceptance oracle is required")

    if not isinstance(shape["parallel_lanes"], int) or isinstance(shape["parallel_lanes"], bool) or shape["parallel_lanes"] < 1:
        raise SelectionError("shape.parallel_lanes must be a positive integer")
    if shape["uncertainty"] not in {"low", "medium", "high"}:
        raise SelectionError("shape.uncertainty is invalid")
    if shape["recurrence"] not in {"one_off", "recurring", "event_driven"}:
        raise SelectionError("shape.recurrence is invalid")
    if shape["failure_cost"] not in {"low", "medium", "high"}:
        raise SelectionError("shape.failure_cost is invalid")
    if shape["novelty_need"] not in {"low", "medium", "high"}:
        raise SelectionError("shape.novelty_need is invalid")
    if not isinstance(shape["code_mutation"], bool):
        raise SelectionError("shape.code_mutation must be boolean")

    for key in ("max_passes", "no_progress_limit", "max_concurrency"):
        value = limits[key]
        if not isinstance(value, int) or isinstance(value, bool) or value < 1:
            raise SelectionError(f"limits.{key} must be a positive integer")
    if not isinstance(limits["max_depth"], int) or isinstance(limits["max_depth"], bool) or limits["max_depth"] < 0:
        raise SelectionError("limits.max_depth must be a non-negative integer")
    cost = limits["max_cost_usd"]
    if cost is not None and (not isinstance(cost, (int, float)) or isinstance(cost, bool) or cost < 0):
        raise SelectionError("limits.max_cost_usd must be non-negative or null")
    if limits["no_progress_limit"] > limits["max_passes"]:
        raise SelectionError("no_progress_limit cannot exceed max_passes")
    if limits["max_concurrency"] > shape["parallel_lanes"]:
        raise SelectionError("max_concurrency cannot exceed declared parallel_lanes")

    for key in ("independent_review", "worktree_isolation", "post_run_learning"):
        if not isinstance(requirements[key], bool):
            raise SelectionError(f"requirements.{key} must be boolean")
    boundaries = requirements["approval_boundaries"]
    if not isinstance(boundaries, list) or any(not isinstance(item, str) or not item.strip() for item in boundaries):
        raise SelectionError("requirements.approval_boundaries must be a string array")
    if len(set(boundaries)) != len(boundaries):
        raise SelectionError("requirements.approval_boundaries contains duplicates")
    if shape["failure_cost"] == "high" and not requirements["independent_review"]:
        raise SelectionError("high failure cost requires independent review")
    if shape["code_mutation"] and shape["parallel_lanes"] > 1 and not requirements["worktree_isolation"]:
        raise SelectionError("parallel code mutation requires worktree isolation")
    if shape["code_mutation"] and shape["parallel_lanes"] > 1 and limits["max_depth"] < 1:
        raise SelectionError("parallel code mutation requires positive recursion depth")
    if shape["recurrence"] == "event_driven" and not evidence["durable_event_source"]:
        raise SelectionError("event-driven work requires a durable event source")
    return request


def load_catalog() -> dict[str, Any]:
    catalog = json.loads(CATALOG_PATH.read_text(encoding="utf-8"))
    if catalog.get("$schema") != "company-os.loop-strategy-catalog.v1" or catalog.get("catalog_version") != 1:
        raise SelectionError("loop strategy catalog is invalid")
    strategies = catalog.get("strategies")
    if not isinstance(strategies, list) or not strategies:
        raise SelectionError("loop strategy catalog has no strategies")
    ids = [item.get("id") for item in strategies]
    if any(not isinstance(item, str) or not item for item in ids) or len(ids) != len(set(ids)):
        raise SelectionError("loop strategy IDs must be unique strings")
    required_ids = {
        "bounded-evidence-loop", "contract-delivery-loop", "recursive-worktree-loop",
        "bounded-divergent-exploration-loop", "recurring-operations-loop", "event-reaction-loop",
        "trace-optimization-adapter", "apprenticeship-learning-adapter", "durable-event-transport-adapter",
    }
    if set(ids) != required_ids:
        raise SelectionError("loop strategy catalog has an unexpected strategy set")
    strategy_keys = {"id", "kind", "source_ids", "use_when", "cycle", "required_controls", "metrics", "terminal_states"}
    for strategy in strategies:
        if set(strategy) != strategy_keys:
            raise SelectionError(f"strategy has an invalid shape: {strategy.get('id')}")
        if strategy["kind"] not in {"primary", "adapter"}:
            raise SelectionError(f"strategy kind is invalid: {strategy['id']}")
        for key in ("source_ids", "use_when", "cycle", "required_controls", "metrics", "terminal_states"):
            values = strategy[key]
            if not isinstance(values, list) or not values or any(not isinstance(value, str) or not value for value in values):
                raise SelectionError(f"strategy {strategy['id']}.{key} must be a non-empty string array")
    return catalog


def choose_primary(request: dict[str, Any], by_id: dict[str, dict[str, Any]]) -> tuple[str, dict[str, int], list[str]]:
    family = request["task_family"]
    shape = request["shape"]
    scores = {item: 0 for item in (
        "bounded-evidence-loop", "contract-delivery-loop", "recursive-worktree-loop",
        "bounded-divergent-exploration-loop", "recurring-operations-loop", "event-reaction-loop"
    )}
    reasons: list[str] = []
    scores["bounded-evidence-loop"] = 10
    if family in {"software_delivery", "product_delivery"}:
        scores["contract-delivery-loop"] += 35
    if (
        family == "software_delivery"
        and shape["code_mutation"]
        and shape["parallel_lanes"] > 1
        and shape["recurrence"] == "one_off"
    ):
        scores["recursive-worktree-loop"] += 55 + min(shape["parallel_lanes"], 20)
    if (
        family in {"creative_exploration", "product_delivery"}
        and shape["novelty_need"] == "high"
        and shape["recurrence"] == "one_off"
    ):
        scores["bounded-divergent-exploration-loop"] += 60
    if shape["recurrence"] == "recurring":
        scores["recurring-operations-loop"] += 90
    if shape["recurrence"] == "event_driven" and request["evidence"]["durable_event_source"]:
        scores["event-reaction-loop"] += 80
    if shape["failure_cost"] == "high":
        scores["contract-delivery-loop"] += 12
    if shape["uncertainty"] == "high":
        scores["bounded-evidence-loop"] += 8

    selected = sorted(scores, key=lambda item: (-scores[item], item))[0]
    if selected == "recursive-worktree-loop":
        reasons.append("parallel code lanes justify recursively owned isolated worktrees")
    elif selected == "contract-delivery-loop":
        reasons.append("delivery requires confirmed contracts, implementation evidence, and integration review")
    elif selected == "bounded-divergent-exploration-loop":
        reasons.append("high novelty need justifies bounded independent variants and held-out selection")
    elif selected == "recurring-operations-loop":
        reasons.append("recurring work requires due-state, health, and missed-run reconciliation")
    elif selected == "event-reaction-loop":
        reasons.append("event-driven work has a durable source and requires fenced replayable handling")
    else:
        reasons.append("a bounded observe-act-verify loop is the smallest justified strategy")
    if selected not in by_id:
        raise SelectionError(f"catalog is missing selected strategy: {selected}")
    return selected, scores, reasons


def select_plan(request: dict[str, Any], catalog: dict[str, Any]) -> dict[str, Any]:
    by_id = {item["id"]: item for item in catalog["strategies"]}
    primary_id, scores, reasons = choose_primary(request, by_id)
    adapters: list[str] = []
    if request["evidence"]["production_traces"]:
        adapters.append("trace-optimization-adapter")
    if request["requirements"]["post_run_learning"]:
        adapters.append("apprenticeship-learning-adapter")
    if request["evidence"]["durable_event_source"] and primary_id != "event-reaction-loop":
        adapters.append("durable-event-transport-adapter")
    adapters = adapters[:3]
    selected = [primary_id, *adapters]
    controls = sorted({control for strategy_id in selected for control in by_id[strategy_id]["required_controls"]})
    if request["shape"]["recurrence"] == "recurring":
        controls = sorted(set(controls) | set(by_id["recurring-operations-loop"]["required_controls"]))
        scheduler_reason = "recurring work requires due-state, health, and missed-run reconciliation"
        if scheduler_reason not in reasons:
            reasons.append(scheduler_reason)
    metrics = sorted({metric for strategy_id in selected for metric in by_id[strategy_id]["metrics"]})
    terminals = sorted({state for strategy_id in selected for state in by_id[strategy_id]["terminal_states"]})
    sources = sorted({source for strategy_id in selected for source in by_id[strategy_id]["source_ids"]})
    return {
        "schema": "company-os.loop-plan.v1",
        "activation_state": "planned",
        "outcome_id": request["outcome_id"],
        "request_sha256": sha256(request),
        "catalog_version": catalog["catalog_version"],
        "primary": {"id": primary_id, "score": scores[primary_id], "cycle": by_id[primary_id]["cycle"]},
        "adapters": [{"id": item, "cycle": by_id[item]["cycle"]} for item in adapters],
        "reasons": reasons,
        "limits": request["limits"],
        "approval_boundaries": request["requirements"]["approval_boundaries"],
        "required_controls": controls,
        "metrics": metrics,
        "terminal_states": terminals,
        "source_ids": sources,
    }


def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("request", type=Path)
    parser.add_argument("--output", type=Path)
    parser.add_argument("--verify-output", type=Path)
    args = parser.parse_args()
    try:
        request = validate_request(json.loads(args.request.read_text(encoding="utf-8")))
        plan = select_plan(request, load_catalog())
        payload = canonical_bytes(plan)
        if args.verify_output:
            if args.verify_output.read_bytes() != payload:
                raise SelectionError("loop plan does not match deterministic selection")
            print(json.dumps({"ok": True, "plan_sha256": sha256(plan)}, sort_keys=True))
            return 0
        if args.output:
            args.output.write_bytes(payload)
        else:
            sys.stdout.buffer.write(payload)
        return 0
    except (OSError, json.JSONDecodeError, SelectionError) as error:
        print(json.dumps({"ok": False, "error": str(error)}, sort_keys=True), file=sys.stderr)
        return 2


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Synthesize cited discovery proposals into a measurable Company OS outcome request."""
from __future__ import annotations

import argparse
import copy
import hashlib
import importlib.util
import json
import re
from pathlib import Path
from typing import Any, Mapping

PROPOSAL_SCHEMA = "company-os.outcome-model-proposal.v1"
REQUEST_SCHEMA = "company-os.outcome-request.v1"
LOCATOR = re.compile(r"^(?:https?://|tool://|runtime://|module://|workspace://|reference://)[^\s]+$")
RICH_MODALITIES = {"interactive", "visual", "audio", "executable", "service", "database", "model", "physical", "composite"}
BENCHMARK_TIERS = {"negative", "baseline", "strong", "exemplar"}

class SynthesisError(ValueError):
    def __init__(self, code: str, message: str) -> None:
        self.code = code
        self.message = message
        super().__init__(f"{code}: {message}")

def canonical(value: Any) -> bytes:
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=False, allow_nan=False).encode("utf-8")

def digest(value: Any) -> str:
    return hashlib.sha256(canonical(value)).hexdigest()

def text(value: Any, label: str) -> str:
    if not isinstance(value, str) or not value.strip() or "\x00" in value:
        raise SynthesisError("E_SCHEMA", f"{label} must be nonempty")
    return value.strip()

def obj(value: Any, label: str) -> Mapping[str, Any]:
    if not isinstance(value, Mapping):
        raise SynthesisError("E_SCHEMA", f"{label} must be an object")
    return value

def strings(value: Any, label: str, *, nonempty: bool = True) -> list[str]:
    if not isinstance(value, list):
        raise SynthesisError("E_SCHEMA", f"{label} must be an array")
    result = [text(item, f"{label}[]") for item in value]
    if len(result) != len(set(result)):
        raise SynthesisError("E_DUPLICATE", f"{label} contains duplicates")
    if nonempty and not result:
        raise SynthesisError("E_EVIDENCE", f"{label} cannot be empty")
    return sorted(result)

def read_json(path: Path, label: str) -> Any:
    try:
        return json.loads(path.read_text(encoding="utf-8"))
    except (OSError, UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise SynthesisError("E_JSON", f"invalid {label}: {path}") from exc

def outcome_module():
    path = Path(__file__).resolve().parents[2] / "compile-outcome-contract/scripts/compile_outcome_contract.py"
    spec = importlib.util.spec_from_file_location("company_os_synthesis_outcome", path)
    if spec is None or spec.loader is None:
        raise SynthesisError("E_RUNTIME", "outcome compiler cannot be loaded")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module

def citations(item: Mapping[str, Any], label: str) -> list[str]:
    return strings(item.get("citations"), f"{label}.citations")

def normalize_resolution(item: Mapping[str, Any], label: str) -> dict[str, Any]:
    unknown_id = text(item.get("unknown_id"), f"{label}.unknown_id")
    counter = strings(item.get("counterevidence", []), f"{label}.counterevidence", nonempty=False)
    reconciliation = item.get("reconciliation")
    if counter:
        reconciliation = text(reconciliation, f"{label}.reconciliation")
    elif reconciliation is not None:
        reconciliation = text(reconciliation, f"{label}.reconciliation")
    return {
        "unknown_id": unknown_id,
        "conclusion": text(item.get("conclusion"), f"{label}.conclusion"),
        "citations": citations(item, label),
        "counterevidence": counter,
        "reconciliation": reconciliation,
        "closure_evidence": strings(item.get("closure_evidence"), f"{label}.closure_evidence"),
    }
def normalize_domain(item: Mapping[str, Any], label: str) -> dict[str, Any]:
    status = item.get("status")
    if status not in {"supported", "refuted"}:
        raise SynthesisError("E_SCHEMA", f"{label}.status must be supported or refuted")
    source_bindings = strings(item.get("source_bindings"), f"{label}.source_bindings")
    return {
        "domain_id": text(item.get("domain_id"), f"{label}.domain_id"),
        "hypothesis": text(item.get("hypothesis"), f"{label}.hypothesis"),
        "status": status,
        "source_bindings": source_bindings,
    }
def normalize_claim(item: Mapping[str, Any], label: str) -> dict[str, Any]:
    return {
        "claim_id": text(item.get("claim_id"), f"{label}.claim_id"),
        "statement": text(item.get("statement"), f"{label}.statement"),
        "evidence_bindings": strings(item.get("evidence_bindings"), f"{label}.evidence_bindings"),
        "source_bindings": citations(item, label),
    }
def normalize_artifact(item: Mapping[str, Any], label: str) -> dict[str, Any]:
    artifact_id = text(item.get("artifact_class_id"), f"{label}.artifact_class_id")
    required = item.get("required", True)
    if not isinstance(required, bool):
        raise SynthesisError("E_SCHEMA", f"{label}.required must be boolean")
    modalities = strings(item.get("modalities"), f"{label}.modalities")
    methods = strings(item.get("observation_methods"), f"{label}.observation_methods")
    required_evidence = strings(item.get("required_evidence"), f"{label}.required_evidence")
    if required and set(modalities) & RICH_MODALITIES and not required_evidence:
        raise SynthesisError("E_EVIDENCE", f"{artifact_id} is rich and requires experiential evidence")
    return {
        "artifact_class_id": artifact_id,
        "label": text(item.get("label"), f"{label}.label"),
        "required": required,
        "modalities": modalities,
        "observation_methods": methods,
        "required_evidence": required_evidence,
        "source_bindings": citations(item, label),
    }
def normalize_evaluator(item: Mapping[str, Any], label: str) -> dict[str, Any]:
    evaluator_id = text(item.get("evaluator_id"), f"{label}.evaluator_id")
    required = item.get("required", True)
    if not isinstance(required, bool):
        raise SynthesisError("E_SCHEMA", f"{label}.required must be boolean")
    independent = item.get("independent_role")
    if independent is not True:
        raise SynthesisError("E_AUTHORITY", f"{evaluator_id} must be independent from production")
    adapter_locator = item.get("adapter_locator")
    if adapter_locator is None:
        adapter_locator = f"workspace://.company-os/evaluators/{evaluator_id}/adapter.py"
    adapter_locator = text(adapter_locator, f"{label}.adapter_locator")
    if LOCATOR.fullmatch(adapter_locator) is None:
        raise SynthesisError("E_SCHEMA", f"{label}.adapter_locator is invalid")
    return {
        "evaluator_id": evaluator_id,
        "label": text(item.get("label"), f"{label}.label"),
        "required": required,
        "independent_role": True,
        "research_only": False,
        "executable_methods": strings(item.get("executable_methods"), f"{label}.executable_methods"),
        "adapter_locator": adapter_locator,
        "artifact_classes": strings(item.get("artifact_classes"), f"{label}.artifact_classes"),
        "produces_evidence": strings(item.get("produces_evidence"), f"{label}.produces_evidence"),
        "score_dimensions": strings(item.get("score_dimensions"), f"{label}.score_dimensions"),
        "source_bindings": citations(item, label),
    }
def normalize_benchmark(item: Mapping[str, Any], label: str) -> dict[str, Any]:
    benchmark_id = text(item.get("benchmark_id"), f"{label}.benchmark_id")
    required = item.get("required", True)
    if not isinstance(required, bool):
        raise SynthesisError("E_SCHEMA", f"{label}.required must be boolean")
    references = item.get("references")
    if not isinstance(references, list) or len(references) < 2:
        raise SynthesisError("E_BENCHMARK", f"{benchmark_id} requires at least two reference tiers")
    normalized_refs = []
    ids = set()
    tiers = set()
    for index, raw in enumerate(references):
        ref = obj(raw, f"{label}.references[{index}]")
        ref_id = text(ref.get("reference_id"), f"{label}.reference_id")
        if ref_id in ids:
            raise SynthesisError("E_DUPLICATE", f"duplicate benchmark reference {ref_id}")
        ids.add(ref_id)
        locator = text(ref.get("locator"), f"{label}.locator")
        if LOCATOR.fullmatch(locator) is None:
            raise SynthesisError("E_SCHEMA", f"benchmark locator invalid: {locator}")
        tier = text(ref.get("quality_tier"), f"{label}.quality_tier")
        if tier not in BENCHMARK_TIERS:
            raise SynthesisError("E_BENCHMARK", f"{benchmark_id} uses unsupported quality tier {tier}")
        tiers.add(tier)
        normalized_refs.append(
            {
                "reference_id": ref_id,
                "locator": locator,
                "quality_tier": tier,
                "provenance": text(ref.get("provenance"), f"{label}.provenance"),
                "citations": citations(ref, f"{label}.references[{index}]"),
            }
        )
    if len(tiers) < 2 or not ({"strong", "exemplar"} & tiers):
        raise SynthesisError("E_BENCHMARK", f"{benchmark_id} must include multiple tiers and a positive anchor")
    return {
        "benchmark_id": benchmark_id,
        "dimension": text(item.get("dimension"), f"{label}.dimension"),
        "required": required,
        "references": sorted(ref["locator"] for ref in normalized_refs),
        "reference_records": sorted(normalized_refs, key=lambda ref: ref["reference_id"]),
        "source_bindings": citations(item, label),
    }
def normalize_reality(item: Mapping[str, Any], label: str) -> dict[str, Any]:
    if item.get("independent_from_production") is not True or item.get("binds_original_objective") is not True:
        raise SynthesisError("E_AUTHORITY", "reality acceptance must be independent and bind the original objective")
    return {
        "policy": text(item.get("policy"), f"{label}.policy"),
        "independent_from_production": True,
        "binds_original_objective": True,
        "source_bindings": citations(item, label),
    }
def validate_proposal(raw: Mapping[str, Any], base: Mapping[str, Any]) -> dict[str, Any]:
    expected = {
        "$schema", "proposal_id", "objective_id", "request_sha256", "sources",
        "unknown_resolutions", "domain_hypotheses", "outcome_claims", "artifact_classes",
        "evaluators", "benchmarks", "reality_acceptance",
    }
    if set(raw) != expected:
        raise SynthesisError("E_SCHEMA", f"proposal keys are invalid: {sorted(set(raw) ^ expected)}")
    if raw.get("$schema") != PROPOSAL_SCHEMA:
        raise SynthesisError("E_SCHEMA", f"proposal must use {PROPOSAL_SCHEMA}")
    proposal_id = text(raw.get("proposal_id"), "proposal_id")
    if raw.get("objective_id") != base.get("objective_id"):
        raise SynthesisError("E_BINDING", f"proposal {proposal_id} objective mismatch")
    if raw.get("request_sha256") != digest(base):
        raise SynthesisError("E_BINDING", f"proposal {proposal_id} is not bound to the exact base request")
    sources = strings(raw.get("sources"), f"{proposal_id}.sources")
    def normalize_array(key: str, fn):
        value = raw.get(key)
        if not isinstance(value, list):
            raise SynthesisError("E_SCHEMA", f"{proposal_id}.{key} must be an array")
        return [fn(obj(item, f"{proposal_id}.{key}[{index}]"), f"{proposal_id}.{key}[{index}]") for index, item in enumerate(value)]
    reality_raw = raw.get("reality_acceptance")
    reality = None if reality_raw is None else normalize_reality(obj(reality_raw, "reality_acceptance"), f"{proposal_id}.reality_acceptance")
    return {
        "proposal_id": proposal_id,
        "sources": sources,
        "unknown_resolutions": normalize_array("unknown_resolutions", normalize_resolution),
        "domain_hypotheses": normalize_array("domain_hypotheses", normalize_domain),
        "outcome_claims": normalize_array("outcome_claims", normalize_claim),
        "artifact_classes": normalize_array("artifact_classes", normalize_artifact),
        "evaluators": normalize_array("evaluators", normalize_evaluator),
        "benchmarks": normalize_array("benchmarks", normalize_benchmark),
        "reality_acceptance": reality,
    }
def merge_records(proposals: list[dict[str, Any]], key: str, id_key: str) -> list[dict[str, Any]]:
    merged: dict[str, dict[str, Any]] = {}
    source: dict[str, str] = {}
    for proposal in proposals:
        for record in proposal[key]:
            identifier = record[id_key]
            if identifier in merged and canonical(merged[identifier]) != canonical(record):
                raise SynthesisError(
                    "E_CONFLICT",
                    f"{key} {identifier} conflicts between proposals {source[identifier]} and {proposal['proposal_id']}",
                )
            merged[identifier] = copy.deepcopy(record)
            source[identifier] = proposal["proposal_id"]
    return [merged[key] for key in sorted(merged)]
def synthesize(base_raw: Mapping[str, Any], proposal_raws: list[Mapping[str, Any]]) -> tuple[dict[str, Any], dict[str, Any]]:
    if base_raw.get("$schema") != REQUEST_SCHEMA:
        raise SynthesisError("E_SCHEMA", f"base request must use {REQUEST_SCHEMA}")
    base = copy.deepcopy(dict(base_raw))
    if not proposal_raws:
        raise SynthesisError("E_SCHEMA", "at least one discovery proposal is required")
    proposals = [validate_proposal(raw, base) for raw in proposal_raws]
    ids = [proposal["proposal_id"] for proposal in proposals]
    if len(ids) != len(set(ids)):
        raise SynthesisError("E_DUPLICATE", "proposal IDs must be unique")
    resolution_records = merge_records(proposals, "unknown_resolutions", "unknown_id")
    resolution_by_id = {record["unknown_id"]: record for record in resolution_records}
    unknowns = []
    for raw in base.get("unknowns", []):
        item = copy.deepcopy(dict(obj(raw, "base unknown")))
        unknown_id = text(item.get("unknown_id"), "unknown_id")
        resolution = resolution_by_id.get(unknown_id)
        if resolution is not None:
            required = set(item.get("closure_evidence", []))
            supplied = set(resolution["closure_evidence"])
            if not required.issubset(supplied):
                raise SynthesisError("E_EVIDENCE", f"{unknown_id} does not satisfy its closure evidence")
            item["resolved"] = True
            item["resolution"] = resolution["conclusion"]
            item["resolution_citations"] = resolution["citations"]
            item["resolution_counterevidence"] = resolution["counterevidence"]
            if resolution["reconciliation"] is not None:
                item["resolution_reconciliation"] = resolution["reconciliation"]
        unknowns.append(item)
    unresolved = sorted(
        item["unknown_id"]
        for item in unknowns
        if item.get("blocking", True) is True and item.get("resolved") is not True
    )
    if unresolved:
        raise SynthesisError("E_INCOMPLETE", f"blocking unknowns remain unresolved: {', '.join(unresolved)}")
    domains = {
        item["domain_id"]: copy.deepcopy(item)
        for item in base.get("domain_hypotheses", [])
        if isinstance(item, Mapping) and isinstance(item.get("domain_id"), str)
    }
    for item in merge_records(proposals, "domain_hypotheses", "domain_id"):
        domains[item["domain_id"]] = item
    reality_values = [proposal["reality_acceptance"] for proposal in proposals if proposal["reality_acceptance"] is not None]
    if not reality_values:
        raise SynthesisError("E_INCOMPLETE", "discovery did not define final reality acceptance")
    reality = reality_values[0]
    for candidate in reality_values[1:]:
        if canonical(candidate) != canonical(reality):
            raise SynthesisError("E_CONFLICT", "reality acceptance proposals conflict")
    request = {
        "$schema": REQUEST_SCHEMA,
        "objective_id": base["objective_id"],
        "objective": base["objective"],
        "outcome_claims": merge_records(proposals, "outcome_claims", "claim_id"),
        "domain_hypotheses": [domains[key] for key in sorted(domains)],
        "artifact_classes": merge_records(proposals, "artifact_classes", "artifact_class_id"),
        "evaluators": merge_records(proposals, "evaluators", "evaluator_id"),
        "benchmarks": merge_records(proposals, "benchmarks", "benchmark_id"),
        "unknowns": sorted(unknowns, key=lambda item: item["unknown_id"]),
        "reality_acceptance": reality,
    }
    try:
        contract = outcome_module().compile_contract(request)
    except Exception as exc:
        raise SynthesisError(getattr(exc, "code", "E_OUTCOME"), f"synthesized outcome is invalid: {exc}") from exc
    if contract.get("blockers"):
        detail = "; ".join(f"{item['code']}:{item['detail']}" for item in contract["blockers"])
        raise SynthesisError("E_INCOMPLETE", f"synthesized outcome still has blockers: {detail}")
    if contract.get("scale_allowed") is not True:
        raise SynthesisError("E_INCOMPLETE", "synthesized outcome did not become measurable")
    return request, contract

def write_json(path: Path, value: Any) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(value, indent=2, sort_keys=True) + "\n", encoding="utf-8")
def main() -> int:
    parser = argparse.ArgumentParser()
    parser.add_argument("--base-request", type=Path, required=True)
    parser.add_argument("--proposal", type=Path, action="append", required=True)
    parser.add_argument("--request-output", type=Path, required=True)
    parser.add_argument("--contract-output", type=Path, required=True)
    args = parser.parse_args()
    try:
        base = obj(read_json(args.base_request, "base request"), "base request")
        proposals = [obj(read_json(path, "proposal"), "proposal") for path in args.proposal]
        request, contract = synthesize(base, proposals)
        write_json(args.request_output, request)
        write_json(args.contract_output, contract)
        print(json.dumps({"ok": True, "objective_id": request["objective_id"], "request_sha256": digest(request), "contract_sha256": contract["contract_sha256"], "state": contract["state"]}, sort_keys=True))
        return 0
    except SynthesisError as exc:
        print(json.dumps({"ok": False, "code": exc.code, "error": exc.message}, sort_keys=True))
        return 2

if __name__ == "__main__":
    raise SystemExit(main())

